#  AUTO .env LOADER
# ══════════════════════════════════════════════════════════════════════
import os as _os
import sys as _sys

def _load_dotenv():
    here = _os.path.dirname(_os.path.abspath(__file__))
    for path in (_os.path.join(here, ".env"),
                 _os.path.join(_os.getcwd(), ".env"),
                 ".env"):
        try:
            if not _os.path.isfile(path):
                continue
            with open(path, "r", encoding="utf-8-sig") as fh:
                for raw in fh:
                    line = raw.strip()
                    if not line or line.startswith("#"):
                        continue
                    if line.lower().startswith("export "):
                        line = line[7:].strip()
                    if "=" not in line:
                        continue
                    key, _, val = line.partition("=")
                    key = key.strip()
                    val = val.strip()
                    if len(val) >= 2 and val[0] == val[-1] and val[0] in ("'", '"'):
                        val = val[1:-1]
                    if key and key not in _os.environ:
                        _os.environ[key] = val
            print(f"[env] loaded: {path}")
            return True
        except Exception as e:
            print(f"[env] load failed {path}: {e}")
    return False

_load_dotenv()
# ══════════════════════════════════════════════════════════════════════


def _version_guard() -> None:
    need = (21, 7) if _sys.version_info >= (3, 13) else (20, 0)
    try:
        from importlib.metadata import version as _v
        raw = _v("python-telegram-bot")
        ver = tuple(int(p) for p in raw.split(".")[:2])
    except Exception:
        return
    if ver < need:
        line = "=" * 64
        print(f"\n{line}")
        print("  WRONG python-telegram-bot VERSION INSTALLED")
        print(f"{line}")
        print(f"  Installed : {raw}")
        print(f"  Required  : {'.'.join(map(str, need))} or newer")
        print(f"  Python    : {_sys.version.split()[0]}")
        print(f"{line}")
        print('\n  Run this in Termux:\n')
        print('      pip install -U "python-telegram-bot[job-queue]==22.5" aiohttp pymongo segno\n')
        print(f"{line}\n")
        _sys.exit(1)


_version_guard()

