_TG_UI_PLAIN = {k.replace("\ufe0f", ""): v for k, v in TG_EMOJI_UI.items()}
TG_EMOJI_UI.update({k: _TG_UI_PLAIN[v] for k, v in TG_EMOJI_ALIAS.items()
                    if v in _TG_UI_PLAIN})

_VS16 = "\ufe0f"
_TG_UI_KEY = {str(k).replace(_VS16, ""): v for k, v in TG_EMOJI_UI.items()}
_TG_UI_RE = re.compile("|".join(
    "(?:%s)%s?" % (re.escape(k), _VS16)
    for k in sorted(_TG_UI_KEY, key=len, reverse=True)) or r"(?!x)x")
TG_BLOCK_RE = re.compile(r"<tg-emoji\b[^>]*>.*?</tg-emoji>", re.S)
_TG_PROTECT_RE = re.compile(
    r"(<tg-emoji\b[^>]*>.*?</tg-emoji>|<(?:pre|code)\b[^>]*>.*?</(?:pre|code)>)",
    re.S)
_TG_FLAG_RE = re.compile("[\U0001F1E6-\U0001F1FF]{2}")
_TG_TAG_RE = re.compile(r"<[^>]+>")


def _flag_glyphs(cc) -> str:
    cc = str(cc or "").strip().upper()
    if len(cc) != 2 or not cc.isalpha():
        return ""
    return "".join(chr(0x1F1E6 + ord(ch) - 65) for ch in cc)


def em(glyph: str) -> str:
    """One emoji -> premium tag (the normal emoji stays as the fallback)."""
    g = str(glyph or "")
    if not g:
        return g
    tid = _TG_UI_KEY.get(g.replace(_VS16, ""))
    if not PREMIUM_EMOJI or not tid:
        return g
    return '<tg-emoji emoji-id="%s">%s</tg-emoji>' % (tid, g)


def emflag(cc) -> str:
    """Country code -> premium flag (countries without an ID keep the normal flag)."""
    fl = _flag_glyphs(cc)
    if not fl:
        return "\u2022"
    tid = TG_EMOJI_CC.get(str(cc or "").strip().upper())
    if not PREMIUM_EMOJI or not tid:
        return fl
    return '<tg-emoji emoji-id="%s">%s</tg-emoji>' % (tid, fl)


def _wrap_flag_glyph(pair: str) -> str:
    cc = "".join(chr(ord(ch) - 0x1F1E6 + 65) for ch in pair)
    return emflag(cc)


