_EMOJI_RANGE_RE = re.compile(
    "[\U0001F000-\U0001FAFF"
    "\u2190-\u21FF\u2300-\u23FF\u2460-\u24FF\u25F0-\u27BF"
    "\u2900-\u297F\u2B00-\u2BFF\uFE00-\uFE0F\u20E3]")
# plain glyphs that are NOT emoji - always kept
_PLAIN_KEEP = set("\u2714\u2716\u25b2\u2605\u2606\u20b9\u25aa\u25ab"
                  "\u25a0\u25a1\u25cf\u25cb\u25c6\u25c7\u25c8\u25a3"
                  "\u25a4\u25f7\u25cd\u25ce\u27f3\u2302\u2190\u2192"
                  "\u2191\u2193\u2194\u203a\u2039\u00bb\u00ab\u2022"
                  "\u00b7\u2014\u2013\u2026\u24d8\u2726\u25b8\u25b6"
                  "\u25c0\u270e\u2709\u00a0\u2049")


def _deemoji_piece(part: str, plain: bool = True) -> str:
    out = []
    for ch in part:
        if ch in _PLAIN_KEEP:
            out.append(ch)
        elif ch in _DEEMOJI_MAP:
            out.append(_DEEMOJI_MAP[ch] if plain else "")
        elif _EMOJI_RANGE_RE.match(ch):
            out.append("")
        else:
            out.append(ch)
    return "".join(out)


def deemoji(text, plain: bool = True):
    """Every emoji -> normal glyph (or removed), country flags untouched."""
    if not isinstance(text, str) or not text:
        return text
    flags: List[str] = []

    def _keep(m):
        flags.append(m.group(0))
        return "\ue000%d\ue000" % (len(flags) - 1)

    t = _TG_FLAG_RE.sub(_keep, text)
    parts = _TG_PROTECT_RE.split(t)
    for i, part in enumerate(parts):
        if i % 2 == 0:
            parts[i] = _deemoji_piece(part, plain)
    t = "".join(parts)
    t = re.sub("[ \t]{2,}", " ", t)
    t = re.sub("(?m)^[ \t]+", "", t)
    t = re.sub("[ \t]+(?=$)", "", t, flags=re.M)
    for i, fl in enumerate(flags):
        t = t.replace("\ue000%d\ue000" % i, fl)
    return t


def _btn_text(text) -> str:
    """v40 button label: no emoji at all, no premium icon - flags allowed."""
    t = deemoji(str(text or ""), plain=False)
    t = re.sub(r"\s{2,}", " ", t).strip(" \u00b7-")
    return t or "\u00b7"


def premiumize(text):
    """Any message text -> HTML with premium emoji.

    * existing <tg-emoji> and <pre>/<code> blocks are never touched
    * both flags and UI icons get wrapped
    * running it twice never double-wraps (idempotent)
    """
    if not isinstance(text, str) or not text:
        return text
    text = deemoji(text)                  # v40: plain icons only
    if not PREMIUM_EMOJI:
        return text
    if "<tg-emoji" in text and not _TG_UI_RE.search(
            TG_BLOCK_RE.sub("", text)) and not _TG_FLAG_RE.search(
            TG_BLOCK_RE.sub("", text)):
        return text
    parts = _TG_PROTECT_RE.split(text)
    out = []
    for i, part in enumerate(parts):
        if i % 2:
            out.append(part)                     # protected block
            continue
        part = _TG_FLAG_RE.sub(lambda m: _wrap_flag_glyph(m.group(0)), part)
        # v40: UI icons are never premium-wrapped - only country flags can be
        out.append(part)
    return "".join(out)


def strip_tg_emoji(text):
    """Aakhri fallback: premium tags hata do, normal emoji rehne do."""
    if not isinstance(text, str) or "<tg-emoji" not in text:
        return text
    return TG_BLOCK_RE.sub(lambda m: _TG_TAG_RE.sub("", m.group(0)), text)


def premium_stats(text):
    """How many premium emoji a text carries (for tests / debug)."""
    return len(TG_BLOCK_RE.findall(str(text or "")))

LINE = "\u2500" * 20
DIV = LINE
THIN = "\u2500" * 20

# ══════════════════════════════════════════════════════════════════════
#   v33 · TELEGRAM KE NAYE MESSAGE STYLES  (rich message toolkit)
# ══════════════════════════════════════════════════════════════════════
# Telegram Bot API in sab ko support karta hai (HTML parse_mode):
#   <b> <i> <u> <s>  <code>  <pre><code class="language-x">  <a href>
#   <blockquote>  <blockquote expandable>  <tg-spoiler>  <tg-emoji>
# Rules jo humne follow kiye:
#   * <pre>/<code> ke andar koi aur tag NAHI (Telegram reject karta hai)
#   * <blockquote> ke andar blockquote NAHI (nesting allowed nahi)
#   * expandable quote = lambi "extra info" ke liye (tap par khulti hai)
HLINE = "\u2501" * 20            # heavy rule - title ke neeche
DOTLINE = "\u00b7" * 24          # soft separator
_ARROW = "\u27a4"


def exp(lines, title=None) -> str:
    """Expandable quote - the first 2-3 lines show, the rest opens on tap.

    A nested <blockquote> is stripped (Telegram does not allow nesting);
    otherwise the whole message would be rejected.
    """
    if isinstance(lines, str):
        body = lines
    else:
        body = "\n".join(str(x) for x in lines if str(x).strip())
    body = body.replace("<blockquote expandable>", "").replace(
        "<blockquote>", "").replace("</blockquote>", "")
    if title:
        body = f"<b>{title}</b>\n" + body
    body = body.strip()
    if not body:
        return ""
    return f"<blockquote expandable>{body}</blockquote>"


def promo(headline, cta=None, extra=None) -> str:
    """v35: naya announcement style (Telegram ke naye update jaisa).

    Badi bold headline, uske neeche quoted CTA line - bilkul wahi look
    jo channel post me hota hai:  heading + blue-bar quote.

        promo("NEED TELEGRAM ACCOUNT?", "Send 20+ reactions 🔥")
    """
    head_txt = " ".join(str(headline or "").split())
    if head_txt and not head_txt.startswith("<b>"):
        head_txt = f"<b>{head_txt}</b>"
    if cta is None:
        lines = []
    elif isinstance(cta, (list, tuple)):
        lines = list(cta)
    else:
        lines = [cta]
    lines = [" ".join(str(x).split()) for x in lines or [] if str(x).strip()]
    out = [head_txt] if head_txt else []
    if lines:
        body = "\n".join(ln.replace("<blockquote>", "").replace(
            "</blockquote>", "") for ln in lines)
        out.append(f"<blockquote>{body}</blockquote>")
    if extra:
        more = extra if isinstance(extra, (list, tuple)) else [extra]
        more = [str(x).strip() for x in more if str(x).strip()]
        if more:
            out.append("\n".join(more))
    return "\n".join(out)


def spoiler(text) -> str:
    """Tap to reveal - used for passwords / API keys / sessions."""
    t = str(text if text is not None else "")
    if not t:
        return "\u2014"
    return f"<tg-spoiler>{t}</tg-spoiler>"


def cb(code, lang=None) -> str:
    """Code block. Passing lang turns on syntax highlight (language-xxx)."""
    body = str(code if code is not None else "")
    body = (body.replace("&", "&amp;").replace("<", "&lt;")
                .replace(">", "&gt;"))
    if lang:
        return (f'<pre><code class="language-{lang}">{body}'
                f'</code></pre>')
    return f"<pre>{body}</pre>"


def link(text, url) -> str:
    """Safe clickable link (only http/https/tg allowed)."""
    u = str(url or "").strip()
    if not u.lower().startswith(("http://", "https://", "tg://")):
        return esc(text)
    return f'<a href="{html.escape(u, quote=True)}">{esc(text)}</a>'


def price_change(old, new) -> str:
    """Old price struck through + new price bold (only when it changed)."""
    try:
        o, n = float(old or 0), float(new or 0)
    except (TypeError, ValueError):
        return money(new)
    if o <= 0 or abs(o - n) < 0.01:
        return f"<b>{money(n)}</b>"
    return f"<s>{money(o)}</s> {_ARROW} <b>{money(n)}</b>"


def chip(label, glyph="") -> str:
    """Small status badge:  ✅ LIVE   /   ⏳ CHECKING."""
    g = (str(glyph).strip() + " ") if str(glyph or "").strip() else ""
    return f"<b>{g}{str(label).strip()}</b>"

