def db_credit(uid, amt, reason, ref=None):
    with _tx() as c:
        c.execute("INSERT OR IGNORE INTO users (user_id) VALUES (?)", (uid,))
        c.execute("UPDATE users SET balance=balance+? WHERE user_id=?", (amt, uid))
        nb = c.execute("SELECT balance FROM users WHERE user_id=?", (uid,)).fetchone()["balance"]
        cur = c.execute(
            "INSERT INTO ledger (user_id,amount,balance_after,reason,reference) "
            "VALUES (?,?,?,?,?)",
            (uid, amt, nb, reason, ref))
        led_id = cur.lastrowid
    mg_push_user(uid)
    mg_push_ledger_row(led_id)
    try:
        fs_touch()
    except Exception:
        pass
    return float(nb)


def db_debit(uid, amt, reason, ref=None):
    with _tx() as c:
        c.execute("INSERT OR IGNORE INTO users (user_id) VALUES (?)", (uid,))
        row = c.execute("SELECT balance FROM users WHERE user_id=?", (uid,)).fetchone()
        bal = float(row["balance"]) if row else 0.0
        if bal < amt:
            return None
        c.execute("UPDATE users SET balance=balance-? WHERE user_id=?", (amt, uid))
        nb = c.execute("SELECT balance FROM users WHERE user_id=?", (uid,)).fetchone()["balance"]
        cur = c.execute(
            "INSERT INTO ledger (user_id,amount,balance_after,reason,reference) "
            "VALUES (?,?,?,?,?)",
            (uid, -amt, nb, reason, ref))
        led_id = cur.lastrowid
    mg_push_user(uid)
    mg_push_ledger_row(led_id)
    try:
        fs_touch()
    except Exception:
        pass
    return float(nb)


