def cloud_protected_uids() -> set:
    """Uids MongoDB cloud still knows something real about (thread-safe)."""
    out = set()
    try:
        # ── FIX #28: dict snapshot to avoid RuntimeError on mutation ──
        cache = dict(list((getattr(mongo, "_cloud_users", None) or {}).items()))
    except Exception:
        return out
    for key, doc in cache.items():
        if not isinstance(doc, dict):
            continue
        try:
            uid = int(key)
        except (TypeError, ValueError):
            continue
        try:
            bal = float(doc.get("balance") or 0)
        except (TypeError, ValueError):
            bal = 0.0
        if (str(doc.get("username") or "").strip()
                or str(doc.get("first_name") or "").strip()
                or str(doc.get("last_seen") or "").strip()
                or bal
                or doc.get("order_count")):
            out.add(uid)
    return out


def db_purge_ghost_users() -> int:
    ids = db_ghost_users()
    if not ids:
        return 0
    conn = _get_conn()
    try:
        mongo.rebuild_balances()
        mongo.ensure_history_users()
    except Exception as e:
        log.warning("purge: ledger rebuild skipped: %s", e)
    protected = cloud_protected_uids()
    safe = []
    for uid in ids:
        if uid in protected:
            continue
        busy = 0
        for tbl in ("orders", "deposits", "ledger"):
            try:
                busy += int(conn.execute(
                    f"SELECT COUNT(*) FROM {tbl} WHERE user_id=?", (uid,)).fetchone()[0])
            except Exception:
                pass
        if busy:
            continue
        safe.append(int(uid))
    if not safe:
        return 0
    with _tx() as c:
        for uid in safe:
            c.execute("DELETE FROM users WHERE user_id=?", (uid,))
    return len(safe)


def refresh_country_soon(bot, cc, delay=2.0):
    async def _work():
        _BG.set(True)
        try:
            if delay:
                await asyncio.sleep(delay)
            r = await price_country(cc)
            log.info("post-sale re-price %s: S1 %s / S2 %s", cc,
                     r.get("floor"), r.get("floor2"))
        except Exception as e:
            log.warning("post-sale re-price %s failed: %s", cc, str(e)[:90])
    try:
        loop = asyncio.get_running_loop()
        loop.create_task(_work())
    except RuntimeError:
        return None


