# ── Roles (v11) ──────────────────────────────────────────────────────
# OWNER  : ids in ADMIN_IDS (env).            Full access, cannot be removed.
# SUPER  : admins promoted by Owner/Super.    Full access (same as Owner).
# ADMIN  : every other row in `admins`.       Restricted - only the
#          permission groups switched on in the "Admin Permissions" screen.
# Storage: JSON in the existing `settings` table (keys `admin_roles`,
# `admin_perms`), so the database schema is not changed.
ROLE_OWNER, ROLE_SUPER, ROLE_ADMIN = "owner", "super", "admin"
ROLE_LABEL = {ROLE_OWNER: "👑 Owner", ROLE_SUPER: "💎 Super Admin",
              ROLE_ADMIN: "🛡 Admin"}
ROLES_SETTING = "admin_roles"
PERMS_SETTING = "admin_perms"
_roles_cache: Dict[str, Any] = {"t": 0.0, "map": {}}


def _role_map() -> dict:
    now = time.monotonic()
    if now - _roles_cache["t"] < 5:
        return _roles_cache["map"]
    try:
        raw = json.loads(db_get_setting(ROLES_SETTING, "{}") or "{}")
    except Exception:
        raw = {}
    m = ({str(k): str(v) for k, v in raw.items() if v == ROLE_SUPER}
         if isinstance(raw, dict) else {})
    _roles_cache.update(t=now, map=m)
    return m


def role_of(uid) -> Optional[str]:
    try:
        uid = int(uid)
    except (TypeError, ValueError):
        return None
    if uid in ADMIN_IDS:
        return ROLE_OWNER
    if not is_admin(uid):
        return None
    return ROLE_SUPER if _role_map().get(str(uid)) == ROLE_SUPER else ROLE_ADMIN


def set_role(uid, role) -> None:
    m = dict(_role_map())
    if role == ROLE_SUPER:
        m[str(int(uid))] = ROLE_SUPER
    else:
        m.pop(str(int(uid)), None)
    db_set_setting(ROLES_SETTING, json.dumps(m))
    _roles_cache["t"] = 0.0


def is_full_admin(uid) -> bool:
    """Owner and Super Admin - identical, unrestricted access."""
    return role_of(uid) in (ROLE_OWNER, ROLE_SUPER)


# Permission groups a restricted ADMIN may be given (owner toggles them).
LIMITED_PERMS: List[Tuple[str, str, List[str]]] = [
    ("deposits", "📥 Deposits - view / approve / reject",
     [r"^adp$", r"^adep_\d+$", r"^rdep_\d+$"]),
    ("orders", "🧾 Orders - list / find / view",
     [r"^adm_orders$", r"^arv$", r"^aol$", r"^ao_\d+$"]),
    ("users", "👥 User lookup (view only)", [r"^aus$"]),
    ("stock", "📦 Stock check", [r"^stk_list_p\d+$", r"^stk_[A-Z]{2}$"]),
    ("stats", "📊 Sales stats (no profit data)", [r"^ast$"]),
]
LIMITED_DEFAULT = ["orders", "users", "stock"]
LIMITED_ALWAYS = [r"^admin$"]           # restricted dashboard
LIMITED_AW = {"user_lookup": "users", "order_lookup": "orders"}
_LIMITED_RE = [(k, [re.compile(p) for p in pats]) for k, _l, pats in LIMITED_PERMS]
_LIMITED_ALWAYS_RE = [re.compile(p) for p in LIMITED_ALWAYS]

# Every admin-panel callback (used by the central access gate).
ADMIN_CB_PATTERNS = [
    r"^admin$", r"^asl[a-z]?$", r"^aad$", r"^ast$", r"^apr(_.*)?$",
    r"^sp_[A-Z]{2}$", r"^stk_.*$", r"^adm_orders$", r"^arv$", r"^arp$",
    r"^ares_\d+$", r"^aref_\d+$", r"^adp$", r"^adep_\d+$", r"^rdep_\d+$",
    r"^aol$", r"^ao_\d+$", r"^agc_\d+$", r"^aus$", r"^ghosts$",
    r"^ghost_del$", r"^acr_\d+$", r"^adb_\d+$", r"^abn_\d+$", r"^apl$",
    r"^apm$", r"^abr$", r"^abal$", r"^afiles$", r"^afsync$", r"^asup$",
    r"^adbg$", r"^dbg$", r"^aer$", r"^aadm.*$", r"^aperm.*$", r"^afj.*$",
    r"^sec_.*$", r"^arate.*$", r"^mg(_.*)?$", r"^alp.*$", r"^adeal.*$",
    r"^aprof.*$", r"^adept$", r"^aprc$", r"^amk.*$",
    r"^maint(_toggle|_msg|_preview)?$", r"^adepl.*$", r"^atp.*$",
    r"^bc_.*$", r"^abulk.*$", r"^apa_\d+$", r"^apg(_set)?$",
    r"^arfc(_set)?$", r"^admcat:[a-z]+$", r"^amupi$", r"^mok_\d+$",
    r"^mno_\d+$",
]
_ADMIN_CB_RE = [re.compile(p) for p in ADMIN_CB_PATTERNS]
FULL_ONLY_COMMANDS = {"restore", "mongo", "saveconfig", "loadconfig",
                      "broadcast", "team"}


def limited_perms() -> List[str]:
    raw = db_get_setting(PERMS_SETTING, None)
    if raw is None:
        return list(LIMITED_DEFAULT)
    try:
        v = json.loads(raw)
        return [k for k in v if k in {p[0] for p in LIMITED_PERMS}]
    except Exception:
        return list(LIMITED_DEFAULT)


def set_limited_perms(keys) -> None:
    db_set_setting(PERMS_SETTING, json.dumps(sorted(set(keys))))


def is_admin_callback(data: str) -> bool:
    return any(r.match(data or "") for r in _ADMIN_CB_RE)


def can_use_callback(uid, data: str) -> bool:
    """True when `uid` may press the admin button `data`."""
    role = role_of(uid)
    if role in (ROLE_OWNER, ROLE_SUPER):
        return True
    if role != ROLE_ADMIN:
        return False
    if any(r.match(data) for r in _LIMITED_ALWAYS_RE):
        return True
    on = set(limited_perms())
    return any(k in on and any(r.match(data) for r in pats)
               for k, pats in _LIMITED_RE)


def has_perm(uid, key) -> bool:
    if is_full_admin(uid):
        return True
    return role_of(uid) == ROLE_ADMIN and key in limited_perms()



