def db_needs_captcha(uid, hours=None) -> bool:
    u = db_user(uid)
    if not u:
        return True
    try:
        last = u["verified_at"]
    except (IndexError, KeyError, TypeError):
        last = None
    if not last:
        return True
    try:
        h = int(hours or db_get_setting("captcha_hours", "12"))
    except (TypeError, ValueError):
        h = 12
    try:
        done = datetime.fromisoformat(str(last))
    except ValueError:
        return True
    return (now_utc() - done) > timedelta(hours=h)


