def merge_item_data(buy_item, detail_item):
    buy_item = buy_item or {}
    detail_item = detail_item or {}
    # ✅ FIX: Agar supplier ne galat data bheja (string/list) toh use empty dict banao
    if not isinstance(detail_item, dict):
        detail_item = {}
    if not isinstance(buy_item, dict):
        buy_item = {}
    merged = dict(buy_item)
    for k, v in detail_item.items():
        if v not in (None, "", [], {}):
            merged[k] = v
    a = buy_item.get("loginData")
    b = detail_item.get("loginData")
    if isinstance(b, dict):
        ld = dict(a) if isinstance(a, dict) else {}
        for k, v in b.items():
            if v not in (None, ""):
                ld[k] = v
        merged["loginData"] = ld
    return merged


def upi_uri(amount: float, note: str = "Topup") -> str:
    return (f"upi://pay?pa={_urlquote(FAMPAY_UPI_ID)}&pn={_urlquote(SHOP_NAME)}"
            f"&am={float(amount):.2f}&cu=INR&tn={_urlquote(note)}")


class FamGateway:
    def __init__(self):
        self._s: Optional[aiohttp.ClientSession] = None
        self.last_error: str = ""
        self.last_code: int = 0
        self.last_raw: str = ""
        self.last_hint: str = ""

    async def _ses(self):
        if not self._s or self._s.closed:
            self._s = aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=25))
        return self._s

    async def close(self):
        if self._s and not self._s.closed:
            await self._s.close()

    @staticmethod
    def _hint(status, msg) -> str:
        m = str(msg or "").lower()
        if status == 401 or "invalid api_key" in m or "unauthorized" in m:
            return "API key is not active yet. Open famgateway.in -> API Keys."
        if status == 403 or "suspended" in m:
            return "Gateway account suspended - write to support@famgateway.in"
        if status == 500 or "gmail" in m or "imap" in m:
            return "FamPay Gmail is not connected."
        if status == 429:
            return "Too many requests - wait a minute and try again."
        if status == 408 or "expire" in m:
            return "This payment session expired - make a fresh deposit."
        if status == 0:
            return "No internet / gateway unreachable."
        return ""

    @staticmethod
    def _order_from(j: dict, amount) -> dict:
        d = j.get("data") if isinstance(j.get("data"), dict) else j
        return {
            "ok": True, "order_id": str(d.get("order_id") or ""),
            "qr_url": str(d.get("qr_url") or ""),
            "checkout_url": str(d.get("checkout_url") or ""),
            "upi_intent": str(d.get("upi_intent") or ""),
            "upi_id": str(d.get("upi_id") or FAMPAY_UPI_ID),
            "payable_amount": float(d.get("payable_amount")
                                    or d.get("amount") or amount),
            "expires_at": str(d.get("expires_at_ist") or ""),
            "created_at": str(d.get("created_at_ist") or ""),
            "raw": {k: str(v)[:120] for k, v in d.items()},
        }

    async def _get_json(self, url, headers=None):
        ses = await self._ses()
        async with ses.get(url, headers=headers
                           or {"Accept": "application/json"}) as r:
            body = await r.text()
            self.last_raw = body[:400]
            try:
                return r.status, json.loads(body)
            except ValueError:
                return r.status, {"raw": body[:200]}

    async def create_order(self, amount, name="Customer", phone="",
                           email="", webhook=""):
        amount = float(f"{float(amount):.2f}")
        payload = {"api_key": FAMPAY_API_KEY, "amount": amount,
                   "customer_name": (name or "Customer")[:40],
                   "redirect_url": SUPPORT_URL}
        if phone:
            payload["customer_phone"] = str(phone)[-10:]
        if email:
            payload["customer_email"] = email
        if webhook:
            payload["webhook_url"] = webhook
        headers = {"X-Api-Key": FAMPAY_API_KEY,
                   "Authorization": f"Bearer {FAMPAY_API_KEY}",
                   "Content-Type": "application/json",
                   "Accept": "application/json"}
        try:
            ses = await self._ses()
            async with ses.post(GATEWAY_CREATE, json=payload,
                                headers=headers) as r:
                body = await r.text()
                self.last_raw = body[:400]
                self.last_code = r.status
                try:
                    j = json.loads(body)
                except ValueError:
                    j = {"raw": body[:200]}
                if r.status == 200 and \
                        str(j.get("status", "")).lower() == "success":
                    out = self._order_from(j, amount)
                    self.last_error = ""
                    self.last_hint = ""
                    if out["order_id"]:
                        return out
                self.last_error = str(j.get("message") or j.get("status")
                                      or j.get("error") or j)[:180]
        except Exception as e:
            self.last_code = 0
            self.last_error = str(e)[:180]
        try:
            url = (f"{GATEWAY_QRALIAS}?api_key={_urlquote(FAMPAY_API_KEY)}"
                   f"&amount={amount:.2f}&customer_name="
                   f"{_urlquote(name or 'Customer')}")
            st, j = await self._get_json(url)
            self.last_code = st
            if st == 200 and str(j.get("status", "")).lower() == "success":
                out = self._order_from(j, amount)
                self.last_error = ""
                self.last_hint = ""
                return out
            if not self.last_error:
                self.last_error = str(j.get("message") or j.get("status") or j)[:180]
        except Exception as e:
            self.last_error = self.last_error or str(e)[:180]
        self.last_hint = self._hint(self.last_code, self.last_error)
        return {"ok": False, "error": self.last_error or "gateway unreachable",
                "code": self.last_code, "hint": self.last_hint,
                "raw": self.last_raw}

    async def verify(self, order_id):
        if not order_id:
            return {"ok": False, "status": "unknown", "paid": False}
        url = (f"{GATEWAY_VERIFY}?api_key={_urlquote(FAMPAY_API_KEY)}"
               f"&order_id={_urlquote(str(order_id))}")
        try:
            st_http, j = await self._get_json(url)
        except Exception as e:
            return {"ok": False, "status": "unknown", "paid": False,
                    "error": str(e)[:120]}
        st = str(j.get("status", "")).lower()
        d = j.get("data") if isinstance(j.get("data"), dict) else j
        return {
            "ok": st in ("success", "pending", "expired", "paid", "completed"),
            "status": st or "unknown",
            "paid": st in ("success", "paid", "completed"),
            "utr": str(d.get("utr") or ""),
            "sender": str(d.get("sender_name") or ""),
            "amount": str(d.get("amount") or ""),
            "txn": str(d.get("transaction_id") or ""),
            "paid_at": str(d.get("payment_time_ist") or ""),
            "http": st_http,
            "error": "" if st_http == 200
            else str(j.get("message") or "")[:120],
        }

    async def checkout_status(self, order_id):
        if not order_id:
            return {"ok": False, "status": "unknown", "paid": False}
        try:
            st_http, j = await self._get_json(
                f"{GATEWAY_CHECKOUT}?order_id={_urlquote(str(order_id))}")
        except Exception:
            return {"ok": False, "status": "unknown", "paid": False}
        st = str(j.get("status", "")).lower()
        d = j.get("data") if isinstance(j.get("data"), dict) else j
        return {
            "ok": st in ("success", "pending", "expired", "paid", "completed"),
            "status": st or "unknown",
            "paid": st in ("success", "paid", "completed"),
            "utr": str(d.get("utr") or ""),
            "sender": str(d.get("sender_name") or ""),
            "amount": str(d.get("amount") or ""),
            "txn": str(d.get("transaction_id") or ""),
            "http": st_http,
        }

    async def status(self, order_id):
        r = await self.verify(order_id)
        if r.get("paid") or r.get("status") == "expired":
            return r
        if r.get("ok") and r.get("status") == "pending":
            return r
        pub = await self.checkout_status(order_id)
        if pub.get("paid") or pub.get("status") == "expired":
            return pub
        return r if r.get("ok") else pub

    async def test(self):
        r = await self.create_order(1.0, name="Test")
        if r.get("ok"):
            return {"ok": True, "note": f"order {r['order_id']} created",
                    "order": r}
        return {"ok": False,
                "note": f"HTTP {self.last_code}: {self.last_error}"[:180],
                "hint": self.last_hint, "raw": self.last_raw}


gateway = FamGateway()


async def gw_status(order_id):
    fn = getattr(gateway, "status", None)
    if callable(fn):
        try:
            return await fn(order_id)
        except Exception as e:
            log.warning("gateway.status failed: %s", str(e)[:100])
    return await gateway.verify(order_id)


