def norm_origin(o):
    o = str(o or "").strip().lower()
    return o if o in VALID_ORIGINS else None


def norm_origins(lst):
    out, seen = [], set()
    for o in lst:
        n = norm_origin(o)
        if n and n not in seen:
            out.append(n)
            seen.add(n)
    return out


def item_country_matches(item, cc) -> bool:
    cc = str(cc or "").upper().strip()
    if not cc:
        return False
    item = item if isinstance(item, dict) else {}
    raw_country = item.get("telegram_country") or item.get("country") or ""
    if isinstance(raw_country, dict):
        raw_country = (raw_country.get("code") or raw_country.get("iso2")
                       or raw_country.get("country_code") or raw_country.get("name") or "")
    ic = str(raw_country or "").strip()
    if ic.upper() == cc:
        return True
    # Providers sometimes return a country name instead of its ISO-2 code.
    if ic:
        try:
            country = db_country(cc)
            if country and ic.casefold() == str(country["name"] or "").casefold():
                return True
            matches = db_country_search(ic)
            if any(str(row["code"]).upper() == cc and
                   str(row["name"] or "").casefold() == ic.casefold()
                   for row in matches):
                return True
        except Exception:
            pass
    phone = _find_phone(item)
    digits = re.sub(r"\D", "", phone or "")
    dial = DIAL_CODES.get(cc, "")
    return bool(dial and digits.startswith(dial)
                and len(digits) - len(dial) >= 6)


def _looks_like_auth_key(v) -> bool:
    s = str(v or "").strip()
    if not s:
        return False
    if re.fullmatch(r"[0-9a-fA-F]{512}", s):
        return True
    if len(s) >= 200 and re.fullmatch(r"[A-Za-z0-9_+/=\-]+", s):
        return True
    return False


def _looks_like_phone(v) -> bool:
    s = str(v or "").strip()
    if not s or _looks_like_auth_key(s):
        return False
    if not re.fullmatch(r"\+?[\d\s\-().]{5,25}", s):
        return False
    return 7 <= len(re.sub(r"\D", "", s)) <= 15


def _with_country_code(phone, item=None) -> str:
    digits = re.sub(r"\D", "", str(phone or ""))
    if not digits:
        return ""
    cc = str((item or {}).get("telegram_country") or "").upper().strip()
    dial = DIAL_CODES.get(cc, "")
    if dial and digits.startswith(dial) and len(digits) - len(dial) >= 6:
        return "+" + digits
    if digits.startswith("00"):
        return "+" + digits[2:]
    if str(phone or "").strip().startswith("+"):
        return "+" + digits
    if digits.startswith("0") and dial:
        return "+" + dial + digits.lstrip("0")
    if dial:
        return "+" + dial + digits
    return "+" + digits


def _decode_maybe_b64(v) -> str:
    s = str(v or "").strip()
    if not s or len(s) < 8 or not re.fullmatch(r"[A-Za-z0-9_\-+/=\s]+", s):
        return ""
    try:
        blob = base64.b64decode(s + "=" * (-len(s) % 4), validate=False)
    except Exception:
        return ""
    try:
        txt = blob.decode("utf-8")
    except Exception:
        try:
            txt = blob.decode("latin-1")
        except Exception:
            return ""
    printable = sum(1 for ch in txt if ch.isprintable() or ch in "\r\n\t")
    if not txt or printable / max(1, len(txt)) < 0.9:
        return ""
    return txt


def _phone_from_text(text, item=None) -> str:
    s = str(text or "")
    if not s:
        return ""
    cc = str((item or {}).get("telegram_country") or "").upper().strip()
    dial = DIAL_CODES.get(cc, "")
    cands = re.findall(r"\+?\d[\d\s\-().]{5,20}\d", s)
    cleaned = [c.strip() for c in cands if _looks_like_phone(c)]
    if dial:
        for c in cleaned:
            d = re.sub(r"\D", "", c)
            if d.startswith(dial) and len(d) - len(dial) >= 6:
                return c
    return cleaned[0] if cleaned else ""


def _login_blobs(item) -> List[str]:
    item = item or {}
    out = []
    for key in ("loginData", "login_data", "emailLoginData", "email_login_data"):
        ld = item.get(key)
        if isinstance(ld, str):
            try:
                ld = json.loads(ld)
            except (TypeError, ValueError):
                out.append(ld)
                continue
        if isinstance(ld, dict):
            for k in ("raw", "login", "password", "oldPassword",
                      "phone", "telephone", "username"):
                v = ld.get(k)
                if v and not _looks_like_auth_key(v):
                    out.append(str(v))
            for k in ("encodedRaw", "encodedPassword", "encodedOldPassword"):
                dec = _decode_maybe_b64(ld.get(k))
                if dec and not _looks_like_auth_key(dec):
                    out.append(dec)
    for k in ("description", "description_en", "information", "note_text",
              "title", "title_en", "item_state_title"):
        v = item.get(k)
        if v:
            out.append(str(v))
    return out


_PHONE_KEY_RE = re.compile(
    r"(phone|telephone|mobile|msisdn|number|login|username)", re.I)
_PHONE_BAD_KEY_RE = re.compile(
    r"(item_id|user_id|order|price|count|id$|_id$|auth|key|token|hash|"
    r"session|dc|date|time|stamp)", re.I)


def _deep_find_phone(obj, depth=0):
    if depth > 5:
        return ""
    if isinstance(obj, str):
        s = obj.strip()
        if s.startswith("{") or s.startswith("["):
            try:
                return _deep_find_phone(json.loads(s), depth + 1)
            except (TypeError, ValueError):
                return ""
        return ""
    if isinstance(obj, dict):
        for k, v in obj.items():
            ks = str(k)
            if _PHONE_BAD_KEY_RE.search(ks):
                continue
            if _PHONE_KEY_RE.search(ks) and _looks_like_phone(v):
                return str(v).strip()
        for k, v in obj.items():
            if _PHONE_BAD_KEY_RE.search(str(k)):
                continue
            if isinstance(v, (dict, list, str)):
                got = _deep_find_phone(v, depth + 1)
                if got:
                    return got
        return ""
    if isinstance(obj, list):
        for v in obj[:50]:
            got = _deep_find_phone(v, depth + 1)
            if got:
                return got
    return ""


def _find_phone(item) -> str:
    item = item or {}
    ld = item.get("loginData") or item.get("login_data") or {}
    if not isinstance(ld, dict):
        ld = {}
    tj_phone = ""
    for tk in ("telegram_json", "telegramJson", "telegram_JSON"):
        tj = item.get(tk)
        if isinstance(tj, dict):
            tj_phone = str(tj.get("phone") or tj.get("telephone") or "")
            if tj_phone:
                break
        elif isinstance(tj, str) and tj.strip():
            try:
                tjo = json.loads(tj)
                if isinstance(tjo, dict):
                    tj_phone = str(tjo.get("phone")
                                   or tjo.get("telephone") or "")
                    if tj_phone:
                        break
            except (TypeError, ValueError):
                pass
    nested = item.get("item") if isinstance(item.get("item"), dict) else {}
    nld = nested.get("loginData") if isinstance(nested.get("loginData"), dict) else {}
    for cand in (ld.get("phone"), ld.get("telephone"), ld.get("mobile"),
                 ld.get("login"), ld.get("username"),
                 item.get("telegram_phone"), item.get("telegram_login"),
                 item.get("phone"), item.get("phone_number"),
                 item.get("telephone"), item.get("mobile"),
                 item.get("login"), item.get("account_login"),
                 nld.get("phone"), nld.get("login"),
                 nested.get("telegram_phone"), nested.get("telegram_login"),
                 tj_phone):
        if _looks_like_phone(cand):
            return _with_country_code(str(cand).strip(), item)
    for title in (item.get("title"), item.get("title_en"),
                  nested.get("title"), nested.get("title_en"),
                  item.get("description"), item.get("item_state_title")):
        for m in re.findall(r"\+\d[\d\s\-().]{5,20}\d", str(title or "")):
            if _looks_like_phone(m):
                return _with_country_code(m.strip(), item)
        for part in re.split(r"[\s|/,;]+", str(title or "")):
            if _looks_like_phone(part):
                return _with_country_code(part.strip(), item)
        for m in re.findall(r"\d{7,15}", str(title or "")):
            if _looks_like_phone(m):
                return _with_country_code(m.strip(), item)
    for blob in _login_blobs(item) + _login_blobs(nested):
        got = _phone_from_text(blob, item)
        if got:
            return _with_country_code(got, item)
    deep = _deep_find_phone(item)
    if deep:
        return _with_country_code(deep, item)
    return ""


def parse_auth_key(raw) -> Optional[bytes]:
    s = str(raw or "").strip()
    if not s:
        return None
    h = re.sub(r"[\s:,\-]", "", s)
    if re.fullmatch(r"[0-9a-fA-F]{512}", h):
        return bytes.fromhex(h)
    if s[0] == "1" and re.fullmatch(r"[A-Za-z0-9_\-+/=]+", s[1:]):
        try:
            blob = base64.urlsafe_b64decode(s[1:] + "=" * (-len(s[1:]) % 4))
            if len(blob) == 263:
                return blob[7:]
        except Exception:
            pass
    for dec in (base64.b64decode, base64.urlsafe_b64decode):
        try:
            blob = dec(s + "=" * (-len(s) % 4))
            if len(blob) == 256:
                return blob
        except Exception:
            continue
    if len(s) == 256:
        try:
            return s.encode("latin-1")
        except Exception:
            return None
    return None


def parse_dc_id(raw) -> int:
    m = re.search(r"\d+", str(raw or ""))
    if m:
        v = int(m.group(0))
        if 1 <= v <= 5:
            return v
        if 10001 <= v <= 10005:
            return v - 10000
    return 2


def _session_raw_key(item) -> str:
    item = item or {}
    ld = item.get("loginData") or item.get("login_data") or {}
    if not isinstance(ld, dict):
        ld = {}
    for cand in (ld.get("login"), ld.get("auth_key"),
                 item.get("auth_key"), item.get("telegram_auth_key")):
        if _looks_like_auth_key(cand):
            return str(cand)
    return ""


def _session_raw_dc(item) -> str:
    item = item or {}
    ld = item.get("loginData") or item.get("login_data") or {}
    if not isinstance(ld, dict):
        ld = {}
    for cand in (ld.get("dc_id"), item.get("dc_id"), item.get("telegram_dc_id")):
        if cand not in (None, ""):
            return str(cand)
    if _looks_like_auth_key(ld.get("login")):
        return str(ld.get("password") or "")
    return ""


def tg_code_pairs(raw) -> List[Tuple[str, int]]:
    pairs: List[Tuple[str, int]] = []

    def _push(code, date=0):
        c = str(code or "").strip()
        if not c:
            return
        if re.fullmatch(r"\d{10,}", c):
            return
        try:
            t = int(float(date or 0))
        except (TypeError, ValueError):
            t = 0
        pairs.append((c, t))

    def _walk(v):
        if v is None or v == "" or isinstance(v, bool):
            return
        if isinstance(v, dict):
            for k in ("code", "otp", "loginCode", "login_code", "value"):
                if v.get(k) not in (None, ""):
                    _push(v[k], v.get("date") or v.get("created_at")
                          or v.get("createdAt") or v.get("time")
                          or v.get("timestamp") or 0)
                    return
            for x in v.values():
                _walk(x)
            return
        if isinstance(v, (list, tuple, set)):
            for x in v:
                _walk(x)
            return
        if isinstance(v, (int, float)):
            if 1_600_000_000 <= float(v) <= 2_200_000_000:
                return
            _push(v)
            return
        _push(v)

    _walk(raw)
    pairs.sort(key=lambda p: p[1], reverse=True)
    return pairs


def to_inr(amount, currency=None) -> float:
    cur = str(currency or SUP_CURRENCY).lower()
    if cur in ("usd", "usdt"):
        return float(amount or 0) * usdt_rate()
    return float(amount or 0) * CUR_TO_INR.get(cur, 1.0)


def flag_int(value, default=0) -> int:
    """v41: supplier "yes"/"no"/"1"/"" flags -> safe int (never raises).

    Asli API `telegram_password` / `telegram_email` me "no" bhejti hai, aur
    `int("no")` ne account-details screen crash kar di thi.
    """
    if value is None or value == "":
        return default
    if isinstance(value, bool):
        return 1 if value else 0
    try:
        return int(float(value))
    except (TypeError, ValueError):
        pass
    txt = str(value).strip().lower()
    if txt in ("yes", "true", "on", "y", "1", "active"):
        return 1
    if txt in ("no", "false", "off", "n", "0", "none", "null", "-"):
        return 0
    return default


def telegram_spam_state(item) -> Optional[bool]:
    v = item.get("telegram_spam_block") if isinstance(item, dict) else None
    if v is None or v == "":
        return None
    try:
        n = int(v)
    except (TypeError, ValueError):
        s = str(v).strip().lower()
        if s in ("yes", "true"):
            return True
        if s in ("no", "false"):
            return False
        return None
    if n == -1 or n == 0:
        return False
    return n > 0 or n <= -2


def _age_secs(sec) -> str:
    try:
        s = float(sec)
    except (TypeError, ValueError):
        return "never"
    if s < 3:
        return "live"
    if s < 60:
        return f"{int(s)}s ago"
    if s < 3600:
        return f"{int(s // 60)}m ago"
    return f"{int(s // 3600)}h ago"


# ══════════════════════════════════════════════════════════════════════
#  v38 — SUPPLIER: TG MANDI RESELLER API  (old market removed)
# ══════════════════════════════════════════════════════════════════════
#  Base : https://tgmandi.myvipsite.fun/api/v1   (docs: /docs.php)
#  Auth : X-Api-Key header
#  Money: the reseller wallet is in INR, prices already include the
#         reseller margin, so nothing is converted any more.
#
#  Endpoints used (all verified live on 4 Nov 2026):
#    GET  /ping                            public health
#    GET  /me | /balance                   wallet + reseller profile
#    GET  /countries                       250 countries, price + stock
#    GET  /accounts?country[]=BD&page=1     catalogue (40 per page, INR)
#         &order_by=price_to_up|price_to_down &pmin &pmax
#         &origin[]=phishing|stealer|resale|autoreg
#         &spam=yes|no &premium=yes|no &email=yes|no &password=yes|no
#    GET  /accounts/{id}                   one account (+ available flag)
#    POST /buy  {"id": "<account id>"}     buy one account
#    GET  /orders | /orders/{order_no}     order history / detail
#    GET  /orders/{order_no}/code          live login OTP (or POST)
#    GET  /sessions | /sessions/{id}       bought sessions (telethon string)
#    POST /sessions/{id}/reset|terminate   kill Telegram authorizations
#    GET  /transactions                    wallet ledger
# ══════════════════════════════════════════════════════════════════════

TGM_PAGE_SIZE = 40                      # supplier caps a page at 40
TGM_SESSION_TTL = 25                    # /sessions cache (sec)
TGM_ORDERS = ("price_to_up", "price_to_down")
# The shop kept its own sort keys (saved filters still send them). The
# reseller API can only order by price, so the date-ish keys are translated
# here and the real age ordering happens locally in sort_items_by_age().
TGM_ORDER_MAP = {
    "price_to_up": "price_to_up",
    "price_to_down": "price_to_down",
    "pdate_to_down_upload": "price_to_up",
    "pdate_to_up_upload": "price_to_up",
    "pdate_to_down": "price_to_up",
    "pdate_to_up": "price_to_up",
    "newest_first": "price_to_up",
    "oldest_first": "price_to_up",
}
TGM_ORIGIN_KEYS = ("phishing", "stealer", "resale", "personal", "autoreg",
                   "self_registration")


def _tgm_iso2(value) -> str:
    """A 2-letter country code, or "" when the value is not one."""
    v = str(value or "").strip().upper()
    return v if len(v) == 2 and v.isalpha() else ""


def _tgm_country_by_name(name) -> str:
    """Resolve a supplier country NAME to the shop's ISO-2 code."""
    n = str(name or "").strip()
    if not n:
        return ""
    try:
        for row in db_country_search(n) or []:
            if str(row["name"] or "").casefold() == n.casefold():
                return str(row["code"] or "").upper()
    except Exception:
        pass
    return ""


def _tgm_item_cc(acc) -> str:
    """Best country code of one supplier account (ISO-2)."""
    acc = acc if isinstance(acc, dict) else {}
    for key in ("flag", "iso2", "country_code"):
        got = _tgm_iso2(acc.get(key))
        if got:
            return got
    got = _tgm_country_by_name(acc.get("country_name"))
    if got:
        return got
    raw = str(acc.get("country") or "").strip().upper()
    return raw if len(raw) == 2 else ""


def _tgm_slug(text) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(text or "").lower())


def tgm_origin(acc) -> str:
    """Supplier origin -> the two shop servers.

    Live data: phishing / stealer / resale  -> Server 1 (aged, real use)
               autoreg / personal          -> Server 2 (registration only)
    """
    raw = _tgm_slug((acc or {}).get("origin")
                    or (acc or {}).get("origin_label"))
    if raw in ("autoreg", "autoregistered", "selfregistration", "personal"):
        return "autoreg" if raw != "personal" else "personal"
    if raw in ("phishing", "stealer", "resale"):
        return raw
    return "resale" if not raw else raw


def tgm_session_parts(raw):
    """Telethon session string -> (auth_key: bytes, dc_id: int).

    The supplier's string is `"1" + base64url(dc_id | ip4 | port | key)`.
    Verified live: dc 5 / 91.108.56.130 / 443 / 256-byte key.
    """
    s = str(raw or "").strip()
    if not s:
        return None, None
    body = s[1:] if s[:1] == "1" else s
    try:
        blob = base64.urlsafe_b64decode(body + "=" * (-len(body) % 4))
    except Exception:
        return None, None
    if len(blob) < 260:
        return None, None
    key, dc = blob[-256:], blob[0]
    if not key or not any(key):
        return None, None
    if dc < 1 or dc > 5:
        dc = 0
    return key, dc


def tgm_map_account(acc, extra=None) -> dict:
    """One supplier account -> the shop's internal item shape.

    Everything the rest of the bot reads (age, spam, premium, price,
    country, delivery) comes out of this one function, so a supplier
    rename only ever touches this file.
    """
    acc = acc if isinstance(acc, dict) else {}
    out: Dict[str, Any] = dict(extra or {})
    iso2 = _tgm_item_cc(acc)
    aid = str(acc.get("id") or acc.get("item_id") or "")
    price = acc.get("price")
    try:
        price = float(str(price)) if price is not None else None
    except (TypeError, ValueError):
        price = None
    spam = _tgm_slug(acc.get("spam"))
    premium = _tgm_slug(acc.get("premium"))
    out.update({
        "item_id": aid,
        "id": aid,
        "price": price,
        "price_currency": TGM_CURRENCY,
        "telegram_country": iso2,
        "country_code": iso2,
        "country_name": str(acc.get("country_name") or ""),
        "tg_flag": str(acc.get("flag") or "").lower(),
        "item_state": ("active" if acc.get("available", True) is not False
                       else "sold"),
        "item_origin": tgm_origin(acc),
        "item_origin_label": str(acc.get("origin_label") or ""),
        "canBuyItem": acc.get("available", True) is not False,
        # ── age: upload date first, session date as the fallback ──
        "published_date": acc.get("uploaded_at"),
        "uploaded_at": acc.get("uploaded_at"),
        "telegram_session_created_at": acc.get("session_created_at"),
        "last_seen": acc.get("last_seen"),
        # ── signals ──
        "telegram_spam_block": ("yes" if spam == "yes" else
                                "no" if spam == "no" else "unknown"),
        "telegram_premium": ("yes" if premium == "yes" else "no"),
        "telegram_premium_expires": acc.get("premium_expires"),
        "telegram_email": str(acc.get("email") or "no"),
        "telegram_password": str(acc.get("password") or "no"),
        "telegram_authorizations": acc.get("sessions"),
        "telegram_dc_id": acc.get("dc"),
        "telegram_api_id": acc.get("api_id"),
        "telegram_api_hash": acc.get("api_hash"),
        "chats": acc.get("chats"),
        "channels": acc.get("channels"),
        "groups": acc.get("conversations"),
        "admin_in": acc.get("admin_of"),
        "contacts": acc.get("contacts"),
        "id_digits": acc.get("id_digits"),
        "_shop_country": iso2,
    })
    return out


def tgm_map_order(order, session=None) -> dict:
    """A bought order (+ its session) -> the internal item shape used by
    the delivery screen, the .session builder and the OTP reader."""
    order = order if isinstance(order, dict) else {}
    acc = order.get("account") if isinstance(order.get("account"), dict) else {}
    item = tgm_map_account(acc)
    phone = re.sub(r"\s+", "", str(order.get("phone") or ""))
    pwd = order.get("password")
    item.update({
        "order_no": str(order.get("order_no") or ""),
        "item_id": str(order.get("order_no") or item.get("item_id") or ""),
        "price": order.get("price") if order.get("price") is not None
                 else item.get("price"),
        "telegram_country": (item.get("telegram_country")
                             or _tgm_item_cc(order)),
        "item_state": "active",
        "canBuyItem": True,
        "buy_time": order.get("created_at"),
    })
    if phone:
        item["telegram_phone"] = phone
        item["loginData"] = {"login": phone,
                             "password": str(pwd) if pwd else ""}
        item["telegram_json"] = json.dumps({"phone": phone})
    if pwd:
        item["telegram_2fa"] = str(pwd)
    if session:
        key, dc = tgm_session_parts(session.get("telethon_string"))
        item["supplier_session_id"] = session.get("id")
        item["telethon_string"] = session.get("telethon_string") or ""
        item["pyrogram_string"] = session.get("pyrogram_string") or ""
        item["telegram_dc_id"] = dc or session.get("dc_id") or item.get(
            "telegram_dc_id")
        if key:
            item["telegram_auth_key"] = base64.b64encode(key).decode()
            if isinstance(item.get("loginData"), dict):
                item["loginData"]["auth_key"] = item["telegram_auth_key"]
                item["loginData"]["dc_id"] = item["telegram_dc_id"]
        item["tg_user_id"] = session.get("tg_user_id")
        item["tg_username"] = session.get("tg_username") or ""
        item["session_status"] = session.get("status")
    return item


class Supplier:
    """TG MANDI reseller API client.

    The whole shop talks to the supplier through this class only, and the
    method names never changed when the market was swapped, so every
    screen, job and admin tool keeps working.
    """

    main_native: float = 0.0

    def __init__(self):
        self._s: Optional[aiohttp.ClientSession] = None
        self._last_cat = 0.0
        self._cat_lock = asyncio.Lock()
        self._bg_sem = asyncio.Semaphore(BG_SEARCH_CONC)
        self._last_bg = 0.0
        self.bg_interval = BG_SEARCH_GAP
        self.cat_interval = SUP_SEARCH_BASE
        self.cat_penalty_at = 0.0
        self.cat_hits = 0
        self.cur_src = "tgm"
        self.raw_me = {}
        self._refs: Dict[str, str] = {}          # account id -> order no
        self._sess_cache: Dict[str, Any] = {"at": 0.0, "rows": []}
        self.currency = TGM_CURRENCY
        self.balance: Optional[float] = None
        self.main_balance: Optional[float] = None
        self.hold: Optional[float] = 0.0
        self.balances: List[dict] = []
        self.buy_balance: Optional[float] = None
        self.buy_balance_id: Optional[int] = None
        self.balance_at: float = 0.0
        self.balance_stamp: str = ""
        self.username: str = ""
        self.user_id = None
        self.stats: Dict[str, Any] = {}
        self.last_error: str = ""
        self.last_buy_error: str = ""
        # v40: supplier health. When the catalogue endpoint dies (the live
        # API answered a plain "error code: 502" for a whole hour), the shop
        # must stop hammering it, keep serving cached pages and tell the
        # buyer "busy" instead of a raw http_502.
        self.fail_streak = 0
        self.broken_until = 0.0
        self.last_fail_at = 0.0

    # ── pacing ───────────────────────────────────────────────────────
    def note_limit(self):
        self.cat_hits += 1
        self.cat_penalty_at = time.monotonic()
        self.cat_interval = min(SUP_SEARCH_MAX,
                                max(self.cat_interval, SUP_SEARCH_BASE) * 1.8)

    def note_ok(self):
        self.note_health_ok()
        if time.monotonic() - self.cat_penalty_at < 6:
            return
        if self.cat_interval > SUP_SEARCH_BASE:
            self.cat_interval = max(SUP_SEARCH_BASE,
                                    self.cat_interval * 0.9)

    def note_fail(self, code=0):
        """Count a hard failure; 3 in a row opens the breaker."""
        now = time.monotonic()
        if now - self.last_fail_at > 45:      # a fresh outage window
            self.fail_streak = 0
        self.last_fail_at = now
        self.fail_streak += 1
        if self.fail_streak >= 3:
            self.broken_until = now + min(90.0, 12.0 * self.fail_streak)
            log.warning("supplier catalogue down (%s fails) - pausing new "
                        "calls for %.0fs", self.fail_streak,
                        max(0.0, self.broken_until - now))
        else:
            # v40: even one bad answer buys the supplier a short pause, so a
            # buyer tapping country after country cannot stampede the API
            self.broken_until = max(self.broken_until, now + 8.0)

    def note_health_ok(self):
        if self.fail_streak:
            log.info("supplier catalogue is back after %d failures",
                     self.fail_streak)
        self.fail_streak = 0
        self.broken_until = 0.0

    def busy(self) -> bool:
        """True while the breaker is open (do not call the catalogue)."""
        return time.monotonic() < self.broken_until

    def busy_left(self) -> int:
        return max(0, int(round(self.broken_until - time.monotonic())))

    @staticmethod
    def _num(v) -> Optional[float]:
        if v is None or v == "":
            return None
        try:
            return float(str(v).replace(",", "").replace(" ", ""))
        except (TypeError, ValueError):
            return None

    # ── wallet (one INR balance, no sub-wallets) ─────────────────────
    def wallet_total(self) -> float:
        return round(float(self.balance or 0.0), 4)

    def spendable(self) -> Optional[float]:
        if self.balance is None:
            return None
        return round(float(self.balance), 4)

    def can_pay(self, amount) -> bool:
        s = self.spendable()
        try:
            need = float(amount or 0)
        except (TypeError, ValueError):
            return True
        return s is None or s >= need

    def _is_buy_wallet(self, w: dict) -> bool:
        return True

    def balance_plan(self, price, balance_id="auto") -> List[Optional[int]]:
        return [balance_id if isinstance(balance_id, int) else None]

    def balance_line(self) -> str:
        if self.balance is None:
            return "not loaded"
        return f"₹{float(self.balance):,.2f} (reseller wallet)"

    async def balance_now(self, force: bool = False) -> dict:
        fresh = (self.balance is not None
                 and (time.monotonic() - self.balance_at) < SUP_BALANCE_TTL)
        if fresh and not force:
            return {"ok": True, "balance": self.balance, "cached": True,
                    "currency": self.currency, "username": self.username,
                    "main_balance": self.main_balance,
                    "buy_balance": self.buy_balance,
                    "buy_balance_id": self.buy_balance_id,
                    "balances": self.balances, "hold": self.hold,
                    "stamp": self.balance_stamp}
        m = await self.me()
        m["cached"] = False
        return m

    def balance_age(self) -> str:
        if not self.balance_at:
            return "never"
        return _age_secs(time.monotonic() - self.balance_at)

    # ── transport ────────────────────────────────────────────────────
    async def _ses(self):
        if not self._s or self._s.closed:
            conn = aiohttp.TCPConnector(limit=48, limit_per_host=24,
                                        ttl_dns_cache=600,
                                        keepalive_timeout=60,
                                        enable_cleanup_closed=True)
            self._s = aiohttp.ClientSession(
                timeout=aiohttp.ClientTimeout(total=120, connect=12,
                                              sock_read=90),
                connector=conn,
                headers={"X-Api-Key": TGM_API_KEY,
                         "Accept": "application/json",
                         "User-Agent": "TGIDStore/39"})
        return self._s

    async def close(self):
        if self._s and not self._s.closed:
            await self._s.close()

    async def _req(self, method, path, cat_search=False, **kw):
        """One API call -> {"st", "d", "err", "headers"}.

        `st` 0 = network/timeout. The supplier answers `{"ok": bool,
        "data": ..., "error": {"code", "message"}}`, so `d` is the whole
        json body and callers read `d["data"]` / `d["error"]`.
        """
        if cat_search:
            _bg_req = _BG.get()
            if _bg_req:
                while _FG_WAIT["n"] > 0:
                    await asyncio.sleep(0.05)
                async with self._bg_sem:
                    gap = max(0.0, self.bg_interval -
                              (time.monotonic() - self._last_bg))
                    if gap:
                        await asyncio.sleep(gap)
                    self._last_bg = time.monotonic()
                    return await self._req_now(method, path, **kw)
            async with self._cat_lock:
                gap = max(0.0, self.cat_interval -
                          (time.monotonic() - self._last_cat))
                if gap:
                    await asyncio.sleep(gap)
                self._last_cat = time.monotonic()
                return await self._req_now(method, path, **kw)
        return await self._req_now(method, path, **kw)

    async def _req_now(self, method, path, **kw):
        url = path if str(path).startswith("http") else f"{TGM_BASE_URL}{path}"
        try:
            s = await self._ses()
            async with s.request(method.upper(), url, **kw) as r:
                txt = await r.text()
                try:
                    d = json.loads(txt) if txt else {}
                except (ValueError, TypeError):
                    d = {"ok": False, "error": {"code": "bad_json",
                                                "message": txt[:200]}}
                return {"st": r.status, "d": d, "err": None,
                        "headers": dict(r.headers)}
        except asyncio.TimeoutError:
            self.last_error = "timeout"
            return {"st": 0, "d": {}, "err": "timeout", "headers": {}}
        except aiohttp.ClientError as e:
            self.last_error = str(e)[:120]
            return {"st": 0, "d": {}, "err": str(e)[:120], "headers": {}}
        except Exception as e:                                  # noqa: BLE001
            self.last_error = f"{type(e).__name__}: {e}"[:120]
            return {"st": 0, "d": {}, "err": self.last_error, "headers": {}}

    @staticmethod
    def api_error(d) -> tuple:
        """(code, message) from the supplier's error envelope."""
        d = d if isinstance(d, dict) else {}
        err = d.get("error")
        if isinstance(err, dict):
            return str(err.get("code") or ""), str(err.get("message") or "")
        if isinstance(err, str):
            return err, str(d.get("message") or "")
        return "", str(d.get("message") or "")

    @classmethod
    def _err_text(cls, d) -> str:
        code, msg = cls.api_error(d)
        return re.sub(r"\s+", " ", f"{code} {msg}".strip())[:300]

    # ── wallet / profile ─────────────────────────────────────────────
    async def me(self):
        self.cur_src = "api"
        r = await self._req("GET", "/me")
        st, d = r["st"], r.get("d") or {}
        if st == 401:
            self.last_error = "auth"
            self.cur_src = "api"
            return {"ok": False, "err": "auth",
                    "error": self._err_text(d) or "API key rejected",
                    "balance": self.balance, "currency": self.currency,
                    "native": self.balance, "inr": self.balance,
                    "usd": sup_usd(self.balance, self.currency),
                    "currency_src": "api",
                    "balances": self.balances,
                    "detail": self._err_text(d) or "API key rejected"}
        if st != 200 or not isinstance(d, dict) or d.get("ok") is False:
            self.last_error = f"http_{st}"
            return {"ok": False, "err": self.last_error,
                    "error": self._err_text(d) or f"HTTP {st}",
                    "detail": self._err_text(d),
                    "balance": self.balance, "currency": self.currency,
                    "native": self.balance, "inr": self.balance,
                    "usd": sup_usd(self.balance, self.currency),
                    "currency_src": "api",
                    "balances": self.balances}
        data = d.get("data") or {}
        user = data.get("user") or {}
        stats = data.get("stats") or {}
        bal = self._num(user.get("balance"))
        if bal is None:
            bal = self._num(stats.get("balance"))
        self.raw_me = data
        self.stats = stats if isinstance(stats, dict) else {}
        self.balance = bal
        self.main_balance = bal
        self.buy_balance = bal
        self.buy_balance_id = None
        self.balances = ([{"id": None, "title": "Reseller wallet",
                           "amount": bal, "native": bal, "converted": bal}]
                         if bal is not None else [])
        self.hold = 0.0
        self.balance_at = time.monotonic()
        self.balance_stamp = time.strftime("%d %b %H:%M:%S")
        self.username = str(user.get("username") or user.get("name") or "")
        self.user_id = user.get("id")
        self.currency = TGM_CURRENCY
        # v38: one INR reseller wallet, so "native" and "converted" are
        # the same number - the admin screens still get every key they read.
        return {"ok": bal is not None, "balance": bal, "err": None,
                "error": "" if bal is not None else "no balance in the reply",
                "currency": self.currency, "currency_src": "api",
                "username": self.username, "user_id": self.user_id,
                "main_balance": bal, "buy_balance": bal,
                "buy_balance_id": None, "balances": self.balances,
                "native": bal, "converted": bal,
                "inr": bal, "usd": sup_usd(bal, self.currency),
                "hold": 0.0, "stamp": self.balance_stamp,
                "role": user.get("role"), "name": user.get("name"),
                "tg_username": user.get("tg_username"),
                "telegram_id": user.get("telegram_id"),
                "member_since": user.get("member_since"),
                "total_deposit": self.stats.get("total_deposit"),
                "total_spent": self.stats.get("total_spent"),
                "total_orders": self.stats.get("total_orders"),
                "stats": self.stats, "raw": data}

    async def test(self):
        r = await self._req("GET", "/ping")
        ping = bool(r["st"] == 200 and (r.get("d") or {}).get("ok"))
        m = await self.me()
        return {"ping": ping, "me": m, "version":
                ((r.get("d") or {}).get("data") or {}).get("version")}

    async def transactions(self, limit=20):
        r = await self._req("GET", "/transactions")
        d = r.get("d") or {}
        rows = ((d.get("data") or {}).get("transactions") or [])
        return {"ok": r["st"] == 200, "rows": rows[:int(limit or 20)],
                "err": None if r["st"] == 200 else self._err_text(d)}

    async def countries(self):
        r = await self._req("GET", "/countries", cat_search=True)
        d = r.get("d") or {}
        rows = ((d.get("data") or {}).get("countries") or [])
        out = []
        for c in rows:
            if not isinstance(c, dict):
                continue
            out.append({"code": (_tgm_iso2(c.get("iso2"))
                                 or _tgm_country_by_name(c.get("name"))),
                        "iso3": str(c.get("code") or "").upper(),
                        "name": str(c.get("name") or ""),
                        "dial": str(c.get("dial") or ""),
                        "price": self._num(c.get("price")),
                        "stock": str(c.get("stock") or "")})
        return {"ok": r["st"] == 200 and bool(out), "countries": out,
                "err": None if r["st"] == 200 else self._err_text(d)}

    # ── catalogue ────────────────────────────────────────────────────
    async def api_search(self, cc, origins=None, page=1, currency=None,
                         order_by="price_to_up", nsb=False, spam=None,
                         premium=None, password=None, email=None, title=None,
                         pmin=None, pmax=None, after=None, not_cc=None,
                         session_age_days=None):
        """One catalogue page, mapped to the shop's item shape.

        The supplier pages with `page` (40 rows) and reports `total` +
        `has_more`, so a page number is all we need. `after` (old cursor
        name) is accepted and ignored, and `session_age_days` is applied by
        the caller on the upload date, because this API filters price,
        origin and signals only.
        """
        params: Dict[str, str] = {"limit": str(TGM_PAGE_SIZE)}
        cc_l = str(cc or "").strip().upper()
        if cc_l and cc_l not in ("ALL", "ANY"):
            params["country[]"] = _tgm_iso2(cc_l) or cc_l[:2]
        ob = str(order_by or "price_to_up")
        params["order_by"] = TGM_ORDER_MAP.get(ob, "price_to_up")
        if page and int(page) > 1:
            params["page"] = str(int(page))
        for key, val in (("spam", spam), ("premium", premium),
                         ("password", password), ("email", email)):
            if val and str(val).lower() in ("yes", "no"):
                params[key] = str(val).lower()
        num_pmin = self._num(pmin)
        if num_pmin and num_pmin > 0:
            params["pmin"] = str(int(num_pmin)) if num_pmin >= 1 else str(
                num_pmin)
        num_pmax = self._num(pmax)
        if num_pmax and num_pmax > 0:
            params["pmax"] = str(int(num_pmax)) if num_pmax >= 1 else str(
                num_pmax)
        qp = [f"{_urlquote(k, safe='[]')}={_urlquote(str(v))}"
              for k, v in params.items()]
        for o in norm_origins(origins or []):
            if o in TGM_ORIGIN_KEYS:
                qp.append(f"origin%5B%5D={_urlquote(o)}")
        url = f"/accounts?{'&'.join(qp)}"
        if self.busy():
            # breaker open: answer instantly from what we already know
            self.last_error = "search busy"
            return {"items": [], "total": 0, "err": "busy", "raw": {},
                    "next": None, "has_next": False, "cursor_api": True,
                    "busy_left": self.busy_left()}
        r, st, d = {}, 0, {}
        for attempt in range(2):
            r = await self._req("GET", url, cat_search=True)
            st, d = r["st"], (r.get("d") or {})
            if st == 200 and d.get("ok") is not False:
                break
            # 5xx / no answer / rate limited: one quick retry can land on a
            # healthy backend node, so the buyer sees a page, not E-101
            if st in (0, 429, 500, 502, 503, 504) and attempt < 1:
                await asyncio.sleep(0.6)
                continue
            break
        if st != 200 or d.get("ok") is False:
            if st in (0, 500, 502, 503, 504):
                self.note_fail(st)
                err = "busy"
            elif st == 429:
                self.note_limit()
                self.note_fail(st)
                err = "rate"
            elif st == 401:
                err = "auth"
            else:
                err = (self._err_text(d) or f"http_{st}")[:120]
            self.last_error = f"search {err}"
            return {"items": [], "total": 0, "err": err, "raw": d,
                    "next": None, "has_next": False, "cursor_api": True,
                    "http": st, "busy_left": self.busy_left()}
        self.note_ok()
        data = d.get("data") or {}
        raw_items = data.get("items") or []
        if not isinstance(raw_items, list):
            raw_items = []
        items = [tgm_map_account(it) for it in raw_items
                 if isinstance(it, dict)]
        # client-side guards the supplier cannot do for us
        skip_cc = {c for c in (_tgm_iso2(x) for x in (not_cc or [])) if c}
        if skip_cc:
            items = [i for i in items if i.get("telegram_country")
                     not in skip_cc]
        if title:
            needle = _tgm_slug(title)
            if needle:
                hit = [i for i in items
                       if needle in _tgm_slug(i.get("item_id"))
                       or needle in _tgm_slug(i.get("country_name"))]
                items = hit                       # keyword = id / country
        try:
            total = int(data.get("total") or 0)
        except (TypeError, ValueError):
            total = 0
        has_next = bool(data.get("has_more"))
        nxt = data.get("next")
        return {"items": items, "total": total, "err": None, "raw": data,
                "next": nxt, "has_next": has_next, "cursor_api": True,
                "page": int(page or 1)}

    async def search(self, cc, origins=None, page=1, nsb=False, spam_no=True,
                     currency=None, pmin=None, pmax=None):
        return await self.api_search(cc, origins, page=page, currency=currency,
                                     nsb=nsb,
                                     spam=("no" if spam_no else None),
                                     pmin=pmin, pmax=pmax)

    def valid(self, item, cc, allowed=None, spam="no",
              strict_country=True) -> bool:
        try:
            st = str(item.get("item_state", "active")).lower()
            if st not in ("active", ""):
                return False
            price = item.get("price")
            if price is None or float(str(price)) <= 0:
                return False
            og = norm_origin(item.get("item_origin"))
            if allowed and og not in allowed:
                return False
            is_spam = telegram_spam_state(item) is True
            mode = str(spam or "nomatter").lower()
            if mode == "no" and is_spam:
                return False
            if mode == "yes" and not is_spam:
                return False
            if strict_country and not item_country_matches(item, cc):
                return False
            if item.get("canBuyItem") is False:
                return False
            return True
        except Exception:
            return False

    async def find_candidates(self, cc, origins=None, limit=MAX_CANDIDATES,
                              spam="nomatter"):
        allowed = norm_origins(origins or SERVER1_ORIGINS)
        tried = []

        async def scan(origins, tag, spam_mode):
            found = []
            for page in range(1, PAGES_TO_SCAN + 1):
                r = await self.api_search(cc, origins, page=page,
                                          spam=spam_mode)
                tried.append({"strategy": tag, "page": page,
                              "total": r["total"], "fetched": len(r["items"]),
                              "err": r["err"]})
                if r["err"] or not r["items"]:
                    break
                for it in r["items"]:
                    if self.valid(it, cc, allowed, spam_mode):
                        found.append(it)
                if len(found) >= limit:
                    break
                if not r.get("has_next"):
                    break
            return found

        for spam_mode, tag in ((spam, "server-origins"),
                               ("nomatter", "server-origins-any-spam")):
            found = await scan(allowed, tag, spam_mode)
            if found:
                found.sort(key=lambda x: float(str(x.get("price", 999) or 999)))
                return found[:limit], tag, tried
        return [], "none", tried

    # ── buying ───────────────────────────────────────────────────────
    def _set_ref(self, account_id, order_no) -> None:
        account_id, order_no = str(account_id or ""), str(order_no or "")
        if account_id and order_no:
            self._refs[account_id] = order_no
            try:
                db_supplier_ref_set(account_id, order_no)
            except Exception as e:                              # noqa: BLE001
                log.debug("ref save %s: %s", account_id, e)

    def order_ref(self, iid) -> str:
        """Account id -> order number (needed for OTP + session control)."""
        ref = str(iid or "").strip()
        if not ref:
            return ""
        if ref.upper().startswith("TGM"):
            return ref
        if ref in self._refs:
            return self._refs[ref]
        try:
            got = db_supplier_ref_get(ref)
        except Exception:
            got = ""
        if got:
            self._refs[ref] = got
            return got
        return ref

    async def buy(self, iid, price, balance_id="auto", max_cost=None):
        """Buy exactly one account. Returns the shop's buy envelope."""
        iid = str(iid or "").strip()
        if not iid:
            return {"ok": False, "d": {}, "err": "bad_req", "unk": False,
                    "detail": "no account id"}
        live = await self.item(iid)
        live_price = self._num((live.get("item") or {}).get("price"))
        if live.get("ok") and not (live.get("item") or {}).get("canBuyItem",
                                                              True):
            return {"ok": False, "d": live.get("item") or {}, "err": "sold",
                    "unk": False, "detail": "This account is no longer available."}
        if live_price is not None and max_cost is not None:
            try:
                if float(live_price) > float(max_cost) + 0.01:
                    return {"ok": False,
                            "d": live.get("item") or {},
                            "err": "price_changed", "unk": False,
                            "detail": f"price is now ₹{live_price:.2f} "
                                      f"(cap ₹{float(max_cost):.2f})"}
            except (TypeError, ValueError):
                pass
        if self.balance is None or (
                time.monotonic() - self.balance_at) > max(SUP_BALANCE_TTL, 30):
            await self.me()
        r = await self._req("POST", "/buy", json={"id": iid})
        st, d = r["st"], (r.get("d") or {})
        code, msg = self.api_error(d)
        low = f"{code} {msg}".lower()
        if st == 200 and d.get("ok") is not False:
            data = d.get("data") or {}
            order = data.get("order") or {}
            order_no = str(order.get("order_no") or "")
            session = await self.session_for(order_no, order.get("phone"))
            item = tgm_map_order(order, session)
            self._set_ref(iid, order_no)
            self.last_buy_error = ""
            bal = self._num((data.get("balance")))
            if bal is not None:
                self.balance = bal
                self.main_balance = bal
                self.balance_at = time.monotonic()
            return {"ok": True, "d": {"item": item, "order": order},
                    "err": None, "unk": False, "detail": "",
                    "order_no": order_no, "balance_id": balance_id}
        self.last_buy_error = (self._err_text(d) or f"HTTP {st}")[:180]
        if st == 0:
            return {"ok": False, "d": d, "err": "timeout", "unk": True,
                    "detail": self.last_buy_error}
        if st == 401:
            return {"ok": False, "d": d, "err": "auth", "unk": False,
                    "detail": self.last_buy_error}
        if st == 429:
            self.note_limit()
            return {"ok": False, "d": d, "err": "check_limit", "unk": False,
                    "detail": self.last_buy_error}
        if any(w in low for w in ("balance", "insufficient", "fund",
                                  "wallet", "credit")):
            return {"ok": False, "d": d, "err": "low_bal", "unk": False,
                    "detail": msg or "reseller wallet is too low"}
        if st == 404 or code in ("not_found", "unavailable", "sold"):
            mark_bad_item(iid)
            return {"ok": False, "d": d, "err": "sold", "unk": False,
                    "detail": msg or "account is no longer available"}
        if code in ("invalid_id", "bad_request", "validation"):
            return {"ok": False, "d": d, "err": "bad_req", "unk": False,
                    "detail": msg or "supplier rejected the request"}
        return {"ok": False, "d": d, "err": f"http_{st}", "unk": False,
                "detail": self.last_buy_error}

    async def check_account(self, iid):
        """Free availability check before the purchase."""
        iid = str(iid or "").strip()
        if not iid:
            return {"ok": False, "err": "unbuyable", "detail": "no id"}
        r = await self._req("GET", f"/accounts/{_urlquote(iid)}")
        st, d = r["st"], (r.get("d") or {})
        if st == 200 and d.get("ok") is not False:
            acc = (d.get("data") or {}).get("account") or {}
            if acc.get("available", True) is False:
                mark_bad_item(iid)
                return {"ok": False, "err": "unbuyable",
                        "detail": "account is not available", "d": d}
            return {"ok": True, "err": None, "d": d,
                    "item": tgm_map_account(acc)}
        et = self._err_text(d)
        if st in (403, 404, 410) or "not found" in et.lower():
            mark_bad_item(iid)
            return {"ok": False, "err": "unbuyable", "detail": et}
        if st == 429:
            self.note_limit()            # slow the whole lane down too
            return {"ok": False, "err": "check_limit", "detail": et}
        return {"ok": False, "err": "check_failed", "detail": et or f"HTTP {st}"}

    async def item(self, iid):
        """One account, live. v40: the failure reason is reported, so the
        screen can tell "sold" (410/404) from "supplier is down" (5xx)."""
        iid = str(iid or "").strip()
        if not iid:
            return {"ok": False, "item": {}, "err": "bad_id"}
        if self.busy():
            return {"ok": False, "item": {}, "err": "busy",
                    "busy_left": self.busy_left()}
        r = await self._req("GET", f"/accounts/{_urlquote(iid)}")
        st, d = r["st"], (r.get("d") or {})
        if st == 200 and d.get("ok") is not False:
            acc = (d.get("data") or {}).get("account")
            if isinstance(acc, dict) and acc:
                self.note_ok()
                return {"ok": True, "item": tgm_map_account(acc)}
            return {"ok": False, "item": {}, "err": "gone"}
        if st == 429:
            self.note_limit()
            self.note_fail(st)
            return {"ok": False, "item": {}, "err": "rate"}
        if st in (0, 500, 502, 503, 504):
            self.note_fail(st)
            return {"ok": False, "item": {}, "err": "busy",
                    "busy_left": self.busy_left()}
        if st in (404, 410):
            return {"ok": False, "item": {}, "err": "gone"}
        return {"ok": False, "item": {}, "err": f"http_{st}"}

    async def item_bulk(self, iid):
        return await self.item(iid)

    async def item_via_code(self, iid):
        return await self.item(iid)

    @staticmethod
    def parse_login_data(item: dict) -> dict:
        out = {"phone": "", "password": "", "email": "",
               "email_password": "", "link": "", "links": [], "two_fa": ""}
        item = item if isinstance(item, dict) else {}
        ld = item.get("loginData") or item.get("login_data") or {}
        if isinstance(ld, str):
            try:
                ld = json.loads(ld)
            except Exception:
                ld = {"login": ld}
        if isinstance(ld, dict):
            _login = str(ld.get("login") or ld.get("phone") or "")
            if not _looks_like_auth_key(_login):
                out["password"] = str(ld.get("password") or "")
            out["email"] = str(ld.get("email") or "")
            out["email_password"] = str(ld.get("emailPassword")
                                        or ld.get("email_password") or "")
        out["phone"] = _find_phone(item)
        out["two_fa"] = (str(item.get("telegram_2fa") or "")
                         or ("yes" if item.get("telegram_password") == "yes"
                             else ""))
        link = str(item.get("account_link") or "")
        out["links"] = [link] if link else []
        out["link"] = link
        return out

    # ── orders / OTP / sessions ──────────────────────────────────────
    async def order(self, ref):
        ref = self.order_ref(ref)
        if not ref:
            return {"ok": False, "order": {}, "err": "no_ref"}
        r = await self._req("GET", f"/orders/{_urlquote(ref)}")
        d = r.get("d") or {}
        if r["st"] == 200 and d.get("ok") is not False:
            return {"ok": True,
                    "order": (d.get("data") or {}).get("order") or {},
                    "err": None}
        return {"ok": False, "order": {}, "err": self._err_text(d)}

    async def orders(self, limit=20):
        r = await self._req("GET", "/orders")
        d = r.get("d") or {}
        rows = ((d.get("data") or {}).get("orders") or [])
        return {"ok": r["st"] == 200, "rows": rows[:int(limit or 20)],
                "err": None if r["st"] == 200 else self._err_text(d)}

    async def sessions(self, force=False):
        """All bought sessions (telethon strings) - cached for 25 s."""
        now = time.monotonic()
        if (not force and self._sess_cache["rows"]
                and now - float(self._sess_cache["at"] or 0) < TGM_SESSION_TTL):
            return self._sess_cache["rows"]
        r = await self._req("GET", "/sessions")
        d = r.get("d") or {}
        rows = ((d.get("data") or {}).get("sessions") or [])
        if r["st"] == 200 and isinstance(rows, list):
            self._sess_cache = {"at": now, "rows": rows}
            return rows
        return self._sess_cache["rows"] or []

    @staticmethod
    def _sess_matches(row, order_no, phone="") -> bool:
        if not isinstance(row, dict):
            return False
        label = str(row.get("label") or "")
        if order_no and label.upper().endswith("#" + str(order_no).upper()):
            return True
        if phone:
            a = re.sub(r"\D", "", str(row.get("phone") or ""))
            b = re.sub(r"\D", "", str(phone))
            if a and b and a == b:
                return True
        return False

    async def session_for(self, order_no, phone=""):
        """The session row of one order (label ends with `#ORDER_NO`)."""
        order_no = str(order_no or "")
        if not order_no and not phone:
            return None
        for rows in (await self.sessions(), await self.sessions(force=True)):
            for row in rows:
                if self._sess_matches(row, order_no, phone):
                    return row
            if not order_no and not phone:
                break
        return None

    async def login_code(self, iid):
        """Live OTP of a bought account."""
        ref = self.order_ref(iid)
        if not ref:
            return {"ok": False, "codes": [], "err": "no_item"}
        r = await self._req("GET", f"/orders/{_urlquote(ref)}/code")
        st, d = r["st"], (r.get("d") or {})
        if st == 200 and d.get("ok") is not False:
            data = d.get("data") or {}
            code = str(data.get("code") or "").strip()
            if code:
                return {"ok": True, "codes": [code],
                        "at": data.get("date")}
            return {"ok": True, "codes": [], "err": "empty"}
        if st == 429:
            hdrs = r.get("headers") or {}
            reset = hdrs.get("X-RateLimit-Reset") or hdrs.get(
                "x-ratelimit-reset")
            try:
                wait = max(1, int(float(reset)) - int(time.time()))
            except (TypeError, ValueError):
                wait = 30
            return {"ok": False, "codes": [], "err": "rate_limit",
                    "retry_after": min(wait, 60)}
        if st == 404:
            return {"ok": True, "codes": [], "err": "empty"}
        et = self._err_text(d)
        low = et.lower()
        # a refunded / not-yet-active order cannot deliver an OTP - that is
        # a normal state, not a supplier failure
        if st == 409 or "not_active" in low or "not active" in low:
            return {"ok": True, "codes": [], "err": "not_active",
                    "detail": et}
        return {"ok": False, "codes": [], "err": f"http_{st} {et}".strip()}

    async def _session_action(self, iid, action, verb):
        ref = self.order_ref(iid)
        if not ref:
            return {"ok": False, "status": 0,
                    "detail": "No account was linked to this order."}
        row = await self.session_for(ref)
        sid = (row or {}).get("id")
        if not sid:
            return {"ok": False, "status": 0,
                    "detail": "No live session found for this order."}
        r = await self._req("POST", f"/sessions/{sid}/{action}", json={})
        d = r.get("d") or {}
        ok = r["st"] == 200 and d.get("ok") is not False
        self._sess_cache = {"at": 0.0, "rows": []}
        return {"ok": ok, "status": r["st"],
                "detail": "" if ok else (self._err_text(d) or f"HTTP {r['st']}"),
                "verb": verb, "session_id": sid}

    async def reset_auth(self, iid):
        return await self._session_action(iid, "reset", "reset")

    async def terminate_all(self, iid):
        return await self._session_action(iid, "terminate", "terminate")

    async def stock_check(self, cc, origins=None, progress=None):
        origins = origins or norm_origins(ALLOWED_ORIGINS)
        out, total_all = {}, 0
        for og in origins:
            r = await self.search(cc, [og], page=1, nsb=False)
            out[og] = r["total"] if not r["err"] else f"err:{r['err']}"
            if isinstance(out[og], int):
                total_all += out[og]
            if progress:
                await progress(og, out[og])
        r = await self.search(cc, None, page=1, nsb=False)
        return {"origins": out, "total": total_all, "all": r["total"],
                "err": r["err"]}


