# ── Typography (v11) ────────────────────────────────────────────────
# Telegram cannot change fonts, so the premium look is built from
# Unicode small-caps for headings and sans-bold for the brand only.
# Body text stays in the normal font so it is easy to read.
_SC_MAP = str.maketrans(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ",
    "ᴀʙᴄᴅᴇꜰɢʜɪᴊᴋʟᴍɴᴏᴘǫʀꜱᴛᴜᴠᴡxʏᴢᴀʙᴄᴅᴇꜰɢʜɪᴊᴋʟᴍɴᴏᴘǫʀꜱᴛᴜᴠᴡxʏᴢ")
_TAG_SPLIT_RE = re.compile(r"(<[^>]+>|&[#a-zA-Z0-9]+;)")


def _map_plain(text, fn) -> str:
    parts = _TAG_SPLIT_RE.split(str(text or ""))
    return "".join(p if (p.startswith("<") or p.startswith("&")) else fn(p)
                   for p in parts)


def sc(text) -> str:
    """Heading case (HTML-safe): plain UPPERCASE for a corporate look."""
    return _map_plain(text, lambda p: p.upper())



def _bs_char(ch):
    o = ord(ch)
    if 65 <= o <= 90:
        return chr(0x1D5D4 + o - 65)
    if 97 <= o <= 122:
        return chr(0x1D5EE + o - 97)
    if 48 <= o <= 57:
        return chr(0x1D7EC + o - 48)
    return ch


def bs(text) -> str:
    """Brand text - plain characters (no decorative Unicode fonts)."""
    return str(text or "")



