def title_emoji(title) -> str:
    """Emoji for a screen title (empty = none)."""
    low = str(title or "").strip().lower()
    if not low:
        return ""
    for needles, glyph in TITLE_EMOJI_RULES:
        for n in needles:
            if n in low:
                return glyph
    return ""


def head(title, icon="", sub=None) -> str:
    """Screen heading: BOLD UPPERCASE title, optional italic subtitle and a
    rule. `icon` (v32) - when given that emoji is used, otherwise one is
    picked from the title."""
    ttl = str(title)
    glyph = str(icon or "").strip() or title_emoji(ttl)
    if glyph:
        ttl = "%s %s" % (glyph, ttl)
    h = f"<b>{_map_plain(ttl, lambda p: p.upper())}</b>"
    if sub:
        h += f"\n<i>{sub}</i>"
    return h + "\n" + HLINE



def pbar(done, total, width=10) -> str:
    total = max(1, int(total or 1))
    done = max(0, min(int(done or 0), total))
    fill = int(round(width * done / total))
    return "\u2588" * fill + "\u2591" * (width - fill)



BRAND = f"<b>{html.escape(SHOP_NAME.upper())} \u2014 ACCOUNT STORE</b>"
BRAND_SUB = BRAND

STATUS_BADGE = {
    "created": "Created", "paid": "Paid", "sourcing": "Sourcing",
    "purchased": "Purchased", "delivered": "Delivered", "failed": "Failed",
    "review-pending": "Under Review", "replacement": "Replacement",
    "pending": "Pending", "approved": "Approved", "rejected": "Rejected",
    "timeout": "Timed Out", "expired": "Expired", "cancelled": "Cancelled",
}

_BLANK_RE = re.compile(r"\n{3,}")
_SPACE_RE = re.compile(r"[ \t]{2,}")


_HEAD_RE = re.compile(
    r"^(?P<pre>[^<\w]{0,8})<b>(?P<t>[A-Z][A-Z0-9 &/#\-—·:'().,+%!?]{2,60})</b>")


def _style_heading_line(line: str) -> str:
    m = _HEAD_RE.match(line)
    if not m:
        return line
    t = m.group("t")
    if sum(ch.isalpha() for ch in t) < 2 or t != t.upper():
        return line
    return (line[:m.start("t")] + sc(t) + line[m.end("t"):])


_PRE_SPLIT_RE = re.compile(r"(<pre>.*?</pre>)", re.S)


# ── v13 corporate typography ─────────────────────────────────────────
# No emojis anywhere in text. Headers are BOLD UPPERCASE, details sit in
# blockquotes, numbers / prices / IDs are monospace. Country flags are only
# allowed on country buttons (see btn_clean).
_TXT_EMOJI_RE = re.compile(
    "[\U0001F000-\U0001FAFF\u2600-\u27BF\u2B00-\u2BFF\u2300-\u23FF"
    "\u2190-\u21FF\u25A0-\u25FF\uFE0E\uFE0F\u200D\u20E3\u2139\u3030"
    "\u303D\u3297\u3299\u203C\u2049\u2934\u2935\U000E0020-\U000E007F]")
_TXT_SYMBOL_MAP = str.maketrans({
    "\u279c": "\u203a", "\u2192": "\u203a", "\u27a1": "\u203a",
    "\u21d2": "\u203a", "\u25b8": "\u2022", "\u25aa": "\u2022",
    "\u25c6": "\u2022", "\u2726": "", "\u00b7": "\u2022"})
_POLISH_SPLIT_RE = re.compile(r"(<pre>.*?</pre>|<code>.*?</code>|<[^>]+>)", re.S)
_TAG_NAME_RE = re.compile(r"<(/?)([a-zA-Z][\w-]*)")
_NUM_FULL_RE = re.compile(r"^\s*-?\u20b9?\s?-?\d[\d,]*(?:\.\d+)?\s?%?\s*$")
_RUPEE_RE = re.compile(r"(?<![\w>])(-?\u20b9\s?-?\d[\d,]*(?:\.\d+)?)")
_INLINE_TAGS = {"b", "strong", "i", "em", "u", "ins", "s", "strike", "del",
                "a", "tg-spoiler", "span"}
_KEYCAP_RE = re.compile("(\\d)\ufe0f?\u20e3")
_OPEN_SPACE_RE = re.compile(
    r"(<(?:blockquote(?: expandable)?|b|i|u|s|tg-spoiler|span"
    r"(?: class=\"tg-spoiler\")?)>)[ \t]+")
_RAW_TEXT = contextvars.ContextVar("raw_text", default=False)


def strip_emoji(text) -> str:
    """Plain-text emoji removal (alerts, captions, toasts)."""
    if not isinstance(text, str):
        return text
    t = _TXT_EMOJI_RE.sub("", text.translate(_TXT_SYMBOL_MAP))
    return re.sub(r"[ \t]{2,}", " ", t).strip()


def polish_text(t):
    """Final pass on every outgoing HTML message.

    * removes emojis / pictographs outside <code> and <pre>
      (credentials and IDs are never modified)
    * <b>₹12.00</b> / <b>42</b> -> <code>…</code>, bare ₹ amounts -> <code>
      (only where nesting is legal: not inside b/i/u/s/a)
    * tidies whitespace left behind by removed symbols
    Idempotent - safe to run more than once."""
    if not isinstance(t, str) or not t or _RAW_TEXT.get():
        return t
    t = _KEYCAP_RE.sub(r"\1.", t)
    toks = [p for p in _POLISH_SPLIT_RE.split(t) if p]
    out, depth, i = [], 0, 0
    while i < len(toks):
        p = toks[i]
        if p.startswith(("<pre>", "<code>")):
            out.append(p)
        elif p.startswith("<"):
            if (p == "<b>" and depth == 0 and i + 2 < len(toks)
                    and toks[i + 2] == "</b>" and not toks[i + 1].startswith("<")
                    and _NUM_FULL_RE.match(toks[i + 1])):
                out.append(f"<code>{toks[i + 1].strip()}</code>")
                i += 3
                continue
            m = _TAG_NAME_RE.match(p)
            if m and m.group(2).lower() in _INLINE_TAGS:
                depth = max(0, depth + (-1 if m.group(1) else 1))
            out.append(p)
        else:
            # v32: emoji hatae nahi jaate - premium emoji ke roop me
            # messages me dikhte hain (pehle "emoji-free" theme thi)
            p = p.translate(_TXT_SYMBOL_MAP)
            if depth == 0:
                p = _RUPEE_RE.sub(r"<code>\1</code>", p)
            out.append(p)
        i += 1
    res = []
    for j, part in enumerate(_PRE_SPLIT_RE.split("".join(out))):
        if j % 2:
            res.append(part)
            continue
        lines = [re.sub(r"[ \t]{2,}", " ", ln).strip(" \t")
                 for ln in part.split("\n")]
        res.append("\n".join(lines))
    t = re.sub(r"\n{3,}", "\n\n", "".join(res))
    t = re.sub(r"<(b|i|u|s)>\s*</\1>", "", t)
    t = _OPEN_SPACE_RE.sub(r"\1", t)
    return t.strip("\n")


def clean_text(t) -> str:
    if not isinstance(t, str):
        return t
    out = []
    for i, part in enumerate(_PRE_SPLIT_RE.split(t)):
        if i % 2:
            out.append(part)
            continue
        lines = []
        for line in part.split("\n"):
            line = line.strip(" \t")
            line = _SPACE_RE.sub(" ", line)
            lines.append(_style_heading_line(line))
        out.append("\n".join(lines))
    return premiumize(
        polish_text(_BLANK_RE.sub("\n\n", "".join(out)).strip("\n")))





def esc(t) -> str:
    return html.escape(str(t if t is not None else ""))


def money(v) -> str:
    return f"₹{float(v or 0):,.2f}"


def flag_emoji(code: str) -> str:
    code = str(code or "").strip().upper()
    if len(code) != 2 or not code.isalpha():
        return f"{ICON['dot']}"
    return "".join(chr(0x1F1E6 + ord(ch) - 65) for ch in code)


def dial_code(code: str) -> str:
    return DIAL_CODES.get(str(code or "").strip().upper(), "")


def ctag(code: str) -> str:
    cc = str(code or "").strip().upper()
    d = dial_code(cc)
    return f"{cc}+{d}" if d else cc


def btn_label(code: str, price=None, age=None) -> str:
    """Account button: "{flag} BR+55 | ₹14.00 · 42d" (v29: age added)."""
    cc = str(code or "").strip().upper()
    flag = flag_emoji(cc) + " " if len(cc) == 2 and cc.isalpha() else ""
    base = f"{flag}{ctag(cc)}"
    if price is None:
        return base
    try:
        p = float(price)
    except (TypeError, ValueError):
        p = 0.0
    label = f"{base} | \u20b9{p:.2f}"
    if age:
        label += f" · {age}"
    return label




def full_phone(phone) -> str:
    raw = str(phone or "").strip()
    if not raw or raw == "N/A" or _looks_like_auth_key(raw):
        return "—"
    return raw


def mask_phone(phone) -> str:
    raw = str(phone or "").strip()
    if not raw or raw == "N/A" or _looks_like_auth_key(raw):
        return "—"
    if not MASK_PHONE_NUMBERS:
        return raw
    digits = re.sub(r"\D", "", raw)
    if not _looks_like_phone(raw) or len(digits) < 8:
        # ── FIX #31: return "N/A" instead of "hidden" ──
        return "N/A"
    return f"+{digits[:6]}xxxxx{digits[-2:]}"


def _as_unix_timestamp(value) -> Optional[int]:
    """Normalize API timestamps (seconds, milliseconds, ISO strings) to UTC."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, datetime):
        dt = value if value.tzinfo else value.replace(tzinfo=timezone.utc)
        try:
            return int(dt.timestamp())
        except (OverflowError, OSError, ValueError):
            return None
    raw = str(value).strip()
    if not raw:
        return None
    try:
        number = float(raw.replace(",", ""))
        if not math.isfinite(number):
            return None
        if abs(number) >= 1_000_000_000_000:
            number /= 1000.0
        return int(number)
    except (TypeError, ValueError, OverflowError):
        pass
    try:
        iso = raw[:-1] + "+00:00" if raw.endswith(("Z", "z")) else raw
        dt = datetime.fromisoformat(iso)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return int(dt.timestamp())
    except (TypeError, ValueError, OSError, OverflowError):
        return None


_AGE_TS_CACHE: Dict[str, int] = {}          # item_id -> unix timestamp


def _item_published_timestamp(item) -> Optional[int]:
    """v29: much wider key scan + cache from item details.

    The supplier puts the upload date under different names depending on
    the endpoint (list vs. item vs. bulk reply), so every known spelling
    is tried - otherwise an account would show "age unknown" and the age
    filter would silently drop it.
    """
    item = item if isinstance(item, dict) else {}
    for nest in ("item", "data", "product"):
        sub = item.get(nest)
        if isinstance(sub, dict) and sub is not item:
            ts = _item_published_timestamp(sub)
            if ts:
                return ts
    for key in ("published_date", "publishedDate", "published_at",
                "publishedAt", "pdate", "date_published", "datePublished",
                "item_created", "itemCreated", "created_at", "createdAt",
                "upload_date", "uploaded_at", "date_create", "date_added",
                "date", "timestamp", "pub_date"):
        value = item.get(key)
        if value in (None, "", 0):
            continue
        parsed = _as_unix_timestamp(value)
        if parsed is not None:
            return parsed
    iid = str(item.get("item_id") or item.get("id") or "")
    if iid and iid in _AGE_TS_CACHE:
        return _AGE_TS_CACHE[iid]
    return None


def remember_item_age(item) -> None:
    """Keep the date we learned from an item-detail reply."""
    if not isinstance(item, dict):
        return
    iid = str(item.get("item_id") or item.get("id") or "")
    ts = None
    for key in ("published_date", "publishedDate", "published_at",
                "publishedAt", "pdate", "item_created", "itemCreated",
                "created_at", "createdAt", "date"):
        if item.get(key) not in (None, ""):
            ts = _as_unix_timestamp(item.get(key))
            if ts:
                break
    if iid and ts:
        _AGE_TS_CACHE[iid] = int(ts)


async def ensure_item_ages(items, limit: int = 24) -> list:
    """v29: fill in missing upload dates with one parallel detail fetch.

    Only used for the few accounts that are on screen (or about to be
    bought) - browsers of an unknown-age account would otherwise show
    "unknown" and the age filter would throw the account away.
    """
    items = [it for it in (items or []) if isinstance(it, dict)]
    missing = [it for it in items if _item_published_timestamp(it) is None]
    missing = missing[:max(1, int(limit or 1))]
    if not missing:
        return items
    sem = asyncio.Semaphore(8)

    async def _one(it):
        iid = str(it.get("item_id") or it.get("id") or "")
        if not iid:
            return
        async with sem:
            try:
                r = await asyncio.wait_for(sup.item(iid), timeout=8)
            except Exception:
                return
        if isinstance(r, dict) and r.get("ok") and isinstance(r.get("item"),
                                                             dict):
            sub = r["item"]
            remember_item_age(sub)
            for key in ("published_date", "publishedDate", "item_created",
                        "created_at", "pdate"):
                if sub.get(key) not in (None, ""):
                    it.setdefault(key, sub[key])
            _ts = _item_published_timestamp(sub)
            if _ts and _item_published_timestamp(it) is None:
                it["published_date"] = _ts

    await asyncio.gather(*[_one(it) for it in missing], return_exceptions=True)
    return items


def _ts_date(ts) -> str:
    parsed = _as_unix_timestamp(ts)
    if parsed is None:
        return ""
    try:
        return datetime.fromtimestamp(parsed, timezone.utc).strftime("%d %b %Y")
    except (TypeError, ValueError, OSError, OverflowError):
        return ""

def _ts_full_date(ts) -> str:
    parsed = _as_unix_timestamp(ts)
    if parsed is None:
        return ""
    try:
        tz = timezone(timedelta(minutes=REPORT_TZ_OFFSET))
        return datetime.fromtimestamp(parsed, tz).strftime("%d %b %Y, %I:%M %p IST")
    except (TypeError, ValueError, OSError, OverflowError):
        return ""


def premium_text(item) -> str:
    """Premium status with exact remaining time.
    Returns: No | Yes · no expiry info | Yes · 5h 23m left | Yes · 47d left
    """
    item = item or {}
    try:
        on = int(item.get("telegram_premium") or 0)
    except (TypeError, ValueError):
        on = 0
    if on <= 0:
        return "No"

    # Multiple field names try karo (supplier kabhi kabhi naam badal deta hai)
    exp = (item.get("telegram_premium_expires")
           or item.get("premium_expires")
           or item.get("premium_until")
           or item.get("telegram_premium_until"))
    try:
        exp_ts = int(float(exp)) if exp not in (None, "", 0) else 0
    except (TypeError, ValueError):
        exp_ts = 0

    if exp_ts <= 0:
        return "Yes · no expiry info"

    try:
        left = exp_ts - int(time.time())
    except (TypeError, ValueError, OSError, OverflowError):
        return "Yes · no expiry info"

    if left <= 0:
        return "Yes · expired"

    d = _ts_date(exp_ts) or "?"
    days = left // 86400
    hours = (left % 86400) // 3600
    mins = (left % 3600) // 60

    if days >= 1:
        return f"Yes · {days}d left (until {d})"
    if hours >= 1:
        return f"Yes · {hours}h {mins}m left"
    return f"Yes · {mins}m left"


