def kv(label, value, width=12) -> str:
    """Aligned two-column row (rich-text editor jaisa saaf table)."""
    lab = " ".join(str(label or "").strip().split())
    pad = "\u00a0" * max(1, width - len(lab))
    return f"{lab}{pad}{value}"


def section(title, icon=None, sub=None) -> str:
    """Chhota section heading: bold + heavy rule ke bina (compact)."""
    ttl = str(title or "").strip()
    glyph = str(icon or "").strip() or title_emoji(ttl)
    head_txt = f"<b>{_map_plain(('%s %s' % (glyph, ttl)).strip(), lambda p: p.upper())}</b>"
    if sub:
        head_txt += f"\n<i>{sub}</i>"
    return head_txt


