def card(title, body_lines=None, note=None, footer=None, icon=None):
    parts = [head(title, icon or "")]
    if body_lines:
        parts.append(box(body_lines))
    if note:
        if len(str(note)) > 110:          # v33: lambi note collapsible
            parts.append(exp([f"<i>{note}</i>"]))
        else:
            parts.append(f"<i>{note}</i>")
    if footer:
        parts.append(THIN)
        parts.append(footer)
    return "\n".join(parts)



