def shop_stock_summary(srv=1) -> dict:
    """v31: how many countries have live stock + total accounts + freshness."""
    srv = 2 if int(srv or 1) == 2 else 1
    col = "stock2" if srv == 2 else "stock1"
    out = {"countries": 0, "with_stock": 0, "accounts": 0, "at": 0}
    try:
        r = _get_conn().execute(
            f"SELECT COUNT(*) AS c, "
            f"SUM(CASE WHEN {col}>0 THEN 1 ELSE 0 END) AS w, "
            f"SUM({col}) AS t, MAX(stock_at) AS a FROM countries "
            f"WHERE is_active=1").fetchone()
        if r:
            out = {"countries": int(r["c"] or 0),
                   "with_stock": int(r["w"] or 0),
                   "accounts": int(r["t"] or 0),
                   "at": int(r["a"] or 0)}
    except Exception:
        pass
    return out


def s_shop_list(uid, bal, total, page, pages, accounts=None, srv=1,
                cheap=None, live_at="", fsum="", stock=None) -> str:
    srv = int(srv or 1)
    col = "price2_inr" if srv == 2 else "price_inr"
    stock_col = "stock2" if srv == 2 else "stock1"
    r = _get_conn().execute(
        f"SELECT MIN({col}) AS lo FROM countries "
        f"WHERE {col}>0 AND is_active=1 AND {stock_col}>0").fetchone()
    lo = float(r["lo"] or 0) if r else 0.0
    if not lo:                       # stock data not in yet - fall back
        r = _get_conn().execute(
            f"SELECT MIN({col}) AS lo FROM countries "
            f"WHERE {col}>0 AND is_active=1").fetchone()
        lo = float(r["lo"] or 0) if r else 0.0
    st = stock or shop_stock_summary(srv)
    accounts = max(int(accounts or 0), int(st.get("accounts") or 0))
    lines = [f"\U0001F4B0 Balance: <b>{money(bal)}</b>",
             f"\U0001F4E6 Live accounts: <b>{accounts:,}</b>  \u2022  "
             f"\U0001F30D Countries with stock: "
             f"<b>{st.get('with_stock') or 0}</b>/"
             f"{st.get('countries') or total}"]
    if st.get("at"):
        age = max(0, int(time.time()) - int(st["at"]))
        when = _age_secs(age)
        lines.append("\U0001F501 Stock checked: "
                     + (f"<b>{when}</b>" if when.endswith("ago")
                        else f"<b>{when}</b> now"))
    if lo:
        lines.append(f"\U0001F3F7 From: <b>{money(lo)}</b>")
    if cheap and cheap.get("price_inr"):
        lines.append(f"\u2B50 Cheapest: {esc(cheap['name'])} "
                     f"<b>{money(cheap['price_inr'])}</b>")
    upd = sync_updated_label(srv)
    body = (head(f"{SERVER_LABEL.get(srv, '')} \u2022 "
                 f"{SERVER_QUALITY.get(srv, '')}",
                 icon="\u26A1" if srv == 1 else "\U0001F48E",
                 sub=f"Updated {esc(upd)}" if upd else None)
            + "\n" + box(lines)
            + f"\nPage <b>{page + 1}</b> of {pages}"
            + (f"\n📅 <i>{esc(fsum)}</i>" if fsum else "")
            + "\n<i>Tap a country to see price and stock.</i>"
            + "\n" + exp([
                "1️⃣ Tap a country - live price and stock appear",
                "2️⃣ Open an account - number, age and 2FA details",
                "3️⃣ Tap Buy - paid from your wallet, delivered instantly",
                "4️⃣ Session file + JSON + receipt are ready there"],
                "🛒 How to buy"))
    return body




