def s_buy_anim(step: int, total: int, title: str, note: str,
               sub_lines=None, prefix="BUYING ACCOUNT", cc=None,
               cname=None, srv=None) -> str:
    """Live progress card while the bot buys an account."""
    STEPS = [
        "Checking wallet",
        "Contacting supplier",
        "Buying account",
        "Waiting for Telegram",
        "Fetching credentials",
        "Finalising your order",
    ]
    step = max(1, min(int(step or 1), len(STEPS)))
    pct = int(step / len(STEPS) * 100)
    sub = []
    if cc and cname:
        sub.append(kv("Country", f"{flag_emoji(cc)} <b>{esc(cname)}</b>"))
    if srv:
        sub.append(kv("Server", f"Server {int(srv)} "
                                f"({SERVER_QUALITY.get(int(srv), '')})"))
    for i, st in enumerate(STEPS, 1):
        if i < step:
            sub.append(f"✅ {st}")
        elif i == step:
            sub.append(f"🔄 <b>{st}</b>")
        else:
            sub.append(f"▫️ <i>{st}</i>")
    if sub_lines:
        sub.extend(sub_lines)
    return (head(str(prefix).title(), "🛒",
                 sub=f"step {step} of {len(STEPS)}") + "\n"
            + f"<code>{pbar(step, len(STEPS), 12)}</code>  <b>{pct}%</b>\n"
            + box(sub)
            + f"\n⏳ <i>{esc(title)}</i>\n"
            + f"<i>{esc(note)}</i>")



