CARD_W, CARD_H = 1280, 900
CARD_CYAN = (63, 201, 255)
CARD_CYAN_D = (22, 122, 190)
CARD_GOLD = (255, 201, 74)
CARD_WHITE = (255, 255, 255)
CARD_MUTED = (150, 172, 202)
CARD_PANEL = (10, 22, 42)
CARD_BG1 = (5, 9, 20)
CARD_BG2 = (11, 28, 56)
_CARD_FONTS = {
    "bold": ["Roboto-Bold.ttf", "DejaVuSans-Bold.ttf",
             "LiberationSans-Bold.ttf", "segoeuib.ttf", "arialbd.ttf"],
    "reg": ["Roboto-Regular.ttf", "DejaVuSans.ttf",
            "LiberationSans-Regular.ttf", "segoeui.ttf", "arial.ttf"],
}
_CARD_FONT_DIRS = (
    "/system/fonts/", "/usr/share/fonts/truetype/dejavu/",
    "/usr/share/fonts/truetype/liberation/", "/usr/share/fonts/TTF/",
    "/usr/share/fonts/truetype/", "/usr/local/share/fonts/",
    "/data/data/com.termux/files/usr/share/fonts/TTF/",
    "/data/data/com.termux/files/usr/share/fonts/",
    "C:/Windows/Fonts/", "/Library/Fonts/", "/System/Library/Fonts/",
)
_cf_cache: Dict[str, Any] = {}
_logo_cache: Dict[str, Any] = {}
_profile_card_cache: Dict[int, dict] = {}


def _card_font_path(kind="reg") -> str:
    if kind in _cf_cache:
        return _cf_cache[kind]
    found = ""
    for folder in _CARD_FONT_DIRS:
        for name in _CARD_FONTS.get(kind, _CARD_FONTS["reg"]):
            try:
                if os.path.isfile(folder + name):
                    found = folder + name
                    break
            except Exception:
                continue
        if found:
            break
    _cf_cache[kind] = found
    return found


_font_cache: Dict[str, Any] = {}


def card_font(kind, size):
    """Bold / regular font at `size` with a safe default fallback.

    v26: font objects are cached - loading a TTF for every single text
    call was a big part of the card render time."""
    key = f"{kind}:{int(size)}"
    hit = _font_cache.get(key)
    if hit is not None:
        return hit
    path = _card_font_path(kind)
    font = None
    if path:
        try:
            font = _CFont.truetype(path, int(size))
        except Exception:
            font = None
    if font is None:
        try:
            font = _CFont.load_default(int(size))
        except Exception:
            font = _CFont.load_default()
    _font_cache[key] = font
    return font


def _card_has_glyph(font, ch) -> bool:
    try:
        return font.getbbox(ch) != font.getbbox("\ue000")
    except Exception:
        return False


def card_money(value, font) -> str:
    """₹ when the font has the glyph, otherwise Rs."""
    try:
        txt = f"\u20b9{float(value or 0):,.2f}"
    except (TypeError, ValueError):
        return "-"
    return txt if _card_has_glyph(font, "\u20b9") else "Rs " + txt[1:]


def shop_logo_image(size=156):
    """The shop logo as a circular RGBA image. Loads from URL first, then local."""
    if not HAS_PIL:
        return None
    key = f"s{int(size)}"
    if key in _logo_cache:
        return _logo_cache[key]

    # 1. Pehle URL (Link) se load karne ki koshish karega
    logo_url = globals().get("SHOP_LOGO_URL", "").strip()
    if logo_url and logo_url.startswith("http"):
        try:
            import urllib.request
            import io as _io
            # Timeout 10s rakha hai taaki bot hang na ho
            req = urllib.request.Request(logo_url, headers={'User-Agent': 'Mozilla/5.0'})
            with urllib.request.urlopen(req, timeout=10) as response:
                img_data = response.read()
            
            im = _CImg.open(_io.BytesIO(img_data))
            im = _card_circle(im, int(size))
            _logo_cache[key] = im
            log.info("Logo loaded from URL successfully.")
            return im
        except Exception as e:
            log.warning("logo URL load failed (%s): %s", logo_url, str(e)[:100])

    # 2. Agar URL fail ho jaye, toh local file check karega
    for path in ("logo.jpg", "logo.png", "assets/logo.jpg", "assets/logo.png"):
        if os.path.isfile(path):
            try:
                im = _CImg.open(path)
                im = _card_circle(im, int(size))
                _logo_cache[key] = im
                return im
            except Exception as e:
                log.warning("logo file load failed (%s): %s", path, str(e)[:100])

    # 3. Agar dono fail ho jayein, toh purane Base64 par fallback karega
    if not SHOP_LOGO_B64:
        return None
    try:
        import io as _io
        im = _CImg.open(_io.BytesIO(base64.b64decode(SHOP_LOGO_B64)))
        im = _card_circle(im, int(size))
        _logo_cache[key] = im
        return im
    except Exception as e:
        log.warning("logo decode failed: %s", str(e)[:100])
        return None


def card_fit_text(d, text, kind, start, minsize, maxw, step=2):
    """Return (font, text) that fits `maxw`; shrinks first, then trims with
    an ellipsis so a long name/username can never run off the card."""
    text = str(text)
    size = start
    f = card_font(kind, size)
    while size > minsize and d.textlength(text, font=f) > maxw:
        size -= step
        f = card_font(kind, size)
    if d.textlength(text, font=f) <= maxw:
        return f, text
    ell = "\u2026"
    while len(text) > 1 and d.textlength(text + ell, font=f) > maxw:
        text = text[:-1]
    return f, text.rstrip() + ell


def _card_circle(image, size):
    """Square-crop, resize and mask an image into a circle (RGBA)."""
    image = _COps.exif_transpose(image).convert("RGB")
    side = min(image.size)
    image = _COps.fit(image, (side, side), _CImg.LANCZOS)
    image = image.resize((int(size), int(size)), _CImg.LANCZOS)
    mask = _CImg.new("L", (int(size) * 4, int(size) * 4), 0)
    _CDraw.Draw(mask).ellipse([0, 0, int(size) * 4 - 1, int(size) * 4 - 1],
                              fill=255)
    mask = mask.resize((int(size), int(size)), _CImg.LANCZOS)
    out = image.convert("RGBA")
    out.putalpha(mask)
    return out


def _card_vgrad(size, top, bottom):
    w, h = size
    strip = _CImg.new("RGB", (1, h))
    d = _CDraw.Draw(strip)
    for y in range(h):
        t = y / max(1, h - 1)
        d.point((0, y), tuple(int(top[i] + (bottom[i] - top[i]) * t)
                              for i in range(3)))
    return strip.resize((w, h))


def _short_ago(stamp) -> str:
    try:
        dt = _parse_ts(stamp)
        if dt is None:
            return "-"
        secs = max(0, int((now_utc() - dt).total_seconds()))
    except Exception:
        return "-"
    if secs < 60:
        return "just now"
    if secs < 3600:
        return f"{secs // 60} min ago"
    if secs < 86400:
        return f"{secs // 3600} h ago"
    return f"{secs // 86400} d ago"


def _nice_date(stamp) -> str:
    dt = _parse_ts(stamp)
    return dt.strftime("%d %b %Y") if dt else "-"


def profile_card_data(uid, tg_user=None) -> dict:
    """Everything the card shows, read from the local database."""
    uid = int(uid)
    ud = db_user(uid)
    uname = str((ud["username"] if ud else "") or
                getattr(tg_user, "username", "") or "").strip()
    fname = str((ud["first_name"] if ud else "") or
                getattr(tg_user, "first_name", "") or "").strip()
    lname = str(getattr(tg_user, "last_name", "") or "").strip()
    name = (fname + (" " + lname if lname else "")).strip() or "Telegram User"
    try:
        bal = db_balance(uid)
    except Exception:
        bal = 0.0
    orders = spent = deposited = 0
    try:
        row = _get_conn().execute(
            "SELECT COUNT(*) AS n, COALESCE(SUM(store_price),0) AS s "
            "FROM orders WHERE user_id=? AND status='delivered'",
            (uid,)).fetchone()
        orders = int(row["n"] or 0)
        spent = float(row["s"] or 0)
    except Exception:
        pass
    try:
        row = _get_conn().execute(
            "SELECT COALESCE(SUM(amount),0) AS s FROM deposits "
            "WHERE user_id=? AND status='approved'", (uid,)).fetchone()
        deposited = float(row["s"] or 0)
    except Exception:
        pass
    try:
        refs, ref_earned = ref_stats(uid)
    except Exception:
        refs, ref_earned = 0, 0.0
    role = role_of(uid)
    if role == ROLE_OWNER:
        role_txt = "OWNER"
    elif role == ROLE_SUPER:
        role_txt = "SUPER ADMIN"
    elif role == ROLE_ADMIN:
        role_txt = "ADMIN"
    else:
        role_txt = "CUSTOMER"
    banned = bool(ud["is_banned"]) if ud else False
    verified = bool(ud["verified_at"]) if ud else False
    if banned:
        status = "BANNED"
    elif spent >= 5000:
        status = "VIP 3 \u00b7 VERIFIED"
    elif spent >= 2000:
        status = "VIP 2 \u00b7 VERIFIED"
    elif spent >= 500:
        status = "VIP 1 \u00b7 VERIFIED"
    elif verified:
        status = "VERIFIED"
    else:
        status = "MEMBER"
    tier = ""
    if spent >= 5000:
        tier = "VIP 3"
    elif spent >= 2000:
        tier = "VIP 2"
    elif spent >= 500:
        tier = "VIP 1"
    return {
        "uid": uid, "name": name, "username": uname,
        "initials": (name[:1] + (name.split()[-1][:1] if " " in name else "")),
        "status": status, "tier": tier, "verified": verified, "banned": banned,
        "role": role_txt, "balance": bal, "orders": orders, "spent": spent,
        "deposited": deposited, "refs": refs, "ref_earned": float(ref_earned),
        "joined": _nice_date(ud["joined_at"]) if ud else "-",
        "last_seen": _short_ago(ud["last_seen"]) if ud else "-",
        "support": SUPPORT_CONTACT,
    }


_card_bg_cache: Dict[str, Any] = {}


def _card_background(W=CARD_W, H=CARD_H):
    """Gradient + glows + grid + frame - built ONCE, reused by every card.
    (The glow blurs were most of the render time; this makes a card that
    only changes numbers render in a few milliseconds.)"""
    key = f"{W}x{H}"
    hit = _card_bg_cache.get(key)
    if hit is not None:
        return hit
    base = _card_vgrad((W, H), CARD_BG1, CARD_BG2).convert("RGBA")
    for (cx, cy, r, col, st) in (
        (140, 90, 430, (9, 78, 132), .50),
        (1180, 840, 470, (12, 52, 118), .45),
        (250, 470, 300, (18, 108, 165), .26),
    ):
        glow = _CImg.new("RGB", (W, H), col)
        m = _CImg.new("L", (W, H), 0)
        _CDraw.Draw(m).ellipse([cx - r, cy - r, cx + r, cy + r],
                               fill=int(255 * st))
        base.paste(glow, (0, 0), m.filter(_CFilter.GaussianBlur(r * .45)))
    grid = _CImg.new("RGBA", (W, H), (0, 0, 0, 0))
    gd = _CDraw.Draw(grid)
    for x in range(0, W, 64):
        gd.line([(x, 0), (x, H)], fill=(70, 160, 230, 11))
    for y in range(0, H, 64):
        gd.line([(0, y), (W, y)], fill=(70, 160, 230, 11))
    base = _CImg.alpha_composite(base, grid)
    d = _CDraw.Draw(base)
    d.rounded_rectangle([16, 16, W - 17, H - 17], radius=44,
                        outline=(48, 160, 230, 200), width=3)
    d.rounded_rectangle([30, 30, W - 31, H - 31], radius=36,
                        outline=(120, 210, 255, 40), width=2)
    # header text
    d.text((88, 72), SHOP_NAME.upper()[:16], font=card_font("bold", 46),
           fill=CARD_WHITE)
    d.text((90, 136), "PREMIUM TELEGRAM ACCOUNT STORE",
           font=card_font("bold", 19), fill=CARD_CYAN)
    d.line([(88, 186), (620, 186)], fill=(60, 140, 200, 120), width=2)
    # logo (static)
    logo_im = shop_logo_image(156)
    if logo_im is not None:
        halo = _CImg.new("RGBA", (280, 280), (0, 0, 0, 0))
        _CDraw.Draw(halo).ellipse([16, 16, 264, 264],
                                  fill=(30, 140, 210, 95))
        base.alpha_composite(halo.filter(_CFilter.GaussianBlur(24)),
                             (W - 288, 30))
        base.alpha_composite(logo_im, (W - 226, 62))
    # avatar glow ring (static)
    AV, AVX, AVY = 272, 92, 262
    ring = _CImg.new("RGBA", (AV + 140, AV + 140), (0, 0, 0, 0))
    _CDraw.Draw(ring).ellipse([38, 38, AV + 102, AV + 102],
                              outline=(60, 200, 255, 255), width=10)
    base.alpha_composite(ring.filter(_CFilter.GaussianBlur(8)),
                         (AVX - 70, AVY - 70))
    _card_bg_cache[key] = base
    return base


def render_profile_card(data, photo_bytes=None, logo=None) -> bytes:
    """Draw the 1280x900 profile card and return JPEG bytes."""
    if not HAS_PIL:
        raise RuntimeError("Pillow not installed")
    W, H = CARD_W, CARD_H
    base = _card_background(W, H).copy()
    d = _CDraw.Draw(base)

    # header + logo + avatar ring already live in the cached background
    if logo is not None:                     # custom logo (rare)
        base.alpha_composite(logo, (W - 226, 62))
        d = _CDraw.Draw(base)
    AV, AVX, AVY = 272, 92, 262
    avatar = None
    if photo_bytes:
        try:
            import io as _io
            avatar = _card_circle(_CImg.open(_io.BytesIO(photo_bytes)), AV)
        except Exception as e:
            log.info("profile photo decode failed: %s", str(e)[:80])
            avatar = None
    if avatar is None:
        avatar = _CImg.new("RGBA", (AV, AV), (17, 46, 82, 255))
        ad = _CDraw.Draw(avatar)
        ad.text((AV / 2, AV / 2), (data.get("initials") or "TG")[:2].upper(),
                font=card_font("bold", 112), fill=CARD_CYAN, anchor="mm")
        mask = _CImg.new("L", (AV * 4, AV * 4), 0)
        _CDraw.Draw(mask).ellipse([0, 0, AV * 4 - 1, AV * 4 - 1], fill=255)
        avatar.putalpha(mask.resize((AV, AV), _CImg.LANCZOS))
    base.alpha_composite(avatar, (AVX, AVY))
    d = _CDraw.Draw(base)
    d.ellipse([AVX - 4, AVY - 4, AVX + AV + 4, AVY + AV + 4],
              outline=CARD_CYAN, width=5)
    if data.get("verified"):
        tx, ty = AVX + AV - 66, AVY + AV - 66
        d.ellipse([tx - 34, ty - 34, tx + 34, ty + 34], fill=(6, 14, 28))
        d.ellipse([tx - 28, ty - 28, tx + 28, ty + 28], fill=CARD_CYAN)
        d.line([(tx - 13, ty + 1), (tx - 4, ty + 12), (tx + 14, ty - 11)],
               fill=(6, 16, 32), width=7, joint="curve")

    # status pill
    pill = str(data.get("status") or "MEMBER")
    pf = card_font("bold", 21)
    pw = int(d.textlength(pill, font=pf)) + 46
    px = AVX + AV // 2 - pw // 2
    py = AVY + AV + 36
    d.rounded_rectangle([px, py, px + pw, py + 48], radius=24,
                        fill=(12, 38, 68),
                        outline=(230, 80, 90) if data.get("banned") else CARD_CYAN,
                        width=2)
    d.text((px + pw // 2, py + 25), pill, font=pf,
           fill=(255, 140, 148) if data.get("banned") else CARD_CYAN,
           anchor="mm")

    # left column mini details
    mini = (("ROLE", str(data.get("role") or "CUSTOMER")),
            ("LAST ACTIVE", str(data.get("last_seen") or "-")),
            ("JOINED", str(data.get("joined") or "-")))
    my = py + 62
    for label, value in mini:
        d.text((96, my), label, font=card_font("bold", 15), fill=CARD_MUTED)
        vfont, vtext = card_fit_text(d, value, "bold", 24, 17, AVX + AV + 40)
        d.text((96, my + 22), vtext, font=vfont, fill=CARD_WHITE)
        my += 58

    # identity
    X = 462
    name_maxw = (W - 92) - X
    nf, name = card_fit_text(d, str(data.get("name") or "Telegram User"),
                             "bold", 60, 32, name_maxw, step=4)
    d.text((X, 208), name, font=nf, fill=CARD_WHITE)
    uname = str(data.get("username") or "").strip()
    uf, utxt = card_fit_text(d, ("@" + uname) if uname else "no username set",
                             "reg", 32, 22, name_maxw)
    d.text((X, 286), utxt, font=uf,
           fill=CARD_MUTED if uname else (120, 140, 168))
    cy0 = 340
    chip = f"ID  {data.get('uid')}"
    cf = card_font("bold", 23)
    cw = int(d.textlength(chip, font=cf)) + 50
    d.rounded_rectangle([X, cy0, X + cw, cy0 + 50], radius=25,
                        fill=(10, 30, 56), outline=(70, 130, 180), width=2)
    d.text((X + 25, cy0 + 25), chip, font=cf, fill=(186, 214, 244), anchor="lm")
    if data.get("tier"):
        tx0 = X + cw + 16
        tf = card_font("bold", 21)
        tw = int(d.textlength(str(data["tier"]), font=tf)) + 46
        d.rounded_rectangle([tx0, cy0 + 3, tx0 + tw, cy0 + 47], radius=23,
                            fill=(46, 34, 8), outline=CARD_GOLD, width=2)
        d.text((tx0 + tw // 2, cy0 + 25), str(data["tier"]), font=tf,
               fill=CARD_GOLD, anchor="mm")

    # stat grid
    vf0 = card_font("bold", 33)
    stat_rows = [
        ("WALLET BALANCE", card_money(data.get("balance"), vf0), True),
        ("ACCOUNTS BOUGHT", str(int(data.get("orders") or 0)), False),
        ("TOTAL SPENT", card_money(data.get("spent"), vf0), False),
        ("TOTAL DEPOSITED", card_money(data.get("deposited"), vf0), False),
        ("REFERRALS", f"{int(data.get('refs') or 0)} \u00b7 "
                      f"{card_money(data.get('ref_earned'), vf0)}", False),
        ("MEMBER SINCE", str(data.get("joined") or "-"), False),
    ]
    sx, sy = X, 428
    cw2, ch2, gap = 352, 104, 20
    for i, (label, value, accent) in enumerate(stat_rows):
        cx = sx + (i % 2) * (cw2 + gap)
        cy = sy + (i // 2) * (ch2 + gap)
        d.rounded_rectangle([cx, cy, cx + cw2, cy + ch2], radius=20,
                            fill=CARD_PANEL, outline=(58, 122, 176, 120),
                            width=2)
        d.rounded_rectangle([cx + 1, cy + 20, cx + 6, cy + ch2 - 20],
                            radius=3,
                            fill=CARD_GOLD if accent else CARD_CYAN)
        d.text((cx + 30, cy + 22), label, font=card_font("bold", 17),
               fill=CARD_MUTED)
        vf, vtxt = card_fit_text(d, value, "bold", 33, 17, cw2 - 58)
        d.text((cx + 30, cy + 52), vtxt, font=vf, fill=CARD_WHITE)

    # footer
    d.line([(88, 812), (W - 88, 812)], fill=(70, 140, 200, 110), width=2)
    d.text((88, 838),
           f"Support {data.get('support') or SUPPORT_CONTACT}   \u00b7   "
           "auto-generated card",
           font=card_font("reg", 23), fill=CARD_MUTED)
    d.text((W - 88, 838), now_ist_str("%d %b %Y, %I:%M %p"),
           font=card_font("reg", 23), fill=CARD_MUTED, anchor="ra")

    out = io.BytesIO()
    # v26: quality 88 + no optimize/progressive = same look, ~2x faster
    base.convert("RGB").save(out, "JPEG", quality=88, optimize=False,
                             progressive=False)
    return out.getvalue()


async def fetch_profile_photo(bot, uid, max_age=900):
    """The user's Telegram DP in the highest resolution the Bot API gives.
    Cached for 15 minutes; returns b'' when the user has no photo."""
    uid = int(uid)
    slot = _profile_card_cache.setdefault(uid, {})
    age = time.monotonic() - float(slot.get("dp_at") or 0)
    if "dp" in slot and age < max_age:
        return slot["dp"]
    blob = b""
    try:
        photos = await bot.get_user_profile_photos(user_id=uid, limit=1)
        if photos and photos.photos:
            sizes = photos.photos[0]
            best = sizes[-1]
            f = await bot.get_file(best.file_id)
            data = await f.download_as_bytearray()
            blob = bytes(data)
    except Exception as e:
        log.info("profile photo for %s: %s", uid, str(e)[:100])
    slot["dp"] = blob
    slot["dp_at"] = time.monotonic()
    return blob


def _plain(txt) -> str:
    """Telegram-safe plain text: no HTML tags, no stray entities."""
    t = re.sub(r"<[^>]+>", "", str(txt or ""))
    t = (t.replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&")
          .replace("&quot;", '"').replace("&#39;", "'"))
    return t


_CAP_TAG_RE = re.compile(r"<[^>]+>")


def _cap_safe(caption, limit=1000) -> str:
    """Cut a caption WITHOUT breaking HTML tags.

    v31 bug: a cut `<b>` made Telegram reject the whole photo.
    v32: premium (`<tg-emoji emoji-id=..>`) tags go through the same tag
    stack, and only *visible* characters are counted (without tags), so a
    premium emoji caption is not cut early.
    """
    cap = str(caption or "")
    if len(cap) <= limit:
        return cap
    out: List[str] = []
    stack: List[str] = []
    vis = 0
    pos = 0
    done = False
    for m in _CAP_TAG_RE.finditer(cap):
        seg = cap[pos:m.start()]
        if vis + len(seg) >= limit:
            out.append(seg[:limit - vis])
            vis = limit
            done = True
            break
        out.append(seg)
        vis += len(seg)
        tag = m.group(0)
        out.append(tag)
        nm = re.match(r"<\s*(/?)\s*([a-zA-Z-]+)", tag)
        if nm:
            closing, name = nm.group(1), nm.group(2).lower()
            if closing:
                if name in stack:
                    while stack and stack.pop() != name:
                        pass
            elif not tag.rstrip().endswith("/>"):
                stack.append(name)
        pos = m.end()
    if not done:
        seg = cap[pos:]
        out.append(seg[:max(0, limit - vis)])
    for name in reversed(stack):
        out.append("</%s>" % name)
    return "".join(out).rstrip() + "…"


async def send_profile_card(bot, chat_id, tg_user, caption, markup=None) -> bool:
    """Send the profile card photo with `caption`.

    v31: a 4-step ladder so the card really shows up:
      1. photo + HTML caption    2. photo + plain caption
      3. document + plain        4. False (caller shows the text profile)
    """
    if not HAS_PIL:
        log.warning("profile card skipped: Pillow is not installed "
                    "(pip install pillow) - showing the text profile")
        return False
    uid = int(tg_user.id)
    caption = _cap_safe(premiumize(caption), 1000)
    plain = _plain(caption)[:1000]
    t0 = time.monotonic()
    slot = _profile_card_cache.setdefault(uid, {})
    try:
        # DB read + Telegram photo download happen at the same time
        data, photo = await asyncio.gather(
            asyncio.to_thread(profile_card_data, uid, tg_user),
            fetch_profile_photo(bot, uid))
        sig = (round(float(data.get("balance") or 0), 2),
               int(data.get("orders") or 0),
               round(float(data.get("spent") or 0), 2),
               round(float(data.get("deposited") or 0), 2),
               int(data.get("refs") or 0), str(data.get("status") or ""),
               str(data.get("name") or ""), str(data.get("username") or ""),
               str(data.get("role") or ""), str(data.get("last_seen") or ""),
               bool(photo))
        cached = slot.get("card")
        if (cached and slot.get("sig") == sig
                and time.monotonic() - float(slot.get("card_at") or 0) < 180):
            card = cached                      # identical card - reuse bytes
        else:
            card = await asyncio.to_thread(render_profile_card, data, photo)
            slot["card"] = card
            slot["sig"] = sig
            slot["card_at"] = time.monotonic()
    except Exception as e:
        log.warning("profile card build failed for %s: %s", uid, str(e)[:150])
        return False
    for mode in ("html", "plain"):
        try:
            await bot.send_photo(
                chat_id, photo=make_input_file(card, f"profile_{uid}.jpg"),
                caption=(caption if mode == "html" else plain),
                parse_mode=(ParseMode.HTML if mode == "html" else None),
                reply_markup=markup)
            slot["sent_at"] = time.monotonic()
            log.info("profile card for %s sent in %.0f ms (%s)", uid,
                     (time.monotonic() - t0) * 1000, mode)
            return True
        except Exception as e:
            log.warning("profile card photo (%s) failed for %s: %s", mode,
                        uid, str(e)[:150])
    # last resort: send it as a document (never blocks the profile screen)
    for mode in ("html", "plain"):
        try:
            await bot.send_document(
                chat_id, document=make_input_file(card, f"profile_{uid}.jpg"),
                caption=(caption if mode == "html" else plain),
                parse_mode=(ParseMode.HTML if mode == "html" else None),
                reply_markup=markup)
            log.info("profile card sent as document (%s) for %s", mode, uid)
            return True
        except Exception as e:
            log.warning("profile card document (%s) failed: %s", mode,
                        str(e)[:120])
    return False



# ══════════════════════════════════════════════════════════════════════
#  v26  RECEIPTS · SALES-CHANNEL CARD · SUPPLIER ₹/$ · BULK HELPERS
#  1) supplier money shown in its own currency AND in ₹ (side by side)
#  2) a branded sale card image posted WITH the sales-channel message
#  3) a real PDF receipt for every single and bulk purchase
#  4) one ZIP instead of loose session files
#  5) faster profile card (render cache + quicker JPEG encode)
# ══════════════════════════════════════════════════════════════════════

def sup_inr_rate(cur=None) -> float:
    """How many ₹ is ONE unit of `cur` worth (at the live bot rate)."""
    c = str(cur or sup.currency or "usd").lower()
    if c == "inr":
        return 1.0
    if c in ("usd", "usdt"):
        try:
            r = float(usdt_rate())
            if r > 1:
                return r
        except Exception:
            pass
    try:
        return float(CUR_TO_INR.get(c, 1.0)) or 1.0
    except Exception:
        return 1.0


def sup_usd(amount, cur=None) -> float:
    """Value of `amount` of `cur` expressed in USD."""
    c = str(cur or sup.currency or "usd").lower()
    amt = float(amount or 0)
    if c in ("usd", "usdt"):
        return amt
    rate = sup_inr_rate("usd") or 1.0
    return amt * sup_inr_rate(c) / rate


def sup_three(native, converted=None, native_cur="rub") -> str:
    """Supplier money in three shapes at once - the API's own currency,
    currency (RUB), rupees and dollars, all from the API's own numbers."""
    try:
        nat = float(native or 0)
    except Exception:
        nat = 0.0
    usd = None
    try:
        usd = float(converted) if converted is not None else None
    except Exception:
        usd = None
    if usd is None:
        usd = sup_usd(nat, native_cur)
    inr = usd * (sup_inr_rate("usd") or 1.0)
    return (f"<b>{nat:,.2f} {str(native_cur).upper()}</b>"
            f"  ·  ₹{inr:,.2f}  ·  ${usd:,.2f}")


def sup_money(amount, cur=None, bold=False) -> str:
    """`1,234.00 INR  ·  ₹1,234.00  ·  $14.03`

    The supplier amount is always shown in the currency the API returned,
    then in ₹ and then in $ - so no number is ever mislabelled.
    """
    c = str(cur or sup.currency or "usd").upper()
    try:
        amt = float(amount or 0)
    except (TypeError, ValueError):
        amt = 0.0
    inr = to_inr(amt, c.lower()) if c != "INR" else amt
    usd = sup_usd(amt, c.lower())
    parts = []
    if c == "INR":
        parts.append(f"₹{inr:,.2f}")
    elif c in ("USD", "USDT"):
        parts.append(f"${amt:,.2f}")
    else:
        parts.append(f"{amt:,.2f} {c}")
    if c != "INR":
        parts.append(f"₹{inr:,.2f}")
    if c not in ("USD", "USDT"):
        parts.append(f"${usd:,.2f}")
    txt = "  \u00b7  ".join(parts)
    return f"<b>{txt}</b>" if bold else txt


def sup_money_plain(amount, cur=None) -> str:
    """Same breakdown without HTML (used inside images / PDFs)."""
    return sup_money(amount, cur, bold=False).replace("</b>", "").replace(
        "<b>", "")


SALE_W, SALE_H = 1200, 1000      # sales-channel card size


def _no_emoji(text) -> str:
    """Strip emoji / flag pictographs - the card font has no glyphs."""
    out = []
    for ch in str(text or ""):
        o = ord(ch)
        if ch.isascii() or o in (0x00B7, 0x20B9) or 0x00C0 <= o <= 0x024F:
            out.append(ch)
    return " ".join("".join(out).split())


def _sale_rows(lines):
    """Turn the kv(...) strings into clean (label, value) pairs."""
    out = []
    for ln in (lines or []):
        raw = str(ln if ln is not None else "")
        if ":" in raw:
            lab, _, val = raw.partition(":")
            lab, val = _card_plain(lab)[:14], _card_plain(val)[:46]
        else:
            lab, val = "", _card_plain(raw)[:60]
        if lab and val:
            out.append((lab.strip().upper(), val.strip()))
        elif val:
            out.append(("", val.strip()))
    return out[:9]


_sale_chrome_cache: Dict[str, Any] = {}


def _sale_chrome(kind) -> Any:
    """Everything that never changes on a sale card - built once per kind."""
    status = _card_status(kind)
    accent = {"DEPOSIT": CARD_GOLD}.get(str(kind or "").upper(), CARD_CYAN)
    key = f"{status}|{accent}"
    hit = _sale_chrome_cache.get(key)
    if hit is not None:
        return hit, status, accent
    W, H = SALE_W, SALE_H
    base = _card_vgrad((W, H), CARD_BG1, CARD_BG2).convert("RGBA")
    for (cx, cy, r, col, st) in ((120, 60, 460, (9, 78, 132), .50),
                                 (W - 60, H - 40, 420, (12, 60, 110), .40)):
        glow = _CImg.new("RGBA", (r * 2, r * 2), (0, 0, 0, 0))
        _CDraw.Draw(glow).ellipse([0, 0, r * 2 - 1, r * 2 - 1],
                                  fill=col + (int(255 * st),))
        base.alpha_composite(glow.filter(_CFilter.GaussianBlur(90)),
                             (cx - r, cy - r))
    d = _CDraw.Draw(base)
    for x in range(0, W, 60):
        d.line([(x, 0), (x, H)], fill=(255, 255, 255, 7))
    for y in range(0, H, 60):
        d.line([(0, y), (W, y)], fill=(255, 255, 255, 7))
    d.rounded_rectangle([16, 16, W - 16, H - 16], radius=34,
                        outline=(70, 150, 205, 110), width=3)
    d.rounded_rectangle([30, 30, W - 30, H - 30], radius=26,
                        outline=(40, 96, 150, 70), width=2)
    d.text((72, 70), SHOP_NAME.upper(), font=card_font("bold", 52),
           fill=CARD_WHITE)
    d.text((74, 138), "PREMIUM TELEGRAM ACCOUNT STORE",
           font=card_font("bold", 21), fill=CARD_MUTED)
    logo = shop_logo_image(132)
    if logo is not None:
        halo = _CImg.new("RGBA", (300, 300), (0, 0, 0, 0))
        _CDraw.Draw(halo).ellipse([0, 0, 299, 299], fill=CARD_CYAN + (90,))
        base.alpha_composite(halo.filter(_CFilter.GaussianBlur(52)),
                             (W - 212, 34))
        base.alpha_composite(logo, (W - 196, 62))
        d = _CDraw.Draw(base)
    d.line([(72, 196), (W - 72, 196)], fill=(70, 140, 200, 120), width=2)
    bf = card_font("bold", 26)
    bw = int(d.textlength(status, font=bf)) + 52
    d.rounded_rectangle([72, 232, 72 + bw, 232 + 56], radius=28,
                        fill=(10, 32, 58), outline=accent, width=3)
    d.text((72 + bw // 2, 260), status, font=bf, fill=accent, anchor="mm")
    _sale_chrome_cache[key] = base
    return base, status, accent


def render_sales_card(kind, title, lines, when=None) -> bytes:
    """Branded sale / top-up card for the sales channel."""
    if not HAS_PIL:
        raise RuntimeError("Pillow not installed")
    chrome, _status, _accent = _sale_chrome(kind)
    base = chrome.copy()
    W = SALE_W
    d = _CDraw.Draw(base)
    tf, ttxt = card_fit_text(d, _no_emoji(_card_plain(title)) or SHOP_NAME,
                             "bold", 44, 26, W - 144)
    d.text((72, 318), ttxt, font=tf, fill=CARD_WHITE)
    rows = _sale_rows(lines)
    y = 396
    rh = int(min(66, max(38, 452 // max(1, len(rows)))))
    for lab, val in rows:
        d.rounded_rectangle([72, y, W - 72, y + rh - 12], radius=16,
                            fill=(10, 24, 44, 210),
                            outline=(52, 110, 160, 90), width=1)
        if lab:
            d.text((100, y + (rh - 12) / 2), lab,
                   font=card_font("bold", 21), fill=CARD_MUTED, anchor="lm")
        vf, vtxt = card_fit_text(d, val, "bold", 28, 18, W - 480, step=2)
        d.text((W - 100, y + (rh - 12) / 2), vtxt, font=vf,
               fill=CARD_GOLD if val.startswith("₹") else CARD_WHITE,
               anchor="rm")
        y += rh
    d.line([(72, 880), (W - 72, 880)], fill=(70, 140, 200, 110), width=2)
    d.text((72, 906), f"Support {SUPPORT_CONTACT}   ·   instant auto-delivery",
           font=card_font("reg", 22), fill=CARD_MUTED)
    d.text((W - 72, 906), when or now_ist_str("%d %b %Y, %I:%M %p"),
           font=card_font("reg", 22), fill=CARD_MUTED, anchor="ra")
    out = io.BytesIO()
    base.convert("RGB").save(out, "JPEG", quality=88, optimize=False)
    return out.getvalue()


# ── PDF RECEIPT ───────────────────────────────────────────────────────
REC_W, REC_H = 1240, 1754        # A4 @ 150 dpi
REC_ROWS = 16                    # account rows per page


def _rec_wrap(d, text, font, maxw):
    words, lines, cur = str(text).split(), [], ""
    for w in words:
        t = (cur + " " + w).strip()
        if d.textlength(t, font=font) <= maxw or not cur:
            cur = t
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines or [""]


def _receipt_page(rec, items, page, pages):
    img = _CImg.new("RGB", (REC_W, REC_H), (255, 255, 255))
    d = _CDraw.Draw(img)
    navy = (10, 22, 42)
    # header band
    d.rectangle([0, 0, REC_W, 214], fill=navy)
    logo = shop_logo_image(112)
    if logo is not None:
        img.paste(logo.convert("RGB"), (72, 50),
                  logo.split()[-1] if logo.mode == "RGBA" else None)
        d = _CDraw.Draw(img)
    d.text((210, 74), SHOP_NAME.upper(), font=card_font("bold", 44),
           fill=(255, 255, 255))
    d.text((212, 130), "PREMIUM TELEGRAM ACCOUNT STORE",
           font=card_font("bold", 19), fill=(150, 175, 205))
    d.text((REC_W - 72, 78), "PAYMENT RECEIPT", font=card_font("bold", 30),
           fill=(255, 255, 255), anchor="ra")
    d.text((REC_W - 72, 122), str(rec.get("no") or "-"),
           font=card_font("bold", 21), fill=(120, 205, 250), anchor="ra")
    d.text((REC_W - 72, 154), str(rec.get("when") or now_ist_str()),
           font=card_font("reg", 19), fill=(150, 175, 205), anchor="ra")

    y = 262
    # buyer block
    buyer = rec.get("buyer") or {}
    d.text((72, y), "BILLED TO", font=card_font("bold", 19),
           fill=(110, 130, 160))
    y += 34
    d.text((72, y), str(buyer.get("name") or "-"),
           font=card_font("bold", 30), fill=(20, 30, 45))
    y += 44
    line2 = []
    if buyer.get("username"):
        line2.append("@" + str(buyer["username"]))
    line2.append(f"ID {buyer.get('uid') or '-'}")
    d.text((72, y), "   ·   ".join(line2), font=card_font("reg", 21),
           fill=(90, 105, 130))
    # right block: payment method / wallet
    d.text((REC_W - 72, 262), "PAID FROM",
           font=card_font("bold", 19), fill=(110, 130, 160), anchor="ra")
    d.text((REC_W - 72, 296), str(rec.get("method") or "Wallet balance"),
           font=card_font("bold", 24), fill=(20, 30, 45), anchor="ra")
    if rec.get("wallet_after") is not None:
        d.text((REC_W - 72, 334),
               f"Balance after: {money(rec.get('wallet_after'))}",
               font=card_font("reg", 20), fill=(90, 105, 130), anchor="ra")
    y += 46

    # table header
    d.rectangle([72, y, REC_W - 72, y + 48], fill=(14, 34, 62))
    cols = ((92, "#"), (150, "ORDER"), (300, "COUNTRY / TYPE"),
            (760, "ACCOUNT"), (REC_W - 92, "AMOUNT"))
    for cx, label in cols:
        anchor = "ra" if cx == REC_W - 92 else "la"
        d.text((cx, y + 24), label, font=card_font("bold", 18),
               fill=(190, 215, 240), anchor=anchor)
    y += 48
    rh = 46
    for i, it in enumerate(items, 1):
        if i % 2 == 0:
            d.rectangle([72, y, REC_W - 72, y + rh], fill=(244, 247, 251))
        d.text((92, y + rh / 2), str(it.get("index") or i),
               font=card_font("reg", 19), fill=(60, 75, 95), anchor="lm")
        d.text((150, y + rh / 2), str(it.get("order") or "-"),
               font=card_font("bold", 19), fill=(20, 30, 45), anchor="lm")
        ctry = f"{it.get('country') or '-'}"
        if it.get("type"):
            ctry += f"  ·  {it['type']}"
        cf, ctxt = card_fit_text(d, ctry, "reg", 19, 14, 430)
        d.text((300, y + rh / 2), ctxt, font=cf, fill=(60, 75, 95),
               anchor="lm")
        pf, ptxt = card_fit_text(d, str(it.get("phone") or "-"), "reg",
                                 19, 14, 300)
        d.text((760, y + rh / 2), ptxt, font=pf, fill=(60, 75, 95),
               anchor="lm")
        d.text((REC_W - 92, y + rh / 2), money(it.get("price")),
               font=card_font("bold", 19), fill=(20, 30, 45), anchor="rm")
        y += rh
    d.line([(72, y), (REC_W - 72, y)], fill=(200, 210, 225), width=2)
    y += 26

    # totals
    total = float(rec.get("total") or 0)
    d.rounded_rectangle([REC_W - 560, y - 8, REC_W - 72, y + 74], radius=16,
                        fill=(240, 245, 251), outline=(205, 216, 230), width=2)
    d.text((REC_W - 536, y + 12), "TOTAL PAID", font=card_font("bold", 21),
           fill=(110, 130, 160))
    d.text((REC_W - 536, y + 40), f"{len(items)} account(s) in this receipt",
           font=card_font("reg", 18), fill=(120, 135, 160))
    d.text((REC_W - 96, y + 30), money(total), font=card_font("bold", 38),
           fill=(10, 90, 160), anchor="rm")
    y += 100

    # summary panel - keeps the page balanced on short receipts
    panel = [("Receipt no", str(rec.get("no") or "-")),
             ("Payment method", str(rec.get("method") or "Wallet balance")),
             ("Accounts", str(len(items))),
             ("Support", str(SUPPORT_CONTACT))]
    if rec.get("wallet_after") is not None:
        panel.insert(3, ("Wallet balance after",
                         money(rec.get("wallet_after"))))
    d.text((72, y), "ORDER SUMMARY", font=card_font("bold", 19),
           fill=(110, 130, 160))
    y += 34
    d.rounded_rectangle([72, y, REC_W - 72, y + 40 + 40 * len(panel)],
                        radius=16, fill=(249, 251, 254),
                        outline=(210, 220, 232), width=2)
    yy = y + 20
    for lab, val in panel:
        d.text((100, yy), lab, font=card_font("reg", 20), fill=(110, 128, 152))
        vf, vtxt = card_fit_text(d, val, "bold", 21, 15, 620)
        d.text((REC_W - 100, yy), vtxt, font=vf, fill=(25, 40, 62),
               anchor="ra")
        yy += 40
    y += 60 + 40 * len(panel)
    note = str(rec.get("note") or "")
    if note:
        d.text((72, y), "NOTES", font=card_font("bold", 19),
               fill=(110, 130, 160))
        y += 32
        for ln in _rec_wrap(d, note, card_font("reg", 19), REC_W - 184)[:6]:
            d.text((92, y), ln, font=card_font("reg", 19),
                   fill=(95, 110, 135))
            y += 28

    # footer
    d.line([(72, REC_H - 132), (REC_W - 72, REC_H - 132)],
           fill=(210, 218, 230), width=2)
    d.text((92, REC_H - 104),
           f"Thank you for shopping with {SHOP_NAME}.",
           font=card_font("bold", 21), fill=(30, 45, 70))
    d.text((92, REC_H - 70),
           f"Support {SUPPORT_CONTACT}  ·  this is a computer-generated "
           "receipt, no signature needed.",
           font=card_font("reg", 18), fill=(120, 135, 160))
    d.text((REC_W - 92, REC_H - 70), f"Page {page}/{pages}",
           font=card_font("reg", 18), fill=(120, 135, 160), anchor="ra")
    return img


def build_receipt_pdf(rec) -> bytes:
    """One-page (or more) PDF receipt built with Pillow - no extra deps."""
    if not HAS_PIL:
        raise RuntimeError("Pillow not installed")
    items = list(rec.get("items") or [])
    if not items:
        items = [{}]
    chunks = [items[i:i + REC_ROWS] for i in range(0, len(items), REC_ROWS)]
    pages = len(chunks)
    imgs = [_receipt_page(rec, chunk, i + 1, pages)
            for i, chunk in enumerate(chunks)]
    out = io.BytesIO()
    imgs[0].save(out, "PDF", resolution=150.0, save_all=True,
                 append_images=imgs[1:] if len(imgs) > 1 else [])
    return out.getvalue()


def receipt_from_order(o, buyer_name="", buyer_uname="",
                       wallet_after=None) -> dict:
    """Receipt record for ONE delivered order."""
    try:
        o = dict(o)
    except Exception:
        o = {}
    d = {}
    try:
        d = json.loads(o.get("login_data") or "{}") or {}
    except Exception:
        d = {}
    price = float(o.get("store_price") or o.get("price") or 0)
    return {
        "no": f"RCPT-{o.get('id') or '?'}",
        "when": now_ist_str("%d %b %Y, %I:%M %p") + " IST",
        "buyer": {"name": buyer_name or "Telegram user",
                  "username": buyer_uname or "",
                  "uid": o.get("user_id") or ""},
        "method": "Wallet balance (UPI / crypto top-up)",
        "wallet_after": wallet_after,
        "items": [{"index": 1, "order": f"#{o.get('id') or '?'}",
                   "country": o.get("country_name") or o.get("country") or "-",
                   "type": (f"Server {o.get('server_id') or '-'} account"),
                   "phone": d.get("phone") or o.get("phone_number") or "-",
                   "price": price}],
        "total": price,
        "note": "Guarantee and login details are available in the bot under "
                "My Orders. Keep this receipt for any support request.",
    }


def receipt_from_bulk(bought, buyer_name="", buyer_uname="", uid=None,
                      wallet_after=None, label="") -> dict:
    """Receipt record for a whole bulk order."""
    items = []
    for i, b in enumerate(bought or [], 1):
        items.append({"index": i, "order": f"#{b.get('oid')}",
                      "country": label or "-",
                      "type": "Bulk account",
                      "phone": full_phone(b.get("phone") or "-"),
                      "price": float(b.get("price") or 0)})
    total = sum(x["price"] for x in items)
    return {
        "no": "RCPT-BULK-" + now_utc().strftime("%y%m%d%H%M%S"),
        "when": now_ist_str("%d %b %Y, %I:%M %p") + " IST",
        "buyer": {"name": buyer_name or "Telegram user",
                  "username": buyer_uname or "", "uid": uid or ""},
        "method": "Wallet balance (UPI / crypto top-up)",
        "wallet_after": wallet_after,
        "items": items,
        "total": total,
        "note": f"Bulk order of {len(items)} account(s). Session files, "
                "JSON settings and session strings were delivered in the "
                "matching ZIP files.",
    }


async def send_receipt_pdf(bot, chat_id, rec, markup=None) -> bool:
    """Build and send the PDF receipt (never blocks a delivery)."""
    if not HAS_PIL:
        return False
    try:
        raw = await asyncio.to_thread(build_receipt_pdf, rec)
    except Exception as e:
        log.warning("receipt build failed: %s", str(e)[:140])
        return False
    name = f"receipt_{re.sub(r'[^0-9A-Za-z]+', '-', str(rec.get('no') or 'order'))}.pdf"
    cap = ("<b>🧾 RECEIPT</b>\n"
           f"{rec.get('no')}  ·  <b>{money(rec.get('total'))}</b>\n"
           f"{len(rec.get('items') or [])} account(s)  ·  "
           f"{esc(str(rec.get('when') or ''))}")
    try:
        await bot.send_document(chat_id, document=make_input_file(raw, name),
                                filename=name, caption=cap,
                                parse_mode=ParseMode.HTML,
                                reply_markup=markup)
        return True
    except Exception as e:
        log.warning("receipt send failed: %s", str(e)[:140])
    return False


# ── ONE ZIP for a single order (session + json + string + login) ──────
def session_zip_bytes(base, db, js, string_val, data, o=None) -> bytes:
    d = data or {}
    login = [f"{SHOP_NAME} - account files",
             f"Order   : #{o.get('id') if o else '-'}",
             f"Number  : {full_phone(d.get('phone') or '-')}"]
    if d.get("password"):
        login.append(f"2FA pass: {d['password']}")
    if d.get("email"):
        login.append(f"Email   : {d['email']}")
    if d.get("email_password"):
        login.append(f"Mail pwd: {d['email_password']}")
    if d.get("link"):
        login.append(f"Link    : {d['link']}")
    entries = [(f"{base}.session", bytes(db))]
    if js:
        entries.append((f"{base}.json", bytes(js)))
    if string_val:
        entries.append((f"{base}.session_string.txt",
                        (string_val + "\n").encode("utf-8")))
    entries.append(("LOGIN.txt", "\n".join(login) + "\n"))
    readme = [
        "Everything you need is in this one ZIP - nothing else to download.",
        "",
        "FILES",
        f"  {base}.session            ready Telethon session (no SMS code)",
        f"  {base}.json               app_id / app_hash / device settings",
        f"  {base}.session_string.txt session string, one line",
        "  LOGIN.txt                 number, 2FA password, email, link",
        "",
        "USE IT",
        "  from telethon import TelegramClient",
        f"  c = TelegramClient('{base}.session', app_id, app_hash)",
        "  c.start()        # already logged in",
        "",
        "Keep this ZIP private - it opens the account.",
    ]
    return _zip_bytes(entries, readme)


