def kb_amounts_legacy() -> InlineKeyboardMarkup:
    """Old quick-amount keyboard, superseded by kb_amounts() below."""
    lo, hi = min_deposit(), max_deposit()
    base = [50, 100, 250, 500, 1000, 2000]
    vals = [v for v in base if lo <= v <= hi]
    if not vals or vals[0] > lo:
        vals.insert(0, int(lo) if float(lo).is_integer() else round(lo, 2))
    vals = sorted(dict.fromkeys(vals))[:9]
    rows, cur = [], []
    for v in vals:
        cur.append((f"{v:g}", f"dp_{v:g}", BTN_SUCCESS))
        if len(cur) == 3:
            rows.append(kb_row(*cur))
            cur = []
    if cur:
        rows.append(kb_row(*cur))
    rows += [
        kb_row(("Custom Amount", "dp_custom", BTN_SUCCESS)),
        kb_row(("Back", "deposit", BTN_PRIMARY)),
    ]
    return _styled_markup(rows)



