def s_err(code, reason=None) -> str:
    msg = ERRS.get(code, f"{code} - Something went wrong. Please contact support.")
    lines = [kv("Details", esc(msg))]
    if reason and _adm_uid_cache.get("uid"):
        lines.append(kv("Reason", f"<code>{esc(str(reason)[:300])}</code>"))
    return card("Something went wrong", body_lines=lines,
                footer=support_line(), icon="⚠️")


_adm_uid_cache: Dict[str, Any] = {"uid": 0}


def s_err_for(code, uid, reason=None) -> str:
    _adm_uid_cache["uid"] = uid if _adm(uid) else 0
    try:
        return s_err(code, reason)
    finally:
        _adm_uid_cache["uid"] = 0


