def _card_plain(v) -> str:
    """Strip HTML tags / entities so a value can sit inside a <pre> table."""
    t = re.sub(r"<[^>]+>", " ", str(v if v is not None else ""))
    t = html.unescape(t)
    t = t.replace("\u00b7", "-").replace("\u2022", "-")
    return re.sub(r"\s+", " ", t).strip()


# kind -> headline shown on the card
_CARD_STATUS = (
    ("purchase", "SALE CONFIRMED"),
    ("sale", "SALE CONFIRMED"),
    ("deposit", "WALLET TOP-UP"),
    ("top-up", "WALLET TOP-UP"),
    ("topup", "WALLET TOP-UP"),
    ("ready", "CHANNEL CONNECTED"),
    ("stock", "STOCK UPDATE"),
    ("restock", "BACK IN STOCK"),
    ("refund", "REFUND ISSUED"),
)


def _card_status(kind) -> str:
    k = _card_plain(kind).lower()
    for key, label in _CARD_STATUS:
        if key in k:
            return label
    return (_card_plain(kind).upper() or "UPDATE")[:34]


def s_log_card(kind, title, lines) -> str:
    """Sales-channel card (v24 UI).

    Layout
    ------
        SHOP BRAND
        channel title
        ──────────────────────────
        SALE CONFIRMED  -  India
        <pre>label  value  (aligned monospace table)</pre>
        ──────────────────────────
        promise line
        date / time IST
    """
    status = _card_status(kind)
    head_txt = _card_plain(title)[:52]
    rows = []
    for ln in (lines or []):
        raw = str(ln if ln is not None else "")
        if ":" in raw:
            lab, _, val = raw.partition(":")
            lab, val = _card_plain(lab)[:13], _card_plain(val)[:44]
        else:
            lab, val = "", _card_plain(raw)[:58]
        if lab and val:
            rows.append(f"{lab:<13}{val}")
        elif val:
            rows.append(val)
    table = "\n".join(rows) if rows else "-"
    line1 = f"<b>{status}</b>"
    if head_txt:
        line1 += f"  -  <b>{esc(head_txt)}</b>"
    return (f"{BRAND}\n"
            f"<i>{esc(sales_channel_title())}</i>\n"
            + LINE + "\n"
            + line1 + "\n"
            + f"<pre>{esc(table)}</pre>\n"
            + THIN + "\n"
            + "Instant auto-delivery \u2022 Verified stock \u2022 24x7 support\n"
            + f"{now_ist_str('%d %b %Y, %I:%M %p')} \u2022 {esc(SHOP_NAME)}")



def bot_start_url(payload="buy", bot=None) -> str:
    uname = ""
    try:
        uname = str(getattr(bot, "username", "") or "").lstrip("@")
    except Exception:
        uname = ""
    uname = uname or str(os.environ.get("BOT_USERNAME", "") or "").lstrip("@")
    if not uname:
        return ""
    return f"https://t.me/{uname}?start={payload}"


def kb_channel_card(bot=None, buy=True):
    """Buttons under a sales-channel post.

    v27: ONLY the Buy Now button (Support and the channel-link buttons
    were removed on request)."""
    rows = []
    if buy:
        link = bot_start_url("buy", bot)
        if link:
            rows.append(kb_url("Buy Now", link, BTN_SUCCESS))
    return ikb(*rows) if rows else None


