BTN_NONE = None
BLANK_LABELS = {"prev", "next", "close", "home", "noop", "·", "-", ""}
BLANK_PREFIXES = ("page ",)


def style_for_label(text) -> Optional[str]:
    low = _lead_strip(str(text or "")).lower()      # v32: emoji ignore
    if not low or low in BLANK_LABELS:
        return BTN_NONE
    if low.startswith(BLANK_PREFIXES):
        return BTN_NONE
    if low.isdigit():
        return BTN_NONE
    if low[:1] in ("\U0001F1E6", "\U0001F1E7", "\U0001F1E8", "\U0001F1E9",
                   "\U0001F1EA", "\U0001F1EB", "\U0001F1EC", "\U0001F1ED",
                   "\U0001F1EE", "\U0001F1EF", "\U0001F1F0", "\U0001F1F1",
                   "\U0001F1F2", "\U0001F1F3", "\U0001F1F4", "\U0001F1F5",
                   "\U0001F1F6", "\U0001F1F7", "\U0001F1F8", "\U0001F1F9",
                   "\U0001F1FA", "\U0001F1FB", "\U0001F1FC", "\U0001F1FD",
                   "\U0001F1FE", "\U0001F1FF"):
        return BTN_NONE
    if len(low) <= 3:
        return BTN_NONE
    for needles, style in STYLE_RULES:
        for n in needles:
            if n in low:
                return style
    return BTN_PRIMARY


def styled_button(b):
    has_style = bool(getattr(b, "style", None))
    has_icon = bool(getattr(b, "icon_custom_emoji_id", None))
    if has_style and (has_icon or not BTN_ICON_EMOJI):
        return b
    st = getattr(b, "style", None) or style_for_label(getattr(b, "text", ""))
    if not st:
        # v36: style na ho par icon banna chahiye (emoji wala label)
        if not BTN_ICON_EMOJI or has_icon:
            return b
        icon, _label = _split_btn_icon(_deco_label(getattr(b, "text", "")))
        if not icon:
            return b
        st = ""
    try:
        if getattr(b, "url", None):
            return _make_btn(b.text, st, url=b.url)
        if getattr(b, "callback_data", None):
            return _make_btn(b.text, st, callback_data=b.callback_data)
        if getattr(b, "web_app", None):
            return _make_btn(b.text, st, web_app=b.web_app)
        if getattr(b, "switch_inline_query", None) is not None:
            return _make_btn(b.text, st,
                             switch_inline_query=b.switch_inline_query)
    except Exception:
        return b
    return b


def _walk_buttons(obj, _depth=0):
    """Every button inside a markup/list (nested ones too)."""
    if obj is None or _depth > 6:
        return []
    if isinstance(obj, InlineKeyboardButton):
        return [obj]
    out = []
    if hasattr(obj, "inline_keyboard"):
        out.extend(_walk_buttons(obj.inline_keyboard, _depth + 1))
    elif isinstance(obj, (list, tuple)):
        for item in obj:
            out.extend(_walk_buttons(item, _depth + 1))
    return out


def _styled_markup(rows):
    return apply_styles(InlineKeyboardMarkup(rows))


def kb_plain(markup):
    """Same keyboard, bina custom-emoji icon (fallback ke liye)."""
    if markup is None or not hasattr(markup, "inline_keyboard"):
        return markup
    try:
        rows = []
        for row in markup.inline_keyboard:
            new_row = []
            for b in row:
                icon = getattr(b, "icon_custom_emoji_id", None)
                if not icon:
                    new_row.append(b)
                    continue
                txt = str(getattr(b, "text", "") or "")
                glyph = next((g for g, tid in _TG_UI_KEY.items()
                              if tid == icon), "")
                if glyph:
                    txt = f"{glyph} {txt}".strip()
                kw = {}
                for k in ("url", "callback_data", "web_app", "login_url",
                          "switch_inline_query", "switch_inline_query_current_chat",
                          "copy_text", "pay"):
                    v = getattr(b, k, None)
                    if v is not None:
                        kw[k] = v
                try:
                    new_row.append(_StyledButton(
                        txt, style=getattr(b, "style", None), **kw))
                except Exception:
                    new_row.append(b)
            rows.append(new_row)
        return InlineKeyboardMarkup(rows)
    except Exception:
        return markup


def _plain_btn(b):
    """v40 final net: strip every emoji/icon from a button that slipped past
    _make_btn (raw InlineKeyboardButton, helper-built labels, aliases)."""
    try:
        if getattr(b, "icon_custom_emoji_id", None):
            object.__setattr__(b, "icon_custom_emoji_id", None)
    except Exception:
        pass
    try:
        txt = str(getattr(b, "text", "") or "")
        clean = _btn_text(txt)
        if clean != txt:
            object.__setattr__(b, "text", clean)
    except Exception:
        pass
    return b


def apply_styles(markup):
    if markup is None or not hasattr(markup, "inline_keyboard"):
        return markup
    try:
        rows = [[_plain_btn(styled_button(_clean_btn_obj(b))) for b in row]
                for row in markup.inline_keyboard]
        return InlineKeyboardMarkup(align_rows(rows))
    except Exception:
        return markup



