# ── v15 colour policy ───────────────────────────────────────────────
_V15_SUCCESS_EXACT = {
    "browse accounts", "deposit", "buy now", "buy account", "bulk buy",
    "confirm", "approve", "verify / joined", "verify payment", "pay now",
    "deposit again", "new deposit", "add funds", "purchase accounts"}
_V15_SUCCESS_RE = re.compile(
    r"^(?:buy\b|confirm\b|approve\b|verify payment|pay\b|"
    r"bulk \u00b7|deposit \u20b9|add \u20b9|\u20b9)")
_V15_DANGER_RE = re.compile(
    r"^(?:(?:cancel|delete|remove|reject|ban|stop|terminate|turn off|sos)\b"
    r"|deposits \(\d+\)|error log \(\d+\)|maintenance \u00b7 on"
    r"|terms of service$)")
_V15_NONE_EXACT = {"back", "main menu", "\u00ab prev", "next \u00bb",
                   "prev", "next", "\u00b7", "-", ""}
_PAGE_LABEL_RE = re.compile(r"^(?:\d+ / \d+|\[\d+\])$")
_PAGER_BTN_RE = re.compile(r"^(?:.* / .*|\u00ab.*|\u00bb.*|\u00ab|\u00bb)$", re.I)


def _final_style(text, style):
    t = str(text or "").strip()
    t = _lead_strip(t) if _lead_strip(t) else t     # v32: emoji ignore
    low = re.sub(r"\s+", " ", t.lower())
    
    # 1. Agar '!' laga hai (Force Color), toh use waisa hi rakho
    if style and isinstance(style, str) and style.endswith("!"):
        return style[:-1]
        
    # 2. Country flags wale buttons ko chhod kar
    if FLAG_RE.search(t):
        return BTN_NONE
        
    # 3. Page Numbers aur Prev/Next ko hamesha RED (Danger) karo
    if _PAGE_LABEL_RE.match(low) or low.isdigit() or low in ("« prev", "next »", "prev", "next", "[1]"):
        return BTN_DANGER
        
    # 4. Back, Cancel, Decline ko hamesha RED (Danger) karo
    if low in ("back", "cancel", "stop", "close", "decline") or low.startswith("back "):
        return BTN_DANGER
        
    # 5. Main Menu, Refresh, Search, Filters ko hamesha BLUE (Primary) karo
    if low in ("main menu", "menu", "home", "refresh", "search", "filters", "sort"):
        return BTN_PRIMARY

    # 6. Baaki standard rules (Buy, Deposit = Green)
    if _V15_DANGER_RE.match(low):
        return BTN_DANGER
    if low in _V15_SUCCESS_EXACT or _V15_SUCCESS_RE.match(low):
        return BTN_SUCCESS
        
    # 7. Jo bache wo sab BLUE (Primary) ho jaye, koi GREY nahi bachega
    return BTN_PRIMARY




def _btn_compact(text) -> bool:
    t = _lead_strip(text) if _lead_strip(text) else str(text or "")
    return (len(t) <= 7 or bool(_FLAG_PAIR_RE.match(t))
            or t.strip("[]").isdigit())


def _is_nav_btn(b) -> bool:
    if getattr(b, "callback_data", None) is None:
        return False
    low = str(getattr(b, "text", "") or "").strip().lower()
    return low in ("back", "main menu") or low.startswith("back ")


def _is_pager_row(r) -> bool:
    if not r or len(r) > 8:
        return False
    for b in r:
        text = str(b.text or "").strip()
        # Brackets, arrows, slashes aur words hata kar check karo
        text = _lead_strip(text) if _lead_strip(text) else text
        clean = re.sub(r"[\[\]\s/\u00ab\u00bb]|prev|next|page", "", text, flags=re.I)
        # Agar bacha hua text sirf number hai (ya khali hai), toh ye pager hai
        if clean and not clean.isdigit():
            return False
    return True



def _is_tools_row(r) -> bool:
    cbs = [str(getattr(b, "callback_data", "") or "") for b in r]
    return (len(r) == 3 and all(len(str(b.text or "")) <= 18 for b in r)
            and all(re.match(r"^(csch|cf_|csort_|shop_tg)", c) for c in cbs))


def _vis_label(b) -> str:
    """Button ka wahi label jo user dekhta hai (icon wala emoji + text)."""
    vis = getattr(b, "_v36_vis", None)
    if vis:
        return str(vis)
    return str(getattr(b, "text", "") or "")


def align_rows(rows):
    rows = [list(r) for r in rows if r]
    nav, body = [], []
    for r in rows:
        if _is_pager_row(r) or _is_tools_row(r):
            body.append(r)
            continue
            
        keep = [b for b in r if not _is_nav_btn(b)]
        nav.extend(b for b in r if _is_nav_btn(b))
        if keep:
            body.append(keep)
    if not body:
        body, nav = [nav], []
    out = []
    for r in body:
        if len(r) <= 1:
            out.append(r)
            continue
            
        if _is_pager_row(r) or _is_tools_row(r):
            out.append(r)
            continue
            
        flags = all(FLAG_RE.match(_vis_label(b)) for b in r)
        for i in range(0, len(r), 2):
            pair = r[i:i + 2]
            if not flags and len(pair) == 2 and \
                    max(len(_vis_label(b)) for b in pair) > LABEL_MAX_HALF:
                out.extend([b] for b in pair)
            else:
                out.append(pair)
    if nav:
        for i in range(0, len(nav), 2):
            pair = nav[i:i + 2]
            if len(pair) == 2 and \
                    max(len(_vis_label(b)) for b in pair) > LABEL_MAX_HALF:
                out.extend([b] for b in pair)
            else:
                out.append(pair)
                
    greens = 0
    final = []
    for r in out:
        nr = []
        for b in r:
            if getattr(b, "_v14_forced", False):
                nr.append(b)
                continue
            if _btn_style_of(b) == BTN_SUCCESS:
                greens += 1
                if greens > 2:
                    b = _restyle_btn(b, BTN_PRIMARY)
            nr.append(b)
        final.append(nr)
    return final


def _restyle_btn(b, want):
    """Rebuild a button with another colour (callback/url kept as is)."""
    try:
        d = b.to_dict()
        d.pop("style", None)
        text = d.pop("text", "")
        kw = {}
        for k in ("url", "callback_data", "switch_inline_query",
                  "switch_inline_query_current_chat", "pay"):
            if d.get(k) is not None:
                kw[k] = d[k]
        if getattr(b, "copy_text", None) is not None:
            kw["copy_text"] = b.copy_text
        if getattr(b, "web_app", None) is not None:
            kw["web_app"] = b.web_app
        if getattr(b, "login_url", None) is not None:
            kw["login_url"] = b.login_url
        if not kw:
            return b
        return _StyledButton(text, style=want, **kw)
    except Exception:
        return b

def _clean_btn_obj(b):
    # _make_btn already applied btn_clean() when the button was created.
    # Recreating the object would drop _v11_style / _v14_forced (grey button bug).
    return b


def _btn_style_of(b):
    st = getattr(b, "_v11_style", None)
    if st:
        return st
    try:
        return (getattr(b, "api_kwargs", None) or {}).get("style") \
            or getattr(b, "style", None)
    except Exception:
        return None

def _recolor_btn(b):
    """Apply the v15 colour policy to any button object."""
    # Never override a button whose colour was explicitly forced with "!"
    if getattr(b, "_v14_forced", False):
        return b
    want = _final_style(getattr(b, "text", ""), None)
    if want == _btn_style_of(b):
        return b
    return _restyle_btn(b, want)



def align_markup(markup):
    if not isinstance(markup, InlineKeyboardMarkup):
        return markup
    rows = [[_recolor_btn(_clean_btn_obj(b)) for b in r]
            for r in markup.inline_keyboard]
    return InlineKeyboardMarkup(align_rows(rows))





# ── v15 button labels: clean_label() is applied to EVERY inline button ──
FLAG_RE = re.compile("[\U0001F1E6-\U0001F1FF]{2}")
EMOJI_RE = re.compile(
    "[\U0001F000-\U0001FAFF"
    "\u2600-\u27BF\u2B00-\u2BFF\u2190-\u21FF\u2300-\u23FF\u25A0-\u25FF"
    "\uFE0E\uFE0F\u200D\u20E3\u2122\u2139\u3030\u303D\u3297\u3299"
    "\u00A9\u00AE\u203C\u2049\u2934\u2935\u2726\u203A\u2605\u2713\u2715"
    "\U000E0020-\U000E007F]")
_LABEL_CAPS_RE = re.compile(r"\b[A-Z]{4,}\b")
_LABEL_KEEP_CAPS = {"USDT", "TRON", "HTML", "JSON", "TRC20", "BEP20", "UPI"}
LABEL_MAX_FULL = 32          # full-width row
LABEL_MAX_HALF = 18          # 2-column row
# Visible text only - callback_data never changes.
LABEL_SHORT = {
    "sync supplier balance": "Sync Balance",
    "test deposit qr": "Test Deposit QR",
    "bulk buy settings": "Bulk Buy Settings",
    "sort by \u00b7 price low to high": "Sort \u00b7 Low",
    "sort by \u00b7 price high to low": "Sort \u00b7 High",
    "server 1 - cheap": "Server 1 \u00b7 Cheap",
    "server 2 - good": "Server 2 \u00b7 Good",
    "back to list": "Back",
    "back to filters": "Back",
    "back to order": "Back",
    "back to orders": "Back",
    "back to admin": "Back",
    "previous": "\u00ab Prev",
    "prev": "\u00ab Prev",
    "next": "Next \u00bb",
}


def clean_label(text, allow_flags=False) -> str:
    """Inline button label policy (v15).

    - no emoji / pictographs; regional-indicator flag pairs are kept only
      when allow_flags is True (country buttons)
    - "•" and "|" separators become "·"
    - ALL CAPS words (4+ letters) become Title Case, short acronyms stay
    - no trailing punctuation, single spaces, max 32 characters"""
    t = str(text or "").replace("\u2022", "\u00b7")
    if not allow_flags:          # country buttons keep "BR+55 | \u20b914.00"
        t = t.replace("|", "\u00b7")
    flags: List[str] = []
    if allow_flags:
        def _keep(m):
            flags.append(m.group(0))
            return f"\x00{len(flags) - 1}\x00"
        t = FLAG_RE.sub(_keep, t)
    t = EMOJI_RE.sub("", t)
    t = re.sub(r"\x00(\d+)\x00", lambda m: flags[int(m.group(1))], t)
    t = re.sub(r"\s*\u00b7\s*", " \u00b7 ", t)
    t = re.sub(r"\s{2,}", " ", t).strip(" \u00b7-")
    t = _LABEL_CAPS_RE.sub(
        lambda m: m.group(0) if m.group(0) in _LABEL_KEEP_CAPS
        else m.group(0).capitalize(), t)
    t = t.rstrip(".!:;,").rstrip()
    t = LABEL_SHORT.get(t.lower(), t)
    if len(t) > LABEL_MAX_FULL:
        t = t[:LABEL_MAX_FULL - 1].rstrip(" \u00b7-") + "\u2026"
    return t


def btn_clean(text) -> str:
    """Every button label goes through clean_label(); flags are allowed
    only on country buttons (labels that start with a flag)."""
    raw = str(text or "")
    t = clean_label(raw, allow_flags=bool(FLAG_RE.match(raw.lstrip())))
    return t or "\u00b7"






