def kb_pager(page, pages, cb_of):
    page, pages = int(page or 0), max(1, int(pages or 1))
    if pages <= 1:
        return []
    row = []
    if page > 0:
        row.append(("\u00ab Prev", cb_of(page - 1), BTN_DANGER + "!"))
    row.append((f"{page + 1} / {pages}", "noop", BTN_DANGER + "!"))
    if page + 1 < pages:
        row.append(("Next \u00bb", cb_of(page + 1), BTN_DANGER + "!"))
    return row


def kb_num_pager(page, pages, cb_of):
    """Numbered page row: [1] 2 3 4 5 6 7 8 (current page in brackets,
    max 8 buttons). cb_of(i) returns the EXISTING page callback."""
    page, pages = int(page or 0), max(1, int(pages or 1))
    if pages <= 1:
        return []
    start = max(0, min(page - 3, max(0, pages - 8)))
    row = []
    for i in range(start, min(pages, start + 8)):
        if i == page:
            row.append((f"[{i + 1}]", "noop", BTN_NONE))
        else:
            row.append((str(i + 1), cb_of(i), BTN_NONE))
    return row


def short_count(n) -> str:
    """1200 -> 1.2k, 14843 -> 14.8k, 77691 -> 77.7k, 1250000 -> 1.2M"""
    try:
        n = int(n or 0)
    except (TypeError, ValueError):
        return "0"
    if n >= 1_000_000:
        return f"{n / 1_000_000:.1f}M".replace(".0M", "M")
    if n >= 10_000:
        return f"{n / 1000:.0f}k"
    if n >= 1000:
        return f"{n / 1000:.1f}k".replace(".0k", "k")
    return str(n)


def country_label(code, price, stock=None) -> str:
    """Button label: flag CODE | ₹price · 12.3k accounts (live stock)."""
    try:
        p = float(price or 0)
    except (TypeError, ValueError):
        p = 0.0
    if p <= 0:
        base = f"{btn_label(code)} | Sold Out"
    else:
        base = btn_label(code, p)
    if stock is None:
        return base
    try:
        n = int(stock)
    except (TypeError, ValueError):
        return base
    if n <= 0:
        return f"{btn_label(code)} | 0 stock"
    return f"{base} · {short_count(n)}"



def kb_page(prefix, page, pages, back_cb="main_menu", extra=None):
    rows = []
    if extra:
        rows.extend(_norm_rows(extra))
    pr = kb_pager(page, pages, lambda i: f"{prefix}{i}")
    if pr:
        rows.append(_norm_row(pr))
    rows.append([_make_btn("Main Menu", BTN_NONE, callback_data=back_cb)])
    return ikb(*rows)



