def build_session_db(auth_key: bytes, dc_id: int) -> bytes:
    dc_id = int(dc_id) if int(dc_id) in TG_DC_ADDRESSES else 2
    addr, port = TG_DC_ADDRESSES[dc_id]
    conn = sqlite3.connect(":memory:")
    try:
        c = conn.cursor()
        c.executescript("""
            CREATE TABLE version (version integer primary key);
            CREATE TABLE sessions (
                dc_id integer primary key, server_address text, port integer,
                auth_key blob, takeout_id integer);
            CREATE TABLE entities (
                id integer primary key, hash integer not null, username text,
                phone integer, name text, date integer);
            CREATE TABLE sent_files (
                md5_digest blob, file_size integer, type integer, id integer,
                hash integer, primary key(md5_digest, file_size, type));
            CREATE TABLE update_state (
                id integer primary key, pts integer, qts integer, date integer,
                seq integer);
        """)
        c.execute("INSERT INTO version VALUES (?)", (7,))
        c.execute("INSERT INTO sessions VALUES (?, ?, ?, ?, NULL)",
                  (dc_id, addr, port, sqlite3.Binary(auth_key)))
        conn.commit()
        try:
            return conn.serialize()
        except AttributeError:
            import tempfile
            fd, path = tempfile.mkstemp(suffix=".session")
            os.close(fd)
            try:
                dst = sqlite3.connect(path)
                conn.backup(dst)
                dst.close()
                with open(path, "rb") as fh:
                    return fh.read()
            finally:
                try:
                    os.remove(path)
                except OSError:
                    pass
    finally:
        conn.close()


def build_session_string(auth_key, dc_id: int) -> str:
    """Telethon ``StringSession`` value for this auth key.

    Byte-for-byte the same packing Telethon uses
    (``sessions/string.py``)::

        "1" + urlsafe_b64( struct.pack(">B{4|16}sH256s",
                                       dc_id, ip, port, auth_key) )

    So ``StringSession(<this string>)`` logs in with no SMS code.
    """
    key = bytes(auth_key or b"")
    if len(key) != 256:
        raise ValueError("auth key must be 256 bytes")
    try:
        dc_id = int(dc_id)
    except (TypeError, ValueError):
        dc_id = 2
    if dc_id not in TG_DC_ADDRESSES:
        dc_id = 2
    addr, port = TG_DC_ADDRESSES[dc_id]
    ip = ipaddress.ip_address(addr).packed
    blob = struct.pack(f">B{len(ip)}sH256s", dc_id, ip, int(port), key)
    return "1" + base64.urlsafe_b64encode(blob).decode("ascii")


def session_string_from_item(item) -> str:
    """StringSession string for a supplier item ('' when there is no key)."""
    item = item or {}
    raw = _session_raw_key(item)
    key = parse_auth_key(raw)
    if not key:
        return ""
    dc = parse_dc_id(_session_raw_dc(item))
    return build_session_string(key, dc)


def session_files_from_item(item, base_name, data=None):
    """Build the Telethon .session (SQLite) + the matching settings .json.

    v24 fixes:
      * the auth key is also read from the deep item tree / extra_data
      * the DC id falls back to ``password`` (the supplier puts the DC
        there when the login field holds the auth key)
      * the .json carries every field opentele / Telethon needs, including
        ``phone`` and ``twoFA`` when they are known
    """
    item = item or {}
    ld = item.get("loginData") or item.get("login_data") or {}
    if not isinstance(ld, dict):
        ld = {}
    data = data or {}
    raw_key = _session_raw_key(item)
    if not _looks_like_auth_key(raw_key):
        # last resort: a key stored on the order itself
        for cand in (data.get("auth_key"), data.get("login"),
                     item.get("telegram_auth_key")):
            if _looks_like_auth_key(cand):
                raw_key = cand
                break
    auth_key = parse_auth_key(raw_key)
    if not auth_key:
        raise ValueError("no auth_key in item data")
    dc_id = parse_dc_id(_session_raw_dc(item))
    db = build_session_db(auth_key, dc_id)
    tj = None
    for tk in ("telegram_json", "telegramJson", "telegram_JSON"):
        if item.get(tk) not in (None, ""):
            tj = item.get(tk)
            break
    cfg = {}
    if isinstance(tj, dict):
        cfg = dict(tj)
    elif isinstance(tj, str) and tj.strip():
        try:
            cfg = json.loads(tj)
            if not isinstance(cfg, dict):
                cfg = {}
        except (TypeError, ValueError):
            cfg = {}
    out = dict(cfg)
    out.setdefault("app_id", SESSION_API_ID)
    out.setdefault("app_hash", SESSION_API_HASH)
    try:
        out["app_id"] = int(out.get("app_id"))
    except (TypeError, ValueError):
        out["app_id"] = SESSION_API_ID
    out["session_file"] = base_name
    out.setdefault("device", "Desktop")
    out.setdefault("sdk", "Windows 10")
    out.setdefault("app_version", "5.12.3 x64")
    out.setdefault("system_lang_pack", "en-US")
    out.setdefault("system_lang_code", "en-US")
    out.setdefault("lang_pack", "tdesktop")
    out.setdefault("lang_code", "en")
    # ── phone (opentele needs it; Telethon ignores it) ──
    phone = ""
    for cand in (data.get("phone"), out.get("phone"), _find_phone(item)):
        if _looks_like_phone(cand):
            phone = _with_country_code(str(cand).strip(), item)
            break
    if phone:
        out["phone"] = phone
    else:
        out.pop("phone", None)
    # ── 2FA password (only a flag; the password itself never leaves the bot) ──
    if data.get("two_fa") or data.get("password"):
        out["twoFA"] = True
    out.setdefault("twoFA", False)
    js = json.dumps(out, indent=2, ensure_ascii=False).encode("utf-8")
    return db, js, {"dc_id": dc_id, "settings": bool(cfg), "phone": phone,
                    "session_string": build_session_string(auth_key, dc_id)}


async def send_session_file(bot, chat_id, o, markup=None,
                            quiet=False):
    try:
        o = dict(o)
    except Exception:
        pass
    oid = o["id"]
    base = f"tg-session-{oid}"
    item = {}
    _siid = _order_iid(o)
    if _siid:
        try:
            r = await sup.item(_siid)
            if r.get("ok") and r.get("item"):
                item = merge_item_data({}, r["item"])
        except Exception as e:
            log.warning("send_session_file: item fetch failed: %s",
                        str(e)[:80])
    if not item:
        stored = {}
        try:
            stored = json.loads(o.get("login_data") or "{}") or {}
        except (TypeError, ValueError):
            stored = {}
        extra = {}
        try:
            extra = json.loads(o.get("extra_data") or "{}") or {}
        except (TypeError, ValueError):
            extra = {}
        item = {"loginData": {"login": extra.get("auth_key") or "",
                              "password": extra.get("dc_id") or ""},
                "telegram_json": extra.get("telegram_json")}
        data_fallback = stored
    else:
        data_fallback = Supplier.parse_login_data(item)
    try:
        db, js, meta = session_files_from_item(item, base, data_fallback)
    except ValueError:
        if quiet:
            return False
        return await send(bot, chat_id,
                          f"{ICON['warn']} "
                          "<b>SESSION FILE NOT AVAILABLE</b>\n"
                          + DIV + "\nThis order has no session data "
                          "(auth key) linked.\n"
                          + "Use <b>Get Login Code</b> to sign in instead.\n"
                          + DIV, markup)
    except Exception as e:
        log.warning("send_session_file: build failed: %s", str(e)[:120])
        if quiet:
            return False
        return await send(bot, chat_id,
                          f"{ICON['warn']} "
                          "<b>SESSION FILE NOT AVAILABLE</b>\n"
                          + DIV + "\nCould not build the session file right now. "
                          "Try again.\n" + DIV, markup)
    string_val = meta.get("session_string") or ""
    zip_name = f"{base}.zip"
    try:
        raw = await asyncio.to_thread(
            session_zip_bytes, base, db, js, string_val, data_fallback, o)
    except Exception as e:
        log.warning("send_session_file: zip build failed: %s", str(e)[:120])
        raw = b""
    caption = ("<b>ALL FILES IN ONE ZIP</b>  -  ORDER "
               f"<code>#{oid}</code>\n" + LINE + "\n"
               + box([f"<code>{base}.session</code>  Telethon session",
                      f"<code>{base}.json</code>  settings",
                      f"<code>{base}.session_string.txt</code>  string"
                      if string_val else "session string: not available",
                      "LOGIN.txt  number / 2FA / email / link"])
               + "\n<b>HOW TO USE</b>\n"
               + box([f"1. Unzip <code>{zip_name}</code>",
                      f"2. <code>TelegramClient('{base}', api_id, "
                      "api_hash)</code>",
                      "3. <code>client.start()</code> - already logged in, "
                      "no SMS code.",
                      "4. opentele: <code>FromSessionJson</code> reads "
                      "the .json."])
               + "\n<i>One file, everything inside. Keep it private.</i>")
    if raw:
        try:
            await bot.send_document(
                chat_id, document=make_input_file(raw, zip_name),
                filename=zip_name, caption=caption,
                parse_mode=ParseMode.HTML, reply_markup=markup)
            return True
        except Exception as e:
            log.warning("send session zip failed: %s", str(e)[:90])
    txt = ("<b>SESSION FILE</b>  -  ORDER "
           f"<code>#{oid}</code>\n" + LINE
           + "\nFile upload failed. Session data:\n"
           + box([f"DC id: <code>{meta['dc_id']}</code>",
                  "Auth key: hidden for safety"])
           + "\nTap Download Session File again in a minute.\n" + LINE)
    return await send(bot, chat_id, txt, markup)


async def _recover_phone(o) -> str:
    try:
        o = dict(o)
    except Exception:
        pass
    ph = str(o.get("phone_number") or "").strip()
    if ph and ph != "N/A" and not _looks_like_auth_key(ph):
        return ph
    iid = _order_iid(o)
    if not iid:
        return ""
    try:
        found, _it = await resolve_phone(iid, {}, tries=2)
        if found:
            try:
                db_upd_order(o["id"], phone_number=found)
            except Exception:
                pass
            return found
    except Exception as e:
        log.warning("phone recovery failed for #%s: %s",
                    o.get("id"), str(e)[:80])
    return ph


async def resolve_phone(iid, item=None, tries: int = 2) -> Tuple[str, dict]:
    """Find the phone number of a bought account.

    v28: the three lookups run IN PARALLEL with a hard 8 s cap (before
    they were tried one after another with 1.5 s / 3 s sleeps, which
    could hold a delivery slot for ~13 s). Almost every buy already
    carries the number, so this only runs for the rare exception.
    """
    item = dict(item or {})
    phone = _find_phone(item)
    if phone:
        return phone, item
    sources = [sup.item, sup.item_bulk, sup.item_via_code]

    async def _one(src):
        try:
            r = await asyncio.wait_for(src(iid), timeout=8)
        except Exception as e:
            log.info("resolve_phone %s %s: %s", iid,
                     getattr(src, "__name__", "?"), str(e)[:80])
            return None
        if isinstance(r, dict) and r.get("ok") and r.get("item"):
            return _find_phone(r["item"]) or "", r["item"]
        return None

    for n in range(max(1, tries)):
        for got in await asyncio.gather(*[_one(s) for s in sources],
                                        return_exceptions=True):
            if not (isinstance(got, tuple) and len(got) == 2):
                continue
            item = merge_item_data(item, got[1])
            if got[0]:
                return got[0], item
        if n + 1 < max(1, tries):
            await asyncio.sleep(0.6 * (n + 1))
    return "", item


