_ANSWERED: Dict[str, float] = {}


async def qans(q, text=None, alert=False):
    try:
        qid = str(getattr(q, "id", "") or "")
        if qid:
            if len(_ANSWERED) > 5000:
                _ANSWERED.clear()
            _ANSWERED[qid] = time.monotonic()
    except Exception:
        pass
    try:
        await q.answer(text=text, show_alert=alert)
    except Exception:
        pass


def _msg_media_kind(msg):
    """Message me photo/video/document hai? (tab caption edit hoti hai)."""
    for k in ("photo", "video", "animation", "document", "audio", "voice",
              "video_note", "sticker"):
        if getattr(msg, k, None):
            return k
    return ""


async def edit_q(q, text, markup=None):
    text = clean_text(text)
    markup = apply_styles(markup)
    kind = _msg_media_kind(getattr(q, "message", None))
    if kind and kind != "sticker":
        try:                       # photo/document wale message: caption
            await q.edit_message_caption(
                caption=_cap_safe(text, 1024), parse_mode=ParseMode.HTML,
                reply_markup=markup)
            return
        except BadRequest as e:
            if "not modified" in str(e).lower():
                return
            log.warning("edit_q caption failed (%s): %s", kind, str(e)[:90])
        except Exception as e:
            log.warning("edit_q caption error (%s): %s", kind, str(e)[:90])
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML,
                                  reply_markup=markup,
                                  disable_web_page_preview=True)
    except BadRequest as e:
        m = str(e).lower()
        if "not modified" in m:
            return
        if "message to edit not found" in m or "no text in the message" in m:
            try:
                await q.message.reply_text(text, parse_mode=ParseMode.HTML,
                                           reply_markup=markup,
                                           disable_web_page_preview=True)
            except Exception:
                pass
            return
        if "<tg-emoji" in text:
            try:
                await q.edit_message_text(strip_tg_emoji(text),
                                          parse_mode=ParseMode.HTML,
                                          reply_markup=markup,
                                          disable_web_page_preview=True)
                return
            except Exception as e2:
                log.warning("edit_q (no premium) failed: %s", str(e2)[:90])
        log.warning("edit_q BadRequest: %s", e)
    except Exception as e:
        log.warning("edit_q error: %s", e)


async def edit_any(obj, text, markup=None):
    text = clean_text(text)
    markup = apply_styles(markup)
    try:
        if hasattr(obj, "edit_message_text"):
            await obj.edit_message_text(text, parse_mode=ParseMode.HTML,
                                        reply_markup=markup,
                                        disable_web_page_preview=True)
        else:
            await obj.edit_text(text, parse_mode=ParseMode.HTML,
                                reply_markup=markup,
                                disable_web_page_preview=True)
    except BadRequest as e:
        if "not modified" not in str(e).lower():
            log.warning("edit_any BadRequest: %s", e)
    except Exception as e:
        log.warning("edit_any error: %s", e)


async def edit_msg(bot, chat_id, mid, text, markup=None):
    text = clean_text(text)
    markup = apply_styles(markup)
    try:
        await bot.edit_message_text(text, chat_id=chat_id, message_id=mid,
                                    parse_mode=ParseMode.HTML,
                                    reply_markup=markup,
                                    disable_web_page_preview=True)
    except BadRequest as e:
        m = str(e).lower()
        if "not modified" in m:
            return
        if "no text in the message" in m or "there is no text" in m:
            try:                   # photo/caption wala message
                await bot.edit_message_caption(
                    chat_id=chat_id, message_id=mid,
                    caption=_cap_safe(text, 1024), parse_mode=ParseMode.HTML,
                    reply_markup=markup)
                return
            except Exception as e3:
                log.warning("edit_msg caption failed: %s", str(e3)[:90])
        if "<tg-emoji" in text:
            try:
                await bot.edit_message_text(
                    strip_tg_emoji(text), chat_id=chat_id, message_id=mid,
                    parse_mode=ParseMode.HTML, reply_markup=markup,
                    disable_web_page_preview=True)
                return
            except Exception as e2:
                log.warning("edit_msg (no premium) failed: %s", str(e2)[:90])
        await send(bot, chat_id, text, markup)
    except Exception:
        pass


async def send(bot, chat_id, text, markup=None):
    text = clean_text(text)
    markup = apply_styles(markup)
    try:
        return await bot.send_message(chat_id, text, parse_mode=ParseMode.HTML,
                                      reply_markup=markup,
                                      disable_web_page_preview=True)
    except Exception as e:
        # v32: premium emoji ki wajah se Telegram ne reject kiya? -> bina
        # custom emoji ke dobara bhejo (normal emoji wapas aa jate hain)
        err = str(e).lower()
        icon_issue = ("emoji" in err or "icon" in err)
        if icon_issue and markup is not None:
            try:                       # v35: buttons se icon hata kar try
                return await bot.send_message(
                    chat_id, strip_tg_emoji(text), parse_mode=ParseMode.HTML,
                    reply_markup=kb_plain(markup),
                    disable_web_page_preview=True)
            except Exception as e0:
                log.warning("send (no btn icon) -> %s: %s", chat_id, str(e0)[:90])
        if "<tg-emoji" in text:
            try:
                return await bot.send_message(
                    chat_id, strip_tg_emoji(text), parse_mode=ParseMode.HTML,
                    reply_markup=kb_plain(markup) if icon_issue else markup,
                    disable_web_page_preview=True)
            except Exception as e2:
                log.warning("send (no premium) -> %s failed: %s", chat_id, e2)
                return None
        log.warning("send -> %s failed: %s", chat_id, e)
        return None


QR_FALLBACK_API = os.environ.get(
    "QR_FALLBACK_API", "https://api.qrserver.com/v1/create-qr-code/")


def local_qr_bytes(link, scale=9, border=3):
    if not link or segno is None:
        return None
    try:
        import io as _io
        q = segno.make_qr(str(link), error="m")
        buf = _io.BytesIO()
        q.save(buf, kind="png", scale=scale, border=border)
        data = buf.getvalue()
        return data if data[:4] == b"\x89PNG" else None
    except Exception as e:
        log.warning("local QR failed: %s", e)
        return None


async def fetch_bytes(url, timeout=20, headers=None, tries=3):
    if not url or not str(url).startswith("http"):
        return None
    if headers is None and "famgateway.in" in str(url):
        headers = {"X-Api-Key": FAMPAY_API_KEY, "Accept": "*/*",
                   "User-Agent": f"{SHOP_NAME} bot"}
    for n in range(max(1, tries)):
        try:
            async with aiohttp.ClientSession(
                timeout=aiohttp.ClientTimeout(total=timeout)
            ) as s:
                async with s.get(url, headers=headers) as r:
                    if r.status != 200:
                        return None
                    data = await r.read()
                    if data and len(data) > 40:
                        return data
                    log.debug("media download: empty body (try %s)", n)
        except asyncio.TimeoutError:
            pass
        except Exception as e:
            log.debug("media download retry: %s", str(e)[:80])
        if n + 1 < max(1, tries):
            await asyncio.sleep(1.5 * (n + 1))
    return None


def upi_intent_string(upi_id, amount, name=None, ref="") -> str:
    if not upi_id:
        return ""
    q = [f"pa={_urlquote(str(upi_id))}", "cu=INR",
         "pn=" + _urlquote(str(name or SHOP_NAME))]
    try:
        q.append("am=" + _urlquote(f"{float(amount):.2f}"))
    except (TypeError, ValueError):
        pass
    if ref:
        q.append("tn=" + _urlquote(f"{ref}"))
    return "upi://pay?" + "&".join(q)


async def qr_image_bytes(qr_url="", upi_id="", amount=0, ref="", intent=""):
    data = await fetch_bytes(qr_url)
    if data and (data[:4] == b"\x89PNG" or len(data) > 200):
        return data
    link = intent or upi_intent_string(upi_id, amount, ref=ref)
    if not link:
        return None
    data = local_qr_bytes(link)
    if data:
        return data
    url = f"{QR_FALLBACK_API}?size=600x600&margin=8&data={_urlquote(link)}"
    return await fetch_bytes(url)


def make_input_file(data: bytes, filename: str):
    try:
        from telegram import InputFile
        return InputFile(data, filename=filename)
    except ImportError:
        from telegram import BufferedInputFile
        return BufferedInputFile(data, filename=filename)


async def send_qr(bot, chat_id, qr_url, caption, markup=None, upi_id="",
                  amount=0, ref="", intent=""):
    markup = apply_styles(markup)
    if qr_url or upi_id:
        caption = premiumize(caption)
        data = await qr_image_bytes(qr_url, upi_id, amount, ref, intent)
        if data:
            for mk in ((markup, None) if markup is not None else (None,)):
                try:
                    if len(caption) <= 1024:
                        return await bot.send_photo(
                            chat_id,
                            photo=make_input_file(data, "upi-qr.png"),
                            caption=caption, parse_mode=ParseMode.HTML,
                            reply_markup=mk)
                    photo_msg = await bot.send_photo(
                        chat_id,
                        photo=make_input_file(data, "upi-qr.png"))
                    await send(bot, chat_id, caption, mk)
                    return photo_msg
                except Exception as e:
                    log.warning("send_photo(bytes) failed: %s", e)
        if qr_url and str(qr_url).startswith("http"):
            try:
                return await bot.send_photo(chat_id, photo=str(qr_url),
                                            caption=caption[:1024],
                                            parse_mode=ParseMode.HTML,
                                            reply_markup=markup)
            except Exception as e:
                log.warning("send_photo(url) failed: %s", e)
    return await send(bot, chat_id, caption, markup)


