# ── Sales channel helpers ────────────────────────────────────────────
def sales_channel_id():
    v = str(db_get_setting("sales_channel", "") or "").strip()
    if not v:
        return None
    try:
        return int(v)
    except (TypeError, ValueError):
        return v


def sales_channel_enabled() -> bool:
    if not sales_channel_id():
        return False
    return str(db_get_setting("sales_channel_on", "1")) not in (
        "0", "off", "no", "false")


def sales_channel_link() -> str:
    v = str(db_get_setting("sales_channel_link", "") or "").strip()
    if v:
        return v
    cid = sales_channel_id()
    if cid is None:
        return ""
    s = str(cid)
    if s.lstrip("-").isdigit():
        return ""  # private channel without public link
    if s.startswith("@"):
        return f"https://t.me/{s.lstrip('@')}"
    return ""


def sales_channel_ads() -> bool:
    return str(db_get_setting("sales_channel_ads", "0")) in (
        "1", "on", "yes", "true")


def sales_channel_title() -> str:
    t = str(db_get_setting("sales_channel_title", "") or "").strip()
    return t or str(SALES_CHANNEL_DEFAULT_TITLE or "Sales & Updates").strip()


def chan_btn_label() -> str:
    """Sales-channel buttons show the channel title - never the text."""
    s = " ".join(str(sales_channel_title() or "").split())
    return s if len(s) <= 26 else s[:25].rstrip() + "…"


def post_shop_ad_enabled() -> bool:
    """Promo posts are OFF by default - the channel only carries
    purchase and deposit notifications."""
    return sales_channel_ads()


def sales_card_image_on() -> bool:
    """v26: post the branded card image with every channel message."""
    return str(db_get_setting("sales_card_image", "1")) not in (
        "0", "off", "no", "false")


def s_log_short(kind, title, lines, limit=780) -> str:
    """Compact caption for the photo post (Telegram allows 1024 chars)."""
    status = _card_status(kind)
    t = _card_plain(title)[:52]
    rows = []
    for lab, val in _sale_rows(lines)[:6]:
        rows.append(esc(f"{lab.title():<11}{val}" if lab else val))
    out = (f"<b>{status}</b>  -  <b>{esc(t)}</b>\n"
           + f"<pre>{chr(10).join(rows)}</pre>\n"
           + f"{now_ist_str('%d %b %Y, %I:%M %p')} \u2022 {esc(SHOP_NAME)}")
    return out[:limit]


async def post_sales_card(bot, kind, title, lines) -> bool:
    """Post a sale / deposit card into the sales channel.

    v26: the message now arrives WITH a branded card image (photo + the
    v24 aligned table as the caption). If the photo cannot be sent - or
    Pillow is missing - the old text-only post is used, so a sale is never
    lost. Setting `sales_card_image = 0` turns the image off.
    """
    if not bot or not sales_channel_enabled():
        return False
    cid = sales_channel_id()
    if not cid:
        return False
    try:
        chat_id = int(cid) if str(cid).lstrip("-").isdigit() else cid
    except (TypeError, ValueError):
        chat_id = cid
    body = s_log_card(kind, title, lines)
    kb = kb_channel_card(bot, buy=True)
    if chat_id and HAS_PIL and sales_card_image_on():
        img = None
        try:
            img = await asyncio.to_thread(render_sales_card, kind, title,
                                          lines)
        except Exception as e:
            log.warning("sales card render failed: %s", str(e)[:120])
        if img:
            cap = body if len(body) <= 1000 else s_log_short(
                kind, title, lines)
            cap = _cap_safe(premiumize(cap), 1000)
            try:
                await bot.send_photo(
                    chat_id, photo=make_input_file(
                        img, f"sale_{int(time.time())}.jpg"),
                    caption=cap, parse_mode=ParseMode.HTML,
                    reply_markup=kb)
                if len(body) > 1000:
                    await bot.send_message(
                        chat_id, body, parse_mode=ParseMode.HTML,
                        reply_markup=kb, disable_web_page_preview=True)
                return True
            except Exception as e:
                log.warning("post_sales_card photo failed: %s",
                            str(e)[:120])
    try:
        if chat_id:
            await bot.send_message(chat_id, body, parse_mode=ParseMode.HTML,
                                   reply_markup=kb,
                                   disable_web_page_preview=True)
            return True
    except Exception as e:
        log.warning("post_sales_card failed: %s", str(e)[:120])
    # ── fallback: plain text post (no parse mode, no markup) ──
    try:
        plain = html.unescape(re.sub(r"<[^>]+>", "", body))
        plain = re.sub(r"\n{3,}", "\n\n", plain).strip()
        if chat_id and plain:
            await bot.send_message(chat_id, plain[:4000],
                                   reply_markup=kb,
                                   disable_web_page_preview=True)
            log.info("post_sales_card: posted as plain text")
            return True
    except Exception as e:
        log.warning("post_sales_card plain fallback failed: %s", str(e)[:120])
    return False


