# ── Promo code helpers ───────────────────────────────────────────────
def db_create_promo(code, ptype, value, max_uses=1):
    code = str(code or "").upper().strip()[:24]
    if not code:
        return False
    try:
        with _tx() as c:
            c.execute(
                "INSERT OR REPLACE INTO promo_codes (code,type,value,max_uses,"
                "used_count) VALUES (?,?,?,?,COALESCE((SELECT used_count FROM "
                "promo_codes WHERE code=?),0))",
                (code, str(ptype)[:16], float(value or 0),
                 int(max_uses or 1), code))
        mg_push_promo(code)
        try:
            if mongo.on():
                _spawn(mongo.push_config())
        except Exception:
            pass
        return True
    except Exception as e:
        log.warning("db_create_promo: %s", e)
        return False


def db_promos(lim=20):
    try:
        return _get_conn().execute(
            "SELECT * FROM promo_codes ORDER BY id DESC LIMIT ?",
            (int(lim),)).fetchall()
    except Exception:
        return []


def db_redeem_promo(code, uid):
    code = str(code or "").upper().strip()
    if not code:
        return "invalid"
    try:
        with _tx() as c:
            p = c.execute("SELECT * FROM promo_codes WHERE code=?",
                          (code,)).fetchone()
            if not p:
                return "invalid"
            if int(p["used_count"] or 0) >= int(p["max_uses"] or 1):
                return "exhausted"
            hit = c.execute(
                "SELECT id FROM promo_used WHERE code=? AND user_id=?",
                (code, int(uid))).fetchone()
            if hit:
                return "already_used"
            c.execute("INSERT INTO promo_used (code,user_id) VALUES (?,?)",
                      (code, int(uid)))
            c.execute(
                "UPDATE promo_codes SET used_count=used_count+1 WHERE code=?",
                (code,))
        val = float(p["value"] or 0)
        mg_push_promo(code)
        if _promo_is_pct(p["type"]):
            pct = max(0.0, min(90.0, val))
            _kv_set(f"pdisc:{int(uid)}", json.dumps({"code": code, "pct": pct}))
            return {"value": 0.0, "pct": pct,
                    "new_balance": db_balance(uid)}
        nb = db_credit(uid, val, f"Promo {code}", code)
        return {"value": val, "new_balance": nb}
    except Exception as e:
        log.warning("db_redeem_promo: %s", e)
        return "invalid"



