async def send_countries(bot, chat_id, ctx, srv, page=0):
    srv = int(srv or 1)
    sort = _CSORT_DB[_csort_norm(ctx.user_data.get("csort"))]
    page = max(0, int(page or 0))
    rows_db, total = db_countries_page(page * PAGE_SIZE, PAGE_SIZE,
                                       active_only=True, srv=srv, sort=sort)
    if not rows_db:
        return await send(bot, chat_id,
                          f"{ICON['box']} <b>No countries with stock on "
                          f"Server {srv}.</b>\n{LINE}",
                          ikb(kb_row(("Server 1", "svshop_1", BTN_SUCCESS),
                                     ("Server 2", "svshop_2", BTN_PRIMARY)),
                              kb_row(("Main Menu", "main_menu"))))
    pages = max(1, (total + PAGE_SIZE - 1) // PAGE_SIZE)
    page = max(0, min(page, pages - 1))
    ctx.user_data["shop_srv"] = srv
    return await send(
        bot, chat_id,
        s_shop_list(0, db_balance(ctx.user_data.get("_uid") or 0),
                    total, page, pages,
                    _global_stock.get(f"accounts{srv}") or 0, srv,
                    live_at=_liveprice.get("at", "")),
        kb_country_grid(srv, page, pages, sort))


