def _cap_new(ctx):
    a, b = random.randint(3, 12), random.randint(2, 9)
    if random.random() < 0.5:
        ans, q = a + b, f"{a} + {b}"
    else:
        a, b = max(a, b), min(a, b)
        ans, q = a - b, f"{a} - {b}"
    opts = {ans}
    while len(opts) < 3:
        d = ans + random.choice([-3, -2, -1, 1, 2, 3, 4])
        if d >= 0:
            opts.add(d)
    opts = sorted(opts)
    random.shuffle(opts)
    ctx.user_data["cap"] = {"ans": ans, "q": q, "tries": 0}
    return q, opts


FJ_JOINED = ("member", "administrator", "creator", "owner")


def chan_ref(r):
    cid = r["chat_id"]
    if cid:
        try:
            return int(cid)
        except (TypeError, ValueError):
            pass
    link = str(r["link"] or "").strip()
    if link.startswith("@"):
        return link
    m = re.search(r"(?:t\.me/|telegram\.me/)([A-Za-z0-9_]{4,64})", link)
    if m and not link.startswith(("https://t.me/+",
                                   "https://t.me/joinchat")):
        return "@" + m.group(1)
    return None


async def check_joins(bot, uid):
    missing, unverified = [], []
    for r in db_channels():
        for check in (chan_ref(r),
                      (int(r["chat_id"])
                       if str(r["chat_id"] or "").isdigit() else None)):
            if check is None:
                continue
            try:
                m = await bot.get_chat_member(chat_id=check, user_id=uid)
                st = getattr(m, "status", "")
                st = str(getattr(st, "value", st)).lower()
                joined = st in FJ_JOINED or (
                    st == "restricted"
                    and bool(getattr(m, "is_member", False)))
                if not joined:
                    missing.append(r)
                break
            except Exception as e:
                log.info("join check failed for %s: %s", check,
                         str(e)[:90])
                continue
        else:
            unverified.append(r)
    seen, m2, u2 = set(), [], []
    for group, dest in ((missing, m2), (unverified, u2)):
        for r in group:
            if r["id"] in seen:
                continue
            seen.add(r["id"])
            dest.append(r)
    return m2, u2


async def missing_joins(bot, uid) -> list:
    missing, _ = await check_joins(bot, uid)
    return missing


def fj_strict() -> bool:
    return str(db_get_setting("fj_strict", "1")) not in ("0", "off", "no")


_FJ_ALERT: Dict[int, float] = {}


async def _fj_alert(bot, rows):
    key = 0
    try:
        key = int(rows[0]["id"]) if rows else 0
    except Exception:
        key = 0
    now = time.time()
    if now - _FJ_ALERT.get(key, 0) < 3600:
        return
    _FJ_ALERT[key] = now
    names = ", ".join(esc(r["title"] or r["link"] or "channel")
                      for r in rows[:4])
    await notify_admins(
        bot,
        f"{ICON['warn']} <b>FORCE JOIN VERIFY FAILED</b>\n{DIV}\n"
        f"The bot cannot read the member list of : {names}\n"
        f"{DIV}\n{ICON['dot']} Add the bot as <b>admin</b> in that channel, "
        "or give it the channel id (-100...) from Admin Panel → Force Join.")


async def _gate_show(update, ctx, text, markup):
    q = getattr(update, "callback_query", None)
    if q:
        await edit_q(q, text, markup)
        return
    msg = getattr(update, "message", None)
    if msg:
        await msg.reply_text(text, parse_mode=ParseMode.HTML,
                             reply_markup=markup)


async def gate(update, ctx, uid, join_extra=None, terms_extra=None) -> bool:
    if maintenance_on() and not _adm(uid):
        await _gate_show(update, ctx, s_maintenance(), kb_maintenance())
        return False
    if not ctx.user_data.get("join_ok") or (
        time.time() - float(ctx.user_data.get("join_ok_at") or 0) > 1800):
        missing, unverified = await check_joins(ctx.bot, uid)
        if missing:
            ctx.user_data.pop("join_ok", None)
            await _gate_show(update, ctx, s_join_required(missing),
                             kb_join(missing))
            return False
        if unverified and fj_strict():
            ctx.user_data.pop("join_ok", None)
            await _fj_alert(ctx.bot, unverified)
            await _gate_show(update, ctx, s_join_unverified(unverified),
                             kb_join_verify())
            return False
        if unverified:
            await _fj_alert(ctx.bot, unverified)
        ctx.user_data["join_ok"] = True
        ctx.user_data["join_ok_at"] = time.time()
    if captcha_on() and db_needs_captcha(uid, captcha_hours()):
        q, opts = _cap_new(ctx)
        await _gate_show(update, ctx, s_captcha(q), kb_captcha(opts))
        return False
    if terms_on() and not db_terms_ok(uid):
        await _gate_show(update, ctx, s_terms(), kb_terms())
        return False
    return True


async def cb_jc_verify(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    u = q.from_user
    await qans(q, "Checking your membership...")
    missing, unverified = await check_joins(ctx.bot, u.id)
    if missing:
        return await qans(q, "Please join every channel first", True)
    if unverified and fj_strict():
        await _fj_alert(ctx.bot, unverified)
        return await qans(
            q, "Bot cannot verify that channel - admin must add it as admin",
            True)
    ctx.user_data["join_ok"] = True
    ctx.user_data["join_ok_at"] = time.time()
    await qans(q, "Verified - welcome")
    if captcha_on() and db_needs_captcha(u.id, captcha_hours()):
        qt, opts = _cap_new(ctx)
        return await edit_q(q, s_captcha(qt), kb_captcha(opts))
    if terms_on() and not db_terms_ok(u.id):
        return await edit_q(q, s_terms(), kb_terms())
    await edit_q(q, s_menu(u.id, db_balance(u.id), u.username),
                 kb_main(u.id))


async def cb_cap(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    u = q.from_user
    cap = ctx.user_data.get("cap") or {}
    try:
        val = int(q.data.split("_")[1])
    except (IndexError, ValueError):
        return await qans(q, "Please try again", True)
    if not cap:
        qt, opts = _cap_new(ctx)
        return await edit_q(q, s_captcha(qt), kb_captcha(opts))
    if val != int(cap.get("ans", -1)):
        cap["tries"] = int(cap.get("tries", 0)) + 1
        ctx.user_data["cap"] = cap
        await qans(q, "Wrong answer", True)
        qt, opts = _cap_new(ctx)
        return await edit_q(q, s_captcha(qt, tries=cap["tries"]),
                            kb_captcha(opts))
    ctx.user_data.pop("cap", None)
    db_mark_verified(u.id)
    await qans(q, "Verified")
    if terms_on() and not db_terms_ok(u.id):
        return await edit_q(q, s_terms(), kb_terms())
    await edit_q(q, s_menu(u.id, db_balance(u.id), u.username),
                 kb_main(u.id))


