async def _watch_user_msg(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    try:
        msg = update.effective_message
        u = update.effective_user
        if msg is not None and u is not None and getattr(msg, "message_id", None):
            if getattr(msg, "chat", None) is not None and \
                    msg.chat.type == "private":
                remember_user_msg(u.id, msg.message_id)
    except Exception:
        pass
    _log_update(update)
    return await gate_watch(update, ctx)


def _log_update(update) -> None:
    if not LOG_UPDATES:
        return
    try:
        u = update.effective_user
        q = getattr(update, "callback_query", None)
        if q is not None:
            log.info("update: button %s from %s", str(q.data)[:40],
                     getattr(u, "id", "?"))
            return
        m = update.effective_message
        if m is None:
            return
        txt = str(getattr(m, "text", "") or "")[:40].replace("\n", " ")
        log.info("update: message from %s -> %s", getattr(u, "id", "?"),
                 txt or "(media)")
    except Exception:
        pass


async def gate_watch(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    u = update.effective_user
    if u is None or is_admin(u.id):
        return
    try:
        if time.time() - _TOUCH_AT.get(u.id, 0) > 600:
            _TOUCH_AT[u.id] = time.time()
            mg_push_user(u.id)
    except Exception:
        pass
    q = getattr(update, "callback_query", None)
    if q is None:
        return
    if hasattr(q, "get_bot"):
        _real = None
        try:
            _real = q.get_bot()
        except Exception:
            _real = None
        if _real is not None and type(_real).__name__ in ("Bot", "ExtBot", "StoreBot"):
            _spawn(_auto_ack(q))
    chat = update.effective_chat
    if chat and chat.type != "private":
        try:
            await q.answer("This bot works only in private chat.", True)
        except Exception:
            pass
        raise ApplicationHandlerStop
    data = q.data or ""
    if data in GATE_FREE_EXACT or data.startswith(GATE_FREE_PREFIX):
        return
    if not await gate(update, ctx, u.id):
        raise ApplicationHandlerStop


