BANNER_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                           "assets", "banner.jpg")


async def send_banner(bot, chat_id, caption, markup=None):
    if os.path.exists(BANNER_PATH) and len(caption) <= 1024:
        try:
            with open(BANNER_PATH, "rb") as fh:
                return await bot.send_photo(
                    chat_id,
                    photo=make_input_file(fh.read(), "banner.jpg"),
                    caption=caption, parse_mode=ParseMode.HTML,
                    reply_markup=markup)
        except Exception as e:
            log.warning("banner send failed: %s", e)
    return await send(bot, chat_id, caption, markup)


