async def cmd_restore(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Admin: restore the complete database from MongoDB."""
    u = update.effective_user
    if not _adm(u.id):
        return await update.message.reply_text(
            f"{ICON['warn']} This command is available to admins only.",
            parse_mode=ParseMode.HTML)
    msg = await update.message.reply_text(
        f"{ICON['gear']} Restoring all data from MongoDB...",
        parse_mode=ParseMode.HTML)
    try:
        rep = await mongo.pull_all()
        try:
            await asyncio.to_thread(mongo.flush_queue, 10)
        except Exception:
            pass
        n_sett = await mongo.pull_settings(force=True)
        n_ch = await mongo.pull_channels()
        rep["settings"] = n_sett
        rep["channels"] = n_ch
    except Exception as e:
        log.warning("cmd_restore: %s", e)
        return await msg.edit_text(
            f"{ICON['warn']} Restore failed: "
            f"<code>{esc(str(e)[:200])}</code>",
            parse_mode=ParseMode.HTML)
    body = [
        kv("Users from cloud", f"<b>{rep.get('users', 0)}</b>"),
        kv("Users in database", f"<b>{rep.get('local_users', 0)}</b>"),
        kv("Users with balance", f"<b>{rep.get('paid_users', 0)}</b>"),
        kv("Orders restored", f"<b>{rep.get('orders', 0)}</b>"),
        kv("Deposits restored", f"<b>{rep.get('deposits', 0)}</b>"),
        kv("Ledger rows restored", f"<b>{rep.get('ledger', 0)}</b>"),
        kv("Balances rebuilt", f"<b>{rep.get('balances', 0)}</b>"),
        kv("Settings restored", f"<b>{rep.get('settings', 0)}</b>"),
        kv("Channels restored", f"<b>{rep.get('channels', 0)}</b>"),
    ]
    # ── FIX #30: try/except in case the message is too old to edit ──
    try:
        await msg.edit_text(
            f"{ICON['check']} <b>RESTORE COMPLETE</b>\n" + LINE + "\n"
            + box(body) + "\n"
            + f"{ICON['info']} All data stored in MongoDB has been "
              "restored to the temporary RAM cache.\n" + LINE,
            parse_mode=ParseMode.HTML)
    except Exception:
        await send(ctx.bot, u.id,
                   f"{ICON['check']} <b>RESTORE COMPLETE</b>\n" + LINE + "\n"
                   + box(body) + "\n" + LINE)


async def cmd_save_config(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Admin: push the ENTIRE shop config to MongoDB in one doc."""
    u = update.effective_user
    if not _adm(u.id):
        return await update.message.reply_text(
            f"{ICON['warn']} Admins only.", parse_mode=ParseMode.HTML)
    if not mongo.on():
        return await update.message.reply_text(
            f"{ICON['warn']} MongoDB is turned off.", parse_mode=ParseMode.HTML)
    msg = await update.message.reply_text(
        f"{ICON['gear']} Saving the configuration to MongoDB...",
        parse_mode=ParseMode.HTML)
    try:
        await mongo.push_config()
        mg_push_all_tables()
        await asyncio.to_thread(mongo.flush_queue, 20)
    except Exception as e:
        return await msg.edit_text(
            f"{ICON['cross']} Save fail: <code>{esc(str(e)[:200])}</code>",
            parse_mode=ParseMode.HTML)
    conn = _get_conn()
    n_users = conn.execute(
        f"SELECT COUNT(*) FROM users WHERE {REAL_USER_WHERE}").fetchone()[0]
    n_countries = conn.execute("SELECT COUNT(*) FROM countries").fetchone()[0]
    n_orders = conn.execute("SELECT COUNT(*) FROM orders").fetchone()[0]
    n_admins = conn.execute("SELECT COUNT(*) FROM admins").fetchone()[0]
    n_channels = conn.execute("SELECT COUNT(*) FROM force_channels").fetchone()[0]
    n_promos = conn.execute("SELECT COUNT(*) FROM promo_codes").fetchone()[0]
    n_settings = conn.execute("SELECT COUNT(*) FROM settings").fetchone()[0]
    body = [
        kv("Config doc", "<b>bot/config</b>"),
        kv("Settings", f"<b>{n_settings}</b>"),
        kv("Countries", f"<b>{n_countries}</b>"),
        kv("Admins", f"<b>{n_admins}</b>"),
        kv("Channels", f"<b>{n_channels}</b>"),
        kv("Promos", f"<b>{n_promos}</b>"),
        f"{THIN}",
        kv("Users", f"<b>{n_users}</b>"),
        kv("Orders", f"<b>{n_orders}</b>"),
    ]
    await msg.edit_text(
        f"{ICON['check']} <b>SAVED TO MONGODB</b>\n" + LINE + "\n"
        + box(body) + "\n"
        + f"{ICON['info']} Persistent data remains in MongoDB; the RAM cache is rebuilt at startup.\n"
        + LINE, parse_mode=ParseMode.HTML)


