async def cb_unknown(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Catch-all for a callback no handler claims.

    v40: pehle ye har purane button ko seedha main menu par phenk deta tha
    ("This button has expired") - account screen par ye bahut bura lagta
    tha. Ab: toast chhota, aur screen wahi rehti hai (kuch bhi delete nahi
    hota), sirf refresh ka mauka milta hai.
    """
    q = update.callback_query
    u = q.from_user
    data = str(getattr(q, "data", "") or "")
    head_ = data.split("_")[0] if data else ""
    log.info("unhandled callback %r from %s", data[:60], u.id)
    if head_ in ("itm", "itmr", "ibuy", "cat", "catall", "catmore", "scl",
                 "srv", "srvs"):
        # account / catalogue button: wapas usi country ke catalogue par
        parts = data.split("_")
        srv_ = 1
        cc_ = ""
        for part in parts[1:3]:
            if part in ("1", "2"):
                srv_ = int(part)
            elif len(part) == 2 and part.isalpha():
                cc_ = part.upper()
        await qans(q, "This view is out of date. Reloading...")
        if cc_ and db_country(cc_):
            return await open_catalog(q, ctx, srv_, cc_, 0)
        return await edit_q(q, s_menu(u.id, db_balance(u.id), u.username),
                            kb_main(u.id))
    await qans(q, "This button is out of date. Opening the main menu.")
    await edit_q(q, s_menu(u.id, db_balance(u.id), u.username),
                 kb_main(u.id))


