def kb_country_grid(srv, page, pages, sort="asc", filt="") -> InlineKeyboardMarkup:
    try:
        srv = int(srv or 1)
        mode = "high" if sort == "desc" else "low"
        st_col = "stock2" if srv == 2 else "stock1"
        rows_db, _total = db_countries_page(page * PAGE_SIZE, PAGE_SIZE,
                                             active_only=True, srv=srv,
                                             sort=sort)
        grid, row = [], []
        for c in rows_db:
            try:
                stock = int(c[st_col] or 0)
            except Exception:
                stock = 0
            try:
                probed = int(c["stock_at"] or 0) > 0
            except Exception:
                probed = False
            price = country_floor(c["code"], srv)
            if not probed:
                # never checked yet - do not invent a price for it
                label = f"{btn_label(c['code'])} | ⏳ checking"
            else:
                label = country_label(c["code"], price, stock)
            row.append((label, f"srv_{srv}_{c['code']}", BTN_PRIMARY + "!"))
            if len(row) == 2:
                grid.append(row)
                row = []
        if row:
            grid.append(row)
            
        # Pagination (Red)
        pr = kb_num_pager(page, pages, lambda i: f"scl_{srv}_{i}")
        if pr:
            grid.append([(txt, cb, BTN_DANGER + "!") for txt, cb, _ in pr])
            
        # Tools (Green)
        grid.append([("Back", "shop_tg", BTN_SUCCESS + "!"),
                     ("Search", f"csch_{srv}", BTN_SUCCESS + "!"),
                     ("Filters", f"cf_{srv}_ALL", BTN_SUCCESS + "!")])
        grid.append(kb_row(("🔄 Refresh Live Stock", f"cstock_{srv}",
                            BTN_SUCCESS + "!")))
                     
        # v31: three states - price low / price high / most stock first
        cur = str(sort).lower()
        if cur.startswith("stock"):
            sort_label = "Sort · Most Stock First"
            next_mode = "low"
        elif mode == "high":
            sort_label = "Sort · Price · High to Low"
            next_mode = "stock"
        else:
            sort_label = "Sort · Price · Low to High"
            next_mode = "high"
        grid.append(kb_row((sort_label, f"csort_{srv}_{next_mode}",
                            BTN_SUCCESS + "!")))
        
        return ikb(*grid)
    except Exception as e:
        log.warning("kb_country_grid error: %s", e)
        return ikb(kb_row(("Back", "shop_tg", BTN_SUCCESS + "!"), ("Main Menu", "main_menu", BTN_PRIMARY + "!")))



async def render_countries(q, u, page, srv, ctx):
    srv = int(srv or 1)
    if srv not in SERVER_ORIGINS:
        srv = 1
    
    csort = ctx.user_data.get("csort") or "low"
    sort = ("desc" if csort == "high" else
            "stock" if csort == "stock" else "asc")
    
    page = max(0, int(page or 0))
    # ... baaki function waise hi rahega
    rows_db, total = db_countries_page(page * PAGE_SIZE, PAGE_SIZE,
                                        active_only=True, srv=srv, sort=sort)
    if not rows_db and page > 0:
        page = 0
        rows_db, total = db_countries_page(0, PAGE_SIZE, active_only=True,
                                            srv=srv, sort=sort)
    if not rows_db:
        return await edit_q(
            q,
            s_header(u.id, db_balance(u.id), u.username)
            + "\n\n<b>SERVER " + str(srv) + "</b>   "
              "<i>no live stock right now</i>\n"
            + LINE + "\nThis server has no country with stock at the moment.\n"
            + f"{ICON['arrow']} Try the other server or refresh in a minute.\n"
            + LINE,
            ikb(kb_row(("Server 1 - Cheap", "svshop_1", BTN_SUCCESS),
                       ("Server 2 - Good", "svshop_2")),
                kb_row(("Main Menu", "main_menu"))))
    pages = max(1, (total + PAGE_SIZE - 1) // PAGE_SIZE)
    page = max(0, min(page, pages - 1))
    ctx.user_data["shop_srv"] = srv
    acc = _global_stock.get(f"accounts{srv}") or None
    _bg_server_refresh(srv)          # v18: never blocks the tap
    # v31: refresh the live stock of the countries the user can SEE first,
    # then the rest of the world keeps filling up in the background
    try:
        _bg_country_sweep(srv, limit=max(24, PAGE_SIZE * 2))
    except Exception:
        pass
    cheap = None
    try:
        cheap_rows, _ct = db_countries_page(0, 1, active_only=True,
                                             srv=srv, sort="asc")
        for c0 in cheap_rows:
            st_col = "stock2" if srv == 2 else "stock1"
            try:
                has = int(c0[st_col] or 0) > 0
            except Exception:
                has = False
            if has:
                cheap = {"code": c0["code"], "name": c0["name"],
                         "price_inr": country_floor(c0["code"], srv)}
    except Exception:
        cheap = None
    if cheap and not cheap.get("price_inr"):
        cheap = None
    fl = get_filters(ctx, srv)
    await edit_q(q, s_shop_list(u.id, db_balance(u.id), total, page, pages,
                                 acc, srv, cheap=cheap,
                                 live_at=_liveprice.get("at", ""),
                                 fsum=filter_summary(fl),
                                 stock=shop_stock_summary(srv)),
                 kb_country_grid(srv, page, pages, sort))


async def cb_stock_refresh(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """v31: force a fresh sweep of every country's live stock."""
    q = update.callback_query
    try:
        srv = int(q.data.split("_")[1])
    except (IndexError, ValueError):
        srv = 1
    srv = 2 if srv == 2 else 1
    await qans(q, "Stock refresh started - every country will be live "
                  "within 1-2 minutes…", True)
    _bg_country_sweep(srv, force=True)
    _country_sweep_at[f"s{srv}"] = 0.0        # allow an immediate re-sweep
    await render_countries(q, q.from_user, 0, srv, ctx)


