async def cb_buy(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    u = q.from_user
    await qans(q, "Loading accounts...")
    if not _guard(u):
        return await edit_q(q, BAN_MSG, None)
    ctx.user_data.pop("locked_item", None)
    cc = q.data[4:]
    srv = int(ctx.user_data.get("shop_srv") or 1)
    c = db_country(cc)
    if not c or country_floor(cc, srv) <= 0:
        return await edit_q(q, f"{ICON['warn']} Country not found or no stock.", kb_home())
        
    # TURANT LOADING SCREEN
    await edit_q(q, s_cat_load(srv, cc, c["name"]))
    
    ctx.user_data["shop_srv"] = srv
    ctx.user_data["_uid"] = u.id
