async def cb_otp(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Fetch Telegram login code for an order.

    otp_{oid}  = Get Login Code (cache allowed, returns recent code)
    otpf_{oid} = Get Fresh Code (cache skipped, requests new code)
    """
    q = update.callback_query
    u = q.from_user
    raw = q.data or ""
    force_fresh = raw.startswith("otpf_")
    try:
        oid = int(raw.split("_")[1])
    except (IndexError, ValueError):
        return await qans(q, "Bad order", True)

    o = db_order(oid)
    if not o or o["user_id"] != u.id:
        return await qans(q, "Order not found", True)
    iid = _order_iid(o)
    if not iid:
        return await qans(q, "This order has no supplier item linked", True)

    ph = await _recover_phone(o)
    _msg_chat = q.message.chat_id if q.message else u.id
    _msg_id = q.message.message_id if q.message else None

    # ── 1. Cached code (last 10 min) -> return instantly ──
    #    Only for "Get Login Code". "Get Fresh Code" bypasses this.
    if not force_fresh:
        try:
            recent = _get_conn().execute(
                "SELECT code, created_at FROM otp_log WHERE order_id=? "
                "AND created_at > datetime('now', '-10 minutes') "
                "ORDER BY id DESC LIMIT 1", (oid,)).fetchone()
        except Exception:
            recent = None
        if recent and str(recent["code"] or "").strip():
            code = str(recent["code"]).strip()
            when = str(recent["created_at"] or "")[:19]
            await qans(q, "Found a recent code in cache")
            body = (
                f"<b>LOGIN CODE</b>   <i>cached</i>\n"
                f"{LINE}\n"
                f"Number : <code>{esc(full_phone(ph))}</code>\n"
                f"Type   : {quality_label(o)}\n"
                f"{THIN}\n"
                f"Code   : <b>{esc(code)}</b>\n"
                f"When   : {esc(when)} UTC\n"
                f"{LINE}\n"
                f"<i>If this code is expired, tap Get Fresh Code.</i>"
            )
            kb_rows = [
                [kb_copy("Copy Code", code, BTN_SUCCESS)],
                kb_row(("Get Fresh Code", f"otpf_{oid}", BTN_SUCCESS),
                       ("Back to Order", f"vo_{oid}", BTN_PRIMARY)),
                kb_row(("Main Menu", "main_menu", BTN_PRIMARY)),
            ]
            return await edit_q(q, body, ikb(*kb_rows))

    # ── 2. Already polling? ──
    t = _otp_tasks.get(oid)
    if t and not t.done():
        return await qans(q, "A login code request is already running. Please wait.",
                          True)

    # ── 3. Background poll start karo ──
    await qans(q, "Requesting a login code from Telegram...")
    await edit_q(q, _otp_wait_screen(o, ph, 0, 20),
                 ikb(kb_row(("Back to Order", f"vo_{oid}", BTN_PRIMARY))))

    task = asyncio.create_task(_poll_otp_bg(
        ctx.bot, oid, u.id, _msg_chat, _msg_id, ph,
        iid, quality_label(o)))
    _otp_tasks[oid] = task


