def _order_iid(o) -> str:
    """Supplier item id of an order - falls back to extra_data.item_ref
    for orders whose supplier_item_id column was never written (fixes
    'session not found' on Terminate and silent OTP polls)."""
    try:
        o = dict(o or {})
    except Exception:
        pass
    iid = str(o.get("supplier_item_id") or "").strip()
    if iid:
        return iid
    try:
        ex = json.loads(o.get("extra_data") or "{}") or {}
    except Exception:
        ex = {}
    return str(ex.get("item_ref") or "").strip()


_otp_warm: Dict[int, float] = {}


def _warm_otp_spawn(oid, iid, uid=0, ph=""):
    """Pre-warm the login code: the first OTP poll right after delivery
    means the user's tap on Get Login Code finds a code instead of waiting
    a full poll cycle."""
    try:
        oid = int(oid)
    except (TypeError, ValueError):
        return
    if not iid:
        return
    now = time.monotonic()
    if now - _otp_warm.get(oid, 0.0) < 300:
        return
    _otp_warm[oid] = now
    if len(_otp_warm) > 1000:
        for k in [k for k, v in _otp_warm.items() if now - v > 900][:400]:
            _otp_warm.pop(k, None)

    async def _work():
        _BG.set(True)
        for gap in (2.0, 12.0, 18.0):
            await asyncio.sleep(gap)
            try:
                r = await sup.login_code(iid)
            except Exception as e:
                log.info("warm otp #%s: %s", oid, str(e)[:60])
                return
            if r.get("err") == "rate_limit":
                return
            if r.get("ok") and r.get("codes"):
                try:
                    db_log_otp(oid, uid or 0, str(r["codes"][0]).strip(),
                               ph or "")
                except Exception:
                    pass

    _spawn(_work())


