_CRYPTO_ADMIN = os.environ.get("CRYPTO_ADMIN", "cheapest_tgbot").lstrip("@")


def db_reject_dep_pending(did, note=None) -> bool:
    """Reject ONLY while still pending - so two admins (or admin panel vs
    screenshot button) can never flip an already-approved deposit (which
    would otherwise leave money credited on a rejected row)."""
    with _tx() as c:
        cur = c.execute(
            "UPDATE deposits SET status='rejected', "
            "resolved_at=datetime('now'), "
            "admin_note=COALESCE(?, admin_note) "
            "WHERE id=? AND status='pending'", (note, did))
        ok = bool(cur.rowcount)
    if ok:
        mg_push_deposit(did)
        try:
            fs_touch()
        except Exception:
            pass
    return ok


