def kb_mupi_home(upi_ok):
    rows = []
    if upi_ok:
        lo, hi = min_deposit(), max_deposit()
        base = [100, 250, 500, 1000, 2000]
        vals = [v for v in base if lo <= v <= hi]
        if not vals or (vals and vals[0] > lo):
            vals.insert(0, int(lo) if float(lo).is_integer() else round(lo, 2))
        vals = sorted(dict.fromkeys(vals))[:8]
        cur = []
        for v in vals:
            cur.append((f"₹{v:g}", f"mpia_{v:g}", BTN_SUCCESS))
            if len(cur) == 3:
                rows.append(kb_row(*cur))
                cur = []
        if cur:
            rows.append(kb_row(*cur))
        rows.append(kb_row(("✏️ Custom Amount", "mpic", BTN_SUCCESS)))
    rows.append(kb_row(("Back", "deposit", BTN_PRIMARY),
                       ("Main Menu", "main_menu")))
    return _styled_markup(rows)


