async def _mupi_show_qr(bot, cid, user, amt) -> Optional[int]:
    """Create a manual_upi deposit row and show its QR + I Have Paid
    button."""
    upi_id, name = manual_upi()
    if not upi_id:
        await send(bot, cid, head("Manual UPI", "📲") + "\nManual UPI is "
                   "not configured yet. Please use Auto UPI.", kb_home())
        return None
    if amt < min_deposit() or amt > max_deposit():
        await send(bot, cid,
                   f"{ICON['warn']} Amount must be between "
                   f"<b>{money(min_deposit())}</b> and "
                   f"<b>{money(max_deposit())}</b>.", kb_home())
        return None
    did = db_create_dep(user.id, float(amt), "manual_upi")
    if not did:
        await send(bot, cid, head("Could not start deposit", "⚠️") + "\n"
                   "A duplicate session was detected. Please start again.",
                   kb_home())
        return None
    ref = f"DEP-{did}"
    txt = s_mupi_pay(amt, upi_id, name, did)
    kb = kb_mupi_pay(did, upi_id)
    await send_qr(bot, cid, "", txt, kb, upi_id=upi_id, amount=amt,
                  ref=ref)
    return did


