_mdep_msgs: Dict[int, List[tuple]] = {}


async def _mupi_ping_admins(bot, d, u, fid):
    """Send the screenshot to every OWNER / SUPER ADMIN with Approve /
    Reject buttons. Message references are remembered so the card clears
    for everyone once one admin acts."""
    did = int(d["id"])
    upi_id, _name = manual_upi()
    cap = (f"💸 <b>MANUAL UPI DEPOSIT</b>\n{DIV}\n"
           f"Deposit : <code>#{did}</code>\n"
           f"User    : <code>{u.id}</code>"
           + (f"  @{esc(u.username)}" if u.username else "")
           + f"\nAmount  : <b>{money(d['amount'])}</b>\n"
           f"UPI ID  : <code>{esc(upi_id or '-')}</code>\n"
           f"Time    : {now_utc().strftime('%d %b %H:%M')} UTC\n{DIV}\n"
           "<i>Check your UPI app, then Approve or Reject.\n"
           "The card clears for every admin once one acts.</i>")
    kb = ikb(kb_row(("✅ Approve", f"mok_{did}", BTN_SUCCESS),
                    ("❌ Reject", f"mno_{did}", BTN_DANGER)))
    cap = premiumize(cap)
    got = []
    for aid in [int(x) for x in admin_dm_ids()
                if str(x).isdigit() and is_full_admin(int(x))]:
        try:
            m = await bot.send_photo(aid, fid, caption=cap,
                                     parse_mode=ParseMode.HTML,
                                     reply_markup=kb)
            got.append((m.chat_id, m.message_id))
        except Exception as e:
            log.warning("manual-upi admin ping -> %s failed: %s",
                        aid, str(e)[:90])
    if got:
        _mdep_msgs[did] = got
        if len(_mdep_msgs) > 300:
            for k in list(_mdep_msgs.keys())[:200]:
                _mdep_msgs.pop(k, None)
    else:
        await notify_admins(
            bot, f"⚠️ <b>MANUAL UPI DEPOSIT #{did}</b>\n{DIV}\n"
            f"User <code>{u.id}</code> sent {money(d['amount'])} but the "
            "screenshot could not be delivered to any admin.\n"
            "Open Admin Panel ➜ Deposits to review it.")


async def _mdep_resolve(bot, did, actor_tag, approved):
    """After one admin acts, the screenshot card is resolved/deleted for
    EVERY admin, so nobody can double-approve or double-reject."""
    mark = "✅ APPROVED" if approved else "❌ REJECTED"
    for cid, mid in _mdep_msgs.pop(int(did), []):
        try:
            await bot.edit_message_caption(
                cid, mid,
                caption=f"{mark}\n<i>Handled by {actor_tag} - "
                        f"deposit #{did}.</i>",
                reply_markup=None)
        except Exception:
            try:
                await bot.delete_message(cid, mid)
            except Exception:
                pass


