async def dep_shot_capture(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Photo messages while a manual-UPI screenshot is awaited."""
    msg = update.message
    u = update.effective_user
    if msg is None or u is None or ctx.user_data is None or not msg.photo:
        return
    aw = str(ctx.user_data.get("aw") or "")
    if not aw.startswith("shot_"):
        return
    try:
        did = int(aw.split("_")[1])
    except (IndexError, ValueError):
        ctx.user_data.pop("aw", None)
        return
    d = db_deposit(did)
    if not d or d["user_id"] != u.id:
        ctx.user_data.pop("aw", None)
        return await msg.reply_text("This deposit was not found.")
    if d["status"] != "pending":
        ctx.user_data.pop("aw", None)
        return await msg.reply_text("This deposit is no longer pending.")
    ctx.user_data.pop("aw", None)
    fid = msg.photo[-1].file_id
    db_upd_dep(did, screenshot=fid)
    await msg.reply_text(
        head("Screenshot received", "✅") + "\n"
        + box([kv("Deposit", f"<code>#{did}</code>"),
               kv("Amount", f"<b>{money(d['amount'])}</b>"),
               kv("Status", "Waiting for admin approval 🕒")])
        + "\n<i>You will be notified the moment it is checked.</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=ikb(kb_row(("➕ Add Funds", "deposit", BTN_SUCCESS)),
                         kb_row(("🏠 Main Menu", "main_menu"))))
    await _mupi_ping_admins(ctx.bot, d, u, fid)
    raise ApplicationHandlerStop


