async def manual_upi_set_text(update: Update,
                              ctx: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    ctx.user_data.pop("aw", None)
    raw = (msg.text or "").strip()
    if raw.lower() in ("off", "0", "disable"):
        db_set_setting("manual_upi_id", "")
        return await msg.reply_text(
            head("Manual UPI", "⚙️") + "\nManual UPI is now <b>OFF</b>.",
            parse_mode=ParseMode.HTML,
            reply_markup=ikb(kb_row(("Admin Panel", "admin"))))
    upi_id, _, uname = raw.partition("|")
    upi_id = upi_id.strip()
    if not re.fullmatch(r"[A-Za-z0-9._\-]{2,}@[A-Za-z]{2,}[A-Za-z0-9]*",
                        upi_id):
        ctx.user_data["aw"] = "set_manual_upi"
        return await msg.reply_text(
            f"{ICON['warn']} That does not look like a UPI ID. "
            "Example: <code>name@okhdfcbank</code> - send again.",
            parse_mode=ParseMode.HTML,
            reply_markup=ikb(kb_row(("Cancel", "admin"))))
    db_set_setting("manual_upi_id", upi_id)
    if uname.strip():
        db_set_setting("manual_upi_name", uname.strip()[:40])
    name = manual_upi()[1] or SHOP_NAME
    await msg.reply_text(
        head("Manual UPI saved", "✅") + "\n"
        + box([kv("UPI ID", f"<code>{esc(upi_id)}</code>"),
               kv("Payee", esc(name)),
               kv("Status", "🟢 LIVE - users can now pay manually")]),
        parse_mode=ParseMode.HTML,
        reply_markup=ikb(kb_row(("💳 Deposit Screen", "depm",
                                 BTN_SUCCESS)),
                         kb_row(("Admin Panel", "admin"))))



