async def _init_pay(q, user, amt, ctx, is_msg=False, chat_id=None):
    """Create a gateway order and show the QR. No manual / UTR fallback:
    if the gateway is down the user is asked to retry (nothing is stored)."""
    use_q = q is not None and not is_msg and not chat_id
    cid = chat_id or (q.message.chat_id if use_q and q.message else user.id)
    if use_q:
        await edit_q(q, s_pay_wait(amt), None)
    r = await gateway.create_order(amt, name=(user.first_name or "Customer")[:40])
    if not r.get("ok"):
        log.warning("Gateway create-order failed: %s", r.get("error"))
        txt = s_pay_err(amt, r.get("error") or "")
        kb = _styled_markup([kb_row(("Try Again", f"dp_{float(amt):g}",
                                     BTN_SUCCESS)),
                             kb_url("Support", SUPPORT_URL, BTN_PRIMARY),
                             kb_row(("Main Menu", "main_menu"))])
        return await (edit_q(q, txt, kb) if use_q
                      else send(ctx.bot, cid, txt, kb))
    did = db_create_dep(user.id, amt, "auto_upi",
                        txn_id=r["order_id"], fam_oid=r["order_id"])
    if not did:
        txt = (head("Could not start deposit", "\u26a0\ufe0f") + "\n"
               "A duplicate payment session was detected. Start a new one.")
        return await (edit_q(q, txt, kb_dep_retry()) if use_q
                      else send(ctx.bot, cid, txt, kb_dep_retry()))
    payable = float(r.get("payable_amount") or amt)
    ref = r["order_id"]
    txt = s_pay(amt, payable, ref, r.get("upi_id") or FAMPAY_UPI_ID,
                expires=r.get("expires_at", ""))
    msg = await send_qr(ctx.bot, cid, r.get("qr_url"), txt,
                        kb_pay(did, r, amount=payable),
                        upi_id=r.get("upi_id") or FAMPAY_UPI_ID,
                        amount=payable, ref=ref,
                        intent=r.get("upi_intent") or "")
    if use_q and msg is not None:
        try:
            await q.message.delete()
        except Exception:
            pass
    chat_id = msg.chat_id if msg is not None else cid
    msg_id = msg.message_id if msg is not None else None
    _pay_tasks[did] = asyncio.create_task(
        _auto_check(ctx, user.id, did, ref, amt, payable,
                    chat_id, msg_id))
    return did

async def create_oxapay_invoice(amount_usdt, order_id):
    url = "https://api.oxapay.com/merchants/request"
    payload = {
        "merchant": OXAPAY_API_KEY,
        "amount": amount_usdt,
        "currency": "USDT",
        "lifeTime": 30,
        "orderId": str(order_id),
        "description": f"Deposit for {SHOP_NAME}"
        # "fee_paid_by_payer": 0  <-- IS LINE KO HATA DO
    }
    # ... baaki code same rahega
    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(url, json=payload) as resp:
                data = await resp.json()
                if data.get("result") == 100:
                    return {"ok": True, "pay_link": data.get("payLink"), "track_id": data.get("trackId")}
                return {"ok": False, "error": data.get("message", "Unknown error")}
    except Exception as e:
        return {"ok": False, "error": str(e)}

async def check_oxapay_status(track_id):
    url = "https://api.oxapay.com/merchants/inquiry"
    payload = {
        "merchant": OXAPAY_API_KEY,
        "trackId": track_id
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(url, json=payload) as resp:
                data = await resp.json()
                if data.get("result") == 100:
                    status = str(data.get("status", "")).lower()
                    if status == "paid":
                        return True, data
                return False, data
    except Exception as e:
        return False, str(e)


async def _auto_check_crypto(bot, uid, did, track_id, cid, mid):
    start = time.monotonic()
    frames = ["|", "/", "-", "\\"]
    frame_idx = 0
    
    # 2 minute (120 seconds) ka loop
    while time.monotonic() - start < 120:
        is_paid, data = await check_oxapay_status(track_id)
        
        if is_paid:
            res = db_approve_dep_auto(did, f"OxaPay-{track_id}")
            if res:
                success_text = (
                    head("Payment Successful") + "\n"
                    + box([f"Added: <b>{money(res['amount'])}</b>",
                           f"Balance: <b>{money(res['new_balance'])}</b>"])
                )
                await edit_msg(bot, cid, mid, success_text, kb_home())
            return
            
        status = str(data.get("status", "")).lower()
        if status == "expired":
            db_dep_timeout(did, "OxaPay expired")
            try:
                await edit_msg(bot, cid, mid, head("Payment Expired", "⚠️") + "\nThe payment window closed.", kb_home())
            except Exception:
                pass
            return

        elapsed = int(time.monotonic() - start)
        spin = frames[frame_idx % len(frames)]
        
        # Smooth Time-based Progress Bar calculation
        pct = int((elapsed / 120) * 100)
        filled = int(pct / 10)
        block_bar = "■" * filled + "□" * (10 - filled)
        
        text = (
            f"<b>PROCESSING PAYMENT</b>\n{LINE}\n"
            f"<i>Scanning blockchain for your transaction...</i>\n\n"
            f"<code>[{block_bar}]</code> {spin} {pct}%\n\n"
            f"Status: <b>Waiting for network confirmation</b>\n"
            f"Time: <b>{elapsed}s / 120s</b>\n"
            f"{THIN}\n"
            f"<i>Please wait, do not close this chat.</i>"
        )
        
        try:
            # Loading ke dauran koi button nahi (None)
            await edit_msg(bot, cid, mid, text, None)
        except Exception:
            pass
        
        frame_idx += 1
        await asyncio.sleep(3)

    # --- 2 MINUTE TIMEOUT (SUSPICIOUS) ---
    # Timeout hone par admin ko notify karo
    await notify_admins(
        bot,
        f"⚠️ <b>CRYPTO VERIFICATION FAILED</b>\n"
        f"User: <code>{uid}</code> clicked 'I Have Paid' but automated verification failed after 2 minutes.\n"
        f"OxaPay ID: <code>{track_id}</code>\n"
        f"<i>Please check this transaction manually.</i>"
    )
    
    # User ko timeout message aur Admin ka contact dikhao
    timeout_text = (
        f"<b>VERIFICATION TIMEOUT</b>\n{LINE}\n"
        f"We could not automatically verify your payment on the blockchain.\n\n"
        f"If you have already paid, please contact our admin immediately:\n"
        f"👉 <b>{esc(SUPPORT_CONTACT)}</b>\n\n"
        f"Please provide your OxaPay ID: <code>{track_id}</code>\n"
        f"{THIN}"
    )
    kb = ikb(kb_url("Contact Admin", SUPPORT_URL, BTN_SUCCESS))
    try:
        await edit_msg(bot, cid, mid, timeout_text, kb)
    except Exception:
        pass

async def cb_cpay(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """'Verify Payment' - asks the gateway API, credits at most once."""
    q = update.callback_query
    u = q.from_user
    try:
        did = int(q.data.split("_")[1])
    except (IndexError, ValueError):
        return await qans(q, "Deposit not found", True)
    d = db_deposit(did)
    if not d or d["user_id"] != u.id:
        return await qans(q, "Deposit not found", True)
    if d["status"] == "approved":
        await qans(q, "Already credited to your wallet")
        return await _q_show(q, s_pay_ok(d["amount"], db_balance(u.id),
                                         d["utr"] or ""), kb_dep_ok())
    if d["status"] == "rejected":
        await qans(q, "This deposit was declined", True)
        return await _q_show(q, S_PAY_FAIL, kb_dep_retry())
    if d["payment_mode"] != "auto_upi":
        return await qans(q, "This older deposit is being reviewed by our "
                             "team. You will be notified.", True)
    now = time.monotonic()
    if now - _verify_cd.get(u.id, 0.0) < 3:
        return await qans(q, "Checking... please wait a moment")
    _verify_cd[u.id] = now
    state, res, r = await dep_check(did)
    if state == "credited":
        await qans(q, "Payment verified")
        m = q.message
        return await _announce_deposit(ctx.bot, u.id, did, res, r,
                                       m.chat_id if m else u.id,
                                       m.message_id if m else None)
    if state == "approved":
        await qans(q, "Already credited to your wallet")
        return await _q_show(q, s_pay_ok(d["amount"], db_balance(u.id)),
                             kb_dep_ok())
    if state == "expired":
        db_dep_timeout(did, "expired on verify")
        await qans(q, "No payment found for this order", True)
        return await _q_show(q, s_dep_expired(d["amount"]),
                             kb_dep_expired(did))
    if state == "review":
        return await qans(q, "The paid amount does not match this order. "
                             "Our team will review it shortly.", True)
    if state == "error":
        return await qans(q, "Payment server is not responding. Please try "
                             "again in a few seconds.", True)
    return await qans(q, "Payment not received yet. Complete the payment, "
                         "then tap Verify Payment again.", True)

