async def _auto_check(ctx, uid, did, ref, amt, payable, cid, mid):
    """Poll immediately, then credit each paid deposit exactly once."""
    me = asyncio.current_task()
    start = time.monotonic()
    try:
        while time.monotonic() - start < PAYMENT_WINDOW + 20:
            state, res, r = await dep_check(did, poll=True)
            if state in ("pending", "error"):
                await asyncio.sleep(PAYMENT_CHECK_INTERVAL)
                continue
            if state == "credited":
                await _announce_deposit(ctx.bot, uid, did, res, r, cid, mid)
            elif state == "expired":
                if db_dep_timeout(did, "gateway expired"):
                    await _replace_msg(ctx.bot, cid, mid, s_dep_expired(amt),
                                       kb_dep_expired(did))
            return
        if db_dep_timeout(did, "bot poll window ended"):
            await _replace_msg(ctx.bot, cid, mid, s_dep_expired(amt),
                               kb_dep_expired(did))
    except asyncio.CancelledError:
        pass
    except Exception as e:
        log.exception("Deposit auto-check error: %s", e)
    finally:
        if _pay_tasks.get(did) is me:
            _pay_tasks.pop(did, None)



