def db_user_flag_countries(uid, limit=24):
    return _get_conn().execute(
        "SELECT country_code, country_name, MAX(id) AS mid FROM orders "
        "WHERE user_id=? AND country_code IS NOT NULL AND country_code!='' "
        "GROUP BY country_code ORDER BY mid DESC LIMIT ?",
        (uid, int(limit))).fetchall()


def s_myflags(uid, bal, rows) -> str:
    if not rows:
        note = "Buy an account once — that country flag is saved here."
        body = [kv("Saved", "None yet")]
    else:
        note = "Tap a flag to open that country."
        body = [kv("Saved", f"<b>{len(rows)}</b> countries"),
                kv("Source", "Your past orders")]
    return (s_header(uid, bal) + "\n\n"
            + card("My Flags", body_lines=body, note=note))


def kb_myflags(rows):
    grid, row = [], []
    for r in rows:
        cc = str(r["country_code"] or "").upper()
        if len(cc) != 2:
            continue
        st = BTN_SUCCESS if (len(row) % 2 == 0) else BTN_PRIMARY
        row.append((btn_label(cc), f"buy_{cc}", st))
        if len(row) == 2:
            grid.append(row)
            row = []
    if row:
        grid.append(row)
    grid.append(kb_row(("Browse Accounts", "shop", BTN_SUCCESS)))
    grid.append(kb_row(("Main Menu", "main_menu")))
    return ikb(*grid) if grid else ikb(
        kb_row(("Browse Accounts", "shop", BTN_SUCCESS)),
        kb_row(("Main Menu", "main_menu")))


