async def cb_myacc(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await qans(q)
    u = q.from_user
    if not _guard(u):
        return await edit_q(q, BAN_MSG, None)

    try:
        page = 0
        if "_" in q.data:
            try:
                page = int(q.data.split("_")[1])
            except ValueError:
                pass

        # SIRF DELIVERED ORDERS (Failed aur dusre sab hide ho jayenge)
        total_ords = _get_conn().execute(
            "SELECT COUNT(*) FROM orders WHERE user_id=? AND status='delivered'",
            (u.id,)).fetchone()[0]

        if not total_ords:
            return await edit_q(
                q, f"<b>MY ORDERS</b>\n{LINE}\n"
                   + box(["No orders yet.",
                          "Purchase an account to see it here."]),
                _styled_markup([
                    kb_row(("Browse Accounts", "shop_tg", BTN_SUCCESS)),
                    kb_row(("Back", "main_menu", BTN_SUCCESS))]))

        per_page = 6
        total_pages = max(1, math.ceil(total_ords / per_page))
        page = max(0, min(page, total_pages - 1))

        # Fetch karte waqt bhi sirf delivered uthayenge
        page_ords = _get_conn().execute(
            "SELECT * FROM orders WHERE user_id=? AND status='delivered' "
            "ORDER BY id DESC LIMIT ? OFFSET ?",
            (u.id, per_page, page * per_page)).fetchall()

        start_idx = page * per_page
        
        cards = []
        rows = []
        
        for idx, o in enumerate(page_ords, start_idx + 1):
            last_code = ""
            try:
                lc = _get_conn().execute(
                    "SELECT code FROM otp_log WHERE order_id=? "
                    "ORDER BY id DESC LIMIT 1", (o["id"],)).fetchone()
                if lc and lc["code"]:
                    last_code = str(lc["code"])
            except Exception:
                pass

            card_lines = [
                f"Order    ·  <b>{idx}</b>",
                f"Status   ·  <b>{badge(o['status'])}</b>",
                f"Country  ·  {flag_emoji(o['country_code'])} {esc(o['country_name'] or 'Unknown')}",
                f"Price    ·  <b>{money(o['store_price'])}</b>",
                f"Date     ·  {str(o['created_at'] or '')[:10]}",
            ]
            if last_code:
                card_lines.append(f"Last OTP ·  <b>{esc(last_code)}</b>")

            cards.append("\n".join(card_lines))
            rows.append(kb_row((f"View {idx}", f"vo_{o['id']}", BTN_PRIMARY)))

        body = "\n\n".join(box(c.split("\n")) for c in cards)

        nav_row = []
        if page > 0:
            nav_row.append(("Prev", f"myacc_{page-1}", BTN_PRIMARY))
        else:
            nav_row.append(("Prev", "noop", BTN_NONE))
        
        nav_row.append((f"{page+1} / {total_pages}", "noop", BTN_DANGER))
        
        if page < total_pages - 1:
            nav_row.append(("Next", f"myacc_{page+1}", BTN_PRIMARY))
        else:
            nav_row.append(("Next", "noop", BTN_NONE))

        rows.append(kb_row(*nav_row))
        rows.append(kb_row(("Session Tools", "sesstools", BTN_DANGER),
                           ("Back", "main_menu", BTN_SUCCESS)))
        
        await edit_q(q, f"<b>MY ORDERS</b>  ·  Page {page+1} of {total_pages}\n"
                        f"{LINE}\n{body}", ikb(*rows))
                        
    except Exception as e:
        log.exception("cb_myacc error: %s", e)
        await edit_q(q, "Error loading orders. Please try again.", kb_home())


def _order_server(o) -> int:
    try:
        return int(o["server"]) if o["server"] else 1
    except (TypeError, ValueError, IndexError, KeyError):
        return 1


def quality_label(o) -> str:
    try:
        srv = int(o["server"]) if o["server"] else 1
    except (TypeError, ValueError, IndexError, KeyError):
        srv = 1
    return f"{SERVER_QUALITY.get(srv, '')} Account"


def _guarantee_active(o) -> bool:
    try:
        return bool(o["guarantee_until"]) and now_utc() < \
            datetime.fromisoformat(o["guarantee_until"])
    except Exception:
        return False


async def cb_vo(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await qans(q)
    u = q.from_user
    
    try:
        oid = int(q.data.split("_")[1])
        o = db_order(oid)
        
        if not o or o["user_id"] != u.id:
            return await qans(q, "Order not found", True)

        ph = str(o["phone_number"] or "").strip()
        if not ph or ph == "N/A":
            ph = "Syncing..."
            async def _bg_fetch():
                try:
                    _ph, _it = await resolve_phone(_order_iid(o), {}, tries=2)
                    if _ph:
                        db_upd_order(o["id"], phone_number=_ph)
                except Exception:
                    pass
            asyncio.create_task(_bg_fetch())

        last_otp = None
        try:
            last_otp = _get_conn().execute(
                "SELECT code, created_at FROM otp_log "
                "WHERE order_id=? ORDER BY id DESC LIMIT 1",
                (oid,)).fetchone()
        except Exception:
            last_otp = None

        extra = {}
        try:
            if o["extra_data"]:
                extra = json.loads(o["extra_data"]) or {}
        except Exception:
            extra = {}

        # ==========================================
        # YAHAN SE 2FA PASSWORD NIKAL RAHE HAIN
        # ==========================================
        login_data = {}
        try:
            if o["login_data"]:
                login_data = json.loads(o["login_data"]) or {}
        except Exception:
            pass
        pass_2fa = login_data.get("password", "")
        # ==========================================

        links = [str(x) for x in (extra.get("links") or []) if x]
        
        rows = []
        if str(o["status"]).lower() == "delivered" and _order_iid(o):
            rows.append(kb_row(("Get Login Code", f"otp_{oid}", BTN_SUCCESS)))
            rows.append(kb_row(("Download Session File", f"sjson_{oid}", BTN_SUCCESS)))
            if ph and full_phone(ph) != "—" and ph != "Syncing...":
                rows.append([kb_copy("Copy Number", full_phone(ph), BTN_SUCCESS)])
            if pass_2fa:
                rows.append([kb_copy("Copy 2FA Password", pass_2fa, BTN_SUCCESS)])
            rows.append(kb_row(("How To Sign In", f"guide_{oid}", BTN_PRIMARY)))
            rows.append(kb_row(("Terminate Bot Session", f"rst_{oid}", BTN_PRIMARY),
                               ("Terminate All Sessions", f"tall_{oid}", BTN_DANGER)))
            
        rows.append(kb_row(("Buy Again", f"srv_{_order_server(o)}_{o['country_code']}", BTN_SUCCESS), 
                           ("Back", "myacc_0", BTN_PRIMARY)))
        rows.append(kb_row(("Main Menu", "main_menu", BTN_PRIMARY)))

        # Sirf valid links ko button banayenge taaki Telegram error na de
        valid_links = [l for l in links[:3] if l.startswith("http")]
        if valid_links:
            for i, l in enumerate(valid_links, 1):
                try:
                    rows.insert(i - 1, kb_url(f"Session Link {i}", l, BTN_PRIMARY))
                except Exception:
                    pass

        prem_days = "No"
        if extra.get("premium"):
            d = _ts_date(extra.get("premium_until"))
            prem_days = "Yes" + (f" · until {d}" if d else "")
            
        sess = extra.get("sessions")
        sess_line = (f"Sessions   {sess} active"
                     + (f"   since {_ts_date(extra.get('session_created'))}"
                        if extra.get("session_created") else "")
                     if sess else "Sessions   —")

        otp_line = ""
        if last_otp and str(last_otp["code"] or "").strip():
            code = str(last_otp["code"]).strip()
            when = str(last_otp["created_at"] or "")[:19]
            otp_line = f"Last OTP   <b>{esc(code)}</b> <i>({esc(when)})</i>\n"

        # ==========================================
        # YAHAN TEXT ME 2FA PASSWORD ADD HO RAHA HAI
        # ==========================================
        pass_line = f"Password   <code>{esc(pass_2fa)}</code>\n" if pass_2fa else ""

        txt = (s_header(u.id, db_balance(u.id), u.username)
               + f"\n\n<b>ORDER #{o['id']}</b>   {badge(o['status'])}\n{DIV}\n"
               f"Country    {flag_emoji(o['country_code'])} <b>{esc(o['country_name'] or 'Unknown')}</b>\n"
               f"Number     <code>{esc(full_phone(ph))}</code>\n"
               f"Type       {quality_label(o)}\n"
               f"{sess_line}\n"
               f"Premium    {prem_days}\n"
               f"{pass_line}"  # <--- 2FA PASSWORD YAHAN DIKHEGA
               f"{otp_line}"
               f"Account link <code>{esc(o['account_link'] or '—')}</code>\n"
               f"Price      <b>{money(o['store_price'])}</b>\n"
               f"Date       {str(o['created_at'])[:16]}\n{DIV}")
               
        clean_txt = clean_text(txt)
        markup = apply_styles(ikb(*rows))
        
        try:
            # Pehle purane message ko edit karne ki koshish karega
            await q.edit_message_text(clean_txt, parse_mode=ParseMode.HTML,
                                      reply_markup=markup,
                                      disable_web_page_preview=True)
        except Exception as e:
            # Agar edit fail ho jaye, toh ek naya message bhej dega
            log.warning("cb_vo edit failed, sending new message: %s", e)
            await send(ctx.bot, u.id, txt, ikb(*rows))
            
    except Exception as e:
        log.exception("cb_vo error for order %s: %s", q.data, e)
        await send(ctx.bot, u.id, "Could not load this order. The data might be incomplete.", kb_home())


async def cb_repl(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await qans(q)
    u = q.from_user
    oid = int(q.data.split("_")[1])
    o = db_order(oid)
    if not o or o["user_id"] != u.id:
        return await qans(q, "Order not found", True)
    if o["status"] != "delivered":
        return await qans(q, "This order was not delivered", True)
    if not _guarantee_active(o):
        return await qans(q, "Warranty has expired for this order", True)
    db_upd_order(oid, status="replacement")
    await notify_admins(
        ctx.bot,
        f"{ICON['swap']} <b>REPLACEMENT REQUEST</b>\n{DIV}\n"
        f"Order #{oid}\nUser <code>{u.id}</code>\n"
        f"Country {esc(o['country_name'])}\n"
        f"{ICON['user']} Number "
        f"<code>{esc(full_phone(o['phone_number']))}</code>\n{DIV}")
    await edit_q(
        q, s_header(u.id, db_balance(u.id), u.username)
        + f"\n\n{ICON['swap']} <b>REPLACEMENT REQUESTED</b>\n{DIV}\n"
        "An admin will review this shortly and send a replacement "
        "or a refund.\n" + DIV, kb_home())

