def min_deposit() -> float:
    try:
        return max(1.0, float(db_get_setting("min_deposit", MIN_DEPOSIT)))
    except (TypeError, ValueError):
        return float(MIN_DEPOSIT)


def max_deposit() -> float:
    try:
        v = float(db_get_setting("max_deposit", MAX_DEPOSIT))
    except (TypeError, ValueError):
        v = float(MAX_DEPOSIT)
    return max(min_deposit() + 1.0, v)


def _adm(uid) -> bool:
    return is_admin(uid)


def admin_menu_text(uid=None) -> str:
    role = role_of(uid) if uid else ROLE_OWNER
    dep = db_pending_dep_count()
    rev = db_review_count()
    try:
        users_total = db_user_count()
    except Exception:
        users_total = 0
    tp = profit_report(0)
    todo = []
    if dep:
        todo.append(f"📥 <b>{dep}</b> deposit(s) waiting for approval")
    if rev:
        todo.append(f"🧾 <b>{rev}</b> order(s) need attention")
    hello = (f"{BRAND}\n<i>{sc('admin control centre')}</i>\n{LINE}\n"
             f"Signed in as <b>{ROLE_LABEL.get(role, 'Admin')}</b>\n")
    if role not in (ROLE_OWNER, ROLE_SUPER):
        perms = limited_perms()
        if not todo:
            todo.append("✅ Nothing pending - all clear")
        allowed = [lbl for k, lbl, _p in LIMITED_PERMS if k in perms]
        return (hello + "\n"
                + f"<b>{sc('today')}</b>  <i>({esc(tp['label'])})</i>\n"
                + box([f"🛒 Orders: <b>{tp['orders']}</b>",
                       f"👥 Users: <b>{users_total}</b>"])
                + "\n" + box(todo)
                + f"\n<b>{sc('your access')}</b>\n"
                + box(allowed or ["<i>No tools enabled - ask the Owner.</i>"]))
    on, allc = db_country_stats()
    cur = sup.currency.upper()
    if sup.balance is not None and sup.balance <= 0:
        todo.append("⚠️ <b>Supplier wallet is empty</b> - top up to keep selling")
    if not todo:
        todo.append("✅ Everything is clear - nothing pending")
    # ── SUPPLIER BALANCE (v24) - always visible, never silently empty ──
    if sup.balance is None:
        health_bal = ("Supplier balance: <b>not loaded</b>"
                      + (f" - <i>{esc(str(sup.last_error)[:70])}</i>"
                         if sup.last_error else
                         " - tap <b>Sync Supplier Balance</b>"))
    else:
        parts = [f"Supplier balance: <b>{sup.balance:,.2f} {cur}</b>"
                 + (f" = <b>₹{to_inr(sup.balance, cur):,.2f}</b>"
                    if cur != "INR" else
                    f" = <b>${sup_usd(sup.balance, cur):,.2f}</b>")
                 + f" <i>({sup.balance_age()})</i>"]
        if sup.main_balance is not None:
            parts.append(f"Main wallet {float(sup.main_balance):,.2f} {cur}"
                         f" / ₹{to_inr(sup.main_balance, cur):,.2f}")
        if sup.buy_balance:
            parts.append(f"Buying wallet {float(sup.buy_balance):,.2f} {cur}"
                         f" / ₹{to_inr(sup.buy_balance, cur):,.2f}"
                         + (f" (id {sup.buy_balance_id})"
                            if sup.buy_balance_id else ""))
        if sup.hold:
            parts.append(f"on hold {float(sup.hold):,.2f} {cur}"
                         f" / ₹{to_inr(sup.hold, cur):,.2f}")
        health_bal = "  •  ".join(parts)
    health = [f"🏭 Supplier: <b>{'online' if sup.balance is not None else 'offline'}</b>",
              health_bal,
              f"🌍 Live countries: <b>{on}</b> / {allc}",
              f"📦 Stock S1 / S2: <b>{_global_stock.get('accounts1') or 0}</b>"
              f" / <b>{_global_stock.get('accounts2') or 0}</b>",
              f"📏 Deposits: {money(min_deposit())} - {money(max_deposit())}"]
    if mongo.on():
        health.append("🍃 MongoDB: <b>"
                      + ("connected" if mongo.status == "ok"
                         else esc(mongo.status_line())) + "</b>")
    return (hello + "\n"
            + profit_block(tp) + "\n"
            + lifetime_block() + "\n"
            + box([f"👥 Users: <b>{users_total}</b>  •  "
                   f"📥 Deposits today: <b>{money(tp['deposits'])}</b>"])
            + "\n" + box(todo)
            + f"\n<b>{sc('system health')}</b>\n" + box(health))



def db_error_count(hours=24) -> int:
    """Errors logged in the last `hours` (drives the red Error Log button)."""
    r = _get_conn().execute(
        "SELECT COUNT(*) AS n FROM error_log "
        "WHERE created_at >= datetime('now', ?)",
        (f"-{int(hours)} hours",)).fetchone()
    return int(r["n"] or 0) if r else 0


