# ── Admin: force-join channels ─────────────────────────────────────
def s_forcejoin() -> str:
    chans = db_channels()
    rows = []
    for c in chans:
        kind = "Private" if str(c["kind"]) == "private" else "Public"
        rows.append(f"{ICON['caret']} <b>{esc(c['title'] or kind)}</b>   "
                    f"<i>{kind}</i>\n"
                    f"     {esc(c['link'] or '-')}"
                    + (f"\n     chat id <code>{c['chat_id']}</code>"
                       if c["chat_id"] else ""))
    if not rows:
        rows.append(f"{ICON['caret']} <i>no channel yet - users join "
                    "directly</i>")
    return (f"<b>FORCE JOIN</b>\n{LINE}\n" + box(rows) + "\n"
            + box([f"{ICON['caret']} Anti-bot math : "
                   f"<b>{'ON' if captcha_on() else 'OFF'}</b>  "
                   f"(every {captcha_hours()}h)",
                   f"{ICON['caret']} Terms screen : "
                   f"<b>{'ON' if terms_on() else 'OFF'}</b>",
                   f"{ICON['caret']} Strict verify : "
                   f"<b>{'ON' if fj_strict() else 'OFF'}</b>"])
            + "\n" + LINE)


def kb_forcejoin():
    rows = [kb_row(("Add Public Channel", "afj_pub", BTN_SUCCESS),
                   ("Add Private Channel", "afj_priv", BTN_PRIMARY))]
    for c in db_channels():
        rows.append(kb_row((f"Remove {c['title'] or c['id']}",
                            f"afj_del_{c['id']}", BTN_DANGER)))
    rows.append(kb_row((("Anti-bot OFF" if captcha_on() else "Anti-bot ON"),
                        "sec_captcha"),
                       (("Terms OFF" if terms_on() else "Terms ON"),
                        "sec_terms")))
    rows.append(kb_row(("Set Verify Hours", "sec_hours"),
                       ("Check Bot Rights", "afj_check")))
    rows.append(kb_row((("Strict Verify OFF" if fj_strict()
                         else "Strict Verify ON"),
                        "afj_strict", BTN_PRIMARY),
                       ("Fix Public Channel IDs", "afj_fix",
                        BTN_SUCCESS if not fj_strict() else BTN_PRIMARY)))
    rows.append(kb_row(("Admin Panel", "admin")))
    return ikb(*rows)


