async def cb_afj_fix(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _adm(q.from_user.id):
        return await qans(q, "Access denied", True)
    await qans(q, "Resolving channels...")
    lines = []
    for r in db_channels():
        if r["chat_id"]:
            lines.append(f"{ICON['check']} "
                         f"{esc(r['title'] or r['link'])}   "
                         f"<i>id ok</i>")
            continue
        ref = chan_ref(r)
        if not ref:
            lines.append(f"{ICON['cross']} {esc(r['link'] or '-')}   "
                         f"<i>no id and no public username</i>")
            continue
        try:
            chat = await ctx.bot.get_chat(ref)
            db_del_channel(r["id"])
            db_add_channel("public", r["link"], chat.id,
                           r["title"] or r["link"])
            lines.append(f"{ICON['check']} "
                         f"{esc(getattr(chat, 'title', r['link']))}   "
                         f"<code>{chat.id}</code>")
        except Exception as e:
            lines.append(f"{ICON['cross']} {esc(r['link'] or '-')}   "
                         f"<i>{esc(str(e)[:50])}</i>")
    if not lines:
        lines = [f"{ICON['dot']} No channels configured"]
    await edit_q(
        q, "<b>CHANNEL ID FIX</b>\n" + LINE + "\n" + box(lines) + "\n"
        + f"{ICON['info']} Channels with an id are verified on every "
          "entry.\n" + LINE,
        kb_forcejoin())


async def cb_afj_check(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _adm(q.from_user.id):
        return await qans(q, "Access denied", True)
    await qans(q, "Checking...")
    lines = []
    for c in db_channels():
        cid = c["chat_id"]
        if not cid:
            lines.append(f"{ICON['check']} "
                         f"{esc(c['title'] or c['link'])}   "
                         f"<i>public - no check needed</i>")
            continue
        try:
            chat = await ctx.bot.get_chat(int(cid))
            me = await ctx.bot.get_chat_member(int(cid), ctx.bot.id)
            st = getattr(getattr(me, "status", ""), "value",
                         getattr(me, "status", ""))
            ok_ = str(st).lower() in ("administrator", "creator")
            lines.append(f"{ICON['check'] if ok_ else ICON['cross']} "
                         f"{esc(getattr(chat, 'title', c['title']) or c['title'])}"
                         f"   <i>bot: {esc(str(st))}</i>")
        except Exception as e:
            lines.append(f"{ICON['cross']} "
                         f"{esc(c['title'] or c['link'])}   "
                         f"<i>{esc(str(e)[:60])}</i>")
    if not lines:
        lines = [f"{ICON['dot']} No channels configured"]
    await edit_q(q, f"<b>BOT RIGHTS CHECK</b>\n{LINE}\n" + box(lines)
                 + "\n" + LINE, kb_forcejoin())


