# ── Admin: MongoDB ─────────────────────────────────────────────────
def s_mongo() -> str:
    counts = {}
    try:
        counts = mongo.counts() if mongo.url() else {}
    except Exception:
        counts = {}
    local = {}
    try:
        conn = _get_conn()
        for t in mongo.ALL_COLLECTIONS:
            try:
                local[t] = int(conn.execute(
                    "SELECT COUNT(*) FROM " + t).fetchone()[0])
            except Exception:
                pass
    except Exception:
        pass
    st = mongo.queue_stats()
    rows = []
    for t in mongo.ALL_COLLECTIONS:
        if t not in counts and t not in local:
            continue
        rows.append(kv(t.replace("_", " ").capitalize(),
                       f"RAM <b>{local.get(t, 0)}</b> · "
                       f"mongo <b>{counts.get(t, '—')}</b>"))
    body = [
        kv("Status", f"<b>{esc(mongo.status_line())}</b>"),
        kv("Database", f"<code>{esc(mongo.dbname())}</code>"),
        kv("Host",
           f"{spoiler(esc((mongo.url().split('@')[-1].split('/')[0] or '—')))}"),
        kv("Mode", "<b>Main database</b> (live mirror, RAM cache)"
           if STORE["native"] else "Backup copy"),
        kv("Pending", f"<b>{STORE['pending']}</b> changes"),
        kv("Written", f"<b>{st['synced']}</b> docs"),
        kv("Queue", f"<b>{st['pending']}</b> pending · "
                    f"<b>{st['batches']}</b> batches"),
        kv("Dropped", f"<b>{st['dropped']}</b>"),
        kv("Sync", "automatic after committed changes"),
    ]
    return (f"<b>MONGODB ATLAS</b>\n{LINE}\n" + box(body) + "\n"
            + box(rows) + "\n"
            + f"{ICON['info']} MongoDB is the primary persistent store for users, "
              "orders,\ndeposits, ledger, settings, countries, admins, "
              "channels, promos.\n"
            + LINE)


def kb_mongo():
    if STORE["native"]:
        toggle = ("Required", "mg_toggle", BTN_NONE)
    else:
        on = mongo.on()
        toggle = (("Disable" if on else "Enable"), "mg_toggle",
                  BTN_DANGER if on else BTN_SUCCESS)
    return ikb(
        kb_row(("Flush Pending", "mg_fromlocal", BTN_SUCCESS),
               ("Full Sync Now", "mg_sync", BTN_PRIMARY)),
        kb_row(("Test Connection", "mg_test"),
               ("Set Connection URL", "mg_url")),
        kb_row(("Restore from MongoDB", "mg_restore", BTN_SUCCESS),
               ("Restore Users+Balance", "mg_restore_all", BTN_DANGER)),
        kb_row(toggle),
        kb_url("MongoDB Atlas Console", "https://cloud.mongodb.com/",
               BTN_PRIMARY),
        kb_row(("Admin Panel", "admin")),
    )



