async def cb_mg_toggle(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _adm(q.from_user.id):
        return await qans(q, "Access denied", True)
    if STORE_MODE == "mongo":
        await qans(q, "MongoDB is required and cannot be disabled", True)
        return await edit_q(q, s_mongo(), kb_mongo())
    cur = mongo.on()
    db_set_setting("mongo_on", "0" if cur else "1")
    mongo.reset()
    await qans(q, "MongoDB " + ("disabled" if cur else "enabled"))
    if not cur:
        db_, err = mongo._connect()
        if db_ is None:
            await edit_q(
                q, s_mongo() + f"\n{ICON['warn']} Connection failed: "
                f"<code>{esc(str(err)[:180])}</code>\n"
                "Run: <code>pip install pymongo</code>",
                kb_mongo())
            return
    await edit_q(q, s_mongo(), kb_mongo())



async def cb_mg_test(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _adm(q.from_user.id):
        return await qans(q, "Access denied", True)
    await qans(q, "Testing MongoDB...")
    db_, err = mongo._connect()
    if db_ is None:
        await edit_q(
            q, s_mongo() + f"\n{ICON['warn']} <b>FAILED</b>\n"
            f"<code>{esc(str(err)[:200])}</code>\n"
            "Run: <code>pip install pymongo</code>",
            kb_mongo())
        return
