async def cb_adept(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _adm(q.from_user.id):
        return await qans(q, "Access denied", True)
    await qans(q, "Testing the gateway...")
    rows = []
    ok_all = True
    rows.append(f"{ICON['caret']} UPI ID : "
                f"<code>{esc(FAMPAY_UPI_ID)}</code>")
    r = await gateway.create_order(1.0, name="QR Test")
    if r.get("ok"):
        rows.append(f"{ICON['check']} create-order : <b>OK</b> "
                    f"<code>{esc(str(r.get('order_id')))}</code>")
    else:
        ok_all = False
        rows.append(f"{ICON['cross']} create-order : <b>failed</b> "
                    f"- {esc(str(r.get('error'))[:70])}")
    qr_url = r.get("qr_url") or ""
    upi_id = r.get("upi_id") or FAMPAY_UPI_ID
    intent = r.get("upi_intent") or upi_intent_string(
        upi_id, r.get("payable_amount") or 1.0,
        ref=r.get("order_id") or "TEST")
    rows.append(f"{ICON['caret']} qr url : "
                + (f"<code>{esc(str(qr_url)[:64])}</code>"
                   if qr_url else "<i>none</i>"))
    gw_bytes = await fetch_bytes(qr_url) if qr_url else None
    rows.append(f"{ICON['caret']} gateway QR : "
                + (f"<b>{len(gw_bytes)} bytes</b>" if gw_bytes
                   else "<i>not available</i>"))
    loc = local_qr_bytes(intent)
    rows.append(f"{ICON['caret']} local QR : "
                + (f"<b>{len(loc)} bytes</b>" if loc
                   else ("<i>segno missing</i>" if segno is None
                         else "<i>failed</i>")))
    data = await qr_image_bytes(qr_url, upi_id, 1.0,
                                r.get("order_id") or "", intent)
    if data:
        rows.append(f"{ICON['check']} QR ready : <b>{len(data)} bytes</b>")
    else:
        ok_all = False
        rows.append(f"{ICON['cross']} QR : <b>NOT AVAILABLE</b>")
    if r.get("ok"):
        v = await gateway.verify(r["order_id"])
        rows.append(f"{ICON['caret']} verify : "
                    f"<code>{esc(str(v.get('status') or v.get('error')))[:40]}</code>")
    txt = ("<b>DEPOSIT / QR TEST</b>\n" + LINE + "\n" + box(rows) + "\n"
           + (f"{ICON['check']} <b>Everything works.</b>" if ok_all
              else f"{ICON['warn']} Fix the red lines above.")
           + "\n" + LINE)
    await edit_q(q, txt, ikb(kb_row(("Run Again", "adept", BTN_SUCCESS),
                                    ("Deposits", "adp")),
                             kb_row(("Admin Panel", "admin"))))
    if data:
        await send_qr(ctx.bot, q.from_user.id, qr_url,
                      f"{ICON['wallet']} <b>TEST QR - ₹1</b>\n{DIV}\n"
                      "Scan it to confirm the payment page opens.\n"
                      "<i>No money is needed for this test.</i>",
                      ikb(kb_row(("Admin Panel", "admin"))),
                      upi_id=upi_id, amount=1.0,
                      ref=r.get("order_id") or "TEST-QR", intent=intent)


