def buyer_tag_by_id(uid) -> str:
    try:
        r = db_user(int(uid))
    except Exception:
        r = None
    if not r:
        return f"<code>{uid}</code>"
    name = (r["first_name"] or "").strip()
    un = (r["username"] or "").strip().lstrip("@")
    bits = []
    if name:
        bits.append(esc(name))
    if un:
        bits.append(f"@{esc(un)}")
    bits.append(f"<code>{uid}</code>")
    return "  ".join(bits)


def buyer_tag(u) -> str:
    try:
        name = (getattr(u, "first_name", "") or "").strip()
        un = (getattr(u, "username", "") or "").strip().lstrip("@")
        uid = getattr(u, "id", None)
    except Exception:
        return ""
    bits = []
    if name:
        bits.append(esc(name))
    if un:
        bits.append(f"@{esc(un)}")
    if uid:
        bits.append(f"<code>{uid}</code>")
    return "  ".join(bits) if bits else "<i>unknown buyer</i>"


try:
    from telegram import ReactionTypeEmoji as _RTE
except Exception:
    _RTE = None

_LAST_USER_MSG: Dict[int, int] = {}
_LAST_MSG_AT: Dict[int, float] = {}


def remember_user_msg(uid, message_id):
    try:
        uid = int(uid)
        mid = int(message_id)
    except (TypeError, ValueError):
        return
    if uid <= 0 or mid <= 0:
        return
    _LAST_USER_MSG[uid] = mid
    _LAST_MSG_AT[uid] = time.time()


REACT_SOLD = "\U0001F389"
REACT_DEPOSIT = "\U0001F4B0"
REACT_OPEN = "\U0001F44D"


async def react(bot, uid, emoji=REACT_SOLD, big=False, message_id=None):
    if bot is None or not uid or not emoji:
        return False
    mid = message_id or _LAST_USER_MSG.get(int(uid))
    if not mid:
        return False
    try:
        if _RTE is not None:
            r = [_RTE(emoji)]
        else:
            r = emoji
        return bool(await bot.set_message_reaction(int(uid), mid, r,
                                                    is_big=bool(big)))
    except Exception as e:
        log.info("reaction skipped (%s): %s", emoji, str(e)[:70])
        return False


_BUSY: Dict[str, float] = {}


def _busy(key: str, ttl: float = 180.0) -> bool:
    now = time.monotonic()
    for k, t in list(_BUSY.items()):
        if now - t > ttl:
            _BUSY.pop(k, None)
    if key in _BUSY:
        return True
    _BUSY[key] = now
    return False


def _bg(coro, key: str = ""):
    async def _run():
        try:
            await coro
        except Exception as e:
            log.warning("background job %s failed: %s", key, str(e)[:160])
        finally:
            _BUSY.pop(key, None)
    return asyncio.create_task(_run())


_BG_TASKS: set = set()


def _spawn(coro):
    try:
        t = asyncio.create_task(coro)
    except Exception:
        return None
    _BG_TASKS.add(t)
    t.add_done_callback(_BG_TASKS.discard)
    return t


async def _auto_ack(q):
    await asyncio.sleep(3.5)
    if str(getattr(q, "id", "") or "") in _ANSWERED:
        return
    try:
        await q.answer()
    except Exception:
        pass


def _clip(text, n=26) -> str:
    s = " ".join(str(text or "").split())
    return s if len(s) <= n else s[:n - 1].rstrip() + "…"


