SORT_LABEL: Dict[str, str] = {
    "price_to_up": "Price  ·  Low to High",
    "price_to_down": "Price  ·  High to Low",
    "pdate_to_down_upload": "Newest Uploaded First",
    "pdate_to_down": "Recently Active First",
}
FILTER_FIELDS = ("spam", "premium", "password", "email")
FILTER_LABEL = {"spam": "Spam", "premium": "Premium",
                "password": "2FA", "email": "Email"}
FILTER_VALUES = ("yes", "no", "nomatter")
FILTER_TEXT = {"yes": "Yes", "no": "No", "nomatter": "Any"}

# Rolling upload-date windows. "1d" means the previous 24 hours, not the
# current calendar day. Short values keep Telegram callback data compact.
UPLOAD_DATE_VALUES = ("any", "new", "old")
UPLOAD_DATE_LABEL = {
    "any": "Any",
    "new": "Last 24 Hours",
    "old": "Older than 24 Hours",
}
UPLOAD_DATE_DAYS = {"new": 1, "old": 1}
RECENT_SCAN_BATCH = 4       # keep one tap responsive; paging resumes later
RECENT_CACHE_TTL = 60

_cat_cache: Dict[str, Any] = {}
_recent_cat_cache: Dict[str, Any] = {}
# v40: last GOOD page of every catalogue view, kept for 45 minutes. When the
# supplier endpoint dies the shop shows this instead of an error screen.
_cat_stale: Dict[str, Any] = {}
CAT_STALE_TTL = max(300, int(os.environ.get("CAT_STALE_TTL", "2700")))


def default_filters() -> dict:
    """v15: every filter defaults to "Any"."""
    return {"spam": "nomatter", "premium": "nomatter", "password": "nomatter",
            "email": "nomatter", "origin": "any", "kw": "",
            "upload_date": "any", "sort": "price_to_up",
            "age_mode": "any", "age_days": 0}


def valid_filters(fl) -> dict:
    """Repair a filter document: unknown / broken values become "Any"."""
    base = default_filters()
    if not isinstance(fl, dict):
        return base
    out = dict(base)
    for k in FILTER_FIELDS:
        v = str(fl.get(k) or "nomatter").lower()
        out[k] = v if v in FILTER_VALUES else "nomatter"
    og = fl.get("origin")
    out["origin"] = str(og).lower() if isinstance(og, str) and og else "any"
    kw = fl.get("kw")
    out["kw"] = str(kw)[:60] if isinstance(kw, str) else ""
    upload_date = str(fl.get("upload_date") or "any").lower()
    out["upload_date"] = (upload_date if upload_date in UPLOAD_DATE_VALUES
                          else "any")
    so = fl.get("sort")
    out["sort"] = so if isinstance(so, str) and so in SORT_LABEL \
        else "price_to_up"
    mode = str(fl.get("age_mode") or "any").lower()
    out["age_mode"] = mode if mode in ("any", "newer", "older") else "any"
    try:
        out["age_days"] = max(0, min(3650, int(fl.get("age_days") or 0)))
    except (TypeError, ValueError):
        out["age_days"] = 0
    if out["age_days"] <= 0:
        out["age_mode"] = "any"
    return out


def default_filter_state() -> dict:
    return {"fl_1": default_filters(), "fl_2": default_filters(),
            "csort": "low"}


def get_filters(ctx, srv, cc=None) -> dict:
    srv = int(srv or 1)
    key = f"fl_{srv}"
    fl = ctx.user_data.get(key)
    if not isinstance(fl, dict):
        fl = default_filters()
        if cc and str(cc).upper() != "ALL":
            old = ctx.user_data.pop(f"fl_{srv}_{cc}", None)
            if isinstance(old, dict):
                for k in default_filters():
                    if k in old:
                        fl[k] = old[k]
        ctx.user_data[key] = fl
    elif cc:
        ctx.user_data.pop(f"fl_{srv}_{cc}", None)
    fixed = valid_filters(fl)
    if fixed != fl:
        fl.clear()
        fl.update(fixed)
    return fl


_fl_saved: Dict[int, str] = {}


def _filter_state(ud) -> dict:
    c = ud.get("csort")
    return {"fl_1": valid_filters(ud.get("fl_1")),
            "fl_2": valid_filters(ud.get("fl_2")),
            "csort": "high" if c == "high" else "low"}


async def v15_filters_load(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Load the saved filters once per bot session (group -8)."""
    u = update.effective_user
    if u is None or ctx.user_data is None or ctx.user_data.get("_fl_loaded"):
        return
    ctx.user_data["_fl_loaded"] = True
    row = _get_conn().execute("SELECT filters_json FROM users WHERE user_id=?",
                              (u.id,)).fetchone()
    raw = row["filters_json"] if row else None
    try:
        doc = json.loads(raw) if raw else None
    except ValueError:
        log.warning("filters_json of %s is broken - reset to Any", u.id)
        doc = None
    st = _filter_state(doc if isinstance(doc, dict) else {})
    ctx.user_data["fl_1"] = st["fl_1"]
    ctx.user_data["fl_2"] = st["fl_2"]
    ctx.user_data["csort"] = st["csort"]
    js = json.dumps(st, sort_keys=True)
    _fl_saved[u.id] = js if (row and raw == js) else ""


async def v15_filters_save(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Persist filters / sort after a handler changed them (group 1)."""
    u = update.effective_user
    if u is None or ctx.user_data is None or not ctx.user_data.get("_fl_loaded"):
        return
    js = json.dumps(_filter_state(ctx.user_data), sort_keys=True)
    if _fl_saved.get(u.id) == js:
        return
    with _tx() as c:
        n = c.execute("UPDATE users SET filters_json=? WHERE user_id=?",
                      (js, u.id)).rowcount
    if n:
        _fl_saved[u.id] = js
        mg_push_user(u.id)







def srv_of_filter(fl) -> int:
    o = str((fl or {}).get("origin") or "").lower()
    return origin_server(o) or 1


def filter_summary(fl, with_sort=False) -> str:
    parts = [f"{FILTER_LABEL[f]} "
             f"{FILTER_TEXT.get(fl.get(f, 'nomatter'), 'Any')}"
             for f in FILTER_FIELDS]
    if fl.get("origin") and fl["origin"] != "any":
        parts.append(f"Origin {olabel(fl['origin'])}")
    upload_date = fl.get("upload_date", "any")
    if upload_date != "any":
        parts.append(f"Upload {UPLOAD_DATE_LABEL.get(upload_date, 'Any')}")
    if fl.get("kw"):
        parts.append(f"Search {fl['kw']}")
    if with_sort:
        sort_key = ("pdate_to_down_upload" if upload_date != "any"
                    else fl.get("sort"))
        parts.append(SORT_LABEL.get(sort_key, sort_key or ""))
    return "  ·  ".join(parts)


SERVER_MARGIN = {1: [ITEM_MARKUP, ITEM_ADDITION],
                 2: [ITEM_MARKUP, ITEM_ADDITION]}


def margin_for(srv) -> tuple:
    try:
        m = SERVER_MARGIN[int(srv or 1)]
    except (KeyError, TypeError, ValueError):
        m = SERVER_MARGIN[1]
    return float(m[0]), float(m[1])


def load_margins():
    for srv in (1, 2):
        try:
            mk = db_get_setting(f"s{srv}_markup")
            ad = db_get_setting(f"s{srv}_add")
            if mk:
                SERVER_MARGIN[srv][0] = float(mk)
            if ad:
                SERVER_MARGIN[srv][1] = float(ad)
        except (TypeError, ValueError):
            pass


def save_margin(srv, markup, add):
    srv = int(srv)
    old_m, old_a = margin_for(srv)
    SERVER_MARGIN[srv] = [float(markup), float(add)]
    db_set_setting(f"s{srv}_markup", f"{float(markup):.4f}")
    db_set_setting(f"s{srv}_add", f"{float(add):.4f}")
    db_log_margin(srv, markup, add)
    log.info("Margin S%s: x%.2f+%.2f -> x%.2f+%.2f",
             srv, old_m, old_a, markup, add)


def item_price_inr(cost, cur=None, floor=0.0, srv=1) -> float:
    """Shop price for one supplier item - never below the Profit Guard
    floor (supplier cost in INR + minimum profit)."""
    mk, ad = margin_for(srv)
    try:
        base = to_inr(cost, cur) * mk + ad
    except (TypeError, ValueError):
        base = float(floor or 0)
    base = math.ceil(base * 2) / 2.0
    return max(base, float(floor or 0), guard_price(cost, cur))



def max_cost_for_price(price_inr, cur=None, srv=1) -> float:
    """Highest supplier cost we accept for a given sale price. Also capped
    by the Profit Guard, so a purchase can never run at a loss."""
    mk, ad = margin_for(srv)
    c = str(cur or SUP_CURRENCY).lower()
    rate = usdt_rate() if c in ("usd", "usdt") else CUR_TO_INR.get(c, 1.0)
    try:
        cap = (float(price_inr) - float(ad)) / (float(rate) * float(mk))
    except (TypeError, ValueError, ZeroDivisionError):
        return 0.0
    return round(max(0.0, min(cap, guard_cost_cap(price_inr, cur))), 4)



def ago(ts) -> str:
    parsed = _as_unix_timestamp(ts)
    if parsed is None:
        return "—"
    sec = max(0, int(time.time()) - parsed)
    if sec < 60:
        return f"{sec}s ago"
    if sec < 3600:
        return f"{sec // 60}m ago"
    if sec < 86400:
        return f"{sec // 3600}h ago"
    return f"{sec // 86400}d ago"


def item_short_label(cc, item, price, srv=None) -> str:
    og = tname_srv(item.get("item_origin"), srv)
    return f"{flag_emoji(cc)} {og} | ₹{price:.2f}"


def item_btn_label(cc, item, price, idx=None, srv=None) -> str:
    og = tname_srv(item.get("item_origin"), srv)
    prefix = f"{idx}· " if idx else ""
    return f"{prefix}{flag_emoji(cc)} {og} | ₹{float(price):.2f}"


def item_origin_text(item, srv=None) -> str:
    return tname_srv(item.get("item_origin"), srv)


def _cat_key(srv, cc, fl) -> str:
    raw = json.dumps({"s": srv, "c": cc,
                      "f": {k: fl.get(k) for k in sorted(fl)}},
                     sort_keys=True)
    return f"{srv}|{cc}|{abs(hash(raw)) % 100000000}"


def _upload_days(fl) -> Optional[int]:
    value = str((fl or {}).get("upload_date") or "any").lower()
    return 1 if value in ("new", "old") else None


def _shop_country_code(item) -> Optional[str]:
    """Find the ISO-2 account country needed for cross-country result buttons."""
    item = item if isinstance(item, dict) else {}
    raw = item.get("telegram_country") or item.get("country") or ""
    if isinstance(raw, dict):
        raw = (raw.get("code") or raw.get("iso2") or raw.get("country_code")
               or raw.get("name") or "")
    candidate = str(raw or "").strip().upper()
    if candidate in DIAL_CODES and db_country(candidate):
        return candidate
    if candidate:
        try:
            rows = db_country_search(candidate)
            exact = [r for r in rows
                     if str(r["name"] or "").strip().casefold()
                     == candidate.casefold()]
            if exact:
                return str(exact[0]["code"]).upper()
        except Exception:
            pass
    phone = _find_phone(item)
    digits = re.sub(r"\D", "", str(phone or ""))
    if not digits:
        return None
    # Longest-prefix match avoids confusing short prefixes with a country
    # that has a more specific international dial code.
    codes = sorted(DIAL_CODES, key=lambda c: len(str(DIAL_CODES[c])),
                   reverse=True)
    for code in codes:
        dial = str(DIAL_CODES.get(code) or "")
        if (dial and digits.startswith(dial)
                and len(digits) - len(dial) >= 6 and db_country(code)):
            return code
    return None


async def _recent_catalog_page(srv, cc, fl, tg_page):
    """Scan newest supplier pages and retain only the requested upload window."""
    srv = int(srv or 1)
    cc = str(cc or "ALL").upper()
    tg_page = max(0, min(int(tg_page or 0), CAT_MAX_PAGES - 1))
    
    mode = str(fl.get("upload_date") or "new").lower()
    if mode not in ("new", "old"):
        return [], 0, "invalid_upload_date", {"recent": True}

    key = _cat_key(srv, cc, fl)
    now_mono = time.monotonic()
    state = _recent_cat_cache.get(key)
    if (not isinstance(state, dict)
            or now_mono - float(state.get("updated") or 0) > RECENT_CACHE_TTL):
        state = {"items": [], "ids": set(), "next_page": 1,
                 "done": False, "updated": now_mono, "api_seen": 0,
                 "api_total": 0}
        if len(_recent_cat_cache) >= 80:
            oldest = min(_recent_cat_cache,
                         key=lambda k: float((_recent_cat_cache.get(k) or {})
                                             .get("updated") or 0))
            _recent_cat_cache.pop(oldest, None)
        _recent_cat_cache[key] = state

    origins = list(SERVER_ORIGINS.get(srv) or [])
    if fl.get("origin") and fl.get("origin") != "any":
        origins = [fl["origin"]]
    allowed = list(origins)
    
    now_epoch = time.time()
    cutoff = now_epoch - 86400  # 24 hours rolling window
    
    # Cache cleanup logic based on new/old mode
    kept_items, kept_ids = [], set()
    for cached_item in state.get("items", []):
        published_ts = _item_published_timestamp(cached_item)
        if published_ts is None:
            continue
        if mode == "new":
            if not (cutoff <= published_ts <= now_epoch + 300):
                continue
        elif mode == "old":
            if published_ts >= cutoff:
                continue
        
        kept_items.append(cached_item)
        cached_id = str(cached_item.get("item_id") or cached_item.get("id") or "")
        if cached_id:
            kept_ids.add(cached_id)
            
    state["items"], state["ids"] = kept_items, kept_ids
    needed = (tg_page + 1) * CAT_PAGE_SIZE + 1
    scanned = 0
    scan_error = None
    
    # New = Latest uploads, Old = Standard price sort
    order_by = "pdate_to_down_upload" if mode == "new" else "price_to_up"

    while (not state.get("done") and len(state["items"]) < needed
           and scanned < RECENT_SCAN_BATCH):
        api_page = max(1, int(state.get("next_page") or 1))
        search_cc = None if cc == "ALL" else cc
        result = await sup.api_search(
            search_cc, origins, page=api_page,
            order_by=order_by,
            title=(fl.get("kw") or None),
            spam=fl.get("spam"), premium=fl.get("premium"),
            password=fl.get("password"), email=fl.get("email"))
        if result.get("err"):
            scan_error = result["err"]
            break

        raw_items = result.get("items") or []
        if not isinstance(raw_items, list):
            raw_items = []
        state["api_total"] = max(0, int(result.get("total") or 0))
        if not raw_items:
            state["done"] = True
            state["updated"] = time.monotonic()
            break

        timestamps = [_item_published_timestamp(it) for it in raw_items]
        
        past_cutoff_page = False
        if mode == "new":
            # Stop paging if the entire page is older than 24h
            past_cutoff_page = (
                len(timestamps) == len(raw_items)
                and all(ts is not None and ts < cutoff for ts in timestamps))

        if not past_cutoff_page:
            for item, published_ts in zip(raw_items, timestamps):
                if not isinstance(item, dict) or published_ts is None:
                    continue
                
                # Filtering based on user's choice (New vs Old)
                if mode == "new":
                    if published_ts < cutoff or published_ts > now_epoch + 300:
                        continue
                elif mode == "old":
                    if published_ts >= cutoff:
                        continue
                        
                if not sup.valid(item, search_cc, allowed,
                                fl.get("spam") or "nomatter",
                                strict_country=False):
                    continue
                if cc == "ALL":
                    item_cc = _shop_country_code(item)
                    if not item_cc or country_floor(item_cc, srv) <= 0:
                        continue
                else:
                    item_cc = cc
                item_id = str(item.get("item_id") or item.get("id") or "")
                if not item_id or item_id in state["ids"]:
                    continue
                state["ids"].add(item_id)
                shown_item = dict(item)
                shown_item["_shop_country"] = item_cc
                state["items"].append(shown_item)

        state["api_seen"] = int(state.get("api_seen") or 0) + len(raw_items)
        cursor_api = bool(result.get("cursor_api"))
        if cursor_api:
            has_next = bool(result.get("has_next"))
        else:
            has_next = (state["api_seen"] < state["api_total"]
                        and len(raw_items) >= CAT_API_PER_PAGE)
        state["next_page"] = api_page + 1
        state["updated"] = time.monotonic()
        scanned += 1

        if past_cutoff_page or not has_next:
            state["done"] = True

    state["updated"] = time.monotonic()
    all_matches = sort_items_for_display(srv, cc, state["items"], fl)
    start = tg_page * CAT_PAGE_SIZE
    end = start + CAT_PAGE_SIZE
    page_items = all_matches[start:end]
    has_next_result = len(all_matches) > end
    exact = bool(state.get("done"))
    load_more = (not exact and
                 (not has_next_result or bool(scan_error)))
    meta = {"recent": True, "exact": exact,
            "has_next": has_next_result, "load_more": load_more,
            "scan_error": scan_error, "scanned_pages": scanned}
    total = len(all_matches)
    if scan_error and not total:
        return [], 0, scan_error, meta
    return page_items, total, None, meta


async def _age_catalog_page(srv, cc, fl, tg_page):
    """v28: catalogue paging that really honours the account-age filter.

    The supplier is asked for the side where matching accounts live
    (newest first for "≤ N days", oldest first for "≥ N days"), so the
    very first page already contains usable accounts instead of the bot
    scanning thousands of irrelevant ones.
    """
    srv = int(srv or 1)
    cc = str(cc or "ALL").upper()
    tg_page = max(0, min(int(tg_page or 0), CAT_MAX_PAGES - 1))
    mode, days = age_mode_of(fl), age_days_of(fl)
    meta0 = {"recent": True, "exact": False, "has_next": False,
             "load_more": False, "age": True}
    if mode == "any" or days <= 0:
        return [], 0, "invalid_age", meta0
    cutoff = time.time() - days * 86400.0
    key = _cat_key(srv, cc, fl)
    now_mono = time.monotonic()
    st = _age_cat_cache.get(key)
    if (not isinstance(st, dict)
            or now_mono - float(st.get("updated") or 0) > RECENT_CACHE_TTL):
        if len(_age_cat_cache) >= 80:
            oldest = min(_age_cat_cache,
                         key=lambda k: float((_age_cat_cache.get(k) or {})
                                             .get("updated") or 0))
            _age_cat_cache.pop(oldest, None)
        st = {"items": [], "ids": set(), "next_page": 1, "done": False,
              "updated": now_mono, "scanned": 0, "api_total": 0,
              "order": age_order_by(fl), "fallback": False,
              "old_side": False, "error": None,
              "deep": False, "deep_runs": 0,
              "first_ids": "", "last_ids": ""}
        _age_cat_cache[key] = st
    else:
        st = dict(st)                      # copy-on-write, keep ids set
        st["ids"] = set(st.get("ids") or set())
        st["items"] = list(st.get("items") or [])
    origins = list(SERVER_ORIGINS.get(srv) or [])
    if fl.get("origin") and fl.get("origin") != "any":
        origins = [fl["origin"]]
    allowed = list(origins)
    search_cc = None if cc == "ALL" else cc
    needed = (tg_page + 1) * CAT_PAGE_SIZE + 1
    guard = 0
    age_budget = [AGE_LOOKUP_BUDGET]   # max item-detail lookups per tap
    # v34: min-age ke liye supplier ko young side se scan karna padta hai;
    # pehle page kaafi young nikal sakta hai, isliye thoda bada budget.
    max_pages = (AGE_DEEP_PAGES if st.get("deep") else
                 (AGE_SCAN_PAGES if mode == "older" else 12))
    while (not st["done"] and len(st["items"]) < needed
           and st["scanned"] < AGE_SCAN_BATCH and guard < max_pages):
        guard += 1
        page = int(st["next_page"] or 1)
        r = await sup.api_search(
            search_cc, origins, page=page, order_by=st["order"],
            title=(fl.get("kw") or None), spam=fl.get("spam"),
            premium=fl.get("premium"), password=fl.get("password"),
            email=fl.get("email"),
            session_age_days=age_session_days(fl))
        if r.get("err"):
            err = str(r.get("err"))
            # some supplier plans reject the oldest-first ordering - fall
            # back to the normal price order once, then keep filtering
            if (st.get("order") != "price_to_up" and not st.get("fallback")
                    and err not in ("check_limit", "rate", "auth")):
                st["fallback"] = True
                st["order"] = "price_to_up"
                continue
            st["error"] = err
            st["done"] = True
            break
        st["scanned"] = int(st.get("scanned") or 0) + 1
        st["next_page"] = page + 1
        try:
            st["api_total"] = max(0, int(r.get("total") or 0))
        except (TypeError, ValueError):
            pass
        items = r.get("items") or []
        if not items:
            st["done"] = True
            break
        # v29: list replies sometimes carry no upload date - ask for the
        # few items of this page so the age check can actually judge them
        if age_budget[0] > 0 and any(
                _item_published_timestamp(it) is None
                for it in items if isinstance(it, dict)):
            _want = min(age_budget[0], CAT_API_PER_PAGE)
            _undated = [it for it in items
                        if isinstance(it, dict)
                        and _item_published_timestamp(it) is None][:_want]
            if _undated:
                await ensure_item_ages(_undated, limit=_want)
                age_budget[0] -= len(_undated)
        stamps = [_item_published_timestamp(it) for it in items]
        if (mode == "newer" and stamps
                and all(t is not None and t < cutoff for t in stamps)):
            st["done"] = True              # everything left is too old
        for item, ts in zip(items, stamps):
            if not isinstance(item, dict) or ts is None:
                continue
            if is_bad_item(item.get("item_id") or item.get("id")):
                continue
            if (not age_filter_ok(item, fl)
                    and not (fl.get("_age_relaxed")
                             and _item_age_days(item) is None)):
                continue
            if not sup.valid(item, search_cc, allowed,
                             fl.get("spam") or "nomatter",
                             strict_country=False):
                continue
            if cc == "ALL":
                item_cc = _shop_country_code(item)
                if not item_cc or country_floor(item_cc, srv) <= 0:
                    continue
            else:
                item_cc = cc
            iid = str(item.get("item_id") or item.get("id") or "")
            if not iid or iid in st["ids"]:
                continue
            st["ids"].add(iid)
            shown = dict(item)
            shown["_shop_country"] = item_cc
            st["items"].append(shown)
        _sig = "|".join(str(it.get("item_id") or it.get("id") or "")
                        for it in (r.get("items") or [])[:8])
        if page <= 1:
            st["first_ids"] = _sig
        st["last_ids"] = _sig
        if not r.get("has_next", True):
            st["done"] = True
        if mode == "older" and len(st["items"]) >= needed:
            break
    # v34: min-age ("≥ N days") me agar young side par kaafi accounts nahi
    # mile (bade shop me hazaron account minimum se naye hote hain), to
    # purane side se ek extra pass chalao. Final list phir bhi age se
    # low -> high sort hoti hai, isliye sabse qareeb wale hi pehle aate hain.
    # v36: min-age me young side khatam hone par wahi side par AAGE scan
    # karo (supplier ka purana-side order ignore karne wale plans bhi kaam
    # karte hain) - ye "lower age ka count" wali shikayat ka asli fix hai.
    if (mode == "older" and len(st["items"]) < needed and not st["done"]
            and not st.get("deep")):
        st["deep"] = True
        st["deep_runs"] = 0
        st["scanned"] = 0
        st["updated"] = time.monotonic()
        _age_cat_cache[key] = st
        return await _age_catalog_page(srv, cc, fl, tg_page)
    if (mode == "older" and len(st["items"]) < needed and not st["done"]
            and st.get("deep") and int(st.get("deep_runs") or 0) < 6):
        st["deep_runs"] = int(st.get("deep_runs") or 0) + 1
        st["scanned"] = 0
        st["updated"] = time.monotonic()
        _age_cat_cache[key] = st
        return await _age_catalog_page(srv, cc, fl, tg_page)
    if (mode == "older" and len(st["items"]) < needed
            and not st.get("old_side")
            and st.get("first_ids") != st.get("last_ids")):
        st["old_side"] = True
        st["order"] = AGE_ORDER_OLD
        st["next_page"] = 1
        st["scanned"] = 0
        st["done"] = False
        st["updated"] = time.monotonic()
        _age_cat_cache[key] = st
        return await _age_catalog_page(srv, cc, fl, tg_page)
    st["updated"] = time.monotonic()
    _age_cat_cache[key] = st
    # v34: age wali list age se low -> high (price sort nahi)
    ordered = (sort_items_by_age(st["items"], fl, srv, cc)
               if age_active(fl)
               else sort_items_for_display(srv, cc, st["items"], fl))
    start = tg_page * CAT_PAGE_SIZE
    page_items = ordered[start:start + CAT_PAGE_SIZE]
    if age_active(fl):
        await ensure_item_ages(page_items, limit=CAT_PAGE_SIZE)
    total = max(len(st["items"]), 0)
    more = (len(st["items"]) > start + CAT_PAGE_SIZE) or not st["done"]
    meta = {"recent": True, "exact": False, "has_next": bool(more),
            "load_more": bool(more), "age": True}
    if st.get("error"):
        meta["scan_error"] = True
    return page_items, total, None, meta


def _cat_stale_key(srv, cc, fl, tg_page) -> tuple:
    """Key of one catalogue view (filters included, page separate)."""
    try:
        key = _cat_key(srv, cc, fl)
    except Exception:
        key = f"{srv}|{cc}"
    return (str(key), int(tg_page or 0))


def _cat_stale_put(srv, cc, fl, tg_page, items, total) -> None:
    if not items:
        return
    key = _cat_stale_key(srv, cc, fl, tg_page)
    if len(_cat_stale) > 400:
        _cat_stale.clear()
    _cat_stale[key] = (time.monotonic(), list(items), int(total or 0))


def _cat_stale_get(srv, cc, fl, tg_page):
    hit = _cat_stale.get(_cat_stale_key(srv, cc, fl, tg_page))
    if not hit:
        return None
    age = time.monotonic() - float(hit[0] or 0)
    if age > CAT_STALE_TTL:
        _cat_stale.pop(_cat_stale_key(srv, cc, fl, tg_page), None)
        return None
    return hit[1], hit[2], int(age)


async def catalog_page(srv, cc, fl, tg_page):
    """Live catalogue + the v40 safety net.

    * supplier error / outage -> the last good page of the same view
      (marked `meta["stale"]`, the screen says so) instead of E-101
    * a dead endpoint is reported as `busy`, never as a raw http_502
    """
    items, total, err, meta = await _catalog_page_live(srv, cc, fl, tg_page)
    meta = dict(meta or {})
    if not err:
        if items:
            _cat_stale_put(srv, cc, fl, tg_page, items, total)
        return items, total, err, meta
    stale = _cat_stale_get(srv, cc, fl, tg_page)
    if stale:
        s_items, s_total, s_age = stale
        meta.update({"stale": True, "stale_age": s_age, "err_note": str(err)})
        log.info("catalogue %s S%s served from cache (%ss old) - supplier: %s",
                 cc, srv, s_age, err)
        return s_items, s_total, None, meta
    if str(err) in ("busy", "rate", "timeout") or str(err).startswith("http_5"):
        meta.update({"err_note": str(err), "busy_left": sup.busy_left()})
        return [], 0, "busy", meta
    return items, total, err, meta


async def _catalog_page_live(srv, cc, fl, tg_page):
    if age_active(fl):                     # v28: age filter first
        items, total, err, meta = await _age_catalog_page(srv, cc, fl,
                                                          tg_page)
        if items or err:
            return items, total, err, meta
        # ── v37: age filter ne kuch na diya to accounts GAYAB nahi honge ──
        # 1) supplier ka apna session-age filter (server side) try karo
        mode, days = age_mode_of(fl), age_days_of(fl)
        if mode == "older" and days > 0:
            fl2 = dict(fl)
            fl2["_force_session_age"] = days
            fl2["_age_relaxed"] = True
            i2, t2, e2, m2 = await _age_catalog_page(srv, cc, fl2, tg_page)
            if i2:
                m2 = dict(m2 or {})
                m2["age_fallback"] = "session"
                return i2, t2, e2, m2
        # 2) phir bhi khali -> live stock dikhao (filter hata kar) + notice
        fl3 = dict(fl)
        fl3["age_mode"], fl3["age_days"] = "any", 0
        i3, t3, e3, m3 = await catalog_page(srv, cc, fl3, tg_page)
        if i3:
            m3 = dict(m3 or {})
            m3["age_fallback"] = "off"
            m3["age_label"] = age_label(fl)
            return i3, t3, e3, m3
        return items, total, err, meta
    if _upload_days(fl):
        return await _recent_catalog_page(srv, cc, fl, tg_page)
    tg_page = max(0, int(tg_page or 0))
    api_page = tg_page + 1  # ✅ FIX: Telegram Page aur API Page ab 1:1 hai
    key = _cat_key(srv, cc, fl)
    slot = _cat_cache.get(key)
    if not isinstance(slot, dict):
        slot = {}
    got = slot.get(api_page)
    now = time.monotonic()
    if got and now - got[0] < CAT_CACHE_TTL:
        items, total = got[1], got[2]
    else:
        origins = list(SERVER_ORIGINS.get(int(srv)) or [])
        if fl.get("origin") and fl["origin"] != "any":
            origins = [fl["origin"]]
        # v31 FIX: `country[]=ALL` is not a filter the supplier knows, so
        # the "all countries" view used to come back EMPTY. Passing no
        # country filter is what actually means "every country".
        search_cc = None if str(cc or "").upper() in ("ALL", "") else cc
        r = await sup.api_search(
            search_cc, origins, page=api_page,
            order_by=fl.get("sort") or "price_to_up",
            title=(fl.get("kw") or None),
            spam=fl.get("spam"), premium=fl.get("premium"),
            password=fl.get("password"), email=fl.get("email"))
        if r["err"]:
            return [], 0, r["err"], {"recent": False, "exact": True,
                                      "has_next": False, "load_more": False}
        items, total = r["items"], r["total"]
        if len(_cat_cache) > 240:
            _cat_cache.clear()
        slot[api_page] = (now, items, total)
        _cat_cache[key] = slot
    if fl.get("origin") and fl["origin"] != "any":
        allowed = [fl["origin"]]
    else:
        allowed = list(SERVER_ORIGINS.get(int(srv)) or [])
    cc_all = str(cc or "").upper() in ("ALL", "")
    if cc_all:
        # every account in this list comes from its own country - tag it so
        # the price, the flag and the button use THAT country's floor
        for _it in items:
            if not isinstance(_it, dict):
                continue
            _cc = _shop_country_code(_it)
            if _cc:
                _it["_shop_country"] = _cc
    clean = [i for i in items
             if not is_bad_item(i.get("item_id") or i.get("id"))
             and sup.valid(i, cc, allowed, fl.get("spam") or "no",
                           strict_country=False)
             and age_filter_ok(i, fl)]
    # v29: price order guaranteed on our side (low → high by default)
    clean = sort_items_for_display(srv, cc, clean, fl)
    page_items = clean[:CAT_PAGE_SIZE]
    if age_active(fl):
        await ensure_item_ages(page_items, limit=CAT_PAGE_SIZE)
    try:
        total = max(0, int(total or 0))
    except (TypeError, ValueError):
        total = 0
    meta = {"recent": False, "exact": True,
            "has_next": (tg_page + 1) * CAT_PAGE_SIZE < total,
            "load_more": False}
    # v31: warm the NEXT page while the user looks at this one, so
    # "Load More" / page+1 opens instantly instead of waiting ~1.3 s
    if meta["has_next"]:
        _prefetch_catalog_page(srv, cc, fl, tg_page + 1)
    return page_items, total, None, meta


_cat_prefetch: Dict[str, float] = {}


def _prefetch_catalog_page(srv, cc, fl, api_page) -> None:
    """Background warm-up of one catalogue page (never blocks a tap)."""
    try:
        key = f"{_cat_key(srv, cc, fl)}#{int(api_page)}"
        now = time.monotonic()
        if now - float(_cat_prefetch.get(key) or 0) < 20:
            return
        slot = _cat_cache.get(_cat_key(srv, cc, fl))
        got = slot.get(int(api_page)) if isinstance(slot, dict) else None
        if got and now - got[0] < CAT_CACHE_TTL:
            return
        _cat_prefetch[key] = now
        if len(_cat_prefetch) > 400:
            _cat_prefetch.clear()
    except Exception:
        return

    async def _work():
        _BG.set(True)
        try:
            origins = list(SERVER_ORIGINS.get(int(srv)) or [])
            if fl.get("origin") and fl["origin"] != "any":
                origins = [fl["origin"]]
            search_cc = None if str(cc or "").upper() in ("ALL", "") else cc
            r = await sup.api_search(
                search_cc, origins, page=int(api_page),
                order_by=fl.get("sort") or "price_to_up",
                title=(fl.get("kw") or None),
                spam=fl.get("spam"), premium=fl.get("premium"),
                password=fl.get("password"), email=fl.get("email"))
            if r.get("err") or not isinstance(r.get("items"), list):
                return
            slot = _cat_cache.setdefault(_cat_key(srv, cc, fl), {})
            slot[int(api_page)] = (time.monotonic(), r["items"],
                                   r.get("total") or 0)
            if len(_cat_cache) > 240:
                _cat_cache.clear()
        except Exception as e:
            log.debug("catalog prefetch: %s", str(e)[:80])
        finally:
            _BG.set(False)
    _spawn(_work())

def item_display_price(srv, cc, item) -> float:
    """Final shop price (INR) of one supplier item - same formula the
    catalogue shows, so sorting and the printed price always agree."""
    item = item if isinstance(item, dict) else {}
    cc_it = str(item.get("_shop_country")
                or ("" if str(cc or "").upper() == "ALL" else cc or "")).upper()
    try:
        floor = country_floor(cc_it, srv) if cc_it else 0.0
    except Exception:
        floor = 0.0
    try:
        return float(item_price_inr(item.get("price"),
                                    item.get("price_currency"), floor, srv))
    except Exception:
        return 0.0


def sort_items_by_age(items, fl=None, srv=None, cc=None) -> list:
    """v34: an age-filtered list is sorted **low -> high age** (newest first).

    * same age: price low -> high (tie-break)
    * when the buyer picked "High -> Low" the list sorts by price instead
    * items with an unknown age always go last
    """
    out = list(items or [])
    want_price_desc = str((fl or {}).get("sort") or "") == "price_to_down"

    def _age(it):
        d = _item_age_days(it)
        if d is None:
            return (1, 0)
        # ghante tak round - warna same din ke accounts ka microsecond
        # farq price tie-break ko bekaar kar deta hai
        return (0, int(round(float(d) * 24.0)))

    def _price(it):
        try:
            return float(item_display_price(srv or 1, cc or "IN", it))
        except Exception:
            return 0.0

    try:
        if want_price_desc:
            out.sort(key=_price, reverse=True)
        else:
            out.sort(key=lambda it: (_age(it), _price(it)))
    except Exception:
        return list(items or [])
    return out


def sort_items_for_display(srv, cc, items, fl) -> list:
    """v29: the bot itself sorts the page it shows.

    The supplier sorts in its own currency; our shop price adds the
    country floor and the margin, so the order could look random
    (high, low, high...). Price sort is applied locally, so
    "Low to High" (default) is guaranteed, and "High to Low" works too.
    """
    items = list(items or [])
    key = str((fl or {}).get("sort") or "price_to_up")
    if key not in ("price_to_up", "price_to_down"):
        return items
    try:
        items.sort(key=lambda it: item_display_price(srv, cc, it),
                   reverse=(key == "price_to_down"))
    except Exception:
        return list(items)
    return items


# v30: items the supplier refuses to sell (failed Telegram validation,
# invalid session, removed by admin...). Remembered so the bot stops
# wasting a purchase slot on them - this was why bulk buy kept
# "failing" on the cheapest accounts.
_BAD_ITEMS: set = set()


def mark_bad_item(iid) -> None:
    iid = str(iid or "").strip()
    if iid:
        _BAD_ITEMS.add(iid)
        if len(_BAD_ITEMS) > 4000:          # keep memory bounded
            _BAD_ITEMS.clear()


def is_bad_item(iid) -> bool:
    return str(iid or "").strip() in _BAD_ITEMS


UNBUYABLE_WORDS = ("validation", "invalid session", "session is invalid",
                   "blocked", "removed by the site administration",
                   "isn't visible", "is not available for purchase",
                   "can't be bought", "cannot be bought", "not for sale",
                   "account is blocked")


def looks_unbuyable(text) -> bool:
    low = str(text or "").lower()
    return any(w in low for w in UNBUYABLE_WORDS)


def _cnt_txt(n) -> str:
    if n is None:
        return "checking..."
    if isinstance(n, str):
        return "unavailable"
    return f"{int(n):,} accounts"


