def _age_fallback_notice(fl, meta) -> str:
    """Age filter ne kuch na diya to user ko saaf-saaf batao."""
    kind = (meta or {}).get("age_fallback")
    if not kind:
        return ""
    if kind == "session":
        return ("\n\n" + exp([
            "\u26a0\ufe0f The supplier could not confirm upload dates for "
            f"{age_label(fl)}.",
            "Showing accounts filtered by the supplier's own age signal, "
            "newest first.",
            "Tap Filters \u2192 Account age \u2192 Any for the full list."]))
    label = (meta or {}).get("age_label") or age_label(fl)
    return ("\n\n" + exp([
        f"\u26a0\ufe0f No account matched <b>{label}</b> right now.",
        "The age filter is paused for this list so you still see live "
        "stock - the accounts below are <b>not</b> age-filtered.",
        "Tap Filters to pick another age, or try again in a few minutes."]))


def s_catalog(srv, cc, cname, total, page_idx, pages, fl, low=None,
              exact=True, meta=None) -> str:
    srv = int(srv)
    cc_all = str(cc or "").upper() == "ALL"
    age_on = age_active(fl)
    recent = _upload_days(fl) is not None or age_on
    if recent:
        count_label = ("Matching accounts" if age_on else
                       "Recent uploads" if cc_all else "Matching uploads")
        count_text = f"{count_label}: " + ("at least " if not exact else "")
        count_text += f"<b>{int(total):,}</b>"
        count_text += (f"\n🎂 Account age: <b>{age_label(fl)}</b>" if age_on
                       else f"\n📅 Window: <b>"
                            f"{UPLOAD_DATE_LABEL.get(fl.get('upload_date'), 'Recent')}</b>")
        lines = [count_text]
    else:
        lines = [f"📦 Stock: <b>{int(total):,}</b>"]
    if low:
        lines.append(f"🏷 From: <b>{money(low)}</b>")
    if exact:
        lines.append(f"📄 Page: <b>{page_idx + 1}</b> of {pages}")
    else:
        lines.append(f"📄 Page: <b>{page_idx + 1}</b>  ·  more results load as you browse")
    if meta and meta.get("scan_error"):
        lines.append("\u25b2 More results could not be fetched just now. "
                     "Tap Load More to retry.")
    if meta and meta.get("stale"):
        # v40: supplier down -> purana page dikh raha hai, saaf saaf batao
        age = int(meta.get("stale_age") or 0)
        ago_txt = (f"{age // 60} min old" if age >= 90 else "just now")
        lines.append(f"\u27f3 Cached stock ({ago_txt}) - the supplier "
                     "catalogue is refreshing, prices may change.")
    if cc_all:
        title, icon, subtitle = "All Countries · Recent Uploads", "🌍", SERVER_SHORT.get(srv, "")
    else:
        title, icon, subtitle = str(cname or cc), flag_emoji(cc), SERVER_SHORT.get(srv, "")
    return (head(title, icon, sub=esc(subtitle)) + "\n"
            + box(lines)
            + "\n<i>Tap an account for full details 👇</i>"
            + _age_fallback_notice(fl, meta))


