def s_item_detail(srv, cc, cname, item, price, floor,
                  for_admin=False, stale=False) -> str:
    ch = flag_int(item.get("telegram_channels_count"))
    gr = flag_int(item.get("telegram_chats_count"))
    adm = flag_int(item.get("telegram_admin_count"))
    tfa = flag_int(item.get("telegram_password"))
    em = flag_int(item.get("telegram_email"))
    spam_state = telegram_spam_state(item)
    origin_text = tname_srv(item.get("item_origin"), srv)
    up_txt = ago(item.get("published_date"))
    seen_txt = ago(item.get("telegram_last_seen"))
    yn = lambda v: "✅ Yes" if v else "➖ No"
    spam = {True: "⚠️ Yes", False: "✅ No", None: "❔ Unknown"}[spam_state]
    admin_block = ""
    if for_admin:
        try:
            _cost = to_inr(item.get("price"), item.get("price_currency"))
        except (TypeError, ValueError):
            _cost = 0.0
        admin_block = ("\n" + f"<b>{sc('admin only')}</b>\n" + box([
            f"💵 Cost: {money(_cost)}",
            f"💹 Profit: <b>{money(max(0.0, price - _cost))}</b>"]))
    return (head("Account details", "📱") + "\n\n"
            + section("Overview", "🌍") + "\n"
            + box([kv("Country", f"{flag_emoji(cc)} <b>{esc(cname)}</b> "
                                f"<i>{ctag(cc)}</i>"),
                   kv("Price", f"<b>{money(price)}</b>"),
                   kv("Type", esc(origin_text)),
                   kv("Origin", esc(olabel(item.get('item_origin'))))])
            + "\n\n"
            + section("Age", "🎂") + "\n"
            + box([kv("Uploaded", f"{_ts_full_date(item.get('published_date')) or '—'}"
                                  f" ({up_txt})"),
                   kv("Account age", f"<b>{age_text_of(item)}</b>"),
                   kv("Last seen", seen_txt)])
            + "\n\n"
            + section("Signals", "🔐") + "\n"
            + box([kv("Premium", premium_text(item)),
                   kv("Chats", f"{ch} channels • {gr} groups • {adm} admin"),
                   kv("Spam block", spam),
                   kv("2FA", yn(tfa)),
                   kv("Email", yn(em))])
            + admin_block
            + ("\n\u27f3 <i>Live check skipped - the supplier catalogue is "
               "refreshing. Details are from the catalogue snapshot.</i>"
               if stale else "")
            + "\n<i>Tap Buy to purchase this exact account.</i>")



