def kb_catalog(srv, cc, items, prices, page, pages, meta=None):
    rows, row = [], []
    for it, pr in zip(items, prices):
        item_cc = str(it.get("_shop_country") or cc).upper()
        iid = it.get("item_id") or it.get("id")
        if not iid or item_cc == "ALL":
            continue
        # Accounts buttons (Blue) - the account age is printed on it
        _age = (age_short(it) if (_item_session_ts(it)
                                  or _item_published_timestamp(it)) else None)
        row.append((btn_label(item_cc, pr, _age),
                    f"itm_{srv}_{item_cc}_{iid}", BTN_PRIMARY + "!"))
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)

    if meta and meta.get("recent"):
        pager = []
        page_cb = (lambda i: f"catall_{srv}_{i}" if str(cc).upper() == "ALL"
                   else f"cat_{srv}_{cc}_{i}")
        if page > 0:
            pager.append(("« Prev", page_cb(page - 1), BTN_DANGER + "!"))
        pager.append((f"Page {page + 1}", "noop", BTN_DANGER + "!"))
        if meta.get("has_next"):
            pager.append(("Next »", page_cb(page + 1), BTN_DANGER + "!"))
        if pager:
            rows.append(pager)
        if meta.get("load_more"):
            rows.append(kb_row((
                "Load More (account age)" if meta.get("age")
                else "Load More Recent Uploads",
                f"catmore_{srv}_{cc}_{page}", BTN_PRIMARY + "!")))
    else:
        page_cb = (lambda i: f"catall_{srv}_{i}" if str(cc).upper() == "ALL"
                   else f"cat_{srv}_{cc}_{i}")
        pg = kb_num_pager(page, pages, page_cb)
        if pg:
            # Pagination (Red)
            rows.append([(txt, cb, BTN_DANGER + "!") for txt, cb, _ in pg])
            
    # Bulk Buy (Green)
    if bulk_on() and str(cc).upper() != "ALL":
        rows.append(kb_row(("Bulk Buy", f"bbuy_{srv}_{cc}", BTN_SUCCESS + "!")))
        
    # « back aur Filters ek line me (Green)
    # (Main Menu hata diya hai aur back ko « back kar diya hai)
    rows.append(kb_row(("« back", f"scl_{srv}_0", BTN_SUCCESS + "!"),
                       ("Filters", f"cf_{srv}_{cc}", BTN_SUCCESS + "!")))
    
    return ikb(*rows)



def kb_item(srv, cc, iid, price, back_cb=None, prev_iid=None, next_iid=None, global_idx=1, total=1):
    rows = []
    rows.append(kb_row((f"Buy Account \u2022 {money(price)}", f"ibuy_{srv}_{cc}_{iid}", BTN_SUCCESS + "!")))
    
    nav = []
    if prev_iid:
        nav.append((f"\u00ab {global_idx - 1}", f"itm_{srv}_{cc}_{prev_iid}", BTN_PRIMARY + "!"))
    else:
        nav.append(("\u00ab", "noop", BTN_NONE))
        
    nav.append((f"{global_idx} / {total}", "noop", BTN_PRIMARY + "!"))
    
    if next_iid:
        nav.append((f"{global_idx + 1} \u00bb", f"itm_{srv}_{cc}_{next_iid}", BTN_PRIMARY + "!"))
    else:
        nav.append(("\u00bb", "noop", BTN_NONE))
        
    rows.append(kb_row(*nav))
    
    back_cb = back_cb or f"cat_{srv}_{cc}_0"
    rows.append(kb_row(("Refresh", f"itmr_{srv}_{cc}_{iid}", BTN_PRIMARY + "!"), 
                       ("Back", back_cb, BTN_DANGER + "!")))
    return _styled_markup(rows)


