# ══════════════════════════════════════════════════════════════════════
#  v26  ACCOUNT-AGE FILTER  (random / server bulk + catalogue)
#  "Age" = how long ago the account was created / uploaded at the
#  supplier. The buyer can pick a preset or type any number of days.
# ══════════════════════════════════════════════════════════════════════
AGE_PRESETS = (("any", "Any age", "any"),
               (1, "\u2264 1 day", "1"),
               (3, "\u2264 3 days", "3"),
               (7, "\u2264 7 days", "7"),
               (30, "\u2264 30 days", "30"),
               (90, "\u2264 90 days", "90"),
               ("old1", "\u2265 1 day", "old1"),
               ("old7", "\u2265 7 days", "old7"),
               ("old30", "\u2265 30 days", "old30"),
               ("old90", "\u2265 90 days", "old90"))
AGE_KEYS = ("telegram_registration_date", "registration_date",
            "telegram_created_at", "created_at", "added_at", "imported_at",
            "published_date", "publishedDate", "published_at", "publishedAt")


def _item_session_ts(item) -> Optional[int]:
    """v30: the REAL account age - when the supplier created the session.

    Live API check (2 Nov 2026): the /telegram list already carries
    `telegram_session_created_at`, so the age filter no longer needs any
    extra item lookup, and the API can even filter on it server side
    (`session_age` + `session_age_period`).
    """
    item = item if isinstance(item, dict) else {}
    for key in ("telegram_session_created_at", "telegramSessionCreatedAt",
                "session_created_at", "sessionCreatedAt", "session_date",
                "telegram_session_date"):
        value = item.get(key)
        if value in (None, "", 0):
            continue
        parsed = _as_unix_timestamp(value)
        if parsed:
            return parsed
    return None


def _item_age_ts(item) -> Optional[int]:
    """Best-known creation / upload timestamp of a supplier item."""
    item = item if isinstance(item, dict) else {}
    for key in AGE_KEYS:
        value = item.get(key)
        if value in (None, ""):
            continue
        parsed = _as_unix_timestamp(value)
        if parsed:
            return int(parsed)
    ts = _item_published_timestamp(item)
    return int(ts) if ts else None


def _item_age_days(item) -> Optional[float]:
    """v31: account age = how long ago the account was UPLOADED (the
    listing date the shop shows). The supplier session date is only used
    when the upload date is missing from the payload."""
    ts = _item_age_ts(item) or _item_session_ts(item)
    if not ts:
        return None
    return max(0.0, (time.time() - ts) / 86400.0)


def _item_upload_days(item) -> Optional[float]:
    ts = _item_age_ts(item)
    if not ts:
        return None
    return max(0.0, (time.time() - ts) / 86400.0)


def _item_session_days(item) -> Optional[float]:
    ts = _item_session_ts(item)
    if not ts:
        return None
    return max(0.0, (time.time() - ts) / 86400.0)


def age_mode_of(fl) -> str:
    m = str((fl or {}).get("age_mode") or "any").lower()
    return m if m in ("newer", "older") else "any"


def age_days_of(fl) -> int:
    try:
        return max(0, min(3650, int((fl or {}).get("age_days") or 0)))
    except (TypeError, ValueError):
        return 0


def age_filter_ok(item, fl) -> bool:
    mode, days = age_mode_of(fl), age_days_of(fl)
    if mode == "any" or days <= 0:
        return True
    age = _item_age_days(item)
    if age is None:
        return False                      # unknown age cannot be trusted
    return age <= days if mode == "newer" else age >= days


def age_label(fl) -> str:
    mode, days = age_mode_of(fl), age_days_of(fl)
    if mode == "any" or days <= 0:
        return "Any"
    return (f"\u2264 {days} day" + ("s" if days > 1 else "")
            if mode == "newer" else
            f"\u2265 {days} day" + ("s" if days > 1 else ""))


# ── v28: the age filter is now really applied everywhere ─────────────
AGE_ORDER_NEW = "pdate_to_down_upload"    # newest uploads first
AGE_ORDER_OLD = "pdate_to_up_upload"      # oldest uploads first
_age_cat_cache: Dict[str, dict] = {}


def age_active(fl) -> bool:
    """True when the buyer picked an account-age filter."""
    return age_mode_of(fl) != "any" and age_days_of(fl) > 0


def age_cutoff(fl) -> Optional[float]:
    """Unix timestamp of the age window edge (None when no filter)."""
    if not age_active(fl):
        return None
    return time.time() - age_days_of(fl) * 86400.0


def age_session_days(fl) -> Optional[int]:
    forced = (fl or {}).get("_force_session_age")
    if forced:
        try:
            return max(1, int(forced))
        except (TypeError, ValueError):
            return None
    return _age_session_days_off(fl)


def _age_session_days_off(fl) -> Optional[int]:
    """v31: the shop's age filter follows the UPLOAD date, so the supplier's
    `session_age` filter (which counts from the session creation) must NOT
    be used - otherwise a 72-day-old ad with a 1-day-old session would be
    dropped. Paging order (`pdate_to_*_upload`) + a local check do the job."""
    return None


def age_order_by(fl, default="price_to_up") -> str:
    """v34: always page from the **newest uploads** side.

    Before this, 'older' (min age) mode paged from the oldest uploads, so
    "min 1 day" showed accounts that were 300-400 days old. Scanning now
    runs young -> old, so the accounts closest to the minimum are found
    first (and the list itself is shown age low -> high).
    """
    if not age_active(fl):
        return default
    return AGE_ORDER_NEW


def age_days_int(item) -> Optional[int]:
    d = _item_age_days(item)
    return None if d is None else int(d)


def age_text_of(item) -> str:
    """Human age of one supplier item: '3 days old' / '7 h old'."""
    d = _item_age_days(item)
    if d is None:
        return "unknown"
    if d < 1:
        return f"{max(1, int(round(d * 24)))} h old"
    days = int(d)
    return f"{days} day" + ("s" if days != 1 else "") + " old"


def age_short(item) -> str:
    """'42d' - used inside file/details lines."""
    d = _item_age_days(item)
    if d is None:
        return "?"
    return f"{int(round(d * 24))}h" if d < 1 else f"{int(d)}d"


def parse_age_input(text):
    """'1' / '1d' / '5 days' / '>30' / 'older 60' / '-' (clear)."""
    raw = " ".join(str(text or "").strip().lower().split())
    if not raw or raw in ("-", "any", "0", "/", "off"):
        return "any", 0
    mode = "newer"
    if raw.startswith((">", "old", "older", "+")):
        mode = "older"
    nums = re.findall(r"\d+", raw)
    if not nums:
        return None, None
    days = max(1, min(3650, int(nums[0])))
    return mode, days


# ── v36: age band counts ─────────────────────────────────────────────
# "≤ 1 day kitne account hain" ka jawab screen par dikhata hai. Newest
# pages scan hote hain (same order jo filter use karta hai) aur result
# 2 minute cache hota hai.
AGE_COUNT_PAGES = max(2, int(os.environ.get("AGE_COUNT_PAGES", "8")))
AGE_COUNT_TTL = 120
AGE_COUNT_LOOKUPS = max(20, int(os.environ.get("AGE_COUNT_LOOKUPS", "120")))
AGE_COUNT_BUDGET = float(os.environ.get("AGE_COUNT_BUDGET", "12"))
_age_band_cache: Dict[str, dict] = {}


def _age_band_key(srv, cc, fl) -> str:
    keep = {k: v for k, v in (fl or {}).items()
            if k not in ("age_mode", "age_days")}
    raw = json.dumps({"s": int(srv or 1), "c": str(cc or "").upper(),
                      "f": {k: keep[k] for k in sorted(keep)}}, sort_keys=True)
    return f"{srv}|{cc}|{abs(hash(raw)) % 100000000}"


def age_band_codes() -> list:
    """Preset codes jin par count dikhana hai (<= aur >= dono)."""
    return [c for _v, _l, c in AGE_PRESETS if c != "any"]


async def age_band_counts(srv, cc, fl=None, force=False) -> dict:
    """Scan newest uploads -> {preset_code: count, '_sampled': n, ...}."""
    fl = dict(fl or default_filters())
    key = _age_band_key(srv, cc, fl)
    now_mono = time.monotonic()
    hit = _age_band_cache.get(key)
    if (not force and isinstance(hit, dict)
            and now_mono - float(hit.get("at") or 0) < AGE_COUNT_TTL):
        return hit
    out = {"at": now_mono, "sampled": 0, "capped": False}
    for code in age_band_codes():
        out[code] = 0
    cc_sel = str(cc or "").upper()
    search_cc = None if cc_sel in ("ALL", "") else cc_sel
    origins = list(SERVER_ORIGINS.get(int(srv or 1)) or [])
    if fl.get("origin") and fl.get("origin") != "any":
        origins = [fl["origin"]]
    budget = AGE_COUNT_LOOKUPS
    seen = set()
    # pehle newest side, phir (agar min-age bands khali hain) oldest side -
    # warna ">= 30 days" jaisa band hamesha 0 dikhta tha
    passes = [AGE_ORDER_NEW]
    for order in passes:
        if order != AGE_ORDER_NEW and not any(
                not out.get(c) for c in age_band_codes()
                if str(c).startswith("old")):
            continue
        try:
            await _age_count_pass(out, seen, srv, cc, search_cc, origins, fl,
                                  order, budget)
        except Exception as e:
            log.warning("age_band_counts(%s): %s", order, str(e)[:100])
        if order == AGE_ORDER_NEW and any(
                not out.get(c) for c in age_band_codes()
                if str(c).startswith("old")):
            passes.append(AGE_ORDER_OLD)
    _age_count_store(key, out)
    return out


async def _age_count_pass(out, seen, srv, cc, search_cc, origins, fl, order,
                          budget):
    """Ek ordering par AGE_COUNT_PAGES page padho aur bands count karo."""
    t0 = time.monotonic()
    for page in range(1, AGE_COUNT_PAGES + 1):
        if time.monotonic() - t0 > AGE_COUNT_BUDGET:
            break                      # screen ko intezaar me na rakho
        try:
            r = await sup.api_search(
                search_cc, origins, page=page, order_by=order,
                title=(fl.get("kw") or None), spam=fl.get("spam"),
                premium=fl.get("premium"), password=fl.get("password"),
                email=fl.get("email"))
        except Exception:
            break
        if True:                       # (indent rakha gaya hai)
            if r.get("err"):
                break
            items = [it for it in (r.get("items") or [])
                     if isinstance(it, dict)]
            if not items:
                break
            undated = [it for it in items
                       if _item_published_timestamp(it) is None]
            if undated and budget > 0:
                take = undated[:budget]
                await ensure_item_ages(take, limit=len(take))
                budget -= len(take)
            for it in items:
                iid = str(it.get("item_id") or it.get("id") or "")
                if iid and iid in seen:
                    continue
                if iid:
                    seen.add(iid)
                if not sup.valid(it, search_cc,
                                 origins, spam=fl.get("spam") or "nomatter",
                                 strict_country=bool(search_cc)):
                    continue
                days = _item_age_days(it)
                out["sampled"] += 1
                if days is None:
                    continue
                for code in age_band_codes():
                    if age_filter_ok(it, {"age_mode": "older" if str(
                            code).startswith("old") else "newer",
                            "age_days": int(str(code).replace("old", "")
                                            or 30)}):
                        out[code] += 1
            if not r.get("has_next", True):
                break


def _age_count_store(key, out) -> None:
    if len(_age_band_cache) > 60:
        oldest = min(_age_band_cache,
                     key=lambda k: float((_age_band_cache.get(k) or {})
                                         .get("at") or 0))
        _age_band_cache.pop(oldest, None)
    _age_band_cache[key] = out


def age_band_of(srv, cc, fl=None) -> dict:
    """Cached counts (sync) - screen builders ke liye."""
    return _age_band_cache.get(_age_band_key(srv, cc, fl or {})) or {}


def age_band_label(code, counts) -> str:
    """'≤ 1 day · 12' - button label ke liye."""
    label = next((str(l) for v, l, c in AGE_PRESETS if c == code), "")
    if not label:
        return ""
    n = counts.get(code) if isinstance(counts, dict) else None
    if n is None:
        return label
    return f"{label} \u00b7 {int(n)}"


def s_age_edit(srv, cc, cname, fl) -> str:
    scope = ("All countries on this server" if str(cc or "").upper() == "ALL"
             else esc(cname or cc))
    txt = (f"<b>\U0001F382 ACCOUNT AGE FILTER</b>\n{LINE}\n"
           f"Scope   : <b>{scope}</b>\n"
           f"Current : <b>{age_label(fl)}</b>\n\n"
           + box(["\u2264 N days  = account created / uploaded in the "
                  "last N days (fresh accounts)",
                  "\u2265 N days  = account is at least N days old "
                  "(aged accounts)",
                  "List order: <b>newest first</b> - with \u2265 1 day the "
                  "youngest eligible accounts come first, 300-400 day old "
                  "accounts at the very end.",
                  "If the supplier sends no dates we fall back to the "
                  "session age, and if that is missing too the list shows "
                  "live stock unfiltered - this screen never goes empty."])
           + _age_count_block(srv, cc, fl)
           + "\n\n<i>Pick a preset or tap Custom and type e.g. "
             "<code>1</code>, <code>5</code>, <code>older 30</code>.</i>")
    return txt


def _age_count_block(srv, cc, fl) -> str:
    """'Kaunse band me kitne account' - screen par live counts."""
    counts = age_band_of(srv, cc, fl)
    if not counts:
        return ("\n\n<i>Stock counts are loading - tap any preset once and "
                "this screen will show how many accounts each band has.</i>")
    rows, row = [], []
    for code in age_band_codes():
        label = next((str(l) for v, l, c in AGE_PRESETS if c == code), "")
        if not label:
            continue
        n = int(counts.get(code) or 0)
        row.append(f"{label}: <b>{n}</b>")
        if len(row) == 2:
            rows.append("  \u2022  ".join(row))
            row = []
    if row:
        rows.append("  \u2022  ".join(row))
    head = ("<b>Live stock by age</b>\n"
            f"<i>{int(counts.get('sampled') or 0)} live accounts "
            "checked right now</i>")
    return "\n\n" + head + "\n" + box(rows)


def kb_age_edit(srv, cc, fl):
    """Preset buttons - built with kb_row so every entry IS a button
    (v26 shipped raw tuples here, which made InlineKeyboardMarkup raise
    and the age screen unclickable)."""
    mode, days = age_mode_of(fl), age_days_of(fl)
    cur = "any" if mode == "any" or days <= 0 else (
        f"{days}" if mode == "newer" else f"old{days}")
    counts = age_band_of(srv, cc, fl)
    btns = []
    for _value, label, code in AGE_PRESETS:
        mark = "  \u2713" if str(code) == cur else ""
        st = BTN_SUCCESS if str(code) == cur else BTN_PRIMARY
        shown = age_band_label(code, counts) or label
        btns.append((shown + mark, f"cfagv_{srv}_{cc}_{code}", st))
    rows = [kb_row(*btns[i:i + 2]) for i in range(0, len(btns), 2)]
    rows.append(kb_row(("\u270F\uFE0F Custom age (days)",
                        f"cfagc_{srv}_{cc}", BTN_SUCCESS)))
    rows.append(kb_row(("Back to Filters", f"cf_{srv}_{cc}", BTN_PRIMARY),
                       ("Main Menu", "main_menu")))
    return _styled_markup(rows)


