async def open_catalog(q, ctx, srv, cc, page=0):
    u = q.from_user
    c = db_country(cc)
    ctx.user_data["shop_srv"] = int(srv)
    if not c:
        return await edit_q(
            q, f"<b>COUNTRY NOT FOUND</b>\n{LINE}\n"
            + box([f"<code>{esc(cc)}</code> is not in the catalogue."]),
            kb_home())
    if country_floor(cc, srv) <= 0:
        # v40: a failed stock probe used to look like "no stock". Ask once,
        # live, and only then say it - otherwise the country is not empty,
        # the supplier is just busy.
        probe = await country_probe(cc, srv)
        if country_floor(cc, srv) <= 0:
            if probe.get("err") in ("busy", "rate") or sup.busy():
                return await edit_q(
                    q, s_catalog_busy(cc, srv, probe.get("err") or ""),
                    ikb(kb_row(("Retry", f"srv_{srv}_{cc}")),
                        kb_row(("Main Menu", "main_menu"))))
            return await edit_q(
                q, f"<b>NO STOCK</b>\n{LINE}\n" + box([f"{esc(c['name'])} has no {SERVER_QUALITY.get(int(srv or 1), '')} stock on Server {int(srv or 1)} right now."]),
                kb_notify(cc, srv))

    # LOADING ANIMATION (Wapas add kar diya)
    await edit_q(q, s_cat_load(srv, cc, c["name"]))

    fl = get_filters(ctx, srv, cc)
    key = _cat_key(srv, cc, fl)
    _cat_cache.pop(key, None)
    _recent_cat_cache.pop(key, None)

    # v40: api_search khud retry karta hai + breaker/cache sambhalta hai,
    # isliye yahan dobara try karne ki zarurat nahi (warna tap slow ho jata)
    items, total, err, meta = await catalog_page(srv, cc, fl, page)
    if err:
        body = (s_catalog_busy(cc, srv, err) if str(err) in ("busy", "rate")
                else s_err("E-101"))
        return await edit_q(q, body, ikb(kb_row(("Retry", f"srv_{srv}_{cc}")), kb_row(("Main Menu", "main_menu"))))
    await render_catalog(q, u, srv, cc, c, items, total, page, ctx, meta=meta)

