async def cb_srvsel(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await qans(q)
    if not _guard(q.from_user):
        return await edit_q(q, BAN_MSG, None)
    cc = q.data.split("_")[1]
    c = db_country(cc)
    if not c:
        return await edit_q(q, f"{ICON['warn']} This country "
                            "is not available right now.", kb_home())
    bal = db_balance(q.from_user.id)
    await edit_q(q, s_srv_pick(cc, c["name"], bal, {1: None, 2: None}),
                 kb_servers(cc))
    # v31: both servers probed at the SAME time (was 2 slow calls in a row)
    counts = {}
    try:
        res = await asyncio.gather(
            country_probe(cc, 1), country_probe(cc, 2),
            return_exceptions=True)
        for srv, r in zip((1, 2), res):
            if isinstance(r, dict) and r.get("ok"):
                counts[srv] = r.get("total") or 0
            else:
                counts[srv] = "err"
    except Exception:
        counts = {1: None, 2: None}
    await edit_q(q, s_srv_pick(cc, c["name"], bal, counts), kb_servers(cc))


async def render_catalog(q, u, srv, cc, c, items, total, page, ctx, meta=None):
    text, kb = _catalog_view(srv, cc, c, items, total, page, ctx, meta)
    return await edit_q(q, text, kb)


def _catalog_view(srv, cc, c, items, total, page, ctx, meta=None):
    """Shared catalogue renderer: returns (text, keyboard).

    Used by render_catalog (edit an existing card) and send_catalog (post
    a fresh card from a text input such as the keyword filter).
    """
    srv = int(srv or 1)
    fl = get_filters(ctx, srv, cc)
    meta = meta or {"recent": False, "exact": True, "has_next": False, "load_more": False}
    cc_all = str(cc or "").upper() == "ALL"
    cname = ("All Countries" if cc_all else (c["name"] if c else str(cc or "")))
    
    if not items:
        if meta.get("recent") and meta.get("load_more"):
            return (s_recent_scan(srv, cc, fl, meta), kb_recent_empty(srv, cc, page))
        return (s_catalog_empty(srv, cc, cname, fl),
                kb_notify(cc, srv) if not cc_all else
                _styled_markup([kb_row(("Filters", f"cf_{srv}_ALL", BTN_PRIMARY), ("Back", f"scl_{srv}_0", BTN_SUCCESS)), kb_row(("Main Menu", "main_menu"))]))

    prices = []
    item_ids = []
    for it in items:
        item_cc = str(it.get("_shop_country") or ("" if cc_all else cc)).upper()
        floor = country_floor(item_cc, srv) if item_cc else 0.0
        pr = item_price_inr(it.get("price"), it.get("price_currency"), floor, srv)
        prices.append(pr)
        iid = str(it.get("item_id") or it.get("id") or "")
        if iid:
            item_ids.append(iid)
            ctx.user_data[f"itmp_{iid}"] = pr
            ctx.user_data[f"itm_{iid}"] = it
            ctx.user_data[f"itmcc_{iid}"] = item_cc
            ctx.user_data[f"itmpage_{iid}"] = page   # ← NAYA
            ctx.user_data[f"itmb_{iid}"] = f"catall_{srv}_{page}" if cc_all else f"cat_{srv}_{cc}_{page}"
            
    ctx.user_data[f"catseq_{srv}_{cc}_{page}"] = item_ids
    ctx.user_data[f"total_{srv}_{cc}"] = total # <--- NAYA: Total accounts save kiye
    
    if meta.get("recent") and not meta.get("exact"):
        pages = max(1, page + 1 + (1 if meta.get("has_next") else 0))
    else:
        pages = max(1, min(CAT_MAX_PAGES, (int(total or 0) + CAT_PAGE_SIZE - 1) // CAT_PAGE_SIZE))
        page = max(0, min(page, pages - 1))
        
    ctx.user_data[f"lastp_{srv}_{cc}"] = page
    ctx.user_data[f"catpages_{srv}_{cc}"] = pages
    low = min(prices) if prices else None
    return (s_catalog(srv, cc, cname, total, page, pages, fl, low,
                      exact=bool(meta.get("exact", True)), meta=meta),
            kb_catalog(srv, cc, items, prices, page, pages, meta=meta))


async def send_catalog(bot, chat_id, ctx, srv, cc, page=0):
    """Post a country catalogue as a NEW message.

    Fixes the crash of the keyword filter input (it called a function that
    did not exist) - same data, same buttons, no query to edit.
    """
    srv = int(srv or 1)
    cc = str(cc or "").upper()
    c = db_country(cc)
    ctx.user_data["shop_srv"] = srv
    fl = get_filters(ctx, srv, cc)
    if not c:
        return await send(bot, chat_id,
                          f"<b>COUNTRY NOT FOUND</b>\n{LINE}\n"
                          + box([f"<code>{esc(cc)}</code> is not in the "
                                 "catalogue."]),
                          kb_home())
    if country_floor(cc, srv) <= 0:
        return await send(
            bot, chat_id,
            f"<b>NO STOCK</b>\n{LINE}\n"
            + box([f"{esc(c['name'])} has no "
                   f"{SERVER_QUALITY.get(srv, '')} stock on Server {srv} "
                   "right now."]),
            kb_notify(cc, srv))
    try:
        items, total, err, meta = await catalog_page(srv, cc, fl, page)
    except Exception as e:
        log.warning("send_catalog %s S%s: %s", cc, srv, str(e)[:120])
        items, total, err, meta = [], 0, str(e)[:80], {}
    if err:
        body = (s_catalog_busy(cc, srv, err) if str(err) in ("busy", "rate")
                else s_err("E-101"))
        return await send(
            bot, chat_id, body,
            ikb(kb_row(("Retry", f"srv_{srv}_{cc}")),
                kb_row(("Main Menu", "main_menu"))))
    text, kb = _catalog_view(srv, cc, c, items, total, page, ctx, meta)
    return await send(bot, chat_id, text, kb)


