async def cb_item(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    # v40: id ke andar "_" ho sakta hai, isliye sirf 3 baar split
    parts = q.data.split("_", 3)
    if len(parts) < 4:
        return await qans(q, "Not available", True)
    pref, srv, cc, iid = parts[0], int(parts[1]), parts[2], parts[3]
    u = q.from_user
    if not _guard(u):
        return await edit_q(q, BAN_MSG, None)
    c = db_country(cc)
    if not c:
        return await qans(q, "Country not found", True)
        
    if pref == "itmr":
        await qans(q, "Refreshing...")
    else:
        await qans(q, "Loading...")
        
    await edit_q(q, s_stage("Loading Account", f"Fetching live details for {esc(c['name'])}...", "\U0001f4f1"))
    
    r = await sup.item(iid)
    back_cb = ctx.user_data.get(f"itmb_{iid}") or f"cat_{srv}_{cc}_0"
    nav_kb = _styled_markup([kb_row(("Back to List", back_cb),
                                    ("Retry", f"itmr_{srv}_{cc}_{iid}")),
                             kb_row(("Main Menu", "main_menu"))])

    if not r["ok"] or not r["item"]:
        reason = str(r.get("err") or "")
        if reason in ("busy", "rate") or reason.startswith("http_5"):
            # supplier down -> purana snapshot dikhao, "sold" mat bolo
            snap = ctx.user_data.get(f"itm_{iid}")
            if snap:
                price = ctx.user_data.get(f"itmp_{iid}")
                if not price:
                    price = item_price_inr(snap.get("price"),
                                           snap.get("price_currency"),
                                           country_floor(cc, srv), srv)
                    ctx.user_data[f"itmp_{iid}"] = price
                page = ctx.user_data.get(f"itmpage_{iid}") \
                    or ctx.user_data.get(f"lastp_{srv}_{cc}") or 0
                total = ctx.user_data.get(f"total_{srv}_{cc}") or 1
                return await edit_q(
                    q, s_item_detail(srv, cc, c["name"], snap, price,
                                     country_floor(cc, srv), stale=True),
                    kb_item(srv, cc, iid, price, back_cb=back_cb,
                            global_idx=1, total=total,
                            prev_iid=None, next_iid=None))
            return await edit_q(q, s_item_busy(cc, srv, reason), nav_kb)
        if reason in ("gone", "bad_id", "") or reason.startswith("http_4"):
            return await edit_q(q, s_item_gone(cc, srv), nav_kb)
        return await edit_q(q, s_item_busy(cc, srv, reason), nav_kb)
    item = r["item"]
    remember_item_age(item)          # v29: latest date known for this id
    
    if not item_country_matches(item, cc):
        return await edit_q(q, f"{ICON['warn']} <b>ACCOUNT UNAVAILABLE</b>\n{DIV}\nThis account does not belong to {esc(c['name'])}.\n{DIV}", 
                            _styled_markup([kb_row(("Back to List", back_cb), ("Refresh", f"itmr_{srv}_{cc}_{iid}")), kb_row(("Main Menu", "main_menu"))]))
        
    ctx.user_data[f"itm_{iid}"] = item
    floor = country_floor(cc, srv)
    price = ctx.user_data.get(f"itmp_{iid}")
    if not price:
        price = item_price_inr(item.get("price"), item.get("price_currency"), floor, srv)
        ctx.user_data[f"itmp_{iid}"] = price
        
    page = ctx.user_data.get(f"itmpage_{iid}") \
        or ctx.user_data.get(f"lastp_{srv}_{cc}") or 0
    item_ids = ctx.user_data.get(f"catseq_{srv}_{cc}_{page}") or []
    total = ctx.user_data.get(f"total_{srv}_{cc}") or 1
    
    prev_iid = None
    next_iid = None
    global_idx = 1
    
    def _stash_page(items_seq, target_page):
        """Store page context for every item on a fetched page so the
        next cb_item() call has itmpage / catseq / itm / itmp ready."""
        ids = []
        floor_ = country_floor(cc, srv)
        for ni in items_seq:
            ni_iid = str(ni.get("item_id") or ni.get("id") or "")
            if not ni_iid:
                continue
            ids.append(ni_iid)
            ctx.user_data[f"itmpage_{ni_iid}"] = target_page
            ctx.user_data[f"itmp_{ni_iid}"] = item_price_inr(
                ni.get("price"), ni.get("price_currency"), floor_, srv)
            ctx.user_data[f"itm_{ni_iid}"] = ni
            ctx.user_data[f"itmcc_{ni_iid}"] = cc
            ctx.user_data[f"itmb_{ni_iid}"] = f"cat_{srv}_{cc}_{target_page}"
        if ids:
            ctx.user_data[f"catseq_{srv}_{cc}_{target_page}"] = ids
        return ids

    if iid in item_ids:
        idx = item_ids.index(iid)
        global_idx = (page * CAT_PAGE_SIZE) + idx + 1

        # Prev logic (page cross karke)
        if idx > 0:
            prev_iid = item_ids[idx - 1]
        elif page > 0:
            fl = get_filters(ctx, srv, cc)
            prev_items, _, _, _ = await catalog_page(srv, cc, fl, page - 1)
            if prev_items:
                prev_ids = _stash_page(prev_items, page - 1)
                if prev_ids:
                    prev_iid = prev_ids[-1]

        # Next logic (page cross karke)
        if idx < len(item_ids) - 1:
            next_iid = item_ids[idx + 1]
        elif (page + 1) * CAT_PAGE_SIZE < total:
            fl = get_filters(ctx, srv, cc)
            next_items, _, _, _ = await catalog_page(srv, cc, fl, page + 1)
            if next_items:
                next_ids = _stash_page(next_items, page + 1)
                if next_ids:
                    next_iid = next_ids[0]
            
    await edit_q(q, s_item_detail(srv, cc, c["name"], item, price, floor, for_admin=is_full_admin(u.id)), 
                 kb_item(srv, cc, iid, price, back_cb=back_cb, prev_iid=prev_iid, next_iid=next_iid, global_idx=global_idx, total=total))


async def cb_ibuy(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    parts = q.data.split("_", 3)     # v40: ids can contain "_"
    if len(parts) < 4:
        return await qans(q, "Not available", True)
    srv, cc, iid = int(parts[1]), parts[2], parts[3]
    back_cb = ctx.user_data.get(f"itmb_{iid}") or f"cat_{srv}_{cc}_0"
    u = q.from_user
    await qans(q, "Opening your order...")
    
    if not _guard(u):
        return await edit_q(q, BAN_MSG, None)
    c = db_country(cc)
    if not c or country_floor(cc, srv) <= 0:
        return await edit_q(q, f"{ICON['warn']} This country is not available right now.", kb_home())
        
    # TURANT LOADING SCREEN
    await edit_q(q, s_stage("Opening Order", "Checking live price and reserving account...", "🛒"))
    
    item = ctx.user_data.get(f"itm_{iid}")
    if not item:
        r = await sup.item(iid)
        if not r["ok"]:
            reason = str(r.get("err") or "")
            if reason in ("busy", "rate") or reason.startswith("http_5"):
                return await edit_q(
                    q, s_item_busy(cc, srv, reason),
                    _styled_markup([kb_row(("Retry", f"ibuy_{srv}_{cc}_{iid}"),
                                           ("Back to List", back_cb)),
                                    kb_row(("Main Menu", "main_menu"))]))
            return await edit_q(
                q, s_item_gone(cc, srv),
                _styled_markup([kb_row(("Back to List", back_cb)),
                                kb_row(("Main Menu", "main_menu"))]))
        item = r["item"]
        ctx.user_data[f"itm_{iid}"] = item
        
    if not item_country_matches(item, cc):
        return await edit_q(q, f"{ICON['warn']} This account does not belong to {esc(c['name'])}.", kb_home())
        
    _og = norm_origin(item.get("item_origin") or item.get("resale_item_origin"))
    if _og and _og not in SERVER_ORIGINS.get(srv, []):
        return await edit_q(q, f"{ICON['warn']} This account type is not available on Server {srv}.", kb_home())

    floor = country_floor(cc, srv)
    price = ctx.user_data.get(f"itmp_{iid}")
    if not price:
        price = item_price_inr(item.get("price"), item.get("price_currency"),
                               floor, srv)
        ctx.user_data[f"itmp_{iid}"] = price
        
    bal = db_balance(u.id)
    if bal < price:
        return await edit_q(
            q, S_LOW_BAL,
            _styled_markup([
                kb_row(("Deposit", "deposit", BTN_SUCCESS)),
                kb_url("SOS Support", SUPPORT_URL, BTN_DANGER),
                kb_row(("Main Menu", "main_menu", BTN_PRIMARY))]))
            
    ctx.user_data["locked_item"] = {
        "iid": iid, "price": price, "srv": srv, "cc": cc,
        "origin": item.get("item_origin"),
        "cost": sup._num(item.get("price")),
        "cur": item.get("price_currency") or sup.currency
    }
    
    txt = s_confirm_item(srv, cc, c["name"], item, price, bal, for_admin=is_full_admin(u.id))
    await edit_q(q, txt, kb_confirm_item(price, cc, srv, iid, back_cb=back_cb))


# ══════════════════════════════════════════════════════════════════════
#   BULK BUY (v11)  -  many accounts of one country in a single order
# ══════════════════════════════════════════════════════════════════════
_bulk_stop: Dict[int, bool] = {}
# ✅ FIX: 100 aur 200 ke naye presets add kiye
BULK_PRESETS = (2, 3, 5, 10, 15, 20, 25, 30, 40, 50, 100, 200)


def bulk_on() -> bool:
    return str(db_get_setting("bulk_on", "1")) not in ("0", "off", "false")


def bulk_max() -> int:
    try:
        v = int(float(db_get_setting("bulk_max", "200"))) # ✅ Default 200 kar diya
    except (TypeError, ValueError):
        v = 200
    # Agar database me 50 saved hai, toh code isko 200 na hone de toh force 200 kar dega
    if v < 200: 
        v = 200
    return max(BULK_MIN, min(BULK_HARD_CAP, v))


def bulk_discount() -> Tuple[float, int]:
    try:
        pct = float(db_get_setting("bulk_disc_pct", "0") or 0)
    except (TypeError, ValueError):
        pct = 0.0
    try:
        mn = int(float(db_get_setting("bulk_disc_min", "5") or 5))
    except (TypeError, ValueError):
        mn = 5
    return max(0.0, min(50.0, pct)), max(BULK_MIN, mn)


def bulk_unit_price(cost, cur, floor, srv, n) -> float:
    """Shop price of one account inside a bulk order. The bulk discount
    never goes below the Profit Guard floor."""
    p = item_price_inr(cost, cur, floor, srv)
    pct, mn = bulk_discount()
    if pct > 0 and n >= mn:
        p = max(guard_price(cost, cur), round(p * (1 - pct / 100.0), 2))
    return p



def _disc_line() -> str:
    pct, mn = bulk_discount()
    if pct <= 0:
        return ""
    return f"🎁 <b>{pct:g}% off</b> every account when you buy <b>{mn}+</b>"


