def load_user_filters(uid, srv) -> dict:
    """Bulk buy has no ctx - read the saved filter doc for this server."""
    try:
        row = _get_conn().execute(
            "SELECT filters_json FROM users WHERE user_id=?",
            (int(uid),)).fetchone()
        raw = row["filters_json"] if row else None
        doc = json.loads(raw) if raw else {}
    except Exception:
        doc = {}
    fl = doc.get(f"fl_{int(srv)}") if isinstance(doc, dict) else None
    return valid_filters(fl)


async def _bulk_candidates(srv, cc, need, fl=None, max_pages=4):
    """Cheapest live accounts of one country, honouring user filters."""
    if str(cc or "").upper() in ("ALL", ""):
        cc = None                      # v31: "all countries" == no filter
    fl = valid_filters(fl) if fl else default_filters()
    out, seen = [], set()

    origins = list(SERVER_ORIGINS.get(int(srv)) or [])
    if fl.get("origin") and fl["origin"] != "any":
        origins = [fl["origin"]]
    allowed = list(origins)

    mode = str(fl.get("upload_date") or "any").lower()
    days = _upload_days(fl)
    cutoff = time.time() - days * 86400 if days else None
    # v29: with an account-age filter, page from the side where matching
    # accounts actually live and scan more pages - otherwise the quote
    # screen said "no stock" even when stock existed.
    order_by = age_order_by(
        fl, "pdate_to_down_upload" if mode == "new" else "price_to_up")
    if age_active(fl):
        max_pages = max(int(max_pages or 4), 10)
    spam_mode = fl.get("spam") or "nomatter"
    age_budget = [40]          # max detail lookups while quoting

    cc_sel = str(cc or "").upper()
    search_cc = None if cc_sel in ("ALL", "") else cc
    for page in range(1, max_pages + 1):
        r = await sup.api_search(
            search_cc, origins, page=page,
            order_by=order_by,
            title=(fl.get("kw") or None),
            spam=fl.get("spam"), premium=fl.get("premium"),
            password=fl.get("password"), email=fl.get("email"),
            session_age_days=age_session_days(fl))
        if r["err"]:
            break
        items = r["items"] or []
        if age_active(fl) and age_budget[0] > 0 and any(
                _item_published_timestamp(it) is None for it in items):
            _undated = [it for it in items
                        if _item_published_timestamp(it) is None][:18]
            await ensure_item_ages(_undated, limit=18)
            age_budget[0] -= len(_undated)
        for it in items:
            iid = str(it.get("item_id") or "")
            if not iid or iid in seen or is_bad_item(iid):
                continue
            if not sup.valid(it, cc, allowed, spam=spam_mode,
                             strict_country=bool(cc)):
                continue
            if not age_filter_ok(it, fl):        # v26 account-age filter
                continue

            if days:
                ts = _item_published_timestamp(it)
                if ts is None:
                    continue
                if mode == "new" and ts < cutoff:
                    continue
                if mode == "old" and ts >= cutoff:
                    continue
                    
            try:
                cost = float(it.get("price") or 0)
            except (TypeError, ValueError):
                continue
            if cost <= 0:
                continue
            seen.add(iid)
            out.append({"iid": iid, "cost": cost,
                        "cur": it.get("price_currency") or sup.currency,
                        "item": it})
        if len(out) >= need or not items:
            break

    out.sort(key=lambda x: to_inr(x["cost"], x["cur"]))
    return out


# ── v21: shared candidate feed + server-wide bulk buy ────────────────
def _sbulk_item_ok(item, origins, fl=None) -> bool:
    """Validity check for the server-wide bulk feed. `fl` (optional)
    makes spam / premium / 2FA / email filters apply."""
    try:
        st = str((item or {}).get("item_state", "active")).lower()
        if st not in ("active", ""):
            return False
        if float(str((item or {}).get("price") or 0)) <= 0:
            return False
        og = norm_origin(item.get("item_origin")) or norm_origin(
            item.get("resale_item_origin"))
        if origins and og not in origins:
            return False
        fl = fl or {}
        spam_mode = fl.get("spam") or "nomatter"
        is_spam = telegram_spam_state(item) is True
        if spam_mode == "no" and is_spam:
            return False
        if spam_mode == "yes" and not is_spam:
            return False
        for key, api in (("premium", "telegram_premium"),
                         ("password", "telegram_password"),
                         ("email", "telegram_email")):
            want = str(fl.get(key) or "nomatter").lower()
            if want == "nomatter":
                continue
            try:
                have = int(item.get(api) or 0) > 0
            except (TypeError, ValueError):
                have = False
            if want == "yes" and not have:
                return False
            if want == "no" and have:
                return False
        if item.get("canBuyItem") is False:
            return False
        return True
    except Exception:
        return False


def _item_cc(item) -> str:
    return str((item or {}).get("telegram_country") or "").upper().strip()


_CC_NAME_CACHE: Dict[str, str] = {}


def _item_cname(cc) -> str:
    cc = str(cc or "").upper().strip()
    if not cc:
        return "Mixed"
    hit = _CC_NAME_CACHE.get(cc)
    if hit:
        return hit
    name = ""
    try:
        c = db_country(cc)
        if c and c["name"]:
            name = str(c["name"])
    except Exception:
        name = ""
    if not name:
        try:
            name = (COUNTRIES.get(cc) or ("", 0))[0] or cc
        except Exception:
            name = cc
    _CC_NAME_CACHE[cc] = name
    return name


class _BulkFeed:
    """Cheapest-first candidate feed used by every bulk order."""

    def __init__(self, srv, cc=None, fl=None, max_pages=80):
        self.srv = int(srv or 1)
        self.cc = str(cc or "").upper().strip() or None
        self.fl = valid_filters(fl) if fl else default_filters()

        origins = list(SERVER_ORIGINS.get(self.srv) or [])
        if self.fl.get("origin") and self.fl["origin"] != "any":
            origins = [self.fl["origin"]]
        self.origins = origins

        self.page = 0
        self.buf: List[dict] = []
        self.seen: set = set()
        self.done = False
        self.stock: Optional[int] = None
        self.max_pages = max(4, int(max_pages or 80))

        self.upload_mode = str(self.fl.get("upload_date") or "any").lower()
        self.days = _upload_days(self.fl)
        self.cutoff = time.time() - self.days * 86400 if self.days else None
        # v28: account-age filter decides which side we page from
        self.age_on = age_active(self.fl)
        self.age_mode = age_mode_of(self.fl)
        self.age_days = age_days_of(self.fl)
        self.age_cut = age_cutoff(self.fl)
        self.order_by = age_order_by(
            self.fl, "pdate_to_down_upload" if self.upload_mode == "new"
            else "price_to_up")
        self.spam_mode = self.fl.get("spam") or "nomatter"
        self._prefetch: Optional[asyncio.Task] = None

    def _ok(self, it) -> bool:
        if is_bad_item(it.get("item_id") or it.get("id")):
            return False
        cc = self.cc or _item_cc(it)
        if not cc:
            return False
        if not sup.valid(it, cc, self.origins, spam=self.spam_mode,
                         strict_country=bool(self.cc)):
            return False
            
        if self.days:
            ts = _item_published_timestamp(it)
            if ts is None:
                return False
            if self.upload_mode == "new" and ts < self.cutoff:
                return False
            if self.upload_mode == "old" and ts >= self.cutoff:
                return False
        if not age_filter_ok(it, self.fl):      # v26 account-age filter
            return False
        return True

    async def _fetch_one(self):
        """v26: a rate-limited or failed page is RETRIED instead of ending
        the feed. Before this, one `check_limit` reply from the supplier
        killed the whole bulk order after the first account."""
        page = self.page + 1
        r = None
        for attempt in range(3):
            try:
                r = await sup.api_search(
                    self.cc, self.origins, page=page,
                    order_by=self.order_by,
                    title=(self.fl.get("kw") or None),
                    spam=self.fl.get("spam"),
                    premium=self.fl.get("premium"),
                    password=self.fl.get("password"),
                    email=self.fl.get("email"),
                    session_age_days=age_session_days(self.fl))
            except Exception as e:
                log.warning("bulk feed S%s p%s: %s", self.srv, page,
                            str(e)[:100])
                r = {"err": str(e)[:120], "items": []}
            if not (r or {}).get("err"):
                break
            if attempt < 2:
                wait = 2.0 + 2.0 * attempt
                log.info("bulk feed S%s p%s retry in %.0fs (%s)",
                         self.srv, page, wait, str(r.get("err"))[:60])
                await asyncio.sleep(wait)
        if not r or r.get("err"):
            log.warning("bulk feed S%s p%s gave up: %s", self.srv, page,
                        str((r or {}).get("err"))[:100])
            self.done = True
            return
        self.page = page
        if self.stock is None:
            try:
                self.stock = int(r.get("total") or 0)
            except (TypeError, ValueError):
                self.stock = 0
        items = r["items"] or []
        if not items:
            self.done = True
            return
            
        if self.days and self.upload_mode == "new":
            stamps = [_item_published_timestamp(it) for it in items]
            if all(ts is not None and ts < self.cutoff for ts in stamps):
                self.done = True
                return
        if self.age_on:
            # v29: some list replies carry no upload date at all - ask the
            # supplier for those few items so the age filter can judge them
            unknown = [it for it in items
                       if _item_published_timestamp(it) is None][:20]
            if unknown:
                await ensure_item_ages(unknown, limit=20)
        if self.age_on and self.age_mode == "newer":
            # newest-first paging: once a whole page is older than the
            # window, nothing further down can match
            stamps = [_item_published_timestamp(it) for it in items]
            if stamps and all(ts is not None and ts < self.age_cut
                              for ts in stamps):
                self.done = True
                
        fresh = []
        for it in items:
            iid = str(it.get("item_id") or "")
            if not iid or iid in self.seen or not self._ok(it):
                continue
            try:
                cost = float(it.get("price") or 0)
            except (TypeError, ValueError):
                continue
            if cost <= 0:
                continue
            self.seen.add(iid)
            fresh.append({"iid": iid, "cost": cost,
                          "cur": it.get("price_currency") or sup.currency,
                          "item": it})
                          
        if not self.days or self.upload_mode == "old":
            fresh.sort(key=lambda x: to_inr(x["cost"], x["cur"]))
            
        self.buf.extend(fresh)
        if r.get("cursor_api") and not r.get("has_next"):
            self.done = True
        elif not r.get("cursor_api") and len(items) < CAT_API_PER_PAGE:
            self.done = True

    async def _fill(self) -> bool:
        """Fetch at most two pages per call so buying never waits long."""
        if self.done:
            return bool(self.buf)
        target = max(24, 4 * BUY_CONCURRENCY)
        pages = 0
        while (not self.done and self.page < self.max_pages
               and pages < 2 and len(self.buf) < target):
            await self._fetch_one()
            pages += 1
        if self.upload_mode == "new" or self.age_on:
            self.buf.sort(key=lambda x: to_inr(x["cost"], x["cur"]))
        return bool(self.buf)

    def prefetch(self):
        """Keep the NEXT supplier page loading while accounts are bought."""
        if self.done:
            return
        if self._prefetch is not None:
            if not self._prefetch.done():
                return
            try:                       # never leave an unread exception
                self._prefetch.exception()
            except Exception:
                pass
        if len(self.buf) >= max(24, 4 * BUY_CONCURRENCY):
            return
        try:
            self._prefetch = asyncio.create_task(self._fill())
        except RuntimeError:
            self._prefetch = None

    def mark_dead(self, iid) -> None:
        """v30: drop an id the supplier already refused (it stays in `seen`
        so a later page can never bring it back)."""
        iid = str(iid or "").strip()
        if not iid:
            return
        self.seen.add(iid)
        self.buf = [c for c in self.buf if str(c.get("iid")) != iid]

    def close(self):
        try:
            if self._prefetch is not None and not self._prefetch.done():
                self._prefetch.cancel()
        except Exception:
            pass
        self._prefetch = None

    async def peek(self, need=1) -> list:
        need = max(1, int(need or 1))
        while len(self.buf) < need and not self.done:
            page_before = self.page
            await self._fill()
            if self.page == page_before and not self.done:
                break
        return list(self.buf[:need])

    async def next(self) -> Optional[dict]:
        """v28: returns instantly when the prefetch already filled the
        buffer - that is what lets the buyer run at full speed."""
        if not self.buf and not self.done:
            self.prefetch()
            if self._prefetch is not None:
                try:
                    await asyncio.shield(self._prefetch)
                except Exception:
                    pass
        if not self.buf and not self.done and self.page < self.max_pages:
            await self._fill()
        item = self.buf.pop(0) if self.buf else None
        self.prefetch()
        return item


def _cand_price(cand, cc_fix, srv, n) -> float:
    """Shop unit price of one feed candidate inside a bulk order."""
    cc = cc_fix or _item_cc(cand.get("item"))
    return bulk_unit_price(cand["cost"], cand["cur"],
                           country_floor(cc, srv), srv, n)


_sbulk_stats_cache: Dict[int, Tuple[float, dict]] = {}


async def server_bulk_stats(srv, force=False) -> dict:
    """Live per-server figures for the bulk hub: TOTAL accounts (all
    countries of that server, direct from the supplier) and the average
    shop price of the cheapest live accounts - i.e. roughly what a buyer
    actually pays, because bulk orders always pick the cheapest first."""
    srv = int(srv or 1)
    hit = _sbulk_stats_cache.get(srv)
    if not force and hit:
        ttl = 25 if hit[1].get("err") else 120
        if time.monotonic() - hit[0] < ttl:
            return dict(hit[1])
    out = {"srv": srv, "total": 0, "avg": 0.0, "low": 0.0, "err": None,
           "at": now_utc().strftime("%H:%M")}
    try:
        r = await sup.api_search(None, SERVER_ORIGINS.get(srv), page=1,
                                 nsb=False)
    except Exception as e:
        out["err"] = str(e)[:60]
        _sbulk_stats_cache[srv] = (time.monotonic(), dict(out))
        return out
    if r["err"]:
        out["err"] = str(r["err"])
        _sbulk_stats_cache[srv] = (time.monotonic(), dict(out))
        return out
    try:
        out["total"] = int(r.get("total") or 0)
    except (TypeError, ValueError):
        out["total"] = 0
    prices = []
    for it in r.get("items") or []:
        if not _sbulk_item_ok(it, SERVER_ORIGINS.get(srv)):
            continue
        try:
            cost = float(it.get("price") or 0)
        except (TypeError, ValueError):
            continue
        if cost <= 0:
            continue
        cur = it.get("price_currency") or sup.currency
        prices.append(item_price_inr(cost, cur,
                                     country_floor(_item_cc(it), srv), srv))
    if prices:
        out["avg"] = round(sum(prices) / len(prices), 2)
        out["low"] = round(min(prices), 2)
    _sbulk_stats_cache[srv] = (time.monotonic(), dict(out))
    return out


def _srv_stat_line(st) -> str:
    if st.get("err"):
        return "stock check failed - tap to retry"
    if not st.get("total"):
        return "no live stock right now"
    avg = f"avg <b>{money(st['avg'])}</b>" if st.get("avg") else "avg -"
    lo = f" · from {money(st['low'])}" if st.get("low") else ""
    return f"<b>{st['total']:,}</b> accounts · {avg}{lo}"


