async def bulk_qty_text(update: Update, ctx: ContextTypes.DEFAULT_TYPE, aw):
    msg = update.message
    u = update.effective_user
    ctx.user_data.pop("aw", None)
    _, srv, cc = aw.split("_")
    srv = int(srv)
    try:
        n = int(re.sub(r"\D", "", msg.text or "") or 0)
    except ValueError:
        n = 0
    if n < BULK_MIN or n > bulk_max():
        return await msg.reply_text(
            f"{ICON['warn']} Send a number between <b>{BULK_MIN}</b> and "
            f"<b>{bulk_max()}</b>.", parse_mode=ParseMode.HTML,
            reply_markup=ikb(kb_row(("✏️ Try Again", f"bqc_{srv}_{cc}"),
                                    ("◀️ Back", f"bbuy_{srv}_{cc}"))))
    wait = await msg.reply_text("🔄 Checking the cheapest accounts...")
    text, kb = await bulk_quote(u.id, srv, cc, n)
    await edit_any(wait, text, kb)


def s_bulk_progress(title, icon, n, bought, failed, skipped, now_txt, bal,
                    t0) -> str:
    done = len(bought)
    el = max(1.0, time.monotonic() - t0)
    eta = ""
    if done:
        eta = f"  •  ETA ~{int(el / done * max(0, n - done))}s"
    return (head(str(title), icon, sub="in progress")
            + "\n"
            + f"<code>{pbar(done, n, 14)}</code>  <b>{done}/{n}</b>\n"
            + box([f"✅ Delivered: <b>{done}</b>",
                   f"♻️ Skipped (sold / changed): <b>{skipped}</b>",
                   f"❌ Failed (refunded): <b>{failed}</b>",
                   f"🛒 Now: {now_txt}",
                   f"💰 Wallet: <b>{money(bal)}</b>"])
            + f"\n⏱ {int(el)}s{eta}\n"
            + "<i>Each account is bought and checked separately. "
              "Tap Stop to finish early.</i>")


def bulk_txt_file(cname, cc, bought) -> bytes:
    out = [f"{SHOP_NAME} - Bulk order",
           f"Product : {cname}" + (f" ({ctag(cc)})" if cc else ""),
           f"Accounts: {len(bought)}",
           f"Date    : {now_utc().strftime('%d %b %Y %H:%M')} UTC", "=" * 40]
    for i, b in enumerate(bought, 1):
        d = b.get("data") or {}
        out.append(f"#{i}  Order {b['oid']}  Price {money(b['price'])}")
        out.append(f"  Number  : {full_phone(b['phone'])}")
        out.append(f"  Age     : {age_text_of(b.get('item') or {})}")
        if d.get("password"):
            out.append(f"  2FA pass: {d.get('password')}")
        if d.get("email"):
            out.append(f"  Email   : {d.get('email')}")
        if d.get("email_password"):
            out.append(f"  Mail pwd: {d.get('email_password')}")
        if d.get("link"):
            out.append(f"  Link    : {d.get('link')}")
        out.append("  Login   : bot ➜ My Orders ➜ Get Login Code (SMS),")
        out.append("            or use the .session / .json / session")
        out.append("            string files from the delivery ZIPs")
        out.append("-" * 40)
    return "\n".join(out).encode("utf-8")


