def _zip_bytes(entries, readme_lines) -> bytes:
    """Small helper: build a ZIP in memory (name -> bytes/text)."""
    import io as _io
    import zipfile as _zip
    buf = _io.BytesIO()
    with _zip.ZipFile(buf, "w", _zip.ZIP_DEFLATED) as z:
        for name, data in entries:
            if isinstance(data, str):
                data = data.encode("utf-8")
            z.writestr(name, bytes(data))
        if readme_lines:
            z.writestr("README.txt", "\n".join(readme_lines))
    return buf.getvalue()


def _bulk_session_bundle(bought, tag="", receipt=None,
                         label="", cc="", with_parts=True) -> dict:
    """Build the three delivery ZIPs for a bulk order.

    Returns dict with:
        session  -> ZIP of ready Telethon .session files
        json     -> ZIP of the matching settings .json files
        string   -> ZIP of StringSession strings (.txt per account
                    + ALL_SESSIONS.txt)
        made     -> how many accounts have a usable session
        missing  -> [(index, record)] without an auth key
    Every ZIP is flat (no folders) and every file uses the same base name
    ``NN_<digits>`` so the three ZIPs pair up one-to-one.
    """
    stamp = now_utc().strftime("%d %b %Y %H:%M")
    sess_entries, json_entries, str_entries = [], [], []
    string_index = []
    accounts_doc = []
    missing = []
    made = 0
    for i, b in enumerate(bought, 1):
        digits = re.sub(r"\D", "", str(full_phone(b.get("phone") or ""))) \
            or f"order{b.get('oid')}"
        base = f"{i:02d}_{digits}"
        try:
            db, js, meta = session_files_from_item(
                b.get("item") or {}, base, b.get("data") or {})
            if not db:
                raise ValueError("empty session")
        except Exception as e:
            log.info("bulk session %s skipped: %s", b.get("oid"), e)
            missing.append((i, b))
            continue
        sess_entries.append((f"{base}.session", bytes(db)))
        if js:
            json_entries.append((f"{base}.json", bytes(js)))
        sval = str(meta.get("session_string") or "")
        if sval:
            str_entries.append((f"{base}.txt", sval + "\n"))
            string_index.append(
                f"#{i:02d}  {full_phone(b.get('phone') or 'N/A')}\n"
                f"      {sval}")
        d = b.get("data") or {}
        accounts_doc.append({
            "index": i, "order": b.get("oid"),
            "phone": full_phone(b.get("phone") or ""),
            "price": b.get("price"), "two_fa": d.get("password") or "",
            "email": d.get("email") or "",
            "email_password": d.get("email_password") or "",
            "link": b.get("link") or d.get("link") or "",
            "dc_id": meta.get("dc_id"), "has_session": True,
            "age_days": age_days_int(b.get("item") or {}),
            "age": age_text_of(b.get("item") or {}),
            "session_string": sval,
        })
        made += 1

    no_sess = []
    if missing:
        no_sess = ["These accounts have NO session auth-key stored at the",
                   "supplier, so only the SMS code works for them",
                   "(bot > My Orders > Get Login Code).", ""]
        for i, b in missing:
            no_sess.append(f"#{i}  Order {b.get('oid')}  "
                           f"{full_phone(b.get('phone') or 'N/A')}")
            d = b.get("data") or {}
            accounts_doc.append({
                "index": i, "order": b.get("oid"),
                "phone": full_phone(b.get("phone") or ""),
                "price": b.get("price"), "two_fa": d.get("password") or "",
                "email": d.get("email") or "",
                "email_password": d.get("email_password") or "",
                "link": b.get("link") or d.get("link") or "",
                "dc_id": None, "has_session": False,
                "age_days": age_days_int(b.get("item") or {}),
                "age": age_text_of(b.get("item") or {}),
                "session_string": "",
            })
    accounts_doc.sort(key=lambda x: int(x.get("index") or 0))

    common_readme = [
        f"{SHOP_NAME} - bulk session delivery",
        f"Created : {stamp} UTC",
        f"Batch   : {tag or 'bulk'}",
        f"Accounts: {len(bought)}  |  with session: {made}",
        "",
        "The same file base name is used in all three ZIPs",
        "(json / session / string), so you can pair them freely.",
    ]
    sess_readme = common_readme + [
        "",
        "HOW TO USE (.session)",
        "1. Unzip.",
        "2. In Python:",
        "     from telethon import TelegramClient",
        "     c = TelegramClient('01_9198xxxxxx.session', app_id, app_hash)",
        "     c.start()          # already logged in, no SMS code",
        "3. app_id / app_hash are inside the matching .json file.",
        "4. Keep the .session private - it opens the account.",
    ]
    json_readme = common_readme + [
        "",
        "HOW TO USE (.json)",
        "1. Unzip next to the matching .session file (same base name).",
        "2. Telethon: read app_id / app_hash from this file.",
        "3. opentele: FromSessionJson('<name>.json') logs in directly.",
        "4. ACCOUNTS.json holds every account (number, 2FA, email, link,",
        "   DC and the session string) in one machine-readable file.",
    ]
    str_readme = common_readme + [
        "",
        "HOW TO USE (session string)",
        "1. Each .txt file holds ONE line - the whole session.",
        "2. Telethon:",
        "     from telethon.sessions import StringSession",
        "     c = TelegramClient(StringSession(open('01_x.txt').read().strip()),",
        "                        app_id, app_hash)",
        "3. ALL_SESSIONS.txt lists every number with its string.",
    ]
    # ── v27: ONE combined ZIP with folders ────────────────────────────
    comb = [(f"session/{n}", d) for n, d in sess_entries]
    comb += [(f"json/{n}", d) for n, d in json_entries]
    comb += [(f"string/{n}", d) for n, d in str_entries]
    if string_index:
        comb.append(("string/ALL_SESSIONS.txt", "\n\n".join(string_index)))
    comb.append(("details/ACCOUNTS.json",
                 json.dumps({"shop": SHOP_NAME, "created": stamp + " UTC",
                             "accounts": accounts_doc},
                            indent=2, ensure_ascii=False)))
    try:
        comb.append(("details/accounts.txt",
                     bulk_txt_file(label or tag or "Bulk order", cc, bought)))
    except Exception as e:
        log.info("bulk txt in combined zip: %s", str(e)[:80])
    if no_sess:
        comb.append(("details/NO-SESSION.txt", "\n".join(no_sess)))
    if receipt:
        try:
            comb.append(("pdf/receipt.pdf", build_receipt_pdf(receipt)))
        except Exception as e:
            log.warning("bulk receipt inside zip failed: %s", str(e)[:100])
    comb_readme = common_readme + [
        "",
        "EVERYTHING IN ONE ZIP - folders:",
        "  session/   ready Telethon .session files (one per account)",
        "  json/      app_id / app_hash / device settings",
        "  string/    session string of every account (+ ALL_SESSIONS.txt)",
        "  pdf/       the receipt of this order",
        "  details/   ACCOUNTS.json, accounts.txt (numbers, 2FA, email),",
        "             NO-SESSION.txt if an account has no auth key",
        "",
        "The same 3 files are also sent separately (session / json /",
        "string ZIPs) - use whichever you prefer.",
    ]
    combined = _zip_bytes(comb, comb_readme)

    if not with_parts:
        # v28: only the combined ZIP is delivered, so the three extra
        # archives are not built at all (saves time on big batches).
        return {"made": made, "missing": missing, "combined": combined}

    return {
        "made": made,
        "missing": missing,
        "combined": combined,
        "session": _zip_bytes(sess_entries +
                              ([("NO-SESSION.txt", "\n".join(no_sess))]
                               if no_sess else []), sess_readme),
        "json": _zip_bytes(json_entries +
                           [("ACCOUNTS.json",
                             json.dumps({"shop": SHOP_NAME,
                                         "created": stamp + " UTC",
                                         "accounts": accounts_doc},
                                        indent=2, ensure_ascii=False))] +
                           ([("NO-SESSION.txt", "\n".join(no_sess))]
                            if no_sess else []), json_readme),
        "string": _zip_bytes(
            str_entries + ([("ALL_SESSIONS.txt", "\n\n".join(string_index))]
                           if string_index else []) +
            ([("NO-SESSION.txt", "\n".join(no_sess))] if no_sess else []),
            str_readme),
    }


async def send_all_files_zip(bot, uid, bought, tag="", receipt=None,
                             label="", cc="", markup=None) -> bool:
    """v28: the ONE delivery file - every account in a single ZIP.

    Folders inside: session/ json/ string/ pdf/ details/
    Used by both single buy and bulk buy, so the buyer always gets
    exactly two files: this ZIP and the PDF receipt.
    """
    try:
        bundle = await asyncio.to_thread(_bulk_session_bundle, bought, tag,
                                         receipt, label, cc, False)
    except Exception as e:
        log.warning("all-files zip build failed: %s", str(e)[:140])
        return False
    data = bundle.get("combined")
    if not data:
        return False
    made = int(bundle.get("made") or 0)
    name = f"ALL_FILES_{tag or 'order'}_{int(time.time())}.zip"
    cap = ("<b>📦 ALL FILES IN ONE ZIP</b>\n" + LINE + "\n"
           + box([f"Accounts: <b>{len(bought)}</b>  ·  "
                  f"sessions: <b>{made}</b>",
                  "<code>session/</code>  ready Telethon logins",
                  "<code>json/</code>  app_id / app_hash",
                  "<code>string/</code>  session strings + ALL_SESSIONS.txt",
                  "<code>pdf/</code>  this order's receipt",
                  "<code>details/</code>  ACCOUNTS.json + accounts.txt "
                  "(number, 2FA, email, age)"])
           + "\n<i>Unzip and log in - no SMS code needed.</i>")
    try:
        await bot.send_document(uid, make_input_file(data, name),
                                filename=name, caption=premiumize(cap),
                                parse_mode=ParseMode.HTML,
                                reply_markup=markup)
        return True
    except Exception as e:
        log.warning("all-files zip send failed: %s", str(e)[:140])
    return False


async def _bulk_send_sessions(bot, uid, bought, tag="",
                              receipt=None, label="", cc="") -> dict:
    """v28: bulk delivery sends ONE file - the ALL_FILES zip.

    (The separate session / json / string ZIPs were removed: everything
    lives inside the single ZIP, in its own folder.)
    """
    rep = {"session": 0, "json": 0, "string": 0, "missing": 0,
           "combined": 0, "made": 0}
    try:
        bundle = await asyncio.to_thread(_bulk_session_bundle, bought, tag,
                                         receipt, label, cc, False)
    except Exception as e:
        log.warning("bulk session bundle failed: %s", e)
        return rep
    made = int(bundle.get("made") or 0)
    rep["made"] = made
    rep["missing"] = len(bundle.get("missing") or [])
    data = bundle.get("combined")
    if not data:
        return rep
    name = f"ALL_FILES_{tag or 'bulk'}_{int(time.time())}.zip"
    cap = ("<b>📦 ALL FILES IN ONE ZIP</b>\n" + LINE + "\n"
           + box([f"Accounts: <b>{len(bought)}</b>  ·  "
                  f"sessions: <b>{made}</b>",
                  "<code>session/</code>  ready Telethon logins",
                  "<code>json/</code>  app_id / app_hash",
                  "<code>string/</code>  session strings + ALL_SESSIONS.txt",
                  "<code>pdf/</code>  this order's receipt",
                  "<code>details/</code>  ACCOUNTS.json + accounts.txt "
                  "(number, 2FA, email, age)"])
           + "\n<i>Everything in one download. Keep it private.</i>")
    try:
        await bot.send_document(uid, make_input_file(data, name),
                                filename=name, caption=cap,
                                parse_mode=ParseMode.HTML)
        rep["combined"] = made or len(bought)
        rep["session"] = made
        rep["string"] = made
        rep["json"] = made
    except Exception as e:
        log.warning("all-files zip send failed: %s", str(e)[:140])
    return rep


# ══════════════════════════════════════════════════════════════════════
#   v24  BULK SESSION RESET
#   One tap signs out every other device on EVERY account of a bulk order.
#   The batch is stored in the existing `settings` table (key bb:<id>), so
#   the button keeps working after a restart and can be used any time.
# ══════════════════════════════════════════════════════════════════════
BULK_BATCH_PREFIX = "bb:"
BULK_BATCH_MAX = 400          # accounts handled per reset run


def db_save_bulk_batch(uid, label, order_ids) -> str:
    """Store the order ids of one bulk purchase; returns the batch id."""
    ids = []
    for o in (order_ids or [])[:BULK_BATCH_MAX]:
        try:
            ids.append(int(o))
        except (TypeError, ValueError):
            continue
    if not ids:
        return ""
    bid = uuid.uuid4().hex[:12]
    payload = {"uid": int(uid), "label": str(label or "Bulk order")[:70],
               "at": now_utc().isoformat(), "orders": ids}
    _kv_set(BULK_BATCH_PREFIX + bid, json.dumps(payload))
    # keep only the last 40 batches per user so settings never grows
    try:
        rows = _get_conn().execute(
            "SELECT key FROM settings WHERE key LIKE ?",
            (BULK_BATCH_PREFIX + "%",)).fetchall()
        mine = []
        for r in rows:
            try:
                d = json.loads(_kv_get(r["key"], "") or "{}")
            except Exception:
                d = {}
            if int(d.get("uid") or 0) == int(uid):
                mine.append((str(d.get("at") or ""), str(r["key"])))
        mine.sort()
        for _at, key in mine[:-40]:
            _kv_del(key)
    except Exception as e:
        log.debug("bulk batch prune: %s", e)
    return bid


def db_get_bulk_batch(bid) -> dict:
    if not bid:
        return {}
    try:
        d = json.loads(_kv_get(BULK_BATCH_PREFIX + str(bid), "") or "{}")
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def db_user_batches(uid, limit=8) -> list:
    """This user's recent bulk batches, newest first: [(bid, batch), ...]"""
    out = []
    try:
        rows = _get_conn().execute(
            "SELECT key FROM settings WHERE key LIKE ?",
            (BULK_BATCH_PREFIX + "%",)).fetchall()
    except Exception:
        return out
    for r in rows:
        key = str(r["key"])
        bid = key[len(BULK_BATCH_PREFIX):]
        b = db_get_bulk_batch(bid)
        if not b or int(b.get("uid") or 0) != int(uid):
            continue
        out.append((bid, b))
    out.sort(key=lambda x: str(x[1].get("at") or ""), reverse=True)
    return out[:limit]


def s_sess_tools(uid) -> str:
    batches = db_user_batches(uid)
    if not batches:
        return (head("Session tools", sub="terminate other sessions")
                + "\n" + box(["No bulk order yet.",
                               "Buy accounts with Bulk Buy and this screen "
                               "will let you sign out every other device on "
                               "all of them with one tap."]))
    lines = []
    for bid, b in batches:
        lines.append(f"<b>{esc(b.get('label') or 'Bulk order')}</b>\n"
                     f"   {len(b.get('orders') or [])} account(s)  ·  "
                     f"{esc(str(b.get('at') or '')[:10])}")
    return (head("Session tools", sub="terminate other sessions")
            + "\n" + box(lines)
            + "\n" + box(["Pick a batch to request a Telegram authorization "
                           "reset on every account of it.",
                           "Other devices are signed out; SMS login keeps "
                           "working."]))


def kb_sess_tools(uid):
    rows = []
    for bid, b in db_user_batches(uid):
        label = (f"{b.get('label') or 'Bulk order'}  ·  "
                 f"{len(b.get('orders') or [])}")[:38]
        rows.append(kb_row((label, f"tallb_{bid}", BTN_DANGER)))
    rows.append(kb_row(("My Orders", "myacc", BTN_PRIMARY),
                       ("Main Menu", "main_menu")))
    return ikb(*rows)


async def cb_sesstools(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await qans(q)
    if not _guard(q.from_user):
        return await edit_q(q, BAN_MSG, None)
    await edit_q(q, s_sess_tools(q.from_user.id),
                 kb_sess_tools(q.from_user.id))


def s_bulk_terminate_confirm(batch, bid) -> str:
    orders = batch.get("orders") or []
    when = str(batch.get("at") or "")[:19].replace("T", " ")
    return (head("Terminate other sessions", sub="all accounts of this order")
            + "\n" + box([f"Batch: <b>{esc(batch.get('label') or 'Bulk order')}</b>",
                           f"Accounts: <b>{len(orders)}</b>",
                           f"Bought: <code>{esc(when)}</code> UTC"])
            + "\n" + box(["A Telegram authorization reset is requested on "
                           "<b>every</b> account of this order.",
                           "All other devices / sessions are signed out, "
                           "including the .session files and session strings "
                           "you downloaded. SMS login keeps working.",
                           "Accounts authorised in the last 24 hours may be "
                           "refused by the provider.",
                           "This cannot be undone."])
            + "\n<i>Tap the red button to start.</i>")


async def cb_tallb(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Bulk 'Terminate All Sessions' for one bulk order.

    tallb_<batch>  -> confirmation screen
    ytallb_<batch> -> run it
    """
    q = update.callback_query
    u = q.from_user
    raw = q.data or ""
    bid = raw.split("_", 1)[1] if "_" in raw else ""
    batch = db_get_bulk_batch(bid)
    if not batch or int(batch.get("uid") or 0) != u.id:
        return await qans(q, "This batch is not available", True)
    orders = [int(x) for x in (batch.get("orders") or []) if str(x).isdigit()]
    if not orders:
        return await qans(q, "Nothing to reset", True)
    if not raw.startswith("ytallb_"):
        await qans(q)
        return await edit_q(q, s_bulk_terminate_confirm(batch, bid),
                            _styled_markup([
                                kb_row((f"Yes, Reset {len(orders)} Accounts",
                                        f"ytallb_{bid}", BTN_DANGER)),
                                kb_row(("Cancel", "myacc", BTN_PRIMARY),
                                       ("Main Menu", "main_menu"))]))
    await qans(q, "Resetting sessions...")
    if db_banned(u.id):
        return await edit_q(q, BAN_MSG, None)
    t0 = time.monotonic()
    ok = fail = skip = 0
    problems = []
    total = len(orders)
    last_edit = 0.0
    for i, oid in enumerate(orders, 1):
        o = db_order(oid)
        iid = _order_iid(o) if o else ""
        ph = (o["phone_number"] if o else "") or ""
        if not iid:
            skip += 1
            problems.append(f"<code>#{oid}</code> - no linked account")
            continue
        try:
            r = await asyncio.wait_for(sup.terminate_all(iid), timeout=45)
        except asyncio.TimeoutError:
            r = {"ok": False, "status": 0, "detail": "timeout"}
        except Exception as e:
            r = {"ok": False, "status": 0, "detail": str(e)[:120]}
        done_ok = bool(r.get("ok"))
        if done_ok:
            ok += 1
        else:
            fail += 1
            problems.append(f"<code>#{oid}</code> "
                            f"{esc(mask_phone(ph))} - "
                            f"{esc(_session_reset_message(r))[:90]}")
        try:
            db_log_action("bulk_terminate_all", oid, u.id,
                          "ok" if done_ok else
                          f"failed HTTP {r.get('status', 0)}: "
                          f"{str(r.get('detail') or '')[:120]}")
        except Exception:
            pass
        if time.monotonic() - last_edit > 1.5 and i < total:
            last_edit = time.monotonic()
            try:
                await edit_q(q,
                             head("Terminating sessions", sub="in progress")
                             + "\n"
                             + f"<code>{pbar(i, total, 14)}</code>  "
                               f"<b>{i}/{total}</b>\n"
                             + box([f"Terminated: <b>{ok}</b>",
                                    f"Failed: <b>{fail}</b>",
                                    f"Skipped: <b>{skip}</b>"]),
                             ikb(kb_row(("Please wait", "noop"))))
            except Exception:
                pass
        await asyncio.sleep(0.35)
    el = int(time.monotonic() - t0)
    body = [f"Accounts: <b>{total}</b>",
            f"Terminated: <b>{ok}</b>",
            f"Failed: <b>{fail}</b>",
            f"Skipped (no account): <b>{skip}</b>",
            f"Time: {el}s"]
    txt = (head("Session reset finished")
           + "\n" + f"<code>{pbar(ok, total, 14)}</code> "
             f"<b>{int(ok / max(1, total) * 100)}%</b>\n"
           + box(body))
    if problems:
        txt += ("\n<b>NOT RESET</b>\n"
                + box(problems[:15])
                + ("\n<i>... and "
                   f"{max(0, len(problems) - 15)} more.</i>"
                   if len(problems) > 15 else ""))
    if ok and fail:
        txt += ("\n<i>Failed accounts are usually too new (24-hour rule) "
                "or already signed out - run the reset again later.</i>")
    await edit_q(q, txt, _styled_markup([
        kb_row(("Run Again", f"tallb_{bid}", BTN_DANGER),
               ("My Orders", "myacc", BTN_PRIMARY)),
        kb_row(("Main Menu", "main_menu"))]))
    _spawn(notify_admins(
        ctx.bot, head("Bulk session reset", "\U0001F6AB") + "\n"
        + box([f"User: <code>{u.id}</code>",
               f"Batch: {esc(batch.get('label') or '-')}",
               f"Terminated: <b>{ok}</b> / {total}",
               f"Failed: <b>{fail}</b>  •  Skipped: <b>{skip}</b>"])))


async def _bulk_engine(q, ctx: ContextTypes.DEFAULT_TYPE, u, srv: int,
                       cc: Optional[str], n: int):
    """One fast loop for EVERY bulk order (country-wide or server-wide).

    v21 upgrades over the old loop:
      * _BulkFeed keeps paging the supplier WHILE buying - the order no
        longer stops early when the first fetched accounts were sold.
      * Delivery (fetching number / login data) is pipelined in the
        background while the next account is already being bought.
      * Live progress, stop button, instant refunds and the final
        TXT + session ZIP are shared by both flows.
    """
    srv = int(srv)
    scope_country = bool(cc)
    c = db_country(cc) if scope_country else None
    if scope_country and (not c or country_floor(cc, srv) <= 0):
        return await edit_q(q, f"{ICON['warn']} No stock.", kb_home())
    title = (f"Bulk buy · {c['name']}" if scope_country
             else f"Bulk buy · Server {srv}")
    icon = flag_emoji(cc) if scope_country else "📦"
    tag = cc.lower() if scope_country else f"server{srv}"
    _plocks[u.id] = True
    _bulk_stop.pop(u.id, None)
    bought: List[dict] = []
    failed = skipped = 0
    blocked = stopped = False
    rate_limited = False
    err_hits = [0]          # supplier check_limit hits in this run
    ok_streak = [0]         # clean buys since the last supplier limit
    t0 = time.monotonic()
    stop_kb = ikb(kb_row(("⏹ Stop", "bstop", BTN_DANGER)))
    last_edit = 0.0
    fl = get_filters(ctx, srv, cc or "ALL")
    feed = _BulkFeed(srv, cc, fl=fl)
    sem = asyncio.Semaphore(BULK_CONCURRENCY)
    pending: Dict[int, tuple] = {}

    async def _deliver_task(oid, iid, cost, cur, acc_cc, acc_name, price,
                            item):
        async with sem:
            return await asyncio.wait_for(
                _deliver_one(u.id, oid, iid, cost, cur, acc_cc, acc_name,
                             price, srv, item), timeout=60)

    async def _drain(block=False):
        nonlocal failed
        if block and pending:
            try:
                await asyncio.wait([t for t, _ in pending.values()],
                                   timeout=95)
            except Exception:
                pass
            hung = [k for k, v in pending.items() if not v[0].done()]
            for oid in hung:
                t, m = pending.pop(oid)
                t.cancel()
                try:
                    db_upd_order(oid, status="review-pending",
                                 error_code="E-106")
                except Exception:
                    pass
                failed += 1
                _spawn(notify_admins(
                    ctx.bot,
                    f"{ICON['warn']} <b>BULK DELIVERY HUNG</b>\n{DIV}\n"
                    f"Order #{oid} • User <code>{u.id}</code>\n"
                    f"Country: {flag_emoji(m.get('cc') or '')} "
                    f"{esc(m.get('name') or '?')}\n"
                    f"Paid: <b>{money(m.get('price') or 0)}</b>\n"
                    f"Status set to review-pending. Verify with supplier.\n{DIV}"))
        done_oids = [k for k, v in pending.items() if v[0].done()]
        for oid in done_oids:
            t, m = pending.pop(oid)
            try:
                info = t.result()
            except Exception as e:
                log.warning("bulk deliver %s failed: %s", oid, e)
                try:
                    db_upd_order(oid, status="review-pending",
                                 error_code="E-106")
                except Exception:
                    pass
                failed += 1
                _spawn(notify_admins(
                    ctx.bot,
                    f"{ICON['warn']} <b>BULK DELIVERY FAILED</b>\n{DIV}\n"
                    f"Order #{oid} • User <code>{u.id}</code>\n"
                    f"Country: {flag_emoji(m.get('cc') or '')} "
                    f"{esc(m.get('name') or '?')}\n"
                    f"Paid: <b>{money(m.get('price') or 0)}</b>\n"
                    f"Reason: <code>{esc(str(e)[:150])}</code>\n"
                    f"Status set to review-pending.\n{DIV}"))
                continue
            bought.append(info)
            _spawn(post_sales_card(
                ctx.bot, "PURCHASE",
                f"{flag_emoji(m['cc'])} {esc(m['name'])}",
                [kv("Buyer", "<i>Hidden</i>"), # ✅ Username aur ID hide kar diya
                 kv("Order", f"<code>#{oid}</code>"),
                 kv("Number", f"<code>{esc(mask_phone(info['phone']))}</code>"),
                 kv("Type", f"{SERVER_QUALITY.get(srv, '')} Account"),
                 kv("Price", f"<b>{money(m['price'])}</b>"),
                 kv("Bulk", f"{len(bought)}/{n}")]))

    try:
        await sup.balance_now(force=True)
        # v29: only a few candidates are needed to work out the price cap -
        # peeking for the full quantity could scan 80 pages (a minute of
        # "checking stock") before the first account was even bought.
        try:
            # v30: the price cap must be worked out from the SAME candidate
            # set the confirmation screen priced - peeking only 24 made the
            # cap too tight, so a 50-account order skipped 30 good accounts
            # ("not enough stock" while stock was right there).
            first = await asyncio.wait_for(feed.peek(min(int(n), 60)),
                                           timeout=40)
        except asyncio.TimeoutError:
            first = await feed.peek(4)
        if not first:
            return await edit_q(
                q, head("Not available", "📦") + "\nAccounts are "
                "<b>not available</b> right now.\nNothing was charged.",
                _styled_markup([
                    kb_row(("🔄 Try Again",
                            f"bbuy_{srv}_{cc}" if scope_country
                            else f"sbk_{srv}", BTN_PRIMARY)),
                    kb_row(("🏠 Main Menu", "main_menu"))]))
        base = [_cand_price(x, cc if scope_country else None, srv, n)
                for x in first]
        cap = round(max(base) * 1.10, 2) if base else 0.0
        buying: Dict[int, asyncio.Task] = {}

        # ── v38: CHECK AHEAD, THEN BUY ───────────────────────────────
        # `GET /accounts/{id}` is free, so a small pool checks the next
        # accounts while the current one is being bought. Accounts that
        # sold out are dropped for free instead of burning a purchase slot
        # plus a refund.
        validate = str(os.environ.get("BULK_VALIDATE", "1")).lower() \
            not in ("0", "no", "off", "false")
        vconc = max(1, int(os.environ.get("VALIDATE_CONCURRENCY", "10")))
        vconc = min(vconc, max(2, 4 * BUY_CONCURRENCY))
        ahead = max(8, 3 * BUY_CONCURRENCY)
        raw_q: asyncio.Queue = asyncio.Queue(maxsize=4 * ahead)
        val_q: asyncio.Queue = asyncio.Queue()
        raw_done = [False]
        val_workers: List[asyncio.Task] = []
        vstats = {"ok": 0, "bad": 0, "err": 0}

        async def _feeder():
            try:
                while not raw_done[0]:
                    if _bulk_stop.get(u.id) or blocked:
                        break
                    if raw_q.full():
                        await asyncio.sleep(0.05)
                        continue
                    cand = await feed.next()
                    if cand is None:
                        break
                    await raw_q.put(cand)
            except asyncio.CancelledError:
                raise
            except Exception as e:
                log.warning("bulk feeder: %s", str(e)[:120])
            finally:
                raw_done[0] = True

        async def _validator():
            """Pulls a candidate, asks the supplier if it is sellable."""
            while True:
                if _bulk_stop.get(u.id) or blocked:
                    return
                try:
                    cand = await asyncio.wait_for(raw_q.get(), timeout=1.0)
                except asyncio.TimeoutError:
                    if raw_done[0] and raw_q.empty():
                        return
                    continue
                if not validate:
                    vstats["ok"] += 1
                    await val_q.put(cand)
                    continue
                try:
                    r = await sup.check_account(cand["iid"])
                except asyncio.CancelledError:
                    raise
                except Exception as e:
                    r = {"ok": False, "err": "check_failed",
                         "detail": str(e)[:120]}
                if r["ok"]:
                    vstats["ok"] += 1
                    await val_q.put(cand)
                    continue
                if r.get("err") == "unbuyable":
                    vstats["bad"] += 1
                    mark_bad_item(cand["iid"])
                else:
                    vstats["err"] += 1
                    if r.get("err") == "check_limit":
                        await asyncio.sleep(1.5)
                try:
                    feed.mark_dead(cand["iid"])
                except Exception:
                    pass

        async def _next_valid():
            """Next account the supplier has already approved."""
            while True:
                if _bulk_stop.get(u.id) or blocked:
                    return None
                try:
                    return await asyncio.wait_for(val_q.get(), timeout=1.0)
                except asyncio.TimeoutError:
                    if (raw_done[0] and raw_q.empty() and val_q.empty()
                            and all(t.done() for t in val_workers)):
                        log.info("bulk: no more candidates (feed done=%s "
                                 "raw=%s val=%s ok=%s bad=%s err=%s)",
                                 feed.done, raw_q.qsize(), val_q.qsize(),
                                 vstats["ok"], vstats["bad"], vstats["err"])
                        return None

        async def _buy_one(oid, iid, cost, cur, acc_cc, acc_name, price,
                           item, cap_cost):
            """v28: one account is bought in its own task, so BUY_CONCURRENCY
            purchases (and their deliveries) run at the same time."""
            nonlocal failed, skipped, blocked, rate_limited
            try:
                r = await sup.buy(iid, cost, balance_id="auto",
                                  max_cost=cap_cost)
                _tries = 0
                while ((not r["ok"]) and not r["unk"]
                       and r.get("err") == "check_limit" and _tries < 3):
                    err_hits[0] += 1
                    rate_limited = True
                    ok_streak[0] = 0
                    _tries += 1
                    wait = (1.5, 3.0, 5.0)[min(_tries - 1, 2)]
                    log.info("bulk: supplier limit on %s - retry %s/3 in "
                             "%.1fs", iid, _tries, wait)
                    await asyncio.sleep(wait)
                    r = await sup.buy(iid, cost, balance_id="auto",
                                      max_cost=cap_cost)
                if r["ok"]:
                    ok_streak[0] += 1
                    if rate_limited and ok_streak[0] >= 5:
                        # the supplier is happy again - back to full speed
                        rate_limited = False
                        ok_streak[0] = 0
                if r["unk"]:
                    db_upd_order(oid, status="review-pending",
                                 error_code="E-106", supplier_item_id=iid,
                                 supplier_cost=cost,
                                 supplier_currency=sup.currency)
                    failed += 1
                    return
                if not r["ok"]:
                    err = r.get("err")
                    code = ("E-107" if err == "low_bal" else
                            "E-102" if err in ("sold", "blacklist",
                                               "unbuyable") else
                            "E-103" if err == "price_changed" else
                            "E-109" if err == "check_limit" else
                            "E-108" if err == "auth" else "E-104")
                    db_credit(u.id, price, "Refund - Purchase Failed",
                              f"ORD-{oid}")
                    db_upd_order(oid, status="failed", error_code=code)
                    if err in ("low_bal", "auth"):
                        failed += 1
                        blocked = err == "low_bal"
                        return
                    if err == "check_limit":
                        failed += 1
                        rate_limited = True
                        return
                    if err in ("sold", "blacklist", "price_changed",
                               "unbuyable"):
                        skipped += 1
                        if err == "unbuyable":
                            mark_bad_item(iid)
                    else:
                        failed += 1
                    return
                db_upd_order(oid, status="purchased", supplier_item_id=iid,
                             supplier_cost=cost,
                             supplier_currency=sup.currency)
                _bd = r.get("d") or {}
                if isinstance(_bd, dict):
                    _bi = (_bd.get("item")
                           if isinstance(_bd.get("item"), dict) else _bd)
                    if isinstance(_bi, dict) and _bi:
                        item = merge_item_data(item, _bi)
                pending[oid] = (asyncio.create_task(_deliver_task(
                    oid, iid, cost, cur, acc_cc, acc_name, price, item)),
                    {"cc": acc_cc, "name": acc_name, "price": price})
            except asyncio.CancelledError:
                raise
            except Exception as e:
                log.warning("bulk buy %s crashed: %s", oid, e)
                failed += 1
                try:
                    o = db_order(oid)
                    if o and str(o["status"]) in ("paid", "purchased"):
                        db_credit(u.id, price, "Refund - System Error",
                                  f"ORD-{oid}")
                        db_upd_order(oid, status="failed",
                                     error_code="E-101")
                except Exception:
                    pass

        def _reap():
            """Collect finished buy tasks (they never raise, but be safe)."""
            for _oid in [k for k, t in buying.items() if t.done()]:
                t = buying.pop(_oid)
                if t.cancelled():
                    continue
                try:
                    exc = t.exception()
                except Exception:
                    exc = None
                if exc:
                    log.warning("bulk buy task %s: %s", _oid, exc)

        # v30 BULK FIX: the scheduler used to stop for good as soon as the
        # requested number of buys was *started*. Every account the supplier
        # refused (validation failed / session dead / price moved) therefore
        # left the order short - that is why bulk "worked" for 1-2 accounts
        # and then stopped. Now the loop keeps refilling until the requested
        # number is actually DELIVERED, the stock runs out or you stop it.
        feeder_task = asyncio.create_task(_feeder())
        for _i in range(vconc):
            val_workers.append(asyncio.create_task(_validator()))
        refills = 0
        while True:
            while (len(bought) + len(pending) + len(buying)) < n:
                if _bulk_stop.get(u.id):
                    stopped = True
                    break
                _reap()
                if blocked:
                    break
                _ceil = (BUY_CONCURRENCY if not rate_limited
                         else max(2, BUY_CONCURRENCY // 3))
                if len(buying) >= _ceil:
                    waiters = ([t for t in buying.values()]
                               + [t for t, _ in pending.values()])
                    try:
                        await asyncio.wait(waiters, timeout=30,
                                           return_when=asyncio.FIRST_COMPLETED)
                    except Exception:
                        pass
                    await _drain()
                    _reap()
                    continue
                cand = await _next_valid()
                if cand is None:
                    break
                iid, cost, cur = cand["iid"], cand["cost"], cand["cur"]
                item = cand.get("item") or {}
                acc_cc = cc if scope_country else _item_cc(item)
                acc_name = (c["name"] if scope_country
                            else _item_cname(acc_cc))
                price = _cand_price(cand, cc if scope_country else None, srv, n)
                if cap and price > cap:
                    skipped += 1
                    continue
                bal = db_balance(u.id)
                if bal < price:
                    blocked = True
                    break
                if time.monotonic() - last_edit > 1.5:
                    last_edit = time.monotonic()
                    await edit_q(q, s_bulk_progress(
                        title, icon, n, bought, failed, skipped,
                        f"<code>{esc(iid)}</code> · {money(price)}", bal, t0),
                        stop_kb)
                await _drain()
                oid = db_create_order(u.id, acc_cc or (cc or ""),
                                      acc_name, price, server=srv)
                _bulk_cur[u.id] = (oid, price)
                nb = db_debit(u.id, price, "Bulk Account Purchase", f"ORD-{oid}")
                if nb is None:
                    db_upd_order(oid, status="failed", error_code="E-104")
                    _bulk_cur.pop(u.id, None)
                    blocked = True
                    break
                db_upd_order(oid, status="paid")
                _cap = max_cost_for_price(price, cur, srv)
                buying[oid] = asyncio.create_task(_buy_one(
                    oid, iid, cost, cur, acc_cc, acc_name, price, item, _cap))
                if rate_limited:
                    await asyncio.sleep(0.25)      # only after a supplier limit
                elif BULK_PACE > 0:
                    await asyncio.sleep(BULK_PACE)
            # every started buy must settle before we decide what is left
            while True:
                _reap()
                left = [t for t in buying.values() if not t.done()]
                if not left:
                    break
                try:
                    await asyncio.wait(left, timeout=90,
                                       return_when=asyncio.FIRST_COMPLETED)
                except Exception:
                    break
                await _drain()
            _reap()
            await _drain()
            if _bulk_stop.get(u.id):
                stopped = True
            refills += 1
            # v30: "no more pages" is NOT the end - candidates may still be
            # sitting in the validation queues, so those must be empty too
            # before the order is allowed to finish short.
            if (len(bought) >= n or stopped or blocked
                    or refills > 40 + n
                    or (feed.done and not feed.buf and val_q.empty()
                        and raw_q.empty()
                        and all(t.done() for t in val_workers))):
                break
            log.info("bulk: %s/%s delivered, refilling (round %s)",
                     len(bought), n, refills)
        raw_done[0] = True
        for _t in val_workers + [feeder_task]:
            if not _t.done():
                _t.cancel()
        log.info("bulk: validated ok=%s refused=%s retry=%s for %s orders",
                 vstats["ok"], vstats["bad"], vstats["err"], n)
        
        # let every scheduled buy finish, then every delivery
        while True:
            _reap()
            left = [t for t in buying.values() if not t.done()]
            if not left:
                break
            try:
                await asyncio.wait(left, timeout=90,
                                   return_when=asyncio.FIRST_COMPLETED)
            except Exception:
                break
        _reap()
        await _drain(block=True)
        bal = db_balance(u.id)
        if not bought:
            again = (f"bbuy_{srv}_{cc}" if scope_country else f"sbk_{srv}")
            body = (head("Low balance", "💰") + "\nAdd funds and try again."
                    if blocked else
                    s_err_for("E-104", u.id, sup.last_buy_error) if failed
                    else head("Not available", "📦") + "\nNo account could "
                    "be bought right now. Nothing was charged.")
            return await edit_q(q, body, _styled_markup([
                kb_row(("Add Funds", "deposit", BTN_SUCCESS),
                       ("Try Again", again, BTN_PRIMARY)),
                kb_row(("Main Menu", "main_menu"))]))
        spent = sum(b["price"] for b in bought)
        note = []
        if stopped:
            note.append("⏹ Stopped by you - you paid only for delivered "
                        "accounts.")
        if rate_limited and len(bought) < n:
            note.append("⏳ The supplier slowed us down (rate limit). "
                        "Tap Bulk Buy Again in a minute to buy the rest.")
        if blocked:
            note.append("⚠️ Wallet ran out - add funds to buy the rest.")
        if len(bought) < n and not (stopped or blocked):
            note.append("ℹ️ Not enough matching stock for the full "
                        "quantity.")
        scope_line = (f"🌍 Country: {flag_emoji(cc)} {esc(c['name'])}"
                      if scope_country else
                      f"🖥 Server: <b>Server {srv}</b> · all countries")
        summary = (head("Bulk order complete", "🎉") + "\n"
                   + f"<code>{pbar(len(bought), n, 14)}</code>  "
                     f"<b>{len(bought)}/{n}</b>\n"
                   + box([scope_line,
                          f"✅ Delivered: <b>{len(bought)}</b>",
                          f"💵 Paid: <b>{money(spent)}</b>",
                          f"♻️ Skipped: {skipped}  •  ❌ Refunded: {failed}",
                          f"💰 Wallet: <b>{money(bal)}</b>"]
                         + ([f"🎂 Account age: <b>{age_label(fl)}</b>"]
                            if age_active(fl) else []))
                   + ("\n" + "\n".join(note) if note else "")
                   + "\n<i>📄 PDF receipt + 📦 ONE ALL_FILES zip (folders: "
                     "session, json, string, pdf, details) - nothing else. "
                     "Tap 🔑 for SMS codes.</i>")
        code_btns = [(f"🔑 #{i} · {str(full_phone(b['phone']))[-4:]}",
                      f"otp_{b['oid']}", BTN_SUCCESS)
                     for i, b in enumerate(bought[:24], 1)]
        rows = [kb_row(*code_btns[i:i + 2])
                for i in range(0, len(code_btns), 2)]
        again = (f"bbuy_{srv}_{cc}" if scope_country else f"sbk_{srv}")
        # ── v24: remember this batch so every account can be reset later ──
        batch_label = (f"{c['name']} (Server {srv})" if scope_country
                       else f"Server {srv} - all countries")
        try:
            bid = db_save_bulk_batch(u.id, batch_label,
                                     [b["oid"] for b in bought])
        except Exception as e:
            bid = ""
            log.warning("bulk batch save failed: %s", str(e)[:100])
        rows += [kb_row(("Terminate All Sessions",
                         f"tallb_{bid}" if bid else "noop", BTN_DANGER))]
        rows += [kb_row(("🧾 My Orders", "myacc", BTN_PRIMARY),
                        ("📦 Bulk Buy Again", again, BTN_SUCCESS)),
                 kb_row(("🏠 Main Menu", "main_menu"))]
        await edit_q(q, summary, _styled_markup(rows))
        rec = None
        scope_label = (c["name"] if scope_country
                       else f"Server {srv} - all countries")
        try:
            rec = receipt_from_bulk(
                bought, getattr(u, "first_name", "") or "",
                getattr(u, "username", "") or "", u.id,
                db_balance(u.id), scope_label)
            await send_receipt_pdf(ctx.bot, u.id, rec)
        except Exception as e:
            log.warning("bulk receipt failed: %s", str(e)[:120])
        # v28: exactly two files go to the buyer - the PDF receipt
        # (sent above) and this ONE zip with all five folders.
        files = await _bulk_send_sessions(
            ctx.bot, u.id, bought, tag, receipt=rec, label=scope_label,
            cc=cc if scope_country else "")
        try:
            await ctx.bot.send_message(
                u.id,
                head("Bulk delivery") + "\n"
                + box(["📄 PDF receipt: 1",
                       f"📦 ALL_FILES ZIP: {1 if files.get('combined') else 0}",
                       f"Accounts inside: <b>{len(bought)}</b>",
                       f"No session (SMS only): "
                       f"<b>{files.get('missing', 0)}</b>"])
                + "\n<i>Unzip ALL_FILES - folders session / json / string / "
                  "pdf / details. Tap Terminate All Sessions to sign out "
                  "every other device on these accounts.</i>",
                parse_mode=ParseMode.HTML)
        except Exception as e:
            log.warning("bulk delivery summary send failed: %s", e)
        await react(ctx.bot, u.id, REACT_SOLD)
        _spawn(notify_admins(
            ctx.bot, head("Bulk sale", "📦") + "\n" + box([
                kv("Buyer", buyer_tag(u)),
                kv("Scope", f"{flag_emoji(cc) if scope_country else '🖥'} "
                            f"{esc(c['name']) if scope_country else f'Server {srv} - all countries'}"),
                kv("Delivered", f"<b>{len(bought)}/{n}</b>"),
                kv("Revenue", f"<b>{money(spent)}</b>")])))
    except Exception as e:
        log.exception("bulk buy failed: %s", e)
        try:
            await _drain(block=True)
        except Exception:
            pass
        cur_ = _bulk_cur.get(u.id)
        if cur_:
            try:
                o = db_order(cur_[0])
            except Exception:
                o = None
            if o and o["status"] == "paid":
                db_credit(u.id, cur_[1], "Refund - System Error",
                          f"ORD-{cur_[0]}")
                db_upd_order(cur_[0], status="failed", error_code="E-101")
                db_log_err("E-101", u.id, cur_[0], str(e))
        try:
            await edit_q(q, s_err("E-101"), kb_home())
        except Exception:
            pass
    finally:
        _plocks.pop(u.id, None)
        _bulk_stop.pop(u.id, None)
        _bulk_cur.pop(u.id, None)
        try:
            feed.close()
        except Exception:
            pass



async def cb_sbulk(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Bulk hub opened from Browse Accounts: both servers with their live
    average price and TOTAL account count (all countries combined)."""
    q = update.callback_query
    u = q.from_user
    await qans(q, "Checking live stock...")
    if not _guard(u):
        return await edit_q(q, BAN_MSG, None)
    if not bulk_on():
        return await edit_q(q, head("Bulk buy is paused", "📦") + "\n"
                            "Please try again later.", kb_home())
    await edit_q(q, s_stage("Bulk buy",
                            "🔄 Checking live stock and prices on both "
                            "servers...", "📦"))
    try:
        s1, s2 = await asyncio.gather(server_bulk_stats(1),
                                      server_bulk_stats(2))
    except Exception as e:
        log.warning("sbulk stats failed: %s", e)
        s1 = s2 = {"err": str(e)[:60], "total": 0, "avg": 0.0, "low": 0.0}
    await edit_q(q, s_sbulk_home(db_balance(u.id), s1, s2),
                 kb_sbulk_home(s1, s2))


