async def sbulk_quote(uid, srv, n):
    """(text, markup) for the server-wide bulk confirmation screen."""
    want = n
    fl = load_user_filters(uid, srv)
    feed = _BulkFeed(srv, fl=fl)
    cands = await feed.peek(n)
    st = await server_bulk_stats(srv)
    total = int(st.get("total") or 0) or int(feed.stock or 0)
    if not cands:
        return (head("Not available", "📦") + "\nThis server has no live "
                "stock matching your filters right now.",
                _styled_markup([
                    kb_row(("Filters", f"cf_{srv}_ALL", BTN_PRIMARY),
                           ("◀️ Servers", "sbulk")),
                    kb_row(("🏠 Main Menu", "main_menu"))]))
    n = min(n, len(cands))
    prices = [_cand_price(x, None, srv, n) for x in cands[:n]]
    est = round(sum(prices), 2)
    bal = db_balance(uid)
    cap = round(max(prices) * 1.10, 2)
    return (s_sbulk_confirm(srv, n, est, bal, total, cap, want),
            kb_sbulk_confirm(srv, n, est, bal))


