# ── admin: profit view ─────────────────────────────────────────────
def _profit_block(no, cost, price) -> str:
    if not price:
        return f"{ICON['cross']} S{no} : <i>no stock / not priced</i>"
    if not cost:
        return (f"{ICON['caret']} S{no} : our <b>{money(price)}</b>   "
                "<i>cost not fetched yet</i>")
    prof = price - cost
    marg = (prof / cost * 100.0) if cost else 0.0
    # ── FIX #32: use → not &rarr; (Telegram HTML safe) ──
    return (f"{ICON['caret']} S{no} : cost <b>{money(cost)}</b>  →  "
            f"our <b>{money(price)}</b>  {ICON['dot']}  profit "
            f"<b>{money(prof)}</b>  <i>({marg:.0f}%)</i>")


def s_profit(page=0) -> str:
    rows_, total = db_countries_page(page * 6, 6, active_only=False, srv=1)
    lines = []
    for r in rows_:
        cc = r["code"]
        hit = FLOOR_CACHE.get(cc) or {}
        lines.append(f"{flag_emoji(cc)} <b>{esc(r['name'])}</b>   "
                     f"<i>{ctag(cc)}</i>\n"
                     f"     {_profit_block(1, hit.get('cost1'), r['price_inr'] or 0)}\n"
                     f"     {_profit_block(2, hit.get('cost2'), r['price2_inr'] or 0)}")
    if not lines:
        lines = [f"{ICON['dot']} No countries yet"]
    pages = max(1, (total + 5) // 6)
    stamp = ""
    if FLOOR_CACHE:
        stamp = (f"\n{ICON['clock']} costs fetched "
                 f"{now_utc().strftime('%H:%M')} UTC, "
                 f"{len(FLOOR_CACHE)} countries")
    return (f"{ICON['wallet']} <b>PROFIT VIEW</b>   "
            "<i>Original cost / Our price / Profit</i>\n"
            + LINE + "\n" + "\n\n".join(lines) + "\n" + LINE
            + f"\n{ICON['info']} Cost = cheapest live account on the "
              "supplier (before margin).\n"
            + f"{ICON['info']} Our price = what the buyer pays (after "
              "margin).\n"
            + f"{ICON['arrow']} Tap <b>Fetch Live Costs</b> to refresh "
              "this page.\n"
            + f"{ICON['arrow']} Page {page + 1} of {pages}" + stamp
            + "\n" + LINE)


def kb_profit(page=0, pages=1):
    rows = [kb_row(("Fetch Live Costs", f"aprof_live_{page}",
                    BTN_PRIMARY))]
    pr = kb_pager(page, pages, lambda i: f"aprof_{i}")
    if pr:
        rows.append(pr)
    rows.append(kb_row(("Margin", "amk"), ("Auto Price", "aprc")))
    rows.append(kb_row(("Admin Panel", "admin")))
    return ikb(*rows)



