async def cb_aprof_live(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _adm(q.from_user.id):
        return await qans(q, "Access denied", True)
    try:
        page = max(0, int(q.data.split("_")[-1]))
    except (IndexError, ValueError):
        page = 0
    await qans(q, "Fetching live costs...")
    rows_, total = db_countries_page(page * 6, 6, active_only=False, srv=1)
    got = 0
    for r in rows_:
        res = await price_country(r["code"])
        if res.get("floor") or res.get("floor2"):
            got += 1
        await asyncio.sleep(0.8)
    pages = max(1, (total + 5) // 6)
    await edit_q(
        q, s_profit(page)
        + f"{ICON['check']} Live costs updated for <b>{got}</b> "
          "countries.\n" + LINE,
        kb_profit(page, pages))


# ── filters ─────────────────────────────────────────────────────────
async def _filters_rerender(q, ctx, srv, cc, note=None):
    srv = int(srv)
    cc = str(cc or "ALL").upper()
    ctx.user_data.pop("locked_item", None)
    fl = get_filters(ctx, srv, cc)
    if cc == "ALL":
        if note:
            await qans(q, note)
        if fl.get("upload_date", "any") != "any":
            ctx.user_data[f"lastp_{srv}_ALL"] = 0
            items, total, err, meta = await catalog_page(srv, "ALL", fl, 0)
            if err:
                return await edit_q(q, s_err("E-101"),
                                    kb_recent_empty(srv, "ALL", 0))
            return await render_catalog(q, q.from_user, srv, "ALL", None,
                                        items, total, 0, ctx, meta=meta)
        return await render_countries(q, q.from_user, 0, srv, ctx)
    c = db_country(cc)
    if not c:
        return await qans(q, "Country not found", True)
    ctx.user_data[f"lastp_{srv}_{cc}"] = 0
    if note:
        await qans(q, note)
    items, total, err, meta = await catalog_page(srv, cc, fl, 0)
    if err:
        return await edit_q(q, catalog_err_text(err, cc, srv), kb_notify(cc, srv))
    return await render_catalog(q, q.from_user, srv, cc, c, items, total, 0,
                                ctx, meta=meta)


