async def cb_cfagv(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Preset picked - Any / ≤1 / ≤3 / ≤7 / ≤30 / ≤90 / ≥30 days."""
    q = update.callback_query
    parts = q.data.split("_")
    srv, cc, code = int(parts[1]), parts[2], parts[3]
    fl = get_filters(ctx, srv, cc)
    if code == "any":
        fl["age_mode"], fl["age_days"] = "any", 0
    elif code.startswith("old"):
        try:
            fl["age_days"] = max(1, min(3650, int(code[3:] or 30)))
        except (TypeError, ValueError):
            fl["age_days"] = 30
        fl["age_mode"] = "older"
    else:
        try:
            fl["age_days"] = max(1, min(3650, int(code)))
        except (TypeError, ValueError):
            fl["age_days"] = 0
        fl["age_mode"] = "newer" if fl["age_days"] else "any"
    ctx.user_data[f"lastp_{srv}_{cc}"] = 0
    title = f"Age filter: {age_label(fl)}"
    counts = age_band_of(srv, cc, fl)
    if counts:
        code = ("any" if fl["age_mode"] == "any" else
                (f"old{fl['age_days']}" if fl["age_mode"] == "older"
                 else str(fl["age_days"])))
        if code in counts:
            title += f"  \u00b7  {int(counts[code])} accounts"
    await qans(q, title)
    cname = "All countries" if str(cc).upper() == "ALL" else _item_cname(cc)
    await edit_q(q, s_age_edit(srv, cc, cname, fl), kb_age_edit(srv, cc, fl))


