# ── admin: price manager ───────────────────────────────────────────
async def render_prices(q, page=0):
    rows_db, total = db_countries_page(page * 12, 12, active_only=False)
    pages = max(1, (total + 11) // 12)
    page = min(page, pages - 1)
    rows_db, _ = db_countries_page(page * 12, 12, active_only=False)
    grid, row = [], []
    for c in rows_db:
        price = float(c["price_inr"])
        try:
            price2 = float(c["price2_inr"])
        except (KeyError, IndexError, TypeError, ValueError):
            price2 = 0.0
        tag = (f"₹{price:.0f}/{price2:.0f}"
               if (price > 0 or price2 > 0) else "OFF")
        row.append((f"{c['name']} {tag}", f"sp_{c['code']}"))
        if len(row) == 2:
            grid.append(row)
            row = []
    if row:
        grid.append(row)
    on, allc = db_country_stats()
    grid.append(kb_row(("Live Price", "alp"), ("Rates", "arate")))
    grid.append(kb_row(("Search Country", "apr_search")))
    grid.append(kb_row(("Enable All Countries", "apr_enable_all")))
    grid.append(kb_row(("Hide All Countries", "apr_hide_all")))
    await edit_q(q, f"{ICON['wallet']} <b>PRICE MANAGER</b>\n{DIV}\n"
                 f"{ICON['dia']} Active: <b>{on}</b> of <b>{allc}</b> "
                 "countries\n"
                 f"Buttons show <b>Server 1 / Server 2</b> prices.\n{DIV}",
                 kb_page("apr_p", page, pages, back_cb="admin",
                         extra=grid))


