async def render_stock_list(q, page=0):
    rows_db, total = db_countries_page(page * 12, 12, active_only=False)
    pages = max(1, (total + 11) // 12)
    page = min(page, pages - 1)
    rows_db, _ = db_countries_page(page * 12, 12, active_only=False)
    grid, row = [], []
    for c in rows_db:
        row.append((c["name"], f"stk_{c['code']}"))
        if len(row) == 2:
            grid.append(row)
            row = []
    if row:
        grid.append(row)
    await edit_q(
        q, f"{ICON['box']} <b>STOCK CHECK</b>\n{DIV}\n"
           "Checks live Supplier stock per origin for a country.\n"
           f"Accepted origins: {', '.join(ALLOWED_ORIGINS)}\n"
           f"Currency: {sup.currency.upper()}\n{DIV}\n"
           "<i>Tap a country to run the check (takes ~20s)</i>",
        kb_page("stk_list_p", page, pages, back_cb="admin", extra=grid))


