async def cb_stk(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _adm(q.from_user.id):
        return await qans(q, "Access denied", True)
    cc = q.data[4:]
    c = db_country(cc)
    if not c:
        return await qans(q, "Country not found", True)
    if _stock_busy.get(cc):
        return await qans(q, "A check for this country is already running",
                          True)
    await qans(q, "Running stock check...")
    _stock_busy[cc] = True
    partial: Dict[str, Any] = {}

    async def progress(og, count):
        partial[og] = count
        await edit_q(q, s_stock(cc, c["name"], partial, checking=og), None)
    try:
        await edit_q(q, s_stock(cc, c["name"], partial,
                                checking="starting"), None)
        res = await sup.stock_check(cc, progress=progress)
        await edit_q(q, s_stock(cc, c["name"], res),
                     _styled_markup([
                         kb_row(("Check Again", f"stk_{cc}"),
                                ("Set Price", f"sp_{cc}")),
                         kb_row(("Countries", "stk_list_p0"),
                                ("Admin Panel", "admin"))]))
    except Exception as e:
        log.exception("stock check failed: %s", e)
        await edit_q(q, f"{ICON['dot']} Stock check failed: {esc(e)}",
                     ikb(kb_row(("Admin Panel", "admin"))))
    finally:
        _stock_busy.pop(cc, None)


