async def render_deps(q):
    ds = db_pending_deps()
    if not ds:
        return await edit_q(q, f"{ICON['wallet']} <b>PENDING DEPOSITS</b>\n"
                            + DIV
                            + f"\n{ICON['check']} No pending deposits.\n"
                            + DIV, ikb(kb_row(("Admin Panel", "admin"))))
    txt = f"{ICON['wallet']} <b>PENDING DEPOSITS</b>\n" + DIV + "\n"
    rows = []
    for d in ds:
        ul = f"@{d['username']}" if d["username"] else str(d["user_id"])
        mode = ("Manual UPI" if d["payment_mode"] == "manual_upi"
                else "Auto UPI")
        utr = f"\n     UTR <code>{esc(d['utr'])}</code>" if d["utr"] else ""
        txt += (f"\n#{d['id']}  {esc(ul)}  •  "
                f"<b>{money(d['amount'])}</b>\n"
                f"     {mode}  •  <i>{str(d['created_at'])[:16]}</i>"
                f"{utr}\n")
        rows.append(kb_row((f"Approve #{d['id']}", f"adep_{d['id']}"),
                           (f"Reject #{d['id']}", f"rdep_{d['id']}")))
    rows.append(kb_row(("Admin Panel", "admin")))
    await edit_q(q, txt + DIV, ikb(*rows))


