def s_ghost_users() -> str:
    ghosts = db_ghost_users()
    real = db_user_count()
    total = real + len(ghosts)
    protected = cloud_protected_uids()
    kept = len([u for u in ghosts if u in protected])
    body = [kv("Real users", f"<b>{real}</b>"),
            kv("Ghost rows", f"<b>{len(ghosts)}</b>"),
            kv("Rows in database", f"<i>{total}</i>"),
            kv("Kept (cloud backup)", f"<b>{kept}</b>")]
    return (f"{ICON['user']} <b>GHOST USERS</b>\n" + LINE + "\n"
            + box(body) + "\n"
            + f"{ICON['info']} Ghost rows are <b>empty</b> entries.\n"
            + LINE)


