_liveprice: Dict[str, Any] = {"i": 0, "n": 0, "at": "", "bulk1": 0.0,
                              "bulk2": 0.0}
_LAST_DEALS: List[dict] = []


def _apply_best(cc, srv_no, raw, cur) -> float:
    cc = str(cc or "").upper()
    floor = item_price_inr(raw, cur, 0, srv_no)
    hit = FLOOR_CACHE.setdefault(cc, {"cc": cc, "t": 0.0})
    hit["t"] = time.time()
    hit[f"cost{srv_no}"] = to_inr(raw, cur)
    hit[f"price{srv_no}"] = floor
    hit[f"raw{srv_no}"] = raw
    hit[f"cur{srv_no}"] = cur
    db_set_price(cc, floor, srv_no)
    return floor


async def live_floor_bulk(srv=None, pages=3) -> int:
    srvs = [int(srv)] if srv else [1, 2]
    n = 0
    for srv_no in srvs:
        origins = SERVER_ORIGINS.get(srv_no) or []
        best: Dict[str, tuple] = {}
        ok = False
        for page in range(1, max(1, int(pages)) + 1):
            r = await sup.api_search("", origins, page=page, order_by="price_to_up", spam=None)
            if r.get("err"):
                break
            ok = True
            if not r.get("items"):
                break
            for it in r["items"]:
                cc = str(it.get("telegram_country") or "").upper().strip()
                if len(cc) != 2 or not cc.isalpha():
                    continue
                if not sup.valid(it, cc, origins, spam="nomatter"):
                    continue
                try:
                    raw = float(it.get("price") or 0)
                except (TypeError, ValueError):
                    raw = 0.0
                if raw <= 0:
                    continue
                inr = to_inr(raw, it.get("price_currency"))
                prev = best.get(cc)
                if prev is None or inr < prev[0]:
                    best[cc] = (inr, raw, it.get("price_currency") or sup.currency)
            if len(r["items"]) < 20:
                break
        for cc, (_inr, raw, cur) in best.items():
            _apply_best(cc, srv_no, raw, cur)
            n += 1
        if ok:
            _liveprice[f"bulk{srv_no}"] = time.monotonic()
            _mark_synced(srv_no)
            
    _liveprice["at"] = now_utc().strftime("%d %b %H:%M") + " UTC"
    _liveprice["n"] = n
    if n > 0:
        _cat_cache.clear()
        _recent_cat_cache.clear()
    return n



async def price_country(cc, save=True) -> dict:
    cc = str(cc or "").upper()
    out = {"cc": cc, "floor": 0.0, "floor2": 0.0, "srv": 0, "cost": 0.0,
           "cur": sup.currency, "err": False, "empty1": False,
           "empty2": False}
           
    for srv_no in (1, 2):
        origins = SERVER_ORIGINS.get(srv_no) or []
        r = await sup.api_search(cc, origins, page=1, order_by="price_to_up", spam=None)
        
        # Agar API error degi (jaise 503/429), toh purana price mat udaao
        if r.get("err"):
            out["err"] = True
            continue
            
        best = None
        for it in r.get("items") or []:
            if not sup.valid(it, cc, origins, spam="nomatter"):
                continue
            try:
                raw = float(it.get("price") or 0)
            except (TypeError, ValueError):
                continue
            if raw <= 0:
                continue
            cur = it.get("price_currency") or sup.currency
            inr = to_inr(raw, cur)
            if best is None or inr < best[0]:
                best = (inr, raw, cur)
                
        if best:
            floor = (_apply_best(cc, srv_no, best[1], best[2]) if save
                     else item_price_inr(best[1], best[2], 0, srv_no))
            if srv_no == 1:
                out.update(floor=floor, srv=1, cost=best[1], cur=best[2])
            else:
                out["floor2"] = floor
        else:
            # API ne sahi jawab diya par stock 0 hai, tabhi price 0 karo
            out[f"empty{srv_no}"] = True
            if save:
                db_set_price(cc, 0, srv_no)
    return out



async def country_probe(cc, srv, save=True) -> dict:
    """v31: ONE supplier call -> live stock count + cheapest price.

    `GET /accounts?country[]=XX&order_by=price_to_up&origin[]=...` answers
    with `total` (how many accounts that country really has on that server)
    plus the cheapest account, so one call per country fills the stock
    column and the price.
    """
    cc = str(cc or "").upper().strip()
    srv = 2 if int(srv or 1) == 2 else 1
    out = {"cc": cc, "srv": srv, "ok": False, "total": 0, "cost": 0.0,
           "cur": sup.currency, "floor": 0.0, "err": None}
    if len(cc) != 2 or not cc.isalpha():
        out["err"] = "bad code"
        return out
    origins = SERVER_ORIGINS.get(srv) or []
    r = await sup.api_search(cc, origins, page=1, order_by="price_to_up",
                             spam=None)
    if r.get("err"):
        out["err"] = str(r.get("err"))[:120]
        return out
    total = 0
    try:
        total = int(r.get("total") or 0)
    except (TypeError, ValueError):
        total = 0
    best = None
    for it in r.get("items") or []:
        if not sup.valid(it, cc, origins, spam="nomatter"):
            continue
        try:
            raw = float(it.get("price") or 0)
        except (TypeError, ValueError):
            continue
        if raw <= 0:
            continue
        cur = it.get("price_currency") or sup.currency
        inr = to_inr(raw, cur)
        if best is None or inr < best[0]:
            best = (inr, raw, cur)
    if best:
        floor = (_apply_best(cc, srv, best[1], best[2]) if save
                 else item_price_inr(best[1], best[2], 0, srv))
        out.update(cost=best[1], cur=best[2], floor=float(floor or 0))
    if save:
        db_set_stock(cc, srv, total,
                     best[1] if best else None)
        if not best:
            db_set_price(cc, 0, srv)      # supplier says: no stock here
    out.update(ok=True, total=total)
    return out


_country_sweep_lock: Dict[str, bool] = {}
_country_sweep_at: Dict[str, float] = {}


def _bg_country_sweep(srv, force=False, limit=None) -> None:
    """Refresh country stock in the background (never blocks a tap)."""
    srv = 2 if int(srv or 1) == 2 else 1
    key = f"s{srv}"
    now = time.monotonic()
    if _country_sweep_lock.get(key):
        return
    ttl = 0 if force else COUNTRY_STOCK_TTL
    if now - float(_country_sweep_at.get(key) or 0) < ttl:
        return
    _country_sweep_lock[key] = True
    _country_sweep_at[key] = now

    async def _work():
        _BG.set(True)                 # users always go first
        try:
            await country_sweep(srv, limit=limit)
        except Exception as e:
            log.warning("country sweep S%s: %s", srv, e)
        finally:
            _BG.set(False)
            _country_sweep_lock.pop(key, None)
    _spawn(_work())


async def country_sweep(srv, limit=None, force=False, page_hint=None) -> int:
    """Probe every country of one server, freshest-unknown first.

    Requests go through `cat_search=True`, so the bot's own search pacing
    (and the "users first" rule) is respected - a sweep can never slow a
    buyer down or burn the supplier's rate limit.
    """
    srv = 2 if int(srv or 1) == 2 else 1
    if sup.busy() and not force:
        # v40: supplier is marked busy - do not burn the sweep on 502s,
        # the breaker closes on its own and the next tick will run normally
        log.debug("country sweep S%s skipped: supplier busy %ss left",
                  srv, sup.busy_left())
        return 0
    col_s = "stock2" if srv == 2 else "stock1"
    try:
        rows = _get_conn().execute(
            f"SELECT code, {col_s} AS st, stock_at FROM countries "
            f"WHERE is_active=1").fetchall()
    except Exception:
        rows = []
    if not rows:
        return 0
    stale = int(time.time()) - (0 if force else COUNTRY_STOCK_TTL)
    todo = [str(r["code"]).upper() for r in rows
            if int(r["stock_at"] or 0) < stale]
    if page_hint:
        hint = [c for c in (str(x).upper() for x in page_hint) if c in todo]
        rest = [c for c in todo if c not in hint]
        todo = hint + rest
    if limit:
        todo = todo[:int(limit)]
    done = 0
    batch = max(1, BG_SEARCH_CONC)
    for i in range(0, len(todo), batch):
        chunk = todo[i:i + batch]
        try:
            res = await asyncio.gather(*[country_probe(cc, srv)
                                         for cc in chunk],
                                       return_exceptions=True)
        except Exception as e:
            log.debug("country sweep batch S%s: %s", srv, str(e)[:80])
            continue
        done += sum(1 for r in res if isinstance(r, dict) and r.get("ok"))
        if sup.busy() and not force:
            log.info("country sweep S%s paused: supplier busy after %s ok",
                     srv, done)
            break
    if done:
        _cat_cache.clear()
        _recent_cat_cache.clear()
        log.info("country sweep S%s: %s countries refreshed", srv, done)
    return done


async def live_price_pass(bot=None, count=None) -> int:
    keys = list(COUNTRIES.keys())
    if not keys:
        return 0
    n = int(count or live_price_batch())
    done = 0
    for _ in range(min(max(1, n), len(keys))):
        cc = keys[_liveprice["i"] % len(keys)]
        _liveprice["i"] = (_liveprice["i"] + 1) % len(keys)
        try:
            r = await price_country(cc)
            if r["floor"] or r["floor2"]:
                done += 1
        except Exception as e:
            log.warning("live price %s failed: %s", cc, e)
            continue
            
    _liveprice["n"] = done
    _liveprice["at"] = now_utc().strftime("%d %b %H:%M") + " UTC"
    
    # Jab bhi background update ho, cache clear ho taaki user ko naya price mile
    if done > 0:
        _cat_cache.clear()
        _recent_cat_cache.clear()
        
    return done


# ── v15 supplier full sync (every origin, every page, both servers) ────
FULL_SYNC_INTERVAL = int(os.environ.get("FULL_SYNC_INTERVAL", "900"))
SYNC_PAGE_GUARD = int(os.environ.get("SYNC_PAGE_GUARD", "2000"))
_fullsync: Dict[str, Any] = {"busy": False, "last": 0.0, "report": {}}


def ist_stamp(ts) -> str:
    """'14 Oct, 7:13 PM IST' from an epoch timestamp."""
    d = datetime.fromtimestamp(float(ts), timezone(timedelta(
        minutes=REPORT_TZ_OFFSET)))
    return (f"{d.day} {d.strftime('%b')}, "
            f"{d.strftime('%I').lstrip('0')}:{d.strftime('%M %p')} "
            f"{REPORT_TZ_LABEL}")


def sync_updated_label(srv) -> str:
    ts = _kv_get(f"sync_at_s{int(srv or 1)}")
    try:
        return ist_stamp(float(ts)) if ts else ""
    except (TypeError, ValueError):
        return ""


def _mark_synced(srv):
    _kv_set(f"sync_at_s{int(srv)}", f"{time.time():.0f}")


async def _crawl_server(srv_no) -> dict:
    """Find EVERY country that has stock on this server (its own origins).

    Cheapest-first search; each country found is added to not_country[] and
    the search restarts, so every request reveals the next cheapest
    country. When a page has no new country the cursor goes one page
    deeper. Done when the supplier returns no more items."""
    origins = SERVER_ORIGINS.get(srv_no) or []
    agg: Dict[str, dict] = {}
    excluded: set = set()
    res = {"srv": srv_no, "pages": 0, "items": 0, "total": 0, "no_cc": 0,
           "invalid": 0, "complete": False, "err": None, "agg": agg}
    cursor = None
    while True:
        r = await sup.api_search("", origins, page=1, after=cursor,
                                 not_cc=sorted(excluded),
                                 order_by="price_to_up", spam=None)
        res["pages"] += 1
        if r.get("err"):
            res["err"] = r["err"]
            break
        items = r["items"]
        if res["pages"] == 1:
            res["total"] = int(r.get("total") or 0)
        if not items:
            res["complete"] = True
            break
        found = set()
        for it in items:
            res["items"] += 1
            cc = str(it.get("telegram_country") or "").upper().strip()
            if len(cc) != 2 or not cc.isalpha():
                res["no_cc"] += 1
                continue
            if cc in excluded:
                continue
            if not sup.valid(it, cc, origins, spam="nomatter"):
                res["invalid"] += 1
                continue
            try:
                raw = float(it.get("price") or 0)
            except (TypeError, ValueError):
                res["invalid"] += 1
                continue
            cur = it.get("price_currency") or sup.currency
            inr = to_inr(raw, cur)
            slot = agg.setdefault(cc, {"stock": 0, "best": None})
            slot["stock"] += 1
            if slot["best"] is None or inr < slot["best"][0]:
                slot["best"] = (inr, raw, cur)
            found.add(cc)
        if found:
            excluded |= found
            cursor = None
        elif r.get("next") and r.get("has_next") is not False:
            cursor = r["next"]
        else:
            res["complete"] = True
            break
        if res["pages"] >= SYNC_PAGE_GUARD:
            res["err"] = f"page_guard_{SYNC_PAGE_GUARD}"
            log.error("SYNC S%d stopped at the request guard (%d) - marked "
                      "incomplete", srv_no, res["pages"])
            break
    return res



def _stock_upsert(c, srv, cc, stock, price, cost, cur, avail, now):
    c.execute(
        "INSERT INTO supplier_stock (server,country_code,stock,price_inr,cost,"
        "currency,available,updated_at) VALUES (?,?,?,?,?,?,?,?) "
        "ON CONFLICT(server,country_code) DO UPDATE SET stock=excluded.stock,"
        " price_inr=excluded.price_inr, cost=excluded.cost,"
        " currency=excluded.currency, available=excluded.available,"
        " updated_at=excluded.updated_at",
        (int(srv), cc, int(stock), float(price or 0), float(cost or 0),
         str(cur or ""), int(avail), now))


def _mongo_stock_push(rows):
    """Mirror supplier_stock to MongoDB (same unique key + index)."""
    db, err = mongo._connect()
    if db is None:
        log.warning("supplier_stock Mongo mirror skipped: %s", err)
        return
    from pymongo import UpdateOne
    col = db["supplier_stock"]
    col.create_index([("server", 1), ("country_code", 1)], unique=True)
    col.create_index("updated_at")
    ops = [UpdateOne({"server": r["server"], "country_code": r["country_code"]},
                     {"$set": r}, upsert=True) for r in rows]
    if ops:
        col.bulk_write(ops, ordered=False)


async def _mongo_stock_task(rows):
    try:
        await asyncio.to_thread(_mongo_stock_push, rows)
    except Exception as e:
        log.warning("supplier_stock Mongo mirror failed: %s", e)
        db_log_err("MONGO", None, None, f"supplier_stock: {e}")


def _apply_sync(res) -> dict:
    """Save one server's crawl: prices through the existing _apply_best
    logic, every origin present in `countries`, stock rows upserted, and
    (only after a complete crawl) unseen countries set to stock 0."""
    srv = res["srv"]
    agg = res["agg"]
    col = "price2_inr" if srv == 2 else "price_inr"
    now = now_utc().strftime("%Y-%m-%d %H:%M:%S")
    live = live_prices_on()
    known = {r["code"]: r for r in
             _get_conn().execute("SELECT code, is_active, price_inr, "
                                 "price2_inr FROM countries").fetchall()}
    missing_name, missing_dial = [], []
    with _tx() as c:
        for cc in agg:
            if cc not in known:
                name = (COUNTRIES.get(cc) or (cc,))[0]
                c.execute("INSERT INTO countries (code,name,flag,price_inr,"
                          "price2_inr,is_active) VALUES (?,?,?,0,0,1)",
                          (cc, name, cc))
                if cc not in COUNTRIES:
                    missing_name.append(cc)
            if cc not in DIAL_CODES:
                missing_dial.append(cc)
    if missing_name:
        log.warning("SYNC S%d: no name mapping for %s - shown by ISO code",
                    srv, ", ".join(sorted(missing_name)))
    if missing_dial:
        log.warning("SYNC S%d: no dial-code mapping for %s - shown without",
                    srv, ", ".join(sorted(missing_dial)))
    prices = {}
    for cc, slot in agg.items():
        _inr, raw, cur = slot["best"]
        prices[cc] = (_apply_best(cc, srv, raw, cur) if live
                      else country_floor(cc, srv))
    zeroed = []
    mrows = []
    with _tx() as c:
        for cc, slot in agg.items():
            _inr, raw, cur = slot["best"]
            _stock_upsert(c, srv, cc, slot["stock"], prices[cc], raw, cur, 1,
                          now)
            mrows.append({"server": srv, "country_code": cc,
                          "stock": slot["stock"], "price_inr": prices[cc],
                          "cost": raw, "currency": cur, "available": 1,
                          "updated_at": now})
        if res["complete"]:
            for cc in known:
                if cc in agg:
                    continue
                _stock_upsert(c, srv, cc, 0, 0, 0, "", 0, now)
                mrows.append({"server": srv, "country_code": cc, "stock": 0,
                              "price_inr": 0, "cost": 0, "currency": "",
                              "available": 0, "updated_at": now})
                if live and float(known[cc][col] or 0) > 0:
                    zeroed.append(cc)
    if zeroed:
        # same effect as db_set_price(cc, 0, srv) per country, but one
        # transaction and one config push instead of hundreds
        with _tx() as c:
            c.executemany(f"UPDATE countries SET {col}=0 WHERE code=?",
                          [(cc,) for cc in zeroed])
        for cc in zeroed:
            (FLOOR_CACHE.get(cc) or {}).pop(f"price{srv}", None)
            db_log_price(cc, srv, float(known[cc][col] or 0), 0, "auto")
            mg_push_country(cc)
        if mongo.on():
            _spawn(mongo.push_config())
    if mrows and mongo.on():
        _spawn(_mongo_stock_task(mrows))
    conn = _get_conn()
    saved = conn.execute(
        "SELECT COUNT(*) AS n FROM supplier_stock WHERE server=? AND "
        "available=1 AND updated_at=?", (srv, now)).fetchone()["n"]
    codes = list(agg)
    shown = disabled = 0
    for i in range(0, len(codes), 400):
        part = codes[i:i + 400]
        ph = ",".join("?" * len(part))
        shown += conn.execute(
            f"SELECT COUNT(*) AS n FROM countries WHERE code IN ({ph}) AND "
            f"is_active=1 AND {col}>0", part).fetchone()["n"]
        disabled += conn.execute(
            f"SELECT COUNT(*) AS n FROM countries WHERE code IN ({ph}) AND "
            f"is_active=0", part).fetchone()["n"]
    rep = {"server": srv, "api": len(agg), "saved": int(saved),
           "shown": int(shown), "admin_disabled": int(disabled),
           "items": res["items"], "pages": res["pages"],
           "total_items": res["total"], "no_country_code": res["no_cc"],
           "invalid": res["invalid"], "set_unavailable": len(zeroed),
           "complete": bool(res["complete"]), "err": res["err"],
           "live_prices": bool(live), "at": now}
    rep["match"] = rep["api"] == rep["saved"] == rep["shown"] + rep["admin_disabled"]
    return rep


async def full_supplier_sync() -> dict:
    """Full sync of both servers. A failed server keeps its last good data
    and its last real sync time."""
    if _fullsync["busy"]:
        return {}
    _fullsync["busy"] = True
    report: Dict[str, Any] = {}
    try:
        for srv in (1, 2):
            res = await _crawl_server(srv)
            if res["err"] and not res["agg"]:
                report[f"s{srv}"] = {"server": srv, "ok": False,
                                     "err": res["err"], "pages": res["pages"]}
                log.warning("SYNC S%d failed (%s) - last good data kept",
                            srv, res["err"])
                db_log_err("SYNC", None, None, f"S{srv} failed: {res['err']}")
                continue
            rep = _apply_sync(res)
            rep["ok"] = True
            report[f"s{srv}"] = rep
            if res["complete"]:
                _mark_synced(srv)
            lvl = logging.INFO if rep["match"] else logging.WARNING
            log.log(lvl, "SYNC S%d api=%d saved=%d shown=%d disabled=%d "
                    "items=%d pages=%d no_cc=%d complete=%s match=%s",
                    srv, rep["api"], rep["saved"], rep["shown"],
                    rep["admin_disabled"], rep["items"], rep["pages"],
                    rep["no_country_code"], rep["complete"], rep["match"])
        _cat_cache.clear()
        _fullsync["report"] = report
        _kv_set("sync_report", json.dumps(report))
    finally:
        _fullsync["busy"] = False
        _fullsync["last"] = time.monotonic()
    return report


async def _sync_task():
    """Background-task boundary: a crash is logged (Error Log + log file),
    never lost silently. The last good data stays untouched."""
    _BG.set(True)
    try:
        await full_supplier_sync()
    except Exception as e:
        log.exception("full supplier sync crashed: %s", e)
        db_log_err("SYNC", None, None, f"crash: {type(e).__name__}: {e}")


async def job_live_price(ctx: ContextTypes.DEFAULT_TYPE):
    _BG.set(True)
    if not _fullsync["busy"] and (
            not _fullsync["last"]
            or time.monotonic() - _fullsync["last"] > FULL_SYNC_INTERVAL):
        _fullsync["last"] = time.monotonic()
        _spawn(_sync_task())
        
    if not live_prices_on() or _autoprice.get("busy") or _fullsync["busy"]:
        return
    try:
        # Pehle bulk me sasti prices uthayega
        await live_floor_bulk(pages=4)
        # Fir baaki bachi countries ko update karega
        await live_price_pass(ctx.bot, live_price_batch())
    except Exception as e:
        log.warning("live price job: %s", e)



async def _run_auto_price(bot, chat_id, msg=None):
    _autoprice["busy"] = True
    priced = empty = failed = 0
    mid = getattr(msg, "message_id", None)
    countries = list(COUNTRIES.keys())
    
    try:
        for i, cc in enumerate(countries, 1):
            rr = await price_country(cc)
            if rr["floor"] or rr["floor2"]:
                priced += 1
            elif rr["err"]:
                failed += 1
            else:
                empty += 1
                
            # Rate limit se bachne ke liye chhota gap
            await asyncio.sleep(0.5) 
            
            if mid and i % 10 == 0:
                await edit_msg(
                    bot, chat_id, mid,
                    f"{ICON['wallet']} <b>AUTO PRICE RUNNING</b>\n{DIV}\n"
                    f"Progress : <b>{i}/{len(countries)}</b> countries\n"
                    f"Priced   : <b>{priced}</b>\n"
                    f"Empty    : <b>{empty}</b>\n"
                    f"Failed   : <b>{failed}</b>\n{DIV}")
                    
        # SAARE CACHE CLEAR KARO TAAKI USER KO NAYA PRICE DIKHE
        _cat_cache.clear()
        _recent_cat_cache.clear()
        
        txt = (f"{ICON['check']} <b>AUTO PRICE FINISHED</b>\n{DIV}\n"
               f"{ICON['dia']} Countries checked : <b>{len(countries)}</b>\n"
               f"{ICON['wallet']} Priced from live stock : <b>{priced}</b>\n"
               f"{ICON['box']} No stock (hidden)      : <b>{empty}</b>\n"
               f"{ICON['dot']} Failed                : <b>{failed}</b>\n{THIN}\n"
               f"Markup ×{ITEM_MARKUP:.2f} + {money(ITEM_ADDITION)}\n{DIV}\n"
               "Buyers now see updated live prices everywhere.")
               
        if mid:
            await edit_msg(bot, chat_id, mid, txt, ikb(kb_row(("Price Manager", "apr"))))
        else:
            await send(bot, chat_id, txt, ikb(kb_row(("Price Manager", "apr"))))
            
    except Exception as e:
        log.exception("auto price failed: %s", e)
    finally:
        _autoprice["busy"] = False


