# ── admin: best deals ─────────────────────────────────────────────
async def _adeal_scan(q, pages: int = 1):
    best: Dict[str, dict] = {}
    origins, seen = [], set()
    for og in list(SERVER1_ORIGINS) + list(SERVER2_ORIGINS):
        if og not in seen:
            seen.add(og)
            origins.append(og)
    scanned = 0
    for og in origins:
        for page in range(1, max(1, pages) + 1):
            r = await sup.api_search(None, [og], page=page,
                                     order_by="price_to_up")
            if r["err"]:
                break
            items = r["items"] or []
            scanned += len(items)
            for it in items:
                cc = str(it.get("telegram_country") or "").upper().strip()
                if len(cc) != 2:
                    continue
                try:
                    cost = float(it.get("price") or 0)
                except (TypeError, ValueError):
                    continue
                if cost <= 0:
                    continue
                cur = it.get("price_currency") or sup.currency
                inr = to_inr(cost, cur)
                srv = 1 if og in SERVER1_ORIGINS else 2
                sell = item_price_inr(cost, cur, 0, srv)
                row = {"cc": cc, "cost": cost, "cur": cur, "inr": inr,
                       "origin": og, "iid": it.get("item_id"),
                       "srv": srv, "sell": sell,
                       "profit": max(0.0, sell - inr),
                       "pct": (max(0.0, sell - inr) / inr * 100)
                       if inr else 0.0}
                cur_best = best.get(cc)
                if not cur_best or inr < cur_best["inr"]:
                    best[cc] = row
            if len(items) < 10:
                break
    found = sorted(best.values(), key=lambda x: (-x["profit"], x["inr"]))
    _LAST_DEALS.clear()
    _LAST_DEALS.extend(found[:10])
    rows = []
    for i, f in enumerate(found[:10], 1):
        cc = f["cc"]
        c = db_country(cc)
        live = bool(c and c["is_active"]
                    and float(c["price_inr"] or 0) > 0)
        floor = float(c["price_inr"]) if c else 0.0
        state = f"{ICON['check']} live" if live else f"{ICON['dot']} off"
        rows.append(f"<b>{i}.</b> {flag_emoji(cc)} <b>{cc}</b>  "
                    f"{esc(ctag(cc))}   <i>S{f['srv']}</i>  {state}\n"
                    f"     cost {money(f['inr'])}  -  sell "
                    f"<b>{money(f['sell'])}</b>   profit "
                    f"<b>{money(f['profit'])}</b> ({f['pct']:.0f}%)\n"
                    f"     {esc(olabel(f['origin']))}"
                    + (f"  -  current price {money(floor)}" if floor
                       else ""))
    if not rows:
        rows = [f"{ICON['dot']} Nothing found."]
    total_profit = sum(f["profit"] for f in found[:10])
    txt = (f"{ICON['bolt']} <b>BEST DEALS</b>   "
           f"<i>top {len(found[:10])} countries</i>\n"
           + LINE + "\n" + box(rows) + "\n"
           + box([kv("Items scanned", f"<b>{scanned}</b>"),
                  kv("Countries found", f"<b>{len(found)}</b>"),
                  kv("Profit if all sold",
                     f"<b>{money(total_profit)}</b>"),
                  kv("Margin S1",
                     f"x{margin_for(1)[0]:.2f} + "
                     f"{money(margin_for(1)[1])}"),
                  kv("Margin S2",
                     f"x{margin_for(2)[0]:.2f} + "
                     f"{money(margin_for(2)[1])}")])
           + "\n"
           + f"{ICON['info']} <b>Apply Lowest</b> publishes these prices "
             "instantly.\n" + LINE)
    await edit_q(q, txt,
                 ikb(kb_row(("Apply Lowest (Top 10)", "adeal_apply",
                             BTN_SUCCESS)),
                     kb_row(("Rescan", "adeal", BTN_PRIMARY),
                            ("Deep Scan", "adeal_deep")),
                     kb_row(("Auto Price", "aprc"), ("Margin", "amk")),
                     kb_row(("Live Price", "alp"),
                            ("Admin Panel", "admin", BTN_PRIMARY))))

async def job_auto_deals(ctx: ContextTypes.DEFAULT_TYPE):
    _BG.set(True)
    # Check karo Sales Channel ON hai ya nahi
    if not sales_channel_enabled():
        return
    if str(db_get_setting("auto_deals_on", "1")) not in ("1", "on", "yes", "true"):
        return
        
    try:
        # Top deals scan karo (Server 1 & 2 combined)
        best_deals = []
        for srv_no in (1, 2):
            origins = SERVER_ORIGINS.get(srv_no) or []
            r = await sup.api_search(None, origins, page=1, order_by="price_to_up", spam=None)
            if r.get("err"): continue
            
            for it in r.get("items", []):
                cc = str(it.get("telegram_country") or "").upper().strip()
                if len(cc) != 2: continue
                if not sup.valid(it, cc, origins, spam="nomatter"): continue
                
                try:
                    cost = float(it.get("price") or 0)
                    inr = to_inr(cost, it.get("price_currency"))
                    if inr <= 0: continue
                    
                    # Price calculate karo (with margin)
                    sell = item_price_inr(cost, it.get("price_currency"), country_floor(cc, srv_no), srv_no)
                    profit = max(0.0, sell - inr)
                    
                    if profit > 0:
                        best_deals.append({
                            "cc": cc, "name": _item_cname(cc),
                            "srv": srv_no, "price": sell,
                            "profit": profit, "iid": it.get("item_id")
                        })
                except Exception:
                    continue
                    
        if not best_deals:
            return
            
        # Top 3 sabse zyada profit wale deals nikalo
        best_deals.sort(key=lambda x: -x["profit"])
        top_3 = best_deals[:3]
        
        # Message banao
        lines = []
        for i, d in enumerate(top_3, 1):
            lines.append(f"{i}. {flag_emoji(d['cc'])} <b>{esc(d['name'])}</b> ({d['cc']})")
            lines.append(f"   Price: <b>{money(d['price'])}</b> | Server {d['srv']}")
            
        body = (
            promo("🔥 TODAY'S HOT DEALS",
                  "✅ Fresh stock is live right now - grab it before it "
                  "is gone 🔥")
            + f"\n{LINE}\n"
            + box(lines)
        )
        
        # Channel me post karo
        cid = sales_channel_id()
        if cid:
            kb = kb_channel_card(ctx.bot, buy=True)
            await ctx.bot.send_message(
                cid, body, parse_mode=ParseMode.HTML, 
                reply_markup=kb, disable_web_page_preview=True
            )
            log.info("Auto deals posted to sales channel")
            
    except Exception as e:
        log.warning("job_auto_deals error: %s", e)


