async def job_expire_deps(ctx: ContextTypes.DEFAULT_TYPE):
    try:
        for d in db_stale_pending_deps():
            did = d["id"]
            if d["payment_mode"] == "auto_upi" and (d["fam_order_id"]
                                                     or d["txn_id"]):
                state, res, r = await dep_check(did, poll=True)
                if state == "credited":
                    await _announce_deposit(ctx.bot, d["user_id"], did, res, r)
                elif state in ("pending", "expired") and \
                        db_dep_timeout(did, "auto timeout"):
                    await send(ctx.bot, d["user_id"],
                               s_dep_expired(d["amount"]), kb_dep_expired(did))
                continue
            key = f"dep_notified_{did}"
            if not db_get_setting(key):
                db_set_setting(key, "1")
                await notify_admins(
                    ctx.bot,
                    head("Deposit needs review", "\u23f0") + "\n"
                    + box([f"#{did}  \u00b7  <code>{d['user_id']}</code>",
                           f"Amount: <b>{money(d['amount'])}</b>"]),
                    _styled_markup([
                        kb_row((f"Approve #{did}", f"adep_{did}"),
                               (f"Reject #{did}", f"rdep_{did}"))]))
        # late payments: re-check recently timed-out orders
        for d in db_recent_timeout_deps(hours=6, limit=15):
            state, res, r = await dep_check(d["id"], poll=True)
            if state == "credited":
                await _announce_deposit(ctx.bot, d["user_id"], d["id"], res, r)
    except Exception as e:
        log.warning("job_expire_deps error: %s", e)



_global_stock: Dict[str, Any] = {"ts": 0.0, "accounts": 0, "countries": 0,
                                 "accounts1": 0, "accounts2": 0}


async def refresh_global_stock(force=False) -> Dict[str, Any]:
    if not force and time.monotonic() - _global_stock.get("ts", 0) < 900:
        return _global_stock
    try:
        total = 0
        per_server = {}
        for srv in (1, 2):
            r = await sup.api_search(None, SERVER_ORIGINS.get(srv),
                                     page=1, nsb=False)
            n = 0 if r["err"] else int(r["total"] or 0)
            per_server[srv] = n
            total += n
        active = 0
        try:
            rows, n = db_countries_page(0, 500, active_only=True)
            active = n
        except Exception:
            active = 0
        _global_stock.update({"ts": time.monotonic(), "accounts": total,
                              "countries": active,
                              "accounts1": per_server.get(1, 0),
                              "accounts2": per_server.get(2, 0)})
        log.info("Live stock: S1 %s / S2 %s accounts / %s countries active",
                 per_server.get(1, 0), per_server.get(2, 0), active)
    except Exception as e:
        log.warning("refresh_global_stock: %s", e)
    return _global_stock


