async def post_init(app: Application):
    """Startup: DB init, MongoDB attach, background jobs, live notice."""
    db_init()
    if STORE_MODE == "mongo":
        _brep = await store_boot()
        log.info("Storage: MongoDB is the main database - %s rows loaded "
                 "(source: %s, RAM cache %s)", _brep["rows"], _brep["source"],
                 DB_FILE)
        db_init()
    load_margins()
    m1 = margin_for(1)
    m2 = margin_for(2)
    log.info("Margins: server 1 x%.2f + %.2f | server 2 x%.2f + %.2f",
             m1[0], m1[1], m2[0], m2[1])
    db_migrate_countries()
    on, allc = db_country_stats()
    log.info("Database ready: %s (%s countries active / %s total)",
             DB_FILE, on, allc)

    # v31: fill the live stock of every country on both servers right away
    # (background, ~4-8 min for the first full pass, then every 10 min)
    async def _stock_warm():
        for _srv in (1, 2):
            try:
                await country_sweep(_srv)
            except Exception as e:
                log.warning("startup stock sweep S%s: %s", _srv, e)
            await asyncio.sleep(2)
    _spawn(_stock_warm())

    async def _stock_loop():
        while True:
            await asyncio.sleep(COUNTRY_STOCK_TTL)
            for _srv in (1, 2):
                try:
                    await country_sweep(_srv)
                except Exception as e:
                    log.warning("stock loop S%s: %s", _srv, e)
    _spawn(_stock_loop())

    try:
        from telegram import BotCommandScopeAllPrivateChats
        await app.bot.set_my_commands(
            [BotCommand(c, d) for c, d in SETUP_COMMANDS],
            scope=BotCommandScopeAllPrivateChats())
        await app.bot.set_my_description(
            f"{SHOP_NAME} — Premium Telegram accounts.\n"
            "Instant automatic delivery • UPI wallet top-up")
        await app.bot.set_my_short_description(
            "Instant Telegram accounts + UPI wallet")
    except Exception as e:
        log.warning("set_my_commands failed: %s", e)

    # ── MongoDB attach ──────────────────────────────────────────
    if STORE["native"]:
        log.info("MongoDB connected (main database, live mirror)")
    elif mongo.on():
        try:
            mongo.start_writer()
            db_, err = mongo._connect()
            if db_ is not None:
                log.info("MongoDB connected: %s (%s)",
                         mongo.dbname(),
                         mongo.url().split("@")[-1].split("/")[0])
                # ONE-SHOT FULL CONFIG RESTORE
                cfg_rep = await mongo.pull_config()
                log.info("MongoDB config restore: %s", cfg_rep)

                rep = await mongo.pull_all()
                log.info(
                    "MongoDB restore: users=%s paid=%s orders=%s "
                    "deposits=%s ledger=%s balances=%s",
                    rep.get("users"), rep.get("paid_users"),
                    rep.get("orders"), rep.get("deposits"),
                    rep.get("ledger"), rep.get("balances"))

                n_sett = await mongo.pull_settings(force=False)
                n_ch = await mongo.pull_channels()
                n_ct = await mongo.pull_countries(force=True)
                n_ad = await mongo.pull_admins()
                n_pr = await mongo.pull_promos()
                log.info("MongoDB legacy restore: settings=%s channels=%s "
                         "countries=%s admins=%s promos=%s",
                         n_sett, n_ch, n_ct, n_ad, n_pr)

                await mongo.push_config()
                mg_push_all_tables()
                try:
                    await asyncio.to_thread(mongo.flush_queue, 15)
                except Exception:
                    pass
                mongo.push_totals()
            else:
                log.warning("MongoDB connect failed: %s", err)
        except Exception as e:
            log.warning("MongoDB init: %s", e)
    else:
        log.info("MongoDB is OFF - set mongo_on=1 in settings or env "
                 "MONGO_URL")

    try:
        m = await sup.me()
    except Exception as e:
        log.warning("Supplier check failed: %s", str(e)[:120])
        m = {"ok": False, "error": str(e)[:200]}
    if m.get("ok"):
        bal = m["balance"] if m["balance"] is not None else 0
        log.info("Supplier OK: %s | wallets: %s", m["username"],
                 sup.balance_line())
        if bal <= 0:
            log.warning("Supplier balance is EMPTY - purchases will fail!")
            try:
                await notify_admins(
                    app.bot,
                    f"{ICON['warn']} "
                    f"<b>SUPPLIER BALANCE EMPTY</b>\n{DIV}\n"
                    f"Supplier wallets: <code>{esc(sup.balance_line())}</code>\n"
                    "Top up the Supplier account, otherwise every order will "
                    "fail (refunds still work).\n" + DIV)
            except Exception as e:
                log.warning("notify_admins failed: %s", str(e)[:120])
        elif sup.buy_balance_id:
            log.info("Fast-buy will pay from balance_id=%s (%.2f %s)",
                     sup.buy_balance_id, sup.buy_balance or 0,
                     str(m["currency"]).upper())
    else:
        log.warning("Supplier not connected: %s", m.get("error"))
        try:
            await notify_admins(
                app.bot,
                f"{ICON['warn']} "
                f"<b>SUPPLIER NOT CONNECTED</b>\n{DIV}\n"
                f"{esc(str(m.get('error'))[:200])}\n"
                "Check Supplier token / internet.\n" + DIV)
        except Exception as e:
            log.warning("notify_admins failed: %s", str(e)[:120])

    try:
        g = await gateway.test()
    except Exception as e:
        log.warning("Gateway check failed: %s", str(e)[:120])
        g = {"ok": False, "note": str(e)[:120]}
    log.info("Gateway %s (%s)",
             "reachable" if g.get("ok") else "unreachable",
             g.get("note", ""))

    try:
        me = await app.bot.get_me()
        log.info("Bot identity: @%s (id %s)", me.username, me.id)
        wi = await app.bot.get_webhook_info()
        if wi.url:
            log.warning("A WEBHOOK IS SET (%s) - removing.", wi.url)
            await app.bot.delete_webhook(drop_pending_updates=False)
            log.info("Webhook removed - polling is active again.")
        else:
            log.info("No webhook set - long polling is active "
                     "(%s update(s) were pending).",
                     wi.pending_update_count)
    except Exception as e:
        log.warning("Startup self-check failed: %s", e)

    # proof for the owner
    try:
        try:
            me2 = me
        except Exception:
            me2 = None
        uname = f"@{me2.username}" if me2 is not None else "the bot"
        for aid in admin_dm_ids():
            try:
                await app.bot.send_message(
                    aid,
                    f"{ICON['check']} <b>BOT IS LIVE</b>\n" + LINE + "\n"
                    + kv("Bot", f"<b>{esc(uname)}</b>")
                    + kv("Server 1",
                         f"<b>{_global_stock.get('accounts1') or 0}</b> "
                         "accounts")
                    + kv("Server 2",
                         f"<b>{_global_stock.get('accounts2') or 0}</b> "
                         "accounts")
                    + kv("Wallet",
                         f"<b>{sup.balance:.2f} {sup.currency.upper()}</b>"
                         if sup.balance is not None else "not loaded")
                    + kv("Storage",
                         "MongoDB "
                         + ("ON" if mongo.on() and mongo.status == "ok"
                            else "OFF"))
                    + kv("Time", now_utc().strftime("%d %b %Y %H:%M:%S"))
                    + "\n" + LINE
                    + f"\n{ICON['info']} Send /start or /ping to test.",
                    parse_mode=ParseMode.HTML)
                log.info("Live notification sent to admin %s", aid)
            except Exception as e:
                log.warning("Could not DM admin %s: %s", aid, str(e)[:120])
    except Exception as e:
        log.warning("Live notification skipped: %s", str(e)[:120])

    if not STORE["native"]:
        try:
            r = fs_sync_all()
            log.info("File store %s: %s files, %s users, %s orders",
                     fs_dir(), r["files"], r["users"], r["orders"])
        except Exception as e:
            log.warning("File store first sync failed: %s", e)

    st = await refresh_global_stock(force=True)
    log.info("Live stock header: %s accounts across %s active countries",
             st.get("accounts"), st.get("countries"))

    if app.job_queue:
        app.job_queue.run_repeating(job_expire_deps, interval=300, first=90)
        app.job_queue.run_repeating(job_v14, interval=60, first=45)
        app.job_queue.run_repeating(job_supplier_watch, interval=10800,
                                    first=600)
        app.job_queue.run_repeating(job_sup_balance, interval=240, first=20)
        app.job_queue.run_repeating(job_live_price, interval=180, first=8)
        app.job_queue.run_repeating(job_file_sync, interval=20, first=6)
        app.job_queue.run_repeating(job_mongo_sync, interval=120, first=20)
        app.job_queue.run_repeating(job_mongo_pull, interval=300, first=150)
        app.job_queue.run_repeating(job_store_flush, interval=2, first=2)
        app.job_queue.run_repeating(job_auto_deals, interval=3600, first=60)        
        log.info(
            "Background jobs started (live pricing %s, %s countries/run, "
            "mongo sync 2m)",
            "ON" if live_prices_on() else "OFF", live_price_batch())
    else:
        log.warning('JobQueue missing - install: '
                    'pip install "python-telegram-bot[job-queue]"')

    asyncio.create_task(recover_pending_deps(app))
    log.info("%s v%s is LIVE", SHOP_NAME, VERSION)


async def post_shutdown(app: Application):
    for t in list(_pay_tasks.values()):
        t.cancel()
    _pay_tasks.clear()
    try:
        store_flush(100000)
        mongo.flush_queue(20)
    except Exception:
        pass
    try:
        mongo.close()
    except Exception:
        pass
    await sup.close()
    await gateway.close()
    log.info("Shutdown complete.")


