def _wrap_screens():
    for _n, _f in list(globals().items()):
        if (_n.startswith("s_") and callable(_f)
                and getattr(_f, "__module__", "") == __name__
                and not getattr(_f, "_cleaned", False)):
            def _mk(fn):
                def _inner(*a, **kw):
                    return clean_text(fn(*a, **kw))
                _inner._cleaned = True
                _inner.__name__ = getattr(fn, "__name__", "_inner")
                _inner.__doc__ = getattr(fn, "__doc__", None)
                return _inner
            globals()[_n] = _mk(_f)
    for _c in ("S_PAY_FAIL", "S_LOW_BAL", "S_NO_STOCK", "S_GONE", "S_HELP",
               "S_ADMIN", "BAN_MSG"):
        _v = globals().get(_c)
        if isinstance(_v, str):
            globals()[_c] = clean_text(_v)


_wrap_screens()


