# ── Today's profit ──────────────────────────────────────────────────
_profit_cache: Dict[int, Tuple[float, dict]] = {}


def _parse_ts(v) -> Optional[datetime]:
    if not v:
        return None
    t = str(v).strip().replace("Z", "").replace(" ", "T")
    try:
        d = datetime.fromisoformat(t[:26])
    except ValueError:
        try:
            d = datetime.strptime(t[:19], "%Y-%m-%dT%H:%M:%S")
        except ValueError:
            return None
    return d.replace(tzinfo=None) if d.tzinfo is None else \
        d.astimezone(timezone.utc).replace(tzinfo=None)


def _day_bounds(day_offset=0) -> Tuple[datetime, datetime, str]:
    """UTC [start, end) of a local day (REPORT_TZ_OFFSET) + its label."""
    off = timedelta(minutes=REPORT_TZ_OFFSET)
    local = (now_utc() + off).replace(hour=0, minute=0, second=0,
                                      microsecond=0) - timedelta(days=day_offset)
    return local - off, local - off + timedelta(days=1), \
        local.strftime("%d %b %Y") + f" · {REPORT_TZ_LABEL}"


def profit_report(day_offset=0) -> dict:
    """Revenue, supplier cost and profit of delivered orders in one day.
    Read-only: only SELECTs on existing tables."""
    hit = _profit_cache.get(day_offset)
    if hit and time.monotonic() - hit[0] < 20:
        return hit[1]
    start, end, label = _day_bounds(day_offset)
    since = (start - timedelta(days=1)).strftime("%Y-%m-%d")
    rep_ = {"label": label, "orders": 0, "revenue": 0.0, "cost": 0.0,
            "profit": 0.0, "margin": 0.0, "unknown": 0, "deposits": 0.0,
            "dep_count": 0, "by_srv": {1: [0, 0.0, 0.0], 2: [0, 0.0, 0.0]},
            "top": []}
    top = Counter()
    try:
        rows = _get_conn().execute(
            "SELECT store_price, supplier_cost, supplier_currency, server, "
            "country_name, delivered_at FROM orders WHERE status='delivered' "
            "AND delivered_at >= ?", (since,)).fetchall()
    except Exception as e:
        log.warning("profit_report: %s", e)
        rows = []
    for r in rows:
        ts = _parse_ts(r["delivered_at"])
        if ts is None or not (start <= ts < end):
            continue
        price = float(r["store_price"] or 0)
        rep_["orders"] += 1
        rep_["revenue"] += price
        if r["supplier_cost"] is None or float(r["supplier_cost"] or 0) <= 0:
            rep_["unknown"] += 1
            cost = 0.0
        else:
            cost = to_inr(r["supplier_cost"], r["supplier_currency"])
        rep_["cost"] += cost
        try:
            srv = int(r["server"] or 1)
        except (TypeError, ValueError):
            srv = 1
        b = rep_["by_srv"].setdefault(srv, [0, 0.0, 0.0])
        b[0] += 1
        b[1] += price
        b[2] += price - cost
        top[str(r["country_name"] or "?")] += 1
    rep_["profit"] = rep_["revenue"] - rep_["cost"]
    rep_["margin"] = (rep_["profit"] / rep_["revenue"] * 100.0
                      if rep_["revenue"] else 0.0)
    rep_["top"] = top.most_common(5)
    try:
        for d in _get_conn().execute(
                "SELECT amount, resolved_at FROM deposits WHERE "
                "status='approved' AND resolved_at >= ?", (since,)):
            ts = _parse_ts(d["resolved_at"])
            if ts is not None and start <= ts < end:
                rep_["deposits"] += float(d["amount"] or 0)
                rep_["dep_count"] += 1
    except Exception:
        pass
    _profit_cache[day_offset] = (time.monotonic(), rep_)
    return rep_


def _delta(now_v, prev_v) -> str:
    if prev_v <= 0:
        return "first sales" if now_v > 0 else ""
    d = (now_v - prev_v) / abs(prev_v) * 100.0
    return f"{'+' if d >= 0 else ''}{d:.0f}% vs previous day"



def profit_block(tp=None, day_offset=0) -> str:
    tp = tp or profit_report(day_offset)
    prev = profit_report(day_offset + 1)
    title = "Today" if day_offset == 0 else tp["label"].split(" \u00b7")[0]
    return fin_block(title, tp, note=_delta(tp["profit"], prev["profit"]))



def s_today_profit(day_offset=0) -> str:
    tp = profit_report(day_offset)
    srv_lines = []
    for srv in (1, 2):
        c, rev_, pr = tp["by_srv"].get(srv, [0, 0.0, 0.0])
        srv_lines.append(f"Server {srv} \u2014 Orders <code>{c}</code> | "
                         f"Revenue <code>{money(rev_)}</code> | "
                         f"Profit <code>{money(pr)}</code>")
    top = [f"{i}. {esc(n)} \u2014 <code>{c}</code>"
           for i, (n, c) in enumerate(tp["top"], 1)] or ["No sales yet"]
    week = [profit_report(i) for i in range(6, -1, -1)]
    hi = max([w["profit"] for w in week] + [1.0])
    trend = [f"{w['label'].split(' ')[0]} {w['label'].split(' ')[1]}  "
             f"{chr(0x2588) * max(1, int(round(10 * max(0.0, w['profit']) / hi)))}"
             f"  {money(w['profit'])}" for w in week]
    recent = account_profit_rows(0, 5)[0]
    acc = [_acc_line(r) for r in recent] or ["No accounts sold yet"]
    return (head("Revenue & profit", sub=esc(tp["label"])) + "\n"
            + profit_block(tp, day_offset) + "\n"
            + lifetime_block() + "\n"
            + "<b>BY SERVER</b>\n" + box(srv_lines) + "\n"
            + "<b>LAST 7 DAYS \u2014 PROFIT</b>\n<pre>" + esc("\n".join(trend))
            + "</pre>\n"
            + "<b>TOP COUNTRIES</b>\n" + box(top) + "\n"
            + "<b>ACCOUNT-WISE PROFIT \u2014 LATEST</b>\n" + box(acc) + "\n"
            + f"Deposits received: <code>{money(tp['deposits'])}</code> "
              f"({tp['dep_count']})\n"
            + "<i>Profit = sale price \u2212 supplier cost (converted to INR).</i>")



