    await qans(q, f"Role updated: {ROLE_LABEL[role_of(uid)]}", True)
    await send(ctx.bot, uid, head("Your role changed", "🎖") + "\n"
               f"You are now <b>{ROLE_LABEL[role_of(uid)]}</b>.\n"
               "Send /admin to open the panel.")
