async def cb_aadm_del(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    try:
        uid = int(q.data.rsplit("_", 1)[-1])
    except ValueError:
        return await qans(q, "Invalid admin", True)
    if uid in ADMIN_IDS:
        return await qans(q, "The owner cannot be removed", True)
    if uid == q.from_user.id:
        return await qans(q, "You cannot remove yourself", True)
    if not db_del_admin(uid):
        return await qans(q, "Admin not found", True)
    set_role(uid, ROLE_ADMIN)          # clear any stored Super flag
    await qans(q, f"Admin {uid} removed")
    await edit_q(q, s_team(), kb_team())


