# ── Central access gate (runs before every other handler) ───────────
_USER_AW_EXACT = {"custom_dep", "csearch", "country_search", "promo"}
_USER_AW_PREFIX = ("cfkw_", "bulkqty_", "cfagc_")


async def access_gate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    u = update.effective_user
    if u is None:
        return
    q = update.callback_query
    if q is not None:
        data = q.data or ""
        if not is_admin_callback(data):
            return
        if can_use_callback(u.id, data):
            return
        msg = ("Access denied" if not is_admin(u.id) else
               "Restricted: your role (Admin) cannot use this. "
               "Ask the Owner or a Super Admin.")
        await qans(q, msg, True)
        raise ApplicationHandlerStop
    m = update.effective_message
    if m is None or not is_admin(u.id) or is_full_admin(u.id):
        return
    txt = (m.text or "").strip()
    if txt.startswith("/"):
        cmd = txt.split()[0][1:].split("@")[0].lower()
        if cmd in FULL_ONLY_COMMANDS:
            await m.reply_text("🔒 This command is for Owner / Super Admin only.")
            raise ApplicationHandlerStop
        return
    aw = (ctx.user_data or {}).get("aw") if ctx.user_data is not None else None
    if aw and aw not in _USER_AW_EXACT and \
            not str(aw).startswith(_USER_AW_PREFIX):
        need = LIMITED_AW.get(aw)
        if not need or not has_perm(u.id, need):
            ctx.user_data.pop("aw", None)


# ── Turbo broadcast ─────────────────────────────────────────────────
class _TokenBucket:
    def __init__(self, rate: float):
        self.rate = float(rate)
        self.tokens = float(rate)
        self.t = time.monotonic()
        self.lock = asyncio.Lock()

    async def take(self):
        async with self.lock:
            while True:
                now = time.monotonic()
                self.tokens = min(self.rate, self.tokens
                                  + (now - self.t) * self.rate)
                self.t = now
                if self.tokens >= 1:
                    self.tokens -= 1
                    return
                await asyncio.sleep((1 - self.tokens) / self.rate)


_HTML_TAG_RE = re.compile(r"</?(b|i|u|s|a|code|pre|blockquote|tg-spoiler)\b",
                          re.I)
_bc_jobs: Dict[int, dict] = {}


def bc_targets(active_days=None) -> List[int]:
    sql = "SELECT user_id FROM users WHERE COALESCE(dead,0)=0 AND " \
          "COALESCE(is_banned,0)=0"
    params: tuple = ()
    if active_days:
        since = (now_utc() - timedelta(days=int(active_days))).isoformat()
        sql += " AND COALESCE(last_seen,'') >= ?"
        params = (since,)
    try:
        return [int(r["user_id"]) for r in _get_conn().execute(sql, params)
                if int(r["user_id"]) > 0]
    except Exception:
        return [int(x) for x in db_all_uids()]


async def bc_capture(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Admin sent the message to broadcast -> show preview + options."""
    msg = update.effective_message
    u = update.effective_user
    ctx.user_data.pop("aw", None)
    html_mode = bool(msg.text and _HTML_TAG_RE.search(msg.text))
    ctx.user_data["bc_src"] = {"chat": msg.chat_id, "mid": msg.message_id,
                               "html": html_mode,
                               "text": msg.text if html_mode else "",
                               "silent": False,
                               "preview": (msg.text or msg.caption
                                           or "(media)")[:200]}
    await _bc_options(ctx.bot, u.id, ctx)
    raise ApplicationHandlerStop


async def _bc_options(bot, uid, ctx, edit_q_obj=None):
    src = ctx.user_data.get("bc_src") or {}
    n_all = len(bc_targets())
    n_act = len(bc_targets(7))
    text = (head("Broadcast preview", "📣") + "\n"
            + box([f"👥 All users: <b>{n_all}</b>",
                   f"🟢 Active last 7 days: <b>{n_act}</b>",
                   f"⚡ Speed: ~<b>{BROADCAST_RATE:g}</b> msg/s "
                   f"(~{max(1, int(n_all / BROADCAST_RATE))}s for all)",
                   f"🔔 Notification: <b>{'silent' if src.get('silent') else 'normal'}</b>",
                   f"📝 Mode: <b>{'HTML text' if src.get('html') else 'exact copy'}</b>"])
            + "\n<i>The message above is exactly what users will receive.</i>")
    kb = ikb(kb_row((f"🚀 Send to All ({n_all})", "bc_go_all", BTN_SUCCESS)),
             kb_row((f"🟢 Active 7d ({n_act})", "bc_go_act", BTN_PRIMARY),
                    ("🔕 Silent" if not src.get("silent") else "🔔 Notify",
                     "bc_silent", BTN_PRIMARY)),
             kb_row(("✖️ Cancel", "bc_cancel", BTN_DANGER)))
    if edit_q_obj is not None:
        return await edit_q(edit_q_obj, text, kb)
    try:
        if src.get("html"):
            await bot.send_message(uid, src["text"], parse_mode=ParseMode.HTML)
        else:
            await bot.copy_message(uid, src["chat"], src["mid"])
    except Exception as e:
        text += f"\n⚠️ Preview failed: <code>{esc(str(e)[:120])}</code>"
    await send(bot, uid, text, kb)


