async def cb_bc(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    uid = q.from_user.id
    act = q.data[3:]
    if act == "stop":
        job = _bc_jobs.get(uid)
        if job:
            job["stop"] = True
        return await qans(q, "Stopping broadcast...", True)
    if act == "cancel":
        ctx.user_data.pop("bc_src", None)
        await qans(q, "Cancelled")
        return await edit_q(q, admin_menu_text(uid), admin_menu_kb(uid))
    src = ctx.user_data.get("bc_src")
    if not src:
        return await qans(q, "Preview expired - start again", True)
    if act == "silent":
        src["silent"] = not src.get("silent")
        await qans(q)
        return await _bc_options(ctx.bot, uid, ctx, edit_q_obj=q)
    if _bc_jobs.get(uid, {}).get("running"):
        return await qans(q, "A broadcast is already running", True)
    targets = bc_targets(7 if act == "go_act" else None)
    ctx.user_data.pop("bc_src", None)
    await qans(q, f"Sending to {len(targets)} users...")
    job = {"running": True, "stop": False}
    _bc_jobs[uid] = job
    asyncio.get_running_loop().create_task(
        run_broadcast(ctx.bot, uid, q.message, src, targets, job))


async def run_broadcast(bot, admin_id, status_msg, src, targets, job):
    """Concurrent workers + token bucket; one global pause on flood-wait."""
    total = len(targets)
    queue: asyncio.Queue = asyncio.Queue()
    for t in targets:
        queue.put_nowait(t)
    bucket = _TokenBucket(BROADCAST_RATE)
    st = {"sent": 0, "failed": 0, "blocked": 0, "pause_until": 0.0}
    dead: List[int] = []
    t0 = time.monotonic()

    async def deliver(uid):
        _RAW_TEXT.set(True)
        if src.get("html"):
            await bot.send_message(uid, src["text"], parse_mode=ParseMode.HTML,
                                   disable_notification=src.get("silent"))
        else:
            await bot.copy_message(uid, src["chat"], src["mid"],
                                   disable_notification=src.get("silent"))

    async def worker():
        while not job["stop"]:
            try:
                uid = queue.get_nowait()
            except asyncio.QueueEmpty:
                return
            
            for attempt in range(3):
                if job["stop"]:  # ✅ Stop button dabane par turant ruk jayega
                    return
                    
                wait = st["pause_until"] - time.monotonic()
                if wait > 0:
                    await asyncio.sleep(wait)
                    if job["stop"]:
                        return
                        
                await bucket.take()
                if job["stop"]:
                    return
                    
                try:
                    await deliver(uid)
                    st["sent"] += 1
                    break
                except RetryAfter as e:
                    ra = getattr(e, "retry_after", 3) or 3
                    ra = float(ra.total_seconds() if hasattr(ra, "total_seconds") else ra)
                    st["pause_until"] = max(st["pause_until"], time.monotonic() + ra + 0.5)
                    continue
                except Forbidden:
                    st["blocked"] += 1
                    dead.append(uid)
                    break
                except BadRequest as e:
                    m = str(e).lower()
                    if "chat not found" in m or "deactivated" in m or "blocked" in m:
                        st["blocked"] += 1
                        dead.append(uid)
                    else:
                        st["failed"] += 1
                    break
                except (TimedOut, NetworkError):
                    await asyncio.sleep(1 + attempt)
                    continue
                except Exception as e:
                    log.warning("Broadcast error for %s: %s", uid, e) # ✅ Error log
                    st["failed"] += 1
                    break
            else:
                st["failed"] += 1

    def card_(final=False):
        done = st["sent"] + st["failed"] + st["blocked"]
        el = max(0.1, time.monotonic() - t0)
        spd = done / el
        eta = int((total - done) / spd) if spd > 0 and not final else 0
        title = ("Broadcast stopped" if job["stop"] and final else
                 "Broadcast finished" if final else "Broadcasting...")
        return (head(title, "📣") + "\n"
                + f"<code>{pbar(done, total, 14)}</code>  "
                  f"<b>{int(done / max(1, total) * 100)}%</b>\n"
                + box([f"✅ Delivered: <b>{st['sent']}</b>",
                       f"🚫 Blocked / gone: <b>{st['blocked']}</b>",
                       f"❌ Failed: <b>{st['failed']}</b>",
                       f"📊 Progress: <b>{done}</b> / {total}",
                       f"⚡ Speed: <b>{spd:.1f}</b> msg/s"
                       + (f"  •  ETA ~{eta}s" if eta else ""),
                       f"⏱ Time: {int(el)}s"]))

    async def reporter():
        last = ""
        while job["running"]:
            await asyncio.sleep(2.5)
            if not job["running"]:
                break
            txt = card_()
            if txt != last:
                last = txt
                await edit_any(status_msg, txt,
                               ikb(kb_row(("⏹ Stop", "bc_stop", BTN_DANGER))))

    rep_task = asyncio.get_running_loop().create_task(reporter())
    try:
        await edit_any(status_msg, card_(),
                       ikb(kb_row(("⏹ Stop", "bc_stop", BTN_DANGER))))
        n = max(1, min(BROADCAST_WORKERS, total))
        await asyncio.gather(*(worker() for _ in range(n)))
    except Exception as e:
        log.exception("broadcast crashed: %s", e)
    finally:
        job["running"] = False
        rep_task.cancel()
        if dead:
            def _mark():
                for d in dead:
                    try:
                        db_set_user(d, dead=1)
                    except Exception:
                        pass
            try:
                await asyncio.to_thread(_mark)
            except Exception as e:
                log.warning("broadcast dead-mark failed: %s", e)
        db_log_broadcast(st["sent"], st["failed"] + st["blocked"],
                         src.get("preview", ""), admin_id)
        await edit_any(status_msg, card_(final=True),
                       ikb(kb_row(("📣 New Broadcast", "abr", BTN_SUCCESS),
                                  ("🛠 Admin Panel", "admin", BTN_PRIMARY))))
        log.info("broadcast done: %s sent, %s blocked, %s failed in %.1fs",
                 st["sent"], st["blocked"], st["failed"], time.monotonic() - t0)


