# ── C2. Profit-safe promo discount + referral payout on delivery ─────
def _promo_is_pct(ptype) -> bool:
    return str(ptype or "").lower() in ("percent", "pct", "discount", "%")


def _on_delivered(oid):
    """Post-delivery rewards. Both are capped by real profit:
    * % promo cashback  <= price - cost - minimum profit
    * referral reward   =  ref_pct of (price - cost - cashback)
    Orders without a recorded supplier cost pay no rewards (profit unknown)."""
    o = db_order(oid)
    if not o or o["status"] != "delivered":
        return
    if o["supplier_cost"] is None or float(o["supplier_cost"] or 0) <= 0:
        return
    uid = int(o["user_id"])
    price = float(o["store_price"] or 0)
    profit = price - to_inr(o["supplier_cost"], o["supplier_currency"])
    cashback = 0.0
    raw = _kv_get(f"pdisc:{uid}")
    if raw and not _ledger_has(f"PDISC-{oid}"):
        try:
            d = json.loads(raw)
        except Exception:
            d = {}
        pct = float(d.get("pct") or 0)
        cashback = round(max(0.0, min(price * pct / 100.0,
                                      profit - min_profit_inr())), 2)
        if cashback >= 0.01:
            _kv_set(f"pdisc:{uid}", "")
            nb = db_credit(uid, cashback, f"Promo {d.get('code', '')} discount",
                           f"PDISC-{oid}")
            _V14_NOTES.append((uid, head("Promo discount applied") + "\n"
                               + box([f"Order: <code>#{oid}</code>",
                                      f"Discount: <code>{money(cashback)}</code>",
                                      f"Balance: <code>{money(nb)}</code>"]),
                               None))
        else:
            cashback = 0.0
    net = profit - cashback
    rid = referrer_of(uid)
    if rid and net > 0 and not _ledger_has(f"REF-{oid}"):
        reward = math.floor(net * ref_pct()) / 100.0
        if reward >= 0.01:
            nb = db_credit(rid, reward, "Referral Reward", f"REF-{oid}")
            _V14_NOTES.append((rid, head("Referral reward") + "\n"
                               + box(["A friend you referred completed a purchase.",
                                      f"Reward: <code>{money(reward)}</code>",
                                      f"Balance: <code>{money(nb)}</code>"]),
                               None))


_db_upd_order_base = db_upd_order


def db_upd_order(oid, **kw):  # noqa: F811 - intentional wrapper
    _db_upd_order_base(oid, **kw)
    if kw.get("status") == "delivered":
        try:
            _on_delivered(oid)
        except Exception as e:
            log.warning("post-delivery rewards for #%s: %s", oid, e)


# ── D. Restock alerts (Notify Me) ────────────────────────────────────
def kb_notify(cc, srv):
    cc = str(cc or "").upper()
    if len(cc) != 2 or not cc.isalpha():
        # v40: restock alerts are per country - an "ALL" view has nothing to
        # watch, and an ntf_..._ALL button used to be a dead ("expired") one
        return ikb(kb_row(("Back", f"scl_{int(srv)}_0", BTN_PRIMARY),
                          ("Main Menu", "main_menu", BTN_PRIMARY)))
    return ikb(kb_row(("Notify Me", f"ntf_{int(srv)}_{cc}", BTN_PRIMARY),
                      ("Back", f"scl_{int(srv)}_0", BTN_PRIMARY)),
               kb_row(("Main Menu", "main_menu", BTN_PRIMARY)))


def _wl_load(cc):
    try:
        return [list(x) for x in json.loads(_kv_get(f"wl:{cc}", "[]"))]
    except Exception:
        return []


async def cb_ntf(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    try:
        _, srv, cc = q.data.split("_")
        srv, cc = int(srv), cc.upper()
    except ValueError:
        return await qans(q)
    uid = q.from_user.id
    wl = _wl_load(cc)
    if not any(int(u) == uid and int(s) == srv for u, s in wl):
        wl.append([uid, srv])
        _kv_set(f"wl:{cc}", json.dumps(wl[-500:]))
    c = db_country(cc)
    name = c["name"] if c else cc
    await qans(q, "You will be notified when it is back in stock.", True)
    await edit_q(q, head("Restock alert saved") + "\n"
                 + box([f"Country: <b>{esc(name)}</b> ({esc(ctag(cc))})",
                        f"Server: <code>{srv}</code>",
                        "We will message you as soon as accounts are "
                        "available again."]),
                 ikb(kb_row(("Browse Accounts", "shop", BTN_SUCCESS)),
                     kb_row(("Main Menu", "main_menu"))))


async def cb_wlb(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """'Buy Now' from a restock alert: opens the country on its server."""
    q = update.callback_query
    try:
        _, srv, cc = q.data.split("_")
    except ValueError:
        return await qans(q)
    ctx.user_data["shop_srv"] = int(srv)
    return await cb_buy(_UpdProxy(update, f"buy_{cc.upper()}"), ctx)


class _QProxy:
    def __init__(self, q, data):
        self._q, self.data = q, data

    def __getattr__(self, n):
        return getattr(self._q, n)


class _UpdProxy:
    def __init__(self, update, data):
        self._u = update
        self.callback_query = _QProxy(update.callback_query, data)

    def __getattr__(self, n):
        return getattr(self._u, n)


async def _restock_pass(bot):
    rows = _get_conn().execute(
        "SELECT key, value FROM settings WHERE key LIKE 'wl:%' "
        "AND value NOT IN ('', '[]') LIMIT 25").fetchall()
    for r in rows:
        cc = r["key"][3:]
        wl = _wl_load(cc)
        keep = []
        for srv in sorted({int(s) for _u, s in wl}):
            users = [int(u) for u, s in wl if int(s) == srv]
            live = False
            if country_floor(cc, srv) > 0:
                try:
                    live = bool(await _bulk_candidates(srv, cc, 1, max_pages=1))
                except Exception:
                    live = False
            if not live:
                keep += [[u, srv] for u in users]
                continue
            c = db_country(cc)
            name = c["name"] if c else cc
            txt = (head("Back in stock", sub="Accounts you asked for are available")
                   + "\n" + box([f"Country: <b>{esc(name)}</b> ({esc(ctag(cc))})",
                                 f"Server: <code>{srv}</code>",
                                 f"Price from: <code>{money(country_floor(cc, srv))}</code>"])
                   + "\n<i>Stock is limited - first come, first served.</i>")
            kb = ikb(kb_row(("Buy Now", f"wlb_{srv}_{cc}", BTN_SUCCESS)),
                     kb_row(("Main Menu", "main_menu")))
            for u in users:
                try:
                    await send(bot, u, txt, kb)
                except Exception as e:
                    log.info("restock send %s/%s failed: %s", cc, u, e)
                    keep.append([u, srv])   # retry next pass
                await asyncio.sleep(0.05)
        _kv_set(f"wl:{cc}", json.dumps(keep))


# ── E. Abandoned deposit reminder (one-time, after 10 minutes) ───────
async def _deposit_reminders(bot):
    c = _get_conn()
    rows = c.execute(
        "SELECT id, user_id, amount FROM deposits WHERE status IN "
        "('pending','timeout') AND payment_mode='auto_upi' "
        "AND created_at <= datetime('now','-10 minutes') "
        "AND created_at >= datetime('now','-45 minutes') ORDER BY id"
    ).fetchall()
    if not rows:
        return
    try:
        done = [int(x) for x in json.loads(_kv_get("dep_reminded", "[]"))]
    except Exception:
        done = []
    seen = set(done)
    for d in rows:
        did = int(d["id"])
        if did in seen:
            continue
        seen.add(did)
        done.append(did)
        newer = c.execute("SELECT 1 FROM deposits WHERE user_id=? AND id>? "
                          "LIMIT 1", (d["user_id"], did)).fetchone()
        if newer:
            continue
        try:
            await send(bot, d["user_id"],
                       head("Payment not completed") + "\n"
                       + box([f"Deposit: <code>#{did}</code>",
                              f"Amount: <code>{money(d['amount'])}</code>"])
                       + "\nIf you have already paid, tap <b>Verify Payment</b> "
                         "and your wallet will be credited instantly.\n"
                       + "<i>Not paid yet? You can start a new deposit at any "
                         "time.</i>",
                       ikb(kb_row(("Verify Payment", f"cpay_{did}", BTN_SUCCESS)),
                           kb_row(("New Deposit", "deposit", BTN_SUCCESS),
                                  ("Main Menu", "main_menu"))))
        except Exception as e:
            log.debug("deposit reminder #%s: %s", did, e)
    _kv_set("dep_reminded", json.dumps(done[-300:]))


async def job_v14(ctx: ContextTypes.DEFAULT_TYPE):
    """Every minute: queued notifications + deposit reminders.
    Every 5 minutes: restock alerts."""
    bot = ctx.bot
    while _V14_NOTES:
        uid, txt, kb = _V14_NOTES.pop(0)
        try:
            await send(bot, uid, txt, kb or ikb(kb_row(("Main Menu", "main_menu"))))
        except Exception:
            pass
    try:
        await _deposit_reminders(bot)
    except Exception as e:
        log.warning("deposit reminders: %s", e)
    job_v14.ticks = getattr(job_v14, "ticks", 0) + 1
    if job_v14.ticks % 5 == 1:
        try:
            await _restock_pass(bot)
        except Exception as e:
            log.warning("restock alerts: %s", e)


# ── Admin: Profit Guard + referral rate ──────────────────────────────
async def cb_apg(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not is_full_admin(q.from_user.id):
        return await qans(q, "Access denied", True)
    await qans(q)
    if q.data == "apg_set":
        ctx.user_data["aw"] = "v14_minprofit"
        return await edit_q(q, head("Profit guard") + "\n"
                            "Send the minimum profit per account in INR "
                            "(for example <code>2</code>).",
                            ikb(kb_row(("Cancel", "apg"))))
    await edit_q(q, head("Profit guard", sub="Zero-loss pricing") + "\n"
                 + box([f"Minimum profit per account: <code>{money(min_profit_inr())}</code>",
                        "Every price shown, every bulk discount and every "
                        "promo discount is floored at supplier cost plus "
                        "this amount.",
                        "Before a picked account is bought, its live cost is "
                        "re-checked; if it went up, the price is raised and the "
                        "buyer confirms again.",
                        "The supplier is never allowed to charge more than "
                        "sale price minus this amount."]),
                 ikb(kb_row(("Set Minimum Profit", "apg_set"),
                            ("Margin", "amk"))))


async def cb_arfc(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not is_full_admin(q.from_user.id):
        return await qans(q, "Access denied", True)
    await qans(q)
    if q.data == "arfc_set":
        ctx.user_data["aw"] = "v14_refpct"
        return await edit_q(q, head("Referral rate") + "\n"
                            "Send the share of net profit paid to referrers, "
                            "0 to 50 (for example <code>10</code>).",
                            ikb(kb_row(("Cancel", "arfc"))))
    c = _get_conn()
    n = c.execute("SELECT COUNT(*) AS n FROM settings WHERE key LIKE 'ref:%' "
                  "AND value<>''").fetchone()["n"]
    paid = c.execute("SELECT COALESCE(SUM(amount),0) AS s FROM ledger "
                     "WHERE reference LIKE 'REF-%'").fetchone()["s"]
    await edit_q(q, head("Referral programme") + "\n"
                 + box([f"Reward rate: <code>{ref_pct():g}% of net profit</code>",
                        f"Referred users: <code>{n}</code>",
                        f"Rewards paid: <code>{money(paid)}</code>"])
                 + "\n<i>Paid only on delivered orders with a known supplier "
                   "cost. No sign-up bonus.</i>",
                 ikb(kb_row(("Set Referral Rate", "arfc_set"),
                            ("Margin", "amk"))))


async def v14_text_hook(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    # channel posts / anonymous admins have no user -> ctx.user_data is None
    if msg is None or ctx.user_data is None or update.effective_user is None:
        return
    aw = ctx.user_data.get("aw")
    if not msg.text or aw not in ("v14_minprofit", "v14_refpct"):
        return
    if not is_full_admin(update.effective_user.id):
        return
    ctx.user_data.pop("aw", None)
    try:
        val = float(msg.text.strip().replace("\u20b9", "").replace("%", ""))
    except ValueError:
        await msg.reply_text("Please send a number.",
                             reply_markup=ikb(kb_row(("Margin", "amk"))))
        raise ApplicationHandlerStop
    if aw == "v14_minprofit":
        val = max(0.0, min(10000.0, val))
        db_set_setting("min_profit_inr", f"{val:g}")
        txt = f"Minimum profit per account set to <code>{money(val)}</code>."
        back = ("Profit Guard", "apg")
    else:
        val = max(0.0, min(50.0, val))
        db_set_setting("ref_pct", f"{val:g}")
        txt = f"Referral reward set to <code>{val:g}%</code> of net profit."
        back = ("Referral Rate", "arfc")
    await msg.reply_text(head("Saved") + "\n" + txt, parse_mode=ParseMode.HTML,
                         reply_markup=ikb(kb_row(back, ("Admin Panel", "admin"))))
    raise ApplicationHandlerStop


def build_app() -> Application:
    _bot = make_bot()
    builder = ApplicationBuilder()
    if _bot is not None:
        builder = builder.bot(_bot)
    else:
        builder = (builder.token(BOT_TOKEN)
                   .connection_pool_size(max(64, BROADCAST_WORKERS * 2))
                   .defaults(Defaults(
                       parse_mode=ParseMode.HTML,
                       link_preview_options=LinkPreviewOptions(
                           is_disabled=True))))
    app = (builder
           .concurrent_updates(256)
           .post_init(post_init)
           .post_shutdown(post_shutdown)
           .build())

    # v11: role-based access gate runs before everything else
    app.add_handler(TypeHandler(Update, v14_ref_capture), group=-9)
    app.add_handler(TypeHandler(Update, access_gate), group=-5)
    app.add_handler(TypeHandler(Update, v15_filters_load), group=-8)
    app.add_handler(TypeHandler(Update, v15_admin_ack), group=-7)
    app.add_handler(MessageHandler(
        filters.TEXT & ~filters.COMMAND & filters.ChatType.PRIVATE
        & filters.UpdateType.MESSAGE, v14_text_hook), group=-3)
    app.add_handler(TypeHandler(Update, _watch_user_msg), group=-1)
    app.add_handler(MessageHandler(
        filters.TEXT & ~filters.COMMAND & filters.ChatType.PRIVATE
        & filters.UpdateType.MESSAGE, v11_text_hook), group=-2)
    app.add_handler(MessageHandler(
        ~filters.TEXT & ~filters.COMMAND & filters.ChatType.PRIVATE,
        bc_media_capture), group=-2)

    PRIV = filters.ChatType.PRIVATE
    app.add_handler(CommandHandler("start", cmd_start, filters=PRIV))
    app.add_handler(CommandHandler("referral", cmd_referral, filters=PRIV))
    app.add_handler(CommandHandler("menu", cmd_menu, filters=PRIV))
