def main():
    _here = os.path.abspath(__file__)
    print("\n"
          "==================================================\n"
          f"   {SHOP_NAME}  -  Bot v{VERSION}\n"
          "   PTB 22.x  |  Python 3.13 ready\n"
          "   Deposit: FamGateway API  |  Supplier: TG MANDI reseller API\n"
          "   Cloud:   MongoDB Atlas (Firebase fully removed)\n"
          "   Animation: Buy progress card enabled\n"
          f"   Countries: {len(COUNTRIES)} (ISO-2)\n"
          f"   Origins: {', '.join(ALLOWED_ORIGINS)}\n"
          f"   Running: {_here}\n"
          f"   Data dir: {os.path.abspath(fs_dir())}\n"
          "==================================================\n")
    if not BOT_TOKEN or ":" not in BOT_TOKEN or "YOUR_" in BOT_TOKEN:
        print("BOT_TOKEN is not set!")
        print('Set it with: export BOT_TOKEN="123:ABC"\n')
        return
    if not TGM_API_KEY:
        print("SUPPLIER_API_KEY is not set!")
        print('Set it with: export SUPPLIER_API_KEY="tgm_your_reseller_key"\n')
        return
    if not mongo.url():
        print("MONGO_URL is not set; MongoDB persistence is required.")
        print('Set it with: export MONGO_URL="mongodb+srv://user:pass@cluster/"\n')
        return
    app = build_app()
    log.info("Starting polling... (Ctrl+C to stop)")
    try:
        app.run_polling(drop_pending_updates=True,
                        allowed_updates=Update.ALL_TYPES)
    except KeyboardInterrupt:
        log.info("Stopped manually.")
    except Exception as e:
        log.exception("Fatal: %s", e)


def db_self_check() -> int:
    """`python3 main.py --dbcheck` - prove the MongoDB connection works.

    Prints the cluster, the database, the collections and how many rows the
    shop already has there, then exits. Nothing is written, so it is safe to
    run on a live server before a restart.
    """
    print(f"\n{SHOP_NAME} - MongoDB self check (v{VERSION})\n" + "-" * 54)
    url = mongo.url()
    if not url:
        print("MONGO_URL is empty - nothing to check.")
        return 2
    try:
        from urllib.parse import urlsplit
        parts = urlsplit(url)
        hosts = [h for h in (parts.netloc.split("@")[-1] or "").split(",") if h]
        print(f"cluster : {', '.join(hosts) or '?'}")
        print(f"user    : {parts.username or '?'}")
        print(f"database: {mongo.dbname()}")
        print(f"options : {parts.query or '-'}")
    except Exception as e:                                      # noqa: BLE001
        print(f"URL parse warning: {e}")
    try:
        import pymongo
    except ImportError:
        print("pymongo is missing - run: pip install pymongo")
        return 2
    try:
        cli = pymongo.MongoClient(url, serverSelectionTimeoutMS=12000,
                                  connectTimeoutMS=12000)
        cli.admin.command("ping")
        dbn = mongo.dbname()
        print("ping    : OK")
        names = cli.list_database_names()
        print(f"visible : {', '.join(names[:8]) or '-'}")
        for coll in MONGO_COLLECTIONS:
            try:
                n = cli[dbn][coll].count_documents({})
            except Exception:                                   # noqa: BLE001
                n = "?"
            print(f"  {dbn}.{coll:<10} {n} rows")
        cli.close()
        print("-" * 54)
        print("Connection works - the bot can start with this cluster.")
        return 0
    except Exception as e:                                      # noqa: BLE001
        print(f"ping    : FAILED - {type(e).__name__}: {str(e)[:200]}")
        print("-" * 54)
        print("Fix: check the password, and add this server's IP to the")
        print("Atlas Network Access list (0.0.0.0/0 allows every IP).")
        return 1


if __name__ == "__main__":
    if "--dbcheck" in _sys.argv:
        raise SystemExit(db_self_check())
    main()
